import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  RefreshCw,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Camera,
  Trash2,
  IdCard,
  Building2,
  Briefcase,
  FileCheck,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

interface RegistroImportado {
  nome: string;
  cargo: string;
  unidade: 'ribas' | 'agua_clara';
  matricula?: string;
  telefone?: string;
}

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Estados do Modal de Cadastro Manual de Colaborador
  const [modalNovoColaboradorAberto, setModalNovoColaboradorAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novaMatricula, setNovaMatricula] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novoStatus, setNovoStatus] = useState<StatusPresenca>('presente');
  const [formErro, setFormErro] = useState<string | null>(null);
  const fotoInputRef = useRef<HTMLInputElement>(null);

  // Estados do Modal de Importação Excel / CSV
  const [modalImportAberto, setModalImportAberto] = useState(false);
  const [arquivoNome, setArquivoNome] = useState('');
  const [registrosPrevia, setRegistrosPrevia] = useState<RegistroImportado[]>([]);
  const [erroImportacao, setErroImportacao] = useState<string | null>(null);
  const [sucessoMsg, setSucessoMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Lista de colaboradores extraídos dos veículos e lista reserva
  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    // Adiciona colaboradores reserva se houver
    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const stats = useMemo(() => {
    const presentes = todosColaboradores.filter((c) => c.status === 'presente').length;
    const faltas = todosColaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = todosColaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: todosColaboradores.length };
  }, [todosColaboradores]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setFormErro('Por favor, selecione um arquivo de imagem válido (PNG, JPG, JPEG, WEBP).');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      setFormErro('A imagem selecionada deve ter no máximo 5MB.');
      return;
    }

    setFormErro(null);
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleRemoverFoto = () => {
    setNovaFoto('');
    if (fotoInputRef.current) {
      fotoInputRef.current.value = '';
    }
  };

  const handleCriarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) {
      setFormErro('O nome do colaborador é obrigatório.');
      return;
    }
    if (!novoCargo.trim()) {
      setFormErro('O cargo do colaborador é obrigatório.');
      return;
    }

    const novoItem: ColaboradorCompleto = {
      id: `colab-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim(),
      matricula: novaMatricula.trim() || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      foto: novaFoto || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
      status: novoStatus,
      regional: novaUnidade,
      equipeId: 'banco',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco Operacional',
      veiculoPlaca: 'BNC-0000',
    };

    setColaboradoresAdicionados((prev) => [novoItem, ...prev]);
    onAdicionarColaborador?.(novoItem);

    setNovoNome('');
    setNovoCargo('');
    setNovaMatricula('');
    setNovoTelefone('');
    setNovaFoto('');
    setFormErro(null);
    setModalNovoColaboradorAberto(false);
  };

  const parsePlanilhaLinhas = (conteudoTexto: string): RegistroImportado[] => {
    const linhas = conteudoTexto.split(/\r?\n/).map((l) => l.trim()).filter((l) => l.length > 0);
    if (linhas.length < 2) return [];

    const delimitador = linhas[0].includes(';') ? ';' : linhas[0].includes('\t') ? '\t' : ',';
    const cabecalho = linhas[0].split(delimitador).map((c) => c.replace(/["']/g, '').trim().toLowerCase());

    const idxNome = cabecalho.findIndex((c) => c.includes('nome') || c.includes('colaborador'));
    const idxCargo = cabecalho.findIndex((c) => c.includes('cargo') || c.includes('funcao') || c.includes('função'));
    const idxUnidade = cabecalho.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('polo'));
    const idxMatricula = cabecalho.findIndex((c) => c.includes('matricula') || c.includes('matrícula') || c.includes('id'));
    const idxTelefone = cabecalho.findIndex((c) => c.includes('telefone') || c.includes('celular') || c.includes('contato'));

    const lista: RegistroImportado[] = [];

    for (let i = 1; i < linhas.length; i++) {
      const colunas = linhas[i].split(delimitador).map((c) => c.replace(/["']/g, '').trim());
      if (colunas.length === 0 || !colunas[0]) continue;

      const nome = idxNome >= 0 ? colunas[idxNome] : colunas[0];
      const cargo = idxCargo >= 0 ? colunas[idxCargo] : (colunas[1] || 'Operador Florestal');
      const unidadeBruta = (idxUnidade >= 0 ? colunas[idxUnidade] : (colunas[2] || 'Ribas')).toLowerCase();
      const matricula = idxMatricula >= 0 ? colunas[idxMatricula] : undefined;
      const telefone = idxTelefone >= 0 ? colunas[idxTelefone] : undefined;

      if (!nome) continue;

      const unidadeFinal: 'ribas' | 'agua_clara' =
        unidadeBruta.includes('agua') || unidadeBruta.includes('água') || unidadeBruta.includes('clara')
          ? 'agua_clara'
          : 'ribas';

      lista.push({
        nome,
        cargo: cargo || 'Operador Florestal',
        unidade: unidadeFinal,
        matricula: matricula || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
        telefone: telefone || '(67) 99999-0000',
      });
    }

    return lista;
  };

  const handleArquivoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErroImportacao(null);
    setSucessoMsg(null);
    setArquivoNome(file.name);

    const extensao = file.name.split('.').pop()?.toLowerCase();
    if (extensao !== 'csv' && extensao !== 'txt' && extensao !== 'tsv') {
      setErroImportacao('Por gentileza, salve a planilha como arquivo (.CSV separado por vírgula ou ponto-e-vírgula) para processamento instantâneo.');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const conteudo = event.target?.result as string;
        const registros = parsePlanilhaLinhas(conteudo);

        if (registros.length === 0) {
          setErroImportacao('Nenhum registro legível foi encontrado. Verifique se o arquivo possui colunas: Nome, Função/Cargo, Unidade.');
          setRegistrosPrevia([]);
          return;
        }

        setRegistrosPrevia(registros);
      } catch {
        setErroImportacao('Erro ao ler os dados do arquivo selecionado.');
      }
    };
    reader.onerror = () => {
      setErroImportacao('Não foi possível ler o arquivo.');
    };
    reader.readAsText(file);
  };

  const handleConfirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novos: ColaboradorCompleto[] = registrosPrevia.map((reg, idx) => ({
      id: `import-${Date.now()}-${idx}`,
      nome: reg.nome,
      cargo: reg.cargo,
      matricula: reg.matricula || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      telefone: reg.telefone || '(67) 99999-0000',
      foto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
      status: 'presente',
      regional: reg.unidade,
      equipeId: 'planilha',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Importado',
      veiculoPlaca: 'IMP-0000',
    }));

    setColaboradoresAdicionados((prev) => [...novos, ...prev]);
    onImportarColaboradores?.(novos);

    setSucessoMsg(`${novos.length} colaboradores foram importados com sucesso!`);
    setRegistrosPrevia([]);
    setArquivoNome('');
    setTimeout(() => {
      setModalImportAberto(false);
      setSucessoMsg(null);
    }, 1500);
  };

  const baixarModeloCSV = () => {
    const csvContent = 'Nome,Cargo,Unidade,Matricula,Telefone\n' +
      'Carlos Eduardo Santos,Mecânico Florestal,Ribas do Rio Pardo,MAT-1029,(67) 99841-2233\n' +
      'Lucas Gabriel Costa,Motorista de Apoio,Água Clara,MAT-1044,(67) 99755-4411\n' +
      'Pedro Henrique Silva,Ajudante Geral,Ribas do Rio Pardo,MAT-2033,(67) 99612-8822\n';

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Barra de Topo com Estatísticas e Botões de Ação */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Gerencie operadores, status diário, dados cadastrais e importação em lote
          </p>
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setModalImportAberto(true)}
            className="flex-1 sm:flex-none border-border/80 hover:bg-emerald-500/10 hover:border-emerald-500/40 text-xs font-semibold gap-1.5"
          >
            <UploadCloud className="w-4 h-4 text-emerald-400" />
            Subir Planilha Excel
          </Button>

          <Button
            size="sm"
            onClick={() => setModalNovoColaboradorAberto(true)}
            className="flex-1 sm:flex-none bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold gap-1.5 shadow-md"
          >
            <Plus className="w-4 h-4" />
            Novo Colaborador
          </Button>
        </div>
      </div>

      {/* Cards de Métricas de Presença */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <Card className="bg-card/40 border-border/60">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider">Total Geral</p>
              <p className="text-2xl font-bold tabular-nums text-foreground mt-0.5">{stats.total}</p>
            </div>
            <div className="w-9 h-9 rounded-xl bg-muted/60 border border-border/60 flex items-center justify-center text-muted-foreground">
              <Users className="w-4 h-4" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-card/40 border-emerald-500/20">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-[11px] font-medium text-emerald-400/80 uppercase tracking-wider">Presentes</p>
              <p className="text-2xl font-bold tabular-nums text-emerald-400 mt-0.5">{stats.presentes}</p>
            </div>
            <div className="w-9 h-9 rounded-xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center text-emerald-400">
              <UserCheck className="w-4 h-4" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-card/40 border-rose-500/20">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-[11px] font-medium text-rose-400/80 uppercase tracking-wider">Faltas</p>
              <p className="text-2xl font-bold tabular-nums text-rose-400 mt-0.5">{stats.faltas}</p>
            </div>
            <div className="w-9 h-9 rounded-xl bg-rose-500/10 border border-rose-500/25 flex items-center justify-center text-rose-400">
              <UserX className="w-4 h-4" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-card/40 border-amber-500/20">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-[11px] font-medium text-amber-400/80 uppercase tracking-wider">Substitutos</p>
              <p className="text-2xl font-bold tabular-nums text-amber-400 mt-0.5">{stats.substitutos}</p>
            </div>
            <div className="w-9 h-9 rounded-xl bg-amber-500/10 border border-amber-500/25 flex items-center justify-center text-amber-400">
              <RefreshCw className="w-4 h-4" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-3 rounded-2xl border border-border/60">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por nome, cargo, matrícula ou veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/50 border-border/60"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={filterRegional}
            onChange={(e) => setFilterRegional(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>

          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Status</option>
            <option value="presente">Presentes</option>
            <option value="falta">Faltas</option>
            <option value="substituto">Substitutos</option>
          </select>
        </div>
      </div>

      {/* Lista / Tabela de Colaboradores */}
      <div className="space-y-2">
        {colaboradoresFiltrados.length === 0 ? (
          <div className="py-12 text-center rounded-2xl border border-dashed border-border/70 bg-card/20">
            <Users className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-50" />
            <p className="text-sm font-semibold text-foreground">Nenhum colaborador encontrado</p>
            <p className="text-xs text-muted-foreground mt-1">
              Ajuste os filtros ou utilize o botão acima para adicionar ou importar via planilha.
            </p>
          </div>
        ) : (
          colaboradoresFiltrados.map((c) => {
            const isExpanded = expandedId === c.id;
            const statusInfo = statusConfig[c.status] || statusConfig.presente;

            return (
              <div
                key={c.id}
                className="rounded-2xl border border-border/60 bg-card/40 hover:bg-card/70 transition-all duration-200 overflow-hidden shadow-sm"
              >
                <div
                  className="p-3.5 sm:p-4 flex items-center justify-between gap-3 cursor-pointer select-none"
                  onClick={() => setExpandedId(isExpanded ? null : c.id)}
                >
                  <div className="flex items-center gap-3 min-w-0">
                    <img
                      src={c.foto}
                      alt={c.nome}
                      className="w-10 h-10 rounded-xl object-cover border border-border/60 shrink-0"
                      onError={(e) => {
                        (e.target as HTMLImageElement).src = 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150';
                      }}
                    />
                    <div className="min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-bold text-sm text-foreground truncate">{c.nome}</span>
                        <Badge variant="outline" className={cn('text-[10px] py-0 px-2 font-semibold', statusInfo.className)}>
                          {statusInfo.label}
                        </Badge>
                      </div>
                      <div className="flex items-center gap-3 text-xs text-muted-foreground mt-0.5 flex-wrap">
                        <span className="flex items-center gap-1">
                          <Briefcase className="w-3 h-3" />
                          {c.cargo}
                        </span>
                        <span className="flex items-center gap-1">
                          <MapPin className="w-3 h-3 text-emerald-400" />
                          {regionalLabel[c.regional]}
                        </span>
                        {c.veiculoPrefixo && (
                          <span className="text-[11px] bg-muted/60 px-2 py-0.5 rounded-md font-mono">
                            {c.veiculoPrefixo}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      className="p-1 rounded-lg text-muted-foreground hover:text-foreground"
                    >
                      {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                    </button>
                  </div>
                </div>

                {isExpanded && (
                  <div className="px-4 pb-4 pt-2 border-t border-border/40 bg-muted/10 grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs">
                    <div>
                      <span className="text-muted-foreground block text-[11px]">Matrícula / ID</span>
                      <span className="font-mono font-bold text-foreground">{c.matricula || 'N/A'}</span>
                    </div>

                    <div>
                      <span className="text-muted-foreground block text-[11px]">Telefone de Contato</span>
                      <span className="font-medium text-foreground flex items-center gap-1">
                        <Phone className="w-3 h-3 text-emerald-400" />
                        {c.telefone || 'Não cadastrado'}
                      </span>
                    </div>

                    <div>
                      <span className="text-muted-foreground block text-[11px]">Ações Rápidas de Presença</span>
                      <div className="flex items-center gap-1.5 mt-1">
                        <button
                          type="button"
                          onClick={() => onUpdateColaboradorStatus?.(c.id, 'presente')}
                          className="px-2 py-1 rounded-lg text-[10px] font-bold bg-emerald-500/20 text-emerald-300 hover:bg-emerald-500/30 transition-all"
                        >
                          Presente
                        </button>
                        <button
                          type="button"
                          onClick={() => onUpdateColaboradorStatus?.(c.id, 'falta', 'Falta Injustificada')}
                          className="px-2 py-1 rounded-lg text-[10px] font-bold bg-rose-500/20 text-rose-300 hover:bg-rose-500/30 transition-all"
                        >
                          Falta
                        </button>
                        <button
                          type="button"
                          onClick={() => onUpdateColaboradorStatus?.(c.id, 'substituto')}
                          className="px-2 py-1 rounded-lg text-[10px] font-bold bg-amber-500/20 text-amber-300 hover:bg-amber-500/30 transition-all"
                        >
                          Substituto
                        </button>
                      </div>
                    </div>

                    {c.motivoFalta && (
                      <div className="sm:col-span-3 p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-300">
                        <span className="font-bold">Motivo do Registro: </span>
                        {c.motivoFalta} {c.observacao ? `— Obs: ${c.observacao}` : ''}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      {/* Modal: Subir Planilha Excel / CSV */}
      {modalImportAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150">
          <div className="relative w-full max-w-xl bg-card border border-border/80 rounded-3xl shadow-2xl p-6 space-y-4">
            <div className="flex items-center justify-between border-b border-border/60 pb-3">
              <div className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
                  <FileSpreadsheet className="w-4 h-4" />
                </div>
                <div>
                  <h3 className="font-bold text-base text-foreground">Importar Planilha de Colaboradores</h3>
                  <p className="text-xs text-muted-foreground">Leitura rápida dos campos: Nome, Função (Cargo) e Unidade</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalImportAberto(false)}
                className="p-1 rounded-lg text-muted-foreground hover:text-foreground"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-3">
              <div
                onClick={() => fileInputRef.current?.click()}
                className="border-2 border-dashed border-border/80 hover:border-emerald-500/50 rounded-2xl p-6 text-center cursor-pointer transition-all bg-muted/5 hover:bg-emerald-500/5"
              >
                <UploadCloud className="w-10 h-10 text-emerald-400 mx-auto mb-2" />
                <p className="text-sm font-semibold text-foreground">
                  {arquivoNome || 'Clique para selecionar o arquivo .CSV ou arraste para cá'}
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  Recomendado: exportar planilha como CSV (delimitado por vírgula ou ponto-e-vírgula)
                </p>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".csv,.txt,.tsv"
                  onChange={handleArquivoUpload}
                  className="hidden"
                />
              </div>

              <div className="flex items-center justify-between">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={baixarModeloCSV}
                  className="text-xs text-muted-foreground hover:text-foreground gap-1.5"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar Modelo de Planilha (.csv)
                </Button>
              </div>

              {erroImportacao && (
                <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/25 text-rose-300 text-xs flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{erroImportacao}</span>
                </div>
              )}

              {sucessoMsg && (
                <div className="p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/25 text-emerald-300 text-xs flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 shrink-0" />
                  <span>{sucessoMsg}</span>
                </div>
              )}

              {registrosPrevia.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-xs">
                    <span className="font-semibold text-foreground">
                      Pré-visualização ({registrosPrevia.length} colaboradores identificados)
                    </span>
                    <span className="text-muted-foreground text-[11px]">Pronto para importar</span>
                  </div>

                  <div className="max-h-48 overflow-y-auto rounded-xl border border-border/60 bg-muted/20 p-2 space-y-1 text-xs">
                    {registrosPrevia.slice(0, 10).map((r, i) => (
                      <div key={i} className="flex items-center justify-between p-1.5 rounded-lg bg-card/60">
                        <div>
                          <p className="font-bold text-foreground text-xs">{r.nome}</p>
                          <p className="text-[11px] text-muted-foreground">{r.cargo}</p>
                        </div>
                        <Badge variant="outline" className="text-[10px] border-emerald-500/30 text-emerald-400">
                          {regionalLabel[r.unidade]}
                        </Badge>
                      </div>
                    ))}
                    {registrosPrevia.length > 10 && (
                      <p className="text-center text-[11px] text-muted-foreground py-1">
                        + {registrosPrevia.length - 10} outros registros...
                      </p>
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="flex items-center justify-end gap-2 pt-3 border-t border-border/60">
              <Button variant="outline" size="sm" onClick={() => setModalImportAberto(false)}>
                Cancelar
              </Button>
              <Button
                size="sm"
                onClick={handleConfirmarImportacao}
                disabled={registrosPrevia.length === 0}
                className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold"
              >
                Confirmar Importação
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Modal: Cadastro Manual de Novo Colaborador */}
      {modalNovoColaboradorAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150">
          <div className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl p-6 space-y-4">
            <div className="flex items-center justify-between border-b border-border/60 pb-3">
              <div className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
                  <Users className="w-4 h-4" />
                </div>
                <div>
                  <h3 className="font-bold text-base text-foreground">Novo Colaborador</h3>
                  <p className="text-xs text-muted-foreground">Cadastre um profissional no sistema</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalNovoColaboradorAberto(false)}
                className="p-1 rounded-lg text-muted-foreground hover:text-foreground"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCriarColaborador} className="space-y-3.5">
              {formErro && (
                <div className="p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-300 text-xs">
                  {formErro}
                </div>
              )}

              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">Nome Completo *</label>
                <Input
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  className="h-9 text-xs"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground block mb-1">Função / Cargo *</label>
                  <Input
                    placeholder="Ex: Operador Florestal"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    className="h-9 text-xs"
                    required
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-muted-foreground block mb-1">Matrícula</label>
                  <Input
                    placeholder="Ex: MAT-1088"
                    value={novaMatricula}
                    onChange={(e) => setNovaMatricula(e.target.value)}
                    className="h-9 text-xs"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground block mb-1">Telefone</label>
                  <Input
                    placeholder="Ex: (67) 99999-0000"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                    className="h-9 text-xs"
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-muted-foreground block mb-1">Unidade Operacional</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as any)}
                    className="w-full h-9 px-3 rounded-xl border border-input bg-card/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-border/60">
                <Button type="button" variant="outline" size="sm" onClick={() => setModalNovoColaboradorAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" size="sm" className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold">
                  Salvar Colaborador
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

