                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    placeholder="Ex: Operador Florestal"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-muted-foreground mb-1">Matrícula</label>
                  <Input
                    value={novaMatricula}
                    onChange={(e) => setNovaMatricula(e.target.value)}
