import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Camera,
  Trash2,
  Building2,
  Briefcase,
  FileCheck,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

interface RegistroImportado {
  nome: string;
  cargo: string;
  unidade: 'ribas' | 'agua_clara';
  matricula?: string;
  telefone?: string;
}

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [modalNovoColaboradorAberto, setModalNovoColaboradorAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novaMatricula, setNovaMatricula] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novoStatus, setNovoStatus] = useState<StatusPresenca>('presente');
  const [formErro, setFormErro] = useState<string | null>(null);
  const fotoInputRef = useRef<HTMLInputElement>(null);

  const [modalImportAberto, setModalImportAberto] = useState(false);
  const [arquivoNome, setArquivoNome] = useState('');
  const [registrosPrevia, setRegistrosPrevia] = useState<RegistroImportado[]>([]);
  const [erroImportacao, setErroImportacao] = useState<string | null>(null);
  const [sucessoMsg, setSucessoMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const stats = useMemo(() => {
    const presentes = todosColaboradores.filter((c) => c.status === 'presente').length;
    const faltas = todosColaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = todosColaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: todosColaboradores.length };
  }, [todosColaboradores]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setFormErro('Por favor, selecione um arquivo de imagem válido (PNG, JPG, JPEG, WEBP).');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      setFormErro('A imagem selecionada deve ter no máximo 5MB.');
      return;
    }

    setFormErro(null);
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        setNovaFoto(reader.result);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCriarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) {
      setFormErro('O nome do colaborador é obrigatório.');
      return;
    }
    if (!novoCargo.trim()) {
      setFormErro('A função/cargo do colaborador é obrigatória.');
      return;
    }

    const novoColab: ColaboradorCompleto = {
      id: `manual-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim(),
      matricula: novaMatricula.trim() || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      foto: novaFoto || '',
      status: novoStatus,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
    };

    setColaboradoresAdicionados((prev) => [novoColab, ...prev]);
    if (onAdicionarColaborador) {
      onAdicionarColaborador(novoColab);
    }

    setNovoNome('');
    setNovoCargo('');
    setNovaMatricula('');
    setNovoTelefone('');
    setNovaFoto('');
    setFormErro(null);
    setModalNovoColaboradorAberto(false);
  };

  const processarLinhasCSV = (conteudo: string) => {
    const linhas = conteudo
      .split(/\r?\n/)
      .map((l) => l.trim())
      .filter((l) => l.length > 0);

    if (linhas.length <= 1) {
      throw new Error('O arquivo precisa conter ao menos uma linha de cabeçalho e uma linha de dados.');
    }

    const separador = linhas[0].includes(';') ? ';' : linhas[0].includes(',') ? ',' : '\t';
    const cabecalho = linhas[0].split(separador).map((c) => c.trim().toLowerCase());

    const idxNome = cabecalho.findIndex((c) => c.includes('nome') || c.includes('colaborador'));
    const idxCargo = cabecalho.findIndex((c) => c.includes('cargo') || c.includes('funcao') || c.includes('função'));
    const idxUnidade = cabecalho.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('polo'));
    const idxMatricula = cabecalho.findIndex((c) => c.includes('matricula') || c.includes('matrícula') || c.includes('chapa'));
    const idxTelefone = cabecalho.findIndex((c) => c.includes('telefone') || c.includes('celular') || c.includes('contato'));

    if (idxNome === -1 || idxCargo === -1) {
      throw new Error('O arquivo precisa ter colunas identificáveis com "Nome" e "Função/Cargo".');
    }

    const registros: RegistroImportado[] = [];

    for (let i = 1; i < linhas.length; i++) {
      const colunas = linhas[i].split(separador).map((c) => c.trim().replace(/^["']|["']$/g, ''));
      if (!colunas[idxNome]) continue;

      const nome = colunas[idxNome];
      const cargo = colunas[idxCargo] || 'Operador Florestal';
      const rawUnidade = idxUnidade !== -1 && colunas[idxUnidade] ? colunas[idxUnidade].toLowerCase() : 'ribas';
      const unidade: 'ribas' | 'agua_clara' = rawUnidade.includes('agua') || rawUnidade.includes('clara') ? 'agua_clara' : 'ribas';

      registros.push({
        nome,
        cargo,
        unidade,
        matricula: idxMatricula !== -1 ? colunas[idxMatricula] : undefined,
        telefone: idxTelefone !== -1 ? colunas[idxTelefone] : undefined,
      });
    }

    return registros;
  };

  const handleArquivoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setArquivoNome(file.name);
    setErroImportacao(null);
    setSucessoMsg(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const conteudo = event.target?.result as string;
        const registros = processarLinhasCSV(conteudo);
        setRegistrosPrevia(registros);
      } catch (err: any) {
        setErroImportacao(err.message || 'Erro ao ler o arquivo.');
        setRegistrosPrevia([]);
      }
    };
    reader.onerror = () => {
      setErroImportacao('Falha ao abrir o arquivo selecionado.');
    };
    reader.readAsText(file, 'UTF-8');
  };

  const confirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novos: ColaboradorCompleto[] = registrosPrevia.map((reg, idx) => ({
      id: `imp-${Date.now()}-${idx}`,
      nome: reg.nome,
      cargo: reg.cargo,
      matricula: reg.matricula || `IMP-${Math.floor(1000 + Math.random() * 9000)}`,
      foto: '',
      telefone: reg.telefone || '(67) 99999-0000',
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: reg.unidade,
    }));

    setColaboradoresAdicionados((prev) => [...novos, ...prev]);
    if (onImportarColaboradores) {
      onImportarColaboradores(novos);
    }

    setSucessoMsg(`${novos.length} colaboradores importados com sucesso!`);
    setRegistrosPrevia([]);
    setArquivoNome('');
    if (fileInputRef.current) fileInputRef.current.value = '';

    setTimeout(() => {
      setModalImportAberto(false);
      setSucessoMsg(null);
    }, 1500);
  };

  const baixarModeloPlanilha = () => {
    const csvContent = 'Nome;Cargo;Unidade;Matrícula;Telefone\n' +
      'Carlos Oliveira;Operador de Motosserra;Ribas do Rio Pardo;MAT-4011;(67) 99123-4567\n' +
      'Lucas Gabriel;Motorista de Apoio;Água Clara;MAT-4012;(67) 99234-5678\n' +
      'Roberto Alves;Ajudante Geral;Ribas do Rio Pardo;MAT-4013;(67) 99345-6789\n';

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Cabeçalho */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Visualize as fotos de cada colaborador, status de presença e alocações na frota
          </p>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <Button
            size="sm"
            variant="outline"
            onClick={() => setModalImportAberto(true)}
            className="border-emerald-500/40 text-emerald-400 hover:bg-emerald-500/10 text-xs font-semibold gap-1.5"
          >
            <UploadCloud className="w-4 h-4" />
            Subir Planilha
          </Button>

          <Button
            size="sm"
            onClick={() => setModalNovoColaboradorAberto(true)}
            className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold gap-1.5 shadow-md"
          >
            <Plus className="w-4 h-4" />
            Novo Colaborador
          </Button>
        </div>
      </div>

      {/* Cards de Métricas */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="p-3.5 rounded-2xl border border-border/60 bg-card/40 flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
            <Users className="w-4 h-4" />
          </div>
          <div>
            <p className="text-[11px] text-muted-foreground font-medium">Efetivo Total</p>
            <p className="text-xl font-extrabold text-foreground tabular-nums">{stats.total}</p>
          </div>
        </div>

        <div className="p-3.5 rounded-2xl border border-emerald-500/20 bg-emerald-500/5 flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
            <UserCheck className="w-4 h-4" />
          </div>
          <div>
            <p className="text-[11px] text-emerald-300 font-medium">Presentes</p>
            <p className="text-xl font-extrabold text-emerald-400 tabular-nums">{stats.presentes}</p>
          </div>
        </div>

        <div className="p-3.5 rounded-2xl border border-rose-500/20 bg-rose-500/5 flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-rose-500/15 border border-rose-500/30 flex items-center justify-center text-rose-400">
            <UserX className="w-4 h-4" />
          </div>
          <div>
            <p className="text-[11px] text-rose-300 font-medium">Faltas</p>
            <p className="text-xl font-extrabold text-rose-400 tabular-nums">{stats.faltas}</p>
          </div>
        </div>

        <div className="p-3.5 rounded-2xl border border-amber-500/20 bg-amber-500/5 flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-amber-500/15 border border-amber-500/30 flex items-center justify-center text-amber-400">
            <Briefcase className="w-4 h-4" />
          </div>
          <div>
            <p className="text-[11px] text-amber-300 font-medium">Substitutos</p>
            <p className="text-xl font-extrabold text-amber-400 tabular-nums">{stats.substitutos}</p>
          </div>
        </div>
      </div>

      {/* Filtros */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-3 rounded-2xl border border-border/60">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por nome, função, matrícula ou veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/50 border-border/60"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Status</option>
            <option value="presente">Apenas Presentes</option>
            <option value="falta">Apenas Faltas</option>
            <option value="substituto">Apenas Substitutos</option>
          </select>

          <select
            value={filterRegional}
            onChange={(e) => setFilterRegional(e.target.value as any)}
            className="h-9 px-3 rounded-xl border border-border/60 bg-background/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>
        </div>
      </div>

      {/* Lista com Foto em Cada Colaborador */}
      <div className="space-y-2.5">
        {colaboradoresFiltrados.length === 0 ? (
          <div className="py-12 text-center rounded-2xl border border-dashed border-border/60 bg-card/20">
            <Users className="w-8 h-8 text-muted-foreground mx-auto mb-2 opacity-50" />
            <p className="text-sm font-semibold text-foreground">Nenhum colaborador encontrado</p>
            <p className="text-xs text-muted-foreground mt-1">Ajuste os filtros ou adicione novos registros.</p>
          </div>
        ) : (
          colaboradoresFiltrados.map((c) => {
            const isExpanded = expandedId === c.id;
            const st = statusConfig[c.status] || statusConfig.presente;

            return (
              <Card
                key={c.id}
                className={cn(
                  'border transition-all duration-150 overflow-hidden',
                  c.status === 'falta'
                    ? 'border-rose-500/30 bg-rose-500/5'
                    : c.status === 'substituto'
                    ? 'border-amber-500/30 bg-amber-500/5'
                    : 'border-border/60 bg-card/50 hover:border-emerald-500/30'
                )}
              >
                <div
                  className="p-3.5 flex items-center justify-between gap-3 cursor-pointer select-none"
                  onClick={() => setExpandedId(isExpanded ? null : c.id)}
                >
                  <div className="flex items-center gap-3 min-w-0">
                    {/* Foto do Colaborador em destaque */}
                    <div className="relative shrink-0">
                      {c.foto ? (
                        <img
                          src={c.foto}
                          alt={c.nome}
                          className="w-11 h-11 rounded-full object-cover border-2 border-emerald-500/30 shadow-md ring-1 ring-border/50"
                          onError={(e) => {
                            (e.target as HTMLImageElement).style.display = 'none';
                            const fallback = (e.target as HTMLElement).nextElementSibling;
                            if (fallback) fallback.classList.remove('hidden');
                          }}
                        />
                      ) : null}
                      <div
                        className={cn(
                          'w-11 h-11 rounded-full bg-muted/90 border-2 border-border/80 flex items-center justify-center text-xs font-bold text-foreground shadow-sm ring-1 ring-border/40',
                          c.foto ? 'hidden' : 'flex'
                        )}
                      >
                        {getIniciais(c.nome)}
                      </div>
                      <span
                        className={cn(
                          'absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full border-2 border-card',
                          c.status === 'presente'
                            ? 'bg-emerald-400'
                            : c.status === 'falta'
                            ? 'bg-rose-500'
                            : 'bg-amber-400'
                        )}
                      />
                    </div>

                    <div className="min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-bold text-sm text-foreground truncate">{c.nome}</span>
                        {c.matricula && (
                          <span className="text-[10px] font-mono text-muted-foreground px-1.5 py-0.2 rounded bg-muted/60 border border-border/40">
                            {c.matricula}
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground truncate">{c.cargo}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3 shrink-0">
                    <Badge variant="outline" className={cn('text-xs font-semibold px-2.5 py-0.5', st.className)}>
                      {st.label}
                    </Badge>

                    <div className="hidden md:flex flex-col items-end text-xs text-muted-foreground">
                      <span className="font-medium text-foreground">{c.veiculoPrefixo}</span>
                      <span className="text-[10px]">{regionalLabel[c.regional] || c.regional}</span>
                    </div>

                    {isExpanded ? (
                      <ChevronUp className="w-4 h-4 text-muted-foreground" />
                    ) : (
                      <ChevronDown className="w-4 h-4 text-muted-foreground" />
                    )}
                  </div>
                </div>

                {/* Detalhes Expandidos */}
                {isExpanded && (
                  <div className="px-4 pb-4 pt-2 border-t border-border/40 bg-muted/20 space-y-3 animate-in fade-in-50 duration-150">
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs">
                      <div>
                        <span className="text-muted-foreground block text-[11px]">Unidade Operacional:</span>
                        <span className="font-semibold text-foreground flex items-center gap-1 mt-0.5">
                          <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                          {regionalLabel[c.regional]}
                        </span>
                      </div>

                      <div>
                        <span className="text-muted-foreground block text-[11px]">Contato:</span>
                        <span className="font-semibold text-foreground flex items-center gap-1 mt-0.5">
                          <Phone className="w-3.5 h-3.5 text-muted-foreground" />
                          {c.telefone || 'Não informado'}
                        </span>
                      </div>

                      <div>
                        <span className="text-muted-foreground block text-[11px]">Lotação / Veículo:</span>
                        <span className="font-semibold text-foreground mt-0.5 block">
                          {c.veiculoPrefixo} ({c.veiculoPlaca})
                        </span>
                      </div>
                    </div>

                    {c.status === 'falta' && (
                      <div className="p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/25 text-xs text-rose-300">
                        <span className="font-bold">Motivo do Desfalque:</span>{' '}
                        {c.motivoFalta || 'Não especificado'}
                        {c.observacao && <p className="mt-1 text-rose-200/90 text-[11px]">{c.observacao}</p>}
                      </div>
                    )}

                    {c.status === 'substituto' && c.substitutoNome && (
                      <div className="p-2.5 rounded-xl bg-amber-500/10 border border-amber-500/25 text-xs text-amber-300">
                        <span className="font-bold">Substituído por:</span> {c.substitutoNome}
                      </div>
                    )}
                  </div>
                )}
              </Card>
            );
          })
        )}
      </div>

      {/* Modal Adicionar Novo Colaborador */}
      {modalNovoColaboradorAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setModalNovoColaboradorAberto(false)}
        >
          <div
            className="w-full max-w-lg bg-card border border-border rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="px-6 py-4 border-b border-border/80 flex items-center justify-between">
              <div className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                  <Plus className="w-4 h-4" />
                </div>
                <div>
                  <h3 className="text-sm font-bold text-foreground">Novo Colaborador</h3>
                  <p className="text-[11px] text-muted-foreground">Cadastre foto, função e lotação</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalNovoColaboradorAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleCriarColaborador} className="p-6 space-y-4">
              {formErro && (
                <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{formErro}</span>
                </div>
              )}

              {/* Upload da Foto do Colaborador */}
              <div className="flex items-center gap-4 p-3 rounded-2xl border border-border/60 bg-muted/20">
                <div className="relative shrink-0">
                  {novaFoto ? (
                    <img
                      src={novaFoto}
                      alt="Prévia da Foto"
                      className="w-16 h-16 rounded-full object-cover border-2 border-emerald-500/50 shadow-md"
                    />
                  ) : (
                    <div className="w-16 h-16 rounded-full bg-card border-2 border-dashed border-border/80 flex items-center justify-center text-muted-foreground">
                      <Camera className="w-6 h-6" />
                    </div>
                  )}
                </div>

                <div className="space-y-1.5 flex-1">
                  <p className="text-xs font-semibold text-foreground">Foto do Perfil</p>
                  <p className="text-[11px] text-muted-foreground">PNG, JPG ou WEBP até 5MB</p>
                  <div className="flex items-center gap-2">
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      onClick={() => fotoInputRef.current?.click()}
                      className="h-7 text-xs border-emerald-500/30 text-emerald-400"
                    >
                      Escolher Foto
                    </Button>
                    {novaFoto && (
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        onClick={() => setNovaFoto('')}
                        className="h-7 text-xs text-rose-400 hover:text-rose-300"
                      >
                        Remover
                      </Button>
                    )}
                  </div>
                  <input
                    ref={fotoInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleFotoUpload}
                    className="hidden"
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
                  Nome Completo *
                </label>
                <Input
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
                    Função / Cargo *
                  </label>
                  <Input
                    placeholder="Ex: Operador de Máquina"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    required
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
                    Matrícula
                  </label>
                  <Input
                    placeholder="Ex: MAT-1029"
                    value={novaMatricula}
                    onChange={(e) => setNovaMatricula(e.target.value)}
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
                    Telefone
                  </label>
                  <Input
                    placeholder="(67) 99999-9999"
                    value={novoTelefone}
                    onChange={(e) => setNovoTelefone(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
                    Unidade
                  </label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as any)}
                    className="h-10 w-full px-3 rounded-xl border border-input bg-card/50 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>
              </div>

              <div className="flex items-center justify-end gap-3 pt-4 border-t border-border/80">
                <Button type="button" variant="outline" onClick={() => setModalNovoColaboradorAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold">
                  Cadastrar Colaborador
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal de Importação de Planilha */}
      {modalImportAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setModalImportAberto(false)}
        >
          <div
            className="w-full max-w-xl bg-card border border-border rounded-3xl shadow-2xl overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="px-6 py-4 border-b border-border/80 flex items-center justify-between">
              <div className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                  <UploadCloud className="w-4 h-4" />
                </div>
                <div>
                  <h3 className="text-sm font-bold text-foreground">Importar Colaboradores via Planilha</h3>
                  <p className="text-[11px] text-muted-foreground">Envie arquivos CSV ou Excel exportado</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalImportAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div className="p-4 rounded-2xl border border-dashed border-border/80 bg-muted/20 text-center space-y-3">
                <FileSpreadsheet className="w-8 h-8 text-emerald-400 mx-auto" />
                <div>
                  <p className="text-xs font-semibold text-foreground">Selecione seu arquivo CSV ou tabela</p>
                  <p className="text-[11px] text-muted-foreground mt-0.5">Colunas: Nome, Cargo/Função, Unidade</p>
                </div>
                <div className="flex items-center justify-center gap-2">
                  <Button
                    type="button"
                    size="sm"
                    onClick={() => fileInputRef.current?.click()}
                    className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold"
                  >
                    Selecionar Arquivo
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    variant="outline"
                    onClick={baixarModeloPlanilha}
                    className="text-xs border-border/80 gap-1.5"
                  >
                    <Download className="w-3.5 h-3.5" />
                    Baixar Modelo
                  </Button>
                </div>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".csv,.txt"
                  onChange={handleArquivoChange}
                  className="hidden"
                />
              </div>

              {arquivoNome && (
                <div className="p-3 rounded-xl bg-card border border-border/80 flex items-center justify-between text-xs">
                  <span className="font-semibold text-foreground truncate">{arquivoNome}</span>
                  <span className="text-emerald-400 font-bold">{registrosPrevia.length} linhas lidas</span>
                </div>
              )}

              {erroImportacao && (
                <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{erroImportacao}</span>
                </div>
              )}

              {sucessoMsg && (
                <div className="p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 text-xs flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 shrink-0" />
                  <span>{sucessoMsg}</span>
                </div>
              )}

              <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/80">
                <Button type="button" variant="outline" onClick={() => setModalImportAberto(false)}>
                  Cancelar
                </Button>
                <Button
                  type="button"
                  disabled={registrosPrevia.length === 0}
                  onClick={confirmarImportacao}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold"
                >
                  Confirmar Importação
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

