import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Camera,
  Trash2,
  Building2,
  Briefcase,
  FileCheck,
  Eye,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novaMatricula, setNovaMatricula] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const fotoInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: novaMatricula.trim(),
      foto: novaFoto,
      telefone: novoTelefone.trim(),
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    if (onAdicionarColaborador) onAdicionarColaborador(novo);

    setNovoNome('');
    setNovoCargo('');
    setNovaMatricula('');
    setNovoTelefone('');
    setNovaFoto('');
    setModalNovoAberto(false);
  };

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores & Fotos
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Identificação facial, matrículas, frentes de trabalho e postos operacionais
          </p>
        </div>

        <Button
          size="sm"
          onClick={() => setModalNovoAberto(true)}
          className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold gap-2 rounded-xl shadow-md"
        >
          <Plus className="w-4 h-4" />
          Novo Colaborador com Foto
        </Button>
      </div>

      {/* Filtros */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/70 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por nome, função, matrícula ou veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-10 h-10 text-xs bg-background/50 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
            className="h-10 px-3 rounded-xl border border-border/60 bg-background/60 text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Status</option>
            <option value="presente">Apenas Presentes</option>
            <option value="falta">Apenas Faltas</option>
            <option value="substituto">Apenas Substitutos</option>
          </select>

          <select
            value={filterRegional}
            onChange={(e) => setFilterRegional(e.target.value as any)}
            className="h-10 px-3 rounded-xl border border-border/60 bg-background/60 text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>
        </div>
      </div>

      {/* Grid com Ênfase Elevada nas Fotos dos Colaboradores */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {colaboradoresFiltrados.map((c) => {
          const isPresente = c.status === 'presente';
          const isFalta = c.status === 'falta';

          return (
            <Card
              key={c.id}
              className={cn(
                'group relative rounded-3xl border transition-all duration-300 overflow-hidden bg-card/80 hover:bg-card hover:shadow-xl',
                isFalta ? 'border-rose-500/30' : 'border-border/70'
              )}
            >
              <CardContent className="p-5 flex items-center gap-4">
                {/* Avatar / Foto Grande de Alto Destaque */}
                <div
                  className="relative shrink-0 cursor-pointer"
                  onClick={() => c.foto && setFotoModalAberta({ url: c.foto, nome: c.nome, cargo: c.cargo })}
                >
                  <div
                    className={cn(
                      'w-18 h-18 sm:w-20 sm:h-20 rounded-2xl overflow-hidden border-2 ring-4 shadow-xl flex items-center justify-center transition-all duration-300 group-hover:scale-105',
                      isPresente
                        ? 'ring-emerald-500/80 border-emerald-500/50 shadow-emerald-500/10'
                        : isFalta
                        ? 'ring-rose-500/80 border-rose-500/50 shadow-rose-500/10'
                        : 'ring-amber-500/80 border-amber-500/50 shadow-amber-500/10'
                    )}
                  >
                    {c.foto ? (
                      <img
                        src={c.foto}
                        alt={c.nome}
                        className="w-full h-full object-cover object-center"
                        onError={(e) => {
                          (e.target as HTMLImageElement).style.display = 'none';
                        }}
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-emerald-950 to-muted text-emerald-300 font-black text-xl">
                        {getIniciais(c.nome)}
                      </div>
                    )}
                  </div>

                  {c.foto && (
                    <span className="absolute bottom-1 right-1 p-1 rounded-lg bg-black/60 text-white opacity-0 group-hover:opacity-100 transition-opacity">
                      <Eye className="w-3 h-3" />
                    </span>
                  )}
                </div>

                {/* Informações Pessoais e Operacionais */}
                <div className="min-w-0 flex-1 space-y-1">
                  <div className="flex items-center justify-between gap-1">
                    <Badge
                      variant="outline"
                      className={cn(
                        'text-[10px] py-0 px-2 rounded-full font-bold',
                        statusConfig[c.status]?.className || statusConfig.presente.className
                      )}
                    >
                      {statusConfig[c.status]?.label || 'Presente'}
                    </Badge>
                  </div>

                  <h4 className="font-extrabold text-base text-foreground truncate tracking-tight group-hover:text-emerald-400 transition-colors">
                    {c.nome}
                  </h4>

                  <p className="text-xs text-muted-foreground font-semibold truncate flex items-center gap-1.5">
                    <Briefcase className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                    {c.cargo}
                  </p>

                  <div className="pt-1 flex flex-col gap-0.5 text-[11px] text-muted-foreground">
                    <span className="truncate">
                      Veículo: <strong className="text-foreground">{c.veiculoPrefixo}</strong>
                    </span>
                    <span className="flex items-center gap-1">
                      <MapPin className="w-3 h-3 text-muted-foreground" />
                      {regionalLabel[c.regional] || 'Ribas'}
                    </span>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Modal de Zoom da Foto do Colaborador */}
      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/90 backdrop-blur-md animate-in fade-in"
          onClick={() => setFotoModalAberta(null)}
        >
          <div
            className="relative max-w-sm w-full bg-card border border-border rounded-3xl p-6 shadow-2xl space-y-4 text-center"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => setFotoModalAberta(null)}
              className="absolute top-4 right-4 p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted"
            >
              <X className="w-5 h-5" />
            </button>
            <div className="w-48 h-48 mx-auto rounded-3xl overflow-hidden border-4 border-emerald-500/50 shadow-2xl ring-4 ring-emerald-500/20">
              <img src={fotoModalAberta.url} alt={fotoModalAberta.nome} className="w-full h-full object-cover" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-foreground">{fotoModalAberta.nome}</h3>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
          </div>
        </div>
      )}

      {/* Modal para Adicionar Colaborador com Foto */}
      {modalNovoAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setModalNovoAberto(false)}
        >
          <div
            className="relative w-full max-w-md bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
              <div className="flex items-center gap-2">
                <Users className="w-4 h-4 text-emerald-400" />
                <h3 className="font-bold text-sm text-foreground">Novo Colaborador com Foto</h3>
              </div>
              <button
                onClick={() => setModalNovoAberto(false)}
                className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="p-6 space-y-4">
              {/* Seção de Upload e Prévia da Foto */}
              <div className="flex flex-col items-center justify-center gap-3 p-4 rounded-2xl border border-dashed border-border/80 bg-muted/20">
                <div className="relative w-24 h-24 rounded-2xl overflow-hidden border-2 border-emerald-500 ring-4 ring-emerald-500/20 bg-muted flex items-center justify-center shadow-lg">
                  {novaFoto ? (
                    <img src={novaFoto} alt="Prévia" className="w-full h-full object-cover" />
                  ) : (
                    <Camera className="w-8 h-8 text-muted-foreground/60" />
                  )}
                </div>
                <input
                  type="file"
                  accept="image/*"
                  ref={fotoInputRef}
                  onChange={handleFotoUpload}
                  className="hidden"
                />
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => fotoInputRef.current?.click()}
                  className="rounded-xl text-xs gap-1.5"
                >
                  <Camera className="w-3.5 h-3.5 text-emerald-400" />
                  {novaFoto ? 'Trocar Foto' : 'Carregar Foto do Colaborador'}
                </Button>
              </div>

              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-1">
                  Nome Completo
                </label>
                <Input
                  placeholder="Ex: Carlos Eduardo de Oliveira"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-1">
                    Cargo / Função
                  </label>
                  <Input
                    placeholder="Ex: Mecânico Florestal"
                    value={novoCargo}
                    onChange={(e) => setNovoCargo(e.target.value)}
                    required
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-1">
                    Matrícula
                  </label>
                  <Input
                    placeholder="Ex: 88412"
                    value={novaMatricula}
                    onChange={(e) => setNovaMatricula(e.target.value)}
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-1">
                  Telefone / WhatsApp
                </label>
                <Input
                  placeholder="Ex: (67) 99884-2211"
                  value={novoTelefone}
                  onChange={(e) => setNovoTelefone(e.target.value)}
                />
              </div>

              <div className="flex items-center justify-end gap-3 pt-4 border-t border-border/60">
                <Button type="button" variant="outline" onClick={() => setModalNovoAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold">
                  Cadastrar Colaborador
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

