import React, { useState } from 'react';
import {
  Car,
  User,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Edit3,
  Phone,
  ShieldAlert,
  UserCheck,
  Building2,
  Calendar,
  Layers,
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate,
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [modalAberto, setModalAberto] = useState(false);
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoAtivoPrefixo, setVeiculoAtivoPrefixo] = useState<string>('');

  const abrirModalColaborador = (colab: Colaborador, veiculoPrefixo: string) => {
    setColaboradorSelecionado(colab);
    setVeiculoAtivoPrefixo(veiculoPrefixo);
    setModalAberto(true);
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    const matchBusca =
      !busca ||
      (v.prefixo || '').toLowerCase().includes(busca.toLowerCase()) ||
      (v.placa || '').toLowerCase().includes(busca.toLowerCase()) ||
      (v.equipe1Codigo || '').toLowerCase().includes(busca.toLowerCase()) ||
      (v.equipe2Codigo || '').toLowerCase().includes(busca.toLowerCase()) ||
      [v.assentos?.motorista?.nome, v.assentos?.frenteDir?.nome, v.assentos?.trasEsq?.nome, v.assentos?.trasDir?.nome].some(
        (n) => (n || '').toLowerCase().includes(busca.toLowerCase())
      );

    const temFalta = [
      v.assentos?.motorista?.status,
      v.assentos?.frenteDir?.status,
      v.assentos?.trasEsq?.status,
      v.assentos?.trasDir?.status,
    ].includes('falta');

    if (filtroStatus === 'completos') return matchRegional && matchBusca && !temFalta;
    if (filtroStatus === 'incompletos') return matchRegional && matchBusca && temFalta;
    return matchRegional && matchBusca;
  });

  const renderAssentoFoto = (colab?: Colaborador, labelPosicao = '', veiculoPrefixo = '') => {
    if (!colab) {
      return (
        <div className="flex items-center gap-3.5 p-3 rounded-2xl border border-dashed border-border/60 bg-muted/20">
          <div className="w-13 h-13 rounded-2xl bg-muted/40 flex items-center justify-center border border-border/60 text-muted-foreground/60 shrink-0">
            <User className="w-6 h-6" />
          </div>
          <div className="min-w-0 flex-1">
            <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider">{labelPosicao}</span>
            <p className="text-xs text-muted-foreground/60 font-medium">Posto Vago</p>
          </div>
        </div>
      );
    }

    const isPresente = colab.status === 'presente';
    const isFalta = colab.status === 'falta';
    const isSubstituto = colab.status === 'substituto';

    let statusRing = 'ring-emerald-500/80 border-emerald-500/50';
    let statusBg = 'bg-card/70 hover:bg-card border-border/70';
    let badgeText = 'Presente';
    let badgeClass = 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30';

    if (isFalta) {
      statusRing = 'ring-rose-500 border-rose-500';
      statusBg = 'bg-rose-500/5 hover:bg-rose-500/10 border-rose-500/30';
      badgeText = colab.motivoFalta || 'Falta';
      badgeClass = 'bg-rose-500/20 text-rose-400 border-rose-500/30 font-bold';
    } else if (isSubstituto) {
      statusRing = 'ring-amber-500 border-amber-500';
      statusBg = 'bg-amber-500/5 hover:bg-amber-500/10 border-amber-500/30';
      badgeText = 'Substituto';
      badgeClass = 'bg-amber-500/20 text-amber-400 border-amber-500/30 font-bold';
    }

    return (
      <div
        onClick={() => abrirModalColaborador(colab, veiculoPrefixo)}
        className={cn(
          'group relative flex items-center gap-3.5 p-3 rounded-2xl border transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md active:scale-[0.99]',
          statusBg
        )}
      >
        {/* Foto do Colaborador com Ênfase Especial, Alta Nitidez e Anel de Presença */}
        <div className="relative shrink-0">
          <div
            className={cn(
              'w-14 h-14 rounded-2xl overflow-hidden border-2 ring-2 shadow-lg transition-transform duration-300 group-hover:scale-105 flex items-center justify-center bg-muted',
              statusRing
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover object-center"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-emerald-900/60 to-emerald-950 text-emerald-300 font-black text-base">
                {getIniciais(colab.nome)}
              </div>
            )}
          </div>

          {/* Microbadge de status fixado na foto */}
          <span
            className={cn(
              'absolute -bottom-1 -right-1 w-4.5 h-4.5 rounded-full ring-2 ring-card flex items-center justify-center shadow-sm',
              isPresente && 'bg-emerald-500 text-white',
              isFalta && 'bg-rose-500 text-white',
              isSubstituto && 'bg-amber-500 text-white'
            )}
          >
            {isPresente && <CheckCircle2 className="w-3 h-3" />}
            {isFalta && <XCircle className="w-3 h-3" />}
            {isSubstituto && <UserCheck className="w-3 h-3" />}
          </span>
        </div>

        {/* Dados e Nome do Colaborador */}
        <div className="min-w-0 flex-1 space-y-0.5">
          <div className="flex items-center justify-between gap-1">
            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
              {labelPosicao}
            </span>
            <Badge variant="outline" className={cn('text-[10px] py-0 px-2 rounded-full', badgeClass)}>
              {badgeText}
            </Badge>
          </div>

          <h5 className="text-sm font-bold text-foreground truncate group-hover:text-emerald-400 transition-colors">
            {colab.nome}
          </h5>

          <p className="text-[11px] text-muted-foreground truncate font-medium">
            {colab.cargo}
            {colab.matricula ? ` · Mat. ${colab.matricula}` : ''}
          </p>

          {isSubstituto && colab.substitutoNome && (
            <p className="text-[10px] font-semibold text-amber-400 truncate">
              Assumido por: {colab.substitutoNome}
            </p>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca Rápida */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/70 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por colaborador, motorista, prefixo do carro ou placa..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-10 h-10 text-xs bg-background/50 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="flex p-1 bg-background/60 rounded-xl border border-border/60">
            <button
              type="button"
              onClick={() => setFiltroStatus('todos')}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all',
                filtroStatus === 'todos' ? 'bg-primary text-primary-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('incompletos')}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all',
                filtroStatus === 'incompletos' ? 'bg-rose-500 text-white shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Com Faltas
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('completos')}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all',
                filtroStatus === 'completos' ? 'bg-emerald-600 text-white shadow-sm' : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Completos
            </button>
          </div>
        </div>
      </div>

      {/* Grid de Veículos com Assentos e Fotos dos Colaboradores */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20 space-y-3">
          <Car className="w-10 h-10 text-muted-foreground mx-auto opacity-40" />
          <p className="text-base font-bold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            Não há carros correspondentes aos critérios de busca ou filtros selecionados.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((v) => {
            const faltasNoVeiculo = [
              v.assentos?.motorista?.status,
              v.assentos?.frenteDir?.status,
              v.assentos?.trasEsq?.status,
              v.assentos?.trasDir?.status,
            ].filter((s) => s === 'falta').length;

            return (
              <Card
                key={v.id}
                className={cn(
                  'border transition-all duration-300 rounded-3xl overflow-hidden bg-card/80 shadow-lg hover:shadow-xl',
                  faltasNoVeiculo > 0 ? 'border-rose-500/30' : 'border-border/80'
                )}
              >
                {/* Header do Veículo */}
                <div className="px-5 py-4 border-b border-border/60 bg-gradient-to-r from-muted/40 via-card to-card flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400 shadow-sm shrink-0">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-base text-foreground tracking-tight">{v.prefixo}</span>
                        <span className="px-2 py-0.5 rounded-md bg-muted text-[11px] font-mono font-bold text-muted-foreground border border-border/70">
                          {v.placa}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground font-medium">
                        {v.modelo} · {v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {faltasNoVeiculo > 0 ? (
                      <Badge variant="outline" className="bg-rose-500/15 text-rose-400 border-rose-500/30 text-xs font-bold gap-1 py-1">
                        <AlertTriangle className="w-3.5 h-3.5" />
                        {faltasNoVeiculo} Falta{faltasNoVeiculo > 1 ? 's' : ''}
                      </Badge>
                    ) : (
                      <Badge variant="outline" className="bg-emerald-500/15 text-emerald-400 border-emerald-500/30 text-xs font-bold gap-1 py-1">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        Tripulação Completa
                      </Badge>
                    )}
                  </div>
                </div>

                {/* Grid dos 4 Assentos Operacionais com Destaque nas Fotos */}
                <div className="p-5 space-y-4">
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
                        <Layers className="w-3.5 h-3.5 text-emerald-400" />
                        {v.equipe1Codigo || 'Equipe 1 — Cabine Dianteira'}
                      </span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {renderAssentoFoto(v.assentos?.motorista, 'Motorista', v.prefixo)}
                      {renderAssentoFoto(v.assentos?.frenteDir, 'Frente Passageiro', v.prefixo)}
                    </div>
                  </div>

                  <div className="pt-2 border-t border-border/50">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
                        <Layers className="w-3.5 h-3.5 text-teal-400" />
                        {v.equipe2Codigo || 'Equipe 2 — Cabine Traseira'}
                      </span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {renderAssentoFoto(v.assentos?.trasEsq, 'Traseiro Esquerdo', v.prefixo)}
                      {renderAssentoFoto(v.assentos?.trasDir, 'Traseiro Direito', v.prefixo)}
                    </div>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Lançamento de Presença/Falta */}
      <AttendanceModal
        isOpen={modalAberto}
        onClose={() => setModalAberto(false)}
        colaborador={colaboradorSelecionado}
        veiculoPrefixo={veiculoAtivoPrefixo}
        colaboradoresReserva={colaboradoresReserva}
        onSave={(novoStatus, motivo, obs, subId) => {
          if (colaboradorSelecionado && onUpdateColaboradorStatus) {
            onUpdateColaboradorStatus(colaboradorSelecionado.id, novoStatus, motivo, obs, subId);
          }
        }}
      />
    </div>
  );
};

