import React, { useState, useEffect } from 'react';
import {
  X,
  User,
  Calendar,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  UserCheck,
  Disc,
  Compass,
} from 'lucide-react';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  colaboradoresReserva?: Colaborador[];
  onSaveAttendance?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  colaboradoresReserva = [],
  onSaveAttendance,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta>('Atestado Médico');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState('');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || 'Atestado Médico');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSave = () => {
    const subSelecionado = colaboradoresReserva.find((r) => r.id === substitutoId);
    if (onSaveAttendance) {
      onSaveAttendance(
        colaborador.id,
        status,
        status === 'falta' ? motivo : undefined,
        observacao,
        status === 'substituto' ? substitutoId : undefined,
        status === 'substituto' ? subSelecionado?.nome : undefined
      );
    }
    onClose();
  };

  const getPosicaoNome = (pos?: string) => {
    switch (pos) {
      case 'motorista':
        return 'Condutor / Motorista (Frente Esquerda)';
      case 'frente_dir':
        return 'Passageiro Dianteiro (Frente Direita)';
      case 'tras_esq':
        return 'Banco Traseiro Esquerdo';
      case 'tras_dir':
        return 'Banco Traseiro Direito';
      default:
        return 'Assento Operacional';
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/85 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header com simulação do carro */}
        <div className="px-6 py-4 border-b border-border/60 bg-muted/30 flex items-center justify-between">
          <div className="flex items-center gap-2 text-xs font-bold text-emerald-400 uppercase tracking-wider">
            <Compass className="w-4 h-4" />
            <span>Assento no Veículo: {getPosicaoNome(colaborador.posicaoVeiculo)}</span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 space-y-5">
          {/* Box estilizado do Colaborador no Assento */}
          <div className="flex items-center gap-4 p-4 rounded-2xl border border-border/70 bg-gradient-to-r from-card to-background shadow-md">
            <div className="relative">
              {/* Encosto do banco atrás da foto */}
              <div className="absolute -top-2 inset-x-2 h-3 rounded-t-lg bg-border/50" />
              <div className="relative w-20 h-20 rounded-2xl p-1 bg-background border-2 border-emerald-500 shadow-lg overflow-hidden">
                {colaborador.foto ? (
                  <img
                    src={colaborador.foto}
                    alt={colaborador.nome}
                    className="w-full h-full object-cover rounded-xl"
                  />
                ) : (
                  <div className="w-full h-full rounded-xl bg-muted flex items-center justify-center font-bold text-base text-foreground">
                    {getIniciais(colaborador.nome)}
                  </div>
                )}
              </div>
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-base text-foreground truncate">{colaborador.nome}</h3>
              </div>
              <p className="text-xs text-muted-foreground">{colaborador.cargo}</p>
              <div className="flex items-center gap-2 mt-2">
                <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-muted/60 border border-border/50 text-muted-foreground">
                  Matrícula: {colaborador.matricula || '---'}
                </span>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                  Equipe {colaborador.equipeNumero}
                </span>
              </div>
            </div>
          </div>

          {/* Seleção do Status de Presença */}
          <div className="space-y-2">
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">
              Status de Presença no Posto
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'presente'
                    ? 'bg-emerald-500/20 border-emerald-500 text-emerald-300 shadow-md ring-2 ring-emerald-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                <span>Presente</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'falta'
                    ? 'bg-rose-500/20 border-rose-500 text-rose-300 shadow-md ring-2 ring-rose-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <XCircle className="w-5 h-5 text-rose-400" />
                <span>Registrar Falta</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'substituto'
                    ? 'bg-amber-500/20 border-amber-500 text-amber-300 shadow-md ring-2 ring-amber-500/20'
                    : 'border-border/60 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <UserCheck className="w-5 h-5 text-amber-400" />
                <span>Substituto</span>
              </button>
            </div>
          </div>

          {/* Opções condicionais para Falta */}
          {status === 'falta' && (
            <div className="p-4 rounded-2xl border border-rose-500/30 bg-rose-500/5 space-y-3 animate-in fade-in">
              <label className="text-xs font-bold text-rose-400 block">Motivo da Ausência</label>
              <select
                value={motivo}
                onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
                className="w-full h-10 px-3 rounded-xl border border-rose-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
              >
                {MOTIVOS_FALTA.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Opções condicionais para Substituto */}
          {status === 'substituto' && (
            <div className="p-4 rounded-2xl border border-amber-500/30 bg-amber-500/5 space-y-3 animate-in fade-in">
              <label className="text-xs font-bold text-amber-400 block">
                Selecione o Colaborador Reserva para este Assento
              </label>
              <select
                value={substitutoId}
                onChange={(e) => setSubstitutoId(e.target.value)}
                className="w-full h-10 px-3 rounded-xl border border-amber-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
              >
                <option value="">Selecione um reserva...</option>
                {colaboradoresReserva.map((res) => (
                  <option key={res.id} value={res.id}>
                    {res.nome} — {res.cargo}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Observações adicionais */}
          <div className="space-y-1.5">
            <label className="text-xs font-bold text-muted-foreground">Observações de Campo</label>
            <input
              type="text"
              placeholder="Ex: Liberado para consulta médica matutina..."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              className="w-full h-10 px-3 rounded-xl border border-border/60 bg-background/50 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
            />
          </div>

          <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/60">
            <Button type="button" variant="outline" onClick={onClose} className="rounded-xl">
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={handleSave}
              className="rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold px-5"
            >
              Confirmar Assento
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

