import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  ShieldAlert,
  ArrowRightLeft,
  Calendar,
  Sparkles,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, Regional } from '../types';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva: Colaborador[];
  onUpdateColaboradorStatus: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: any,
    observacao?: string,
    substitutoId?: string
  ) => void;
  selectedRegional: Regional;
  selectedDate: Date;
}

const statusConfig: Record<StatusPresenca, { label: string; bg: string; text: string; border: string; ring: string }> = {
  presente: {
    label: 'Presente',
    bg: 'bg-emerald-500/20',
    text: 'text-emerald-400',
    border: 'border-emerald-500/30',
    ring: 'ring-emerald-500/40',
  },
  falta: {
    label: 'Falta',
    bg: 'bg-rose-500/20',
    text: 'text-rose-400',
    border: 'border-rose-500/30',
    ring: 'ring-rose-500/40',
  },
  substituto: {
    label: 'Substituto',
    bg: 'bg-amber-500/20',
    text: 'text-amber-400',
    border: 'border-amber-500/30',
    ring: 'ring-amber-500/40',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  onUpdateColaboradorStatus,
  selectedRegional,
  selectedDate,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [veiculoSelecionado, setVeiculoSelecionado] = useState<Veiculo | null>(null);
  const [modalOpen, setModalOpen] = useState(false);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional =
      selectedRegional === 'todas' || v.regional === selectedRegional;

    const assentosLista = [
      v.assentos?.motorista?.nome,
      v.assentos?.frenteDir?.nome,
      v.assentos?.trasEsq?.nome,
      v.assentos?.trasDir?.nome,
    ].filter(Boolean);

    const matchSearch =
      v.prefixo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      v.placa?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      assentosLista.some((nome) => nome?.toLowerCase().includes(searchTerm.toLowerCase()));

    const temFalta = [
      v.assentos?.motorista?.status,
      v.assentos?.frenteDir?.status,
      v.assentos?.trasEsq?.status,
      v.assentos?.trasDir?.status,
    ].some((s) => s === 'falta');

    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'incompletos' && temFalta) ||
      (statusFilter === 'completos' && !temFalta);

    return matchRegional && matchSearch && matchStatus;
  });

  const handleOpenAttendance = (veiculo: Veiculo) => {
    setVeiculoSelecionado(veiculo);
    setModalOpen(true);
  };

  const renderAssentoCarro = (
    colaborador?: Colaborador,
    posicaoTitulo: string = '',
    isDriver: boolean = false,
    veiculo?: Veiculo
  ) => {
    if (!colaborador) {
      return (
        <div className="relative flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed border-border/50 bg-card/30 min-h-[145px]">
          <span className="text-[11px] text-muted-foreground font-semibold">Vago</span>
          <span className="text-[9px] text-muted-foreground/60">{posicaoTitulo}</span>
        </div>
      );
    }

    const st = statusConfig[colaborador.status] || statusConfig.presente;

    return (
      <div
        onClick={() => veiculo && handleOpenAttendance(veiculo)}
        className={cn(
          'group relative flex flex-col items-center text-center p-3 rounded-2xl border transition-all duration-200 cursor-pointer overflow-hidden',
          'bg-gradient-to-b from-card/90 via-card/60 to-card/40 backdrop-blur-sm',
          'hover:border-primary/50 hover:shadow-lg hover:-translate-y-0.5',
          colaborador.status === 'falta'
            ? 'border-rose-500/40 shadow-rose-950/20'
            : colaborador.status === 'substituto'
            ? 'border-amber-500/40 shadow-amber-950/20'
            : 'border-border/70 hover:border-emerald-500/40'
        )}
      >
        {/* Marcador de posição no veículo */}
        <div className="w-full flex items-center justify-between gap-1 mb-2">
          <div className="flex items-center gap-1">
            {isDriver ? (
              <span className="flex items-center gap-1 text-[10px] font-bold text-amber-400 bg-amber-500/10 px-1.5 py-0.5 rounded-md border border-amber-500/20">
                <Disc className="w-3 h-3 animate-spin text-amber-400" />
                Motorista
              </span>
            ) : (
              <span className="text-[10px] font-semibold text-muted-foreground px-1.5 py-0.5 bg-muted/40 rounded-md">
                {posicaoTitulo}
              </span>
            )}
          </div>

          <Badge
            variant="outline"
            className={cn('text-[10px] py-0 px-1.5 font-bold border shadow-xs', st.bg, st.text, st.border)}
          >
            {st.label}
          </Badge>
        </div>

        {/* Foto de Destaque no Assento */}
        <div className="relative mb-2">
          <div
            className={cn(
              'w-16 h-16 rounded-full overflow-hidden border-2 shadow-md transition-transform duration-200 group-hover:scale-105 shrink-0 bg-muted/60',
              colaborador.status === 'falta'
                ? 'border-rose-500 ring-4 ring-rose-500/20 grayscale'
                : colaborador.status === 'substituto'
                ? 'border-amber-500 ring-4 ring-amber-500/20'
                : 'border-emerald-500/80 ring-4 ring-emerald-500/15'
            )}
          >
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover object-top"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center font-black text-sm bg-muted text-muted-foreground">
                {getIniciais(colaborador.nome)}
              </div>
            )}
          </div>

          {/* Ícone Indicador de Status */}
          <div className="absolute -bottom-1 -right-1">
            {colaborador.status === 'presente' && (
              <CheckCircle2 className="w-5 h-5 text-emerald-400 bg-background rounded-full p-0.5 shadow-sm" />
            )}
            {colaborador.status === 'falta' && (
              <XCircle className="w-5 h-5 text-rose-400 bg-background rounded-full p-0.5 shadow-sm" />
            )}
            {colaborador.status === 'substituto' && (
              <HelpCircle className="w-5 h-5 text-amber-400 bg-background rounded-full p-0.5 shadow-sm" />
            )}
          </div>
        </div>

        {/* Nome e Cargo */}
        <h4 className="text-xs font-bold text-foreground line-clamp-1 group-hover:text-primary transition-colors">
          {colaborador.nome}
        </h4>
        <p className="text-[10px] text-muted-foreground line-clamp-1 font-medium mt-0.5">
          {colaborador.cargo}
        </p>

        {/* Substituto ou Motivo da Falta */}
        {colaborador.status === 'substituto' && colaborador.substitutoNome && (
          <div className="mt-1.5 flex items-center gap-1 text-[9px] text-amber-300 bg-amber-500/15 px-1.5 py-0.5 rounded-md font-semibold border border-amber-500/20">
            <ArrowRightLeft className="w-2.5 h-2.5" />
            Subst: {colaborador.substitutoNome.split(' ')[0]}
          </div>
        )}

        {colaborador.status === 'falta' && colaborador.motivoFalta && (
          <div className="mt-1.5 text-[9px] text-rose-300 bg-rose-500/15 px-1.5 py-0.5 rounded-md font-semibold border border-rose-500/20 line-clamp-1">
            {colaborador.motivoFalta}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/80 shadow-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Buscar por prefixo, placa ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-background/50 border border-border/70 rounded-xl text-xs font-medium text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              statusFilter === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Completos
          </button>
          <button
            onClick={() => setStatusFilter('incompletos')}
            className={cn(
              'px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              statusFilter === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grid de Veículos com Habitáculo / Cabine Sentada */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-3xl border-2 border-dashed border-border/70 bg-card/20 p-8">
          <Car className="w-12 h-12 text-muted-foreground/40 mx-auto mb-3" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto mt-1">
            Nenhum carro corresponde aos filtros de regional ou pesquisa selecionados.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean) as Colaborador[];

            const faltasCount = assentos.filter((a) => a.status === 'falta').length;
            const subsCount = assentos.filter((a) => a.status === 'substituto').length;
            const presentesCount = assentos.filter((a) => a.status === 'presente').length;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'rounded-3xl border transition-all duration-300 overflow-hidden shadow-xl hover:shadow-2xl',
                  faltasCount > 0
                    ? 'border-rose-500/40 bg-card/80'
                    : 'border-border/80 bg-card/60 hover:border-emerald-500/40'
                )}
              >
                {/* Header do Veículo */}
                <CardHeader className="p-4 sm:p-5 border-b border-border/50 bg-gradient-to-r from-muted/30 via-transparent to-muted/10">
                  <div className="flex items-center justify-between gap-3 flex-wrap">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-2xl bg-emerald-500/15 border border-emerald-500/25 flex items-center justify-center shrink-0 shadow-inner">
                        <Car className="w-5 h-5 text-emerald-400" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <CardTitle className="text-base font-extrabold tracking-tight">
                            {veiculo.prefixo}
                          </CardTitle>
                          <Badge
                            variant="outline"
                            className="text-[11px] font-mono px-2 py-0 border-border/80 bg-background/50 font-semibold"
                          >
                            {veiculo.placa}
                          </Badge>
                        </div>
                        <p className="text-xs text-muted-foreground flex items-center gap-2 mt-0.5 font-medium">
                          <span>{veiculo.modelo}</span>
                          <span>•</span>
                          <span className="capitalize">
                            {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                          </span>
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      <Button
                        size="sm"
                        onClick={() => handleOpenAttendance(veiculo)}
                        className="h-8 px-3 rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground text-xs font-semibold gap-1.5 shadow-sm"
                      >
                        <Eye className="w-3.5 h-3.5" />
                        <span>Gerenciar Presenças</span>
                      </Button>
                    </div>
                  </div>

                  {/* Resumo Rápido de Status */}
                  <div className="flex items-center gap-3 mt-3 pt-3 border-t border-border/30 text-xs">
                    <div className="flex items-center gap-1.5 text-emerald-400 font-semibold">
                      <span className="w-2 h-2 rounded-full bg-emerald-400" />
                      <span>{presentesCount} Presentes</span>
                    </div>
                    {subsCount > 0 && (
                      <div className="flex items-center gap-1.5 text-amber-400 font-semibold">
                        <span className="w-2 h-2 rounded-full bg-amber-400" />
                        <span>{subsCount} Substitutos</span>
                      </div>
                    )}
                    {faltasCount > 0 ? (
                      <div className="flex items-center gap-1.5 text-rose-400 font-bold ml-auto bg-rose-500/10 px-2 py-0.5 rounded-full border border-rose-500/20">
                        <AlertTriangle className="w-3.5 h-3.5 text-rose-400" />
                        <span>{faltasCount} Falta(s)</span>
                      </div>
                    ) : (
                      <div className="flex items-center gap-1.5 text-emerald-400 font-semibold ml-auto">
                        <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                        <span>Veículo Operacional</span>
                      </div>
                    )}
                  </div>
                </CardHeader>

                {/* Conteúdo: Habitáculo do Carro (Layout Sentado em 4 Posições) */}
                <CardContent className="p-4 sm:p-5">
                  <div className="relative rounded-2xl border-2 border-border/60 bg-muted/15 p-4 shadow-inner">
                    {/* Representação do Vidro Frontal / Para-brisa */}
                    <div className="relative w-full h-5 rounded-t-xl bg-gradient-to-b from-sky-500/15 to-transparent border-t-2 border-x-2 border-sky-400/30 mb-3 flex items-center justify-center">
                      <span className="text-[9px] uppercase tracking-widest font-black text-sky-400/80">
                        FRENTE DO VEÍCULO (PARA-BRISA)
                      </span>
                    </div>

                    {/* Fileira da Frente: Motorista & Carona */}
                    <div className="space-y-1 mb-4">
                      <div className="flex items-center justify-between text-[10px] font-bold text-muted-foreground uppercase tracking-wider px-1">
                        <span>Equipe 1 • Fila Dianteira</span>
                        <span className="text-[9px] font-mono opacity-60">Eq: {veiculo.equipe1Codigo || 'EQ-1'}</span>
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        {renderAssentoCarro(veiculo.assentos?.motorista, 'Frente Esquerda', true, veiculo)}
                        {renderAssentoCarro(veiculo.assentos?.frenteDir, 'Frente Direita', false, veiculo)}
                      </div>
                    </div>

                    {/* Divisória Central de Habitáculo */}
                    <div className="relative flex items-center justify-center py-1">
                      <div className="w-full border-t border-dashed border-border/60" />
                      <span className="absolute bg-card px-2 text-[9px] font-bold text-muted-foreground uppercase">
                        Corredor Interno
                      </span>
                    </div>

                    {/* Fileira de Trás: Traseiro Esquerdo & Traseiro Direito */}
                    <div className="space-y-1 mt-3">
                      <div className="flex items-center justify-between text-[10px] font-bold text-muted-foreground uppercase tracking-wider px-1">
                        <span>Equipe 2 • Fila Traseira</span>
                        <span className="text-[9px] font-mono opacity-60">Eq: {veiculo.equipe2Codigo || 'EQ-2'}</span>
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        {renderAssentoCarro(veiculo.assentos?.trasEsq, 'Trás Esquerda', false, veiculo)}
                        {renderAssentoCarro(veiculo.assentos?.trasDir, 'Trás Direita', false, veiculo)}
                      </div>
                    </div>

                    {/* Traseira do Veículo */}
                    <div className="relative w-full h-3 rounded-b-xl bg-muted/30 border-b border-x border-border/40 mt-3 flex items-center justify-center">
                      <span className="text-[8px] uppercase tracking-wider font-semibold text-muted-foreground/60">
                        Porta-malas / Traseira
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Frequência */}
      {modalOpen && veiculoSelecionado && (
        <AttendanceModal
          isOpen={modalOpen}
          onClose={() => {
            setModalOpen(false);
            setVeiculoSelecionado(null);
          }}
          veiculo={veiculoSelecionado}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={(colabId, status, motivo, obs, subId) => {
            onUpdateColaboradorStatus(colabId, status, motivo, obs, subId);
            setModalOpen(false);
            setVeiculoSelecionado(null);
          }}
        />
      )}
    </div>
  );
};

files.newContent:
import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  Building2,
  Calendar,
  Sparkles,
  ArrowRightLeft,
  UserCheck,
  UserX,
  FileText,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateStatus?: (
    veiculoId: string,
    colabId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substituto?: Colaborador
  ) => void;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const statusConfig: Record<
  StatusPresenca,
  { label: string; badgeClass: string; borderClass: string; bgClass: string; icon: any }
> = {
  presente: {
    label: 'Presente',
    badgeClass: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30',
    borderClass: 'border-emerald-500/30 group-hover:border-emerald-400',
    bgClass: 'bg-emerald-500/5',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    badgeClass: 'bg-rose-500/15 text-rose-400 border-rose-500/30',
    borderClass: 'border-rose-500/40 group-hover:border-rose-400 ring-1 ring-rose-500/20',
    bgClass: 'bg-rose-500/10',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    badgeClass: 'bg-amber-500/15 text-amber-400 border-amber-500/30',
    borderClass: 'border-amber-500/30 group-hover:border-amber-400',
    bgClass: 'bg-amber-500/5',
    icon: AlertTriangle,
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateStatus,
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [selectedVehicleForModal, setSelectedVehicleForModal] = useState<Veiculo | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => {
      setToastMessage(null);
    }, 2800);
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional =
      selectedRegional === 'todas' || v.regional === selectedRegional;

    const term = searchTerm.toLowerCase();
    const matchSearch =
      !searchTerm ||
      v.prefixo?.toLowerCase().includes(term) ||
      v.placa?.toLowerCase().includes(term) ||
      v.modelo?.toLowerCase().includes(term) ||
      Object.values(v.assentos || {}).some((c) =>
        c?.nome?.toLowerCase().includes(term) || c?.matricula?.toLowerCase().includes(term)
      );

    const assentosArr = [
      v.assentos?.motorista,
      v.assentos?.frenteDir,
      v.assentos?.trasEsq,
      v.assentos?.trasDir,
    ].filter(Boolean) as Colaborador[];

    const hasFaltas = assentosArr.some((c) => c?.status === 'falta');
    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'completos' && !hasFaltas) ||
      (statusFilter === 'incompletos' && hasFaltas);

    return matchRegional && matchSearch && matchStatus;
  });

  const handleToggleColaboradorStatus = (
    e: React.MouseEvent,
    veiculo: Veiculo,
    colaborador: Colaborador
  ) => {
    e.stopPropagation();
    if (!colaborador) return;

    const novoStatus: StatusPresenca = colaborador.status === 'falta' ? 'presente' : 'falta';
    const motivoPadrao: MotivoFalta | undefined =
      novoStatus === 'falta' ? 'Falta Injustificada' : undefined;

    if (onUpdateStatus) {
      onUpdateStatus(veiculo.id, colaborador.id, novoStatus, motivoPadrao);
    } else if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(colaborador.id, novoStatus, motivoPadrao);
    }

    showToast(
      novoStatus === 'falta'
        ? `⚠️ ${colaborador.nome} marcado como FALTA`
        : `✅ ${colaborador.nome} marcado como PRESENTE`
    );
  };

  return (
    <div className="space-y-6">
      {/* Toast Feedback */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 flex items-center gap-2.5 px-4 py-3 rounded-2xl bg-foreground text-background shadow-2xl animate-in slide-in-from-bottom-3 duration-200 text-xs font-semibold">
          <span>{toastMessage}</span>
        </div>
      )}

      {/* Barra de Filtros */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/70 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por veículo, placa ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 h-10 text-xs bg-background/50 border-border/60 rounded-xl focus-visible:ring-emerald-500/20"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
          <button
            type="button"
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-semibold transition-all border shrink-0 cursor-pointer',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculosFiltrados.length})
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-semibold transition-all border shrink-0 cursor-pointer',
              statusFilter === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/40'
            )}
          >
            <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
            100% Presentes
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('incompletos')}
            className={cn(
              'flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-semibold transition-all border shrink-0 cursor-pointer',
              statusFilter === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/40'
            )}
          >
            <AlertTriangle className="w-3.5 h-3.5 text-rose-300" />
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grade de Veículos */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {veiculosFiltrados.map((veiculo) => {
          const assentosArr = [
            veiculo.assentos?.motorista,
            veiculo.assentos?.frenteDir,
            veiculo.assentos?.trasEsq,
            veiculo.assentos?.trasDir,
          ].filter(Boolean) as Colaborador[];

          const faltasCount = assentosArr.filter((c) => c?.status === 'falta').length;
          const presentesCount = assentosArr.filter(
            (c) => c?.status === 'presente' || c?.status === 'substituto'
          ).length;

          const renderSeat = (
            colab: Colaborador | undefined,
            cargoPos: string,
            seatLabel: string,
            lado: 'esq' | 'dir'
          ) => {
            if (!colab) {
              return (
                <div className="flex flex-col items-center justify-center p-3 rounded-2xl border border-dashed border-border/60 bg-muted/20 min-h-[148px]">
                  <Disc className="w-5 h-5 text-muted-foreground/40 mb-1" />
                  <span className="text-[11px] font-semibold text-muted-foreground/60">Vago</span>
                  <span className="text-[9px] text-muted-foreground/40">{seatLabel}</span>
                </div>
              );
            }

            const cfg = statusConfig[colab.status] || statusConfig.presente;
            const StatusIcon = cfg.icon;
            const isFalta = colab.status === 'falta';

            return (
              <div
                className={cn(
                  'group relative flex flex-col items-center text-center p-3 rounded-2xl border transition-all duration-200 min-h-[154px]',
                  cfg.bgClass,
                  cfg.borderClass,
                  'hover:shadow-md'
                )}
              >
                {/* Botão de Troca Rápida de Presença / Falta ao Clicar na Foto */}
                <button
                  type="button"
                  title={
                    isFalta
                      ? 'Clique para marcar como PRESENTE'
                      : 'Clique para marcar como FALTA'
                  }
                  onClick={(e) => handleToggleColaboradorStatus(e, veiculo, colab)}
                  className="relative group/photo focus:outline-none focus:ring-2 focus:ring-emerald-500/40 rounded-full transition-transform active:scale-95 cursor-pointer"
                >
                  <div
                    className={cn(
                      'w-16 h-16 rounded-full overflow-hidden border-2 shadow-md transition-all flex items-center justify-center',
                      isFalta
                        ? 'border-rose-500 ring-4 ring-rose-500/20 grayscale contrast-125'
                        : 'border-emerald-500 ring-2 ring-emerald-500/20 group-hover/photo:ring-4 group-hover/photo:ring-emerald-500/30'
                    )}
                  >
                    {colab.foto ? (
                      <img
                        src={colab.foto}
                        alt={colab.nome}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          (e.target as HTMLImageElement).style.display = 'none';
                        }}
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center bg-muted text-foreground font-black text-sm">
                        {getIniciais(colab.nome)}
                      </div>
                    )}
                  </div>

                  {/* Badge de Ação / Toggle sobreposta na foto */}
                  <span
                    className={cn(
                      'absolute -bottom-1 -right-1 p-1 rounded-full text-white shadow-md transition-all duration-150',
                      isFalta
                        ? 'bg-rose-600 hover:bg-rose-500 ring-2 ring-background'
                        : 'bg-emerald-600 hover:bg-emerald-500 ring-2 ring-background'
                    )}
                  >
                    {isFalta ? (
                      <XCircle className="w-4 h-4" />
                    ) : (
                      <CheckCircle2 className="w-4 h-4" />
                    )}
                  </span>

                  {/* Tooltip Hover indicando a ação */}
                  <span className="absolute -top-7 left-1/2 -translate-x-1/2 whitespace-nowrap px-2 py-0.5 rounded-md bg-foreground text-background text-[10px] font-bold opacity-0 group-hover/photo:opacity-100 transition-opacity pointer-events-none z-20 shadow-lg">
                    {isFalta ? 'Marcar Presente' : 'Marcar Falta'}
                  </span>
                </button>

                {/* Dados do Colaborador */}
                <div className="mt-2.5 w-full">
                  <p
                    className={cn(
                      'text-xs font-bold truncate tracking-tight',
                      isFalta ? 'text-rose-400 line-through decoration-rose-500/50' : 'text-foreground'
                    )}
                    title={colab.nome}
                  >
                    {colab.nome}
                  </p>
                  <p className="text-[10px] text-muted-foreground truncate font-medium">
                    {colab.cargo || cargoPos}
                  </p>
                </div>

                {/* Pílula de Status com clique para alternar */}
                <button
                  type="button"
                  onClick={(e) => handleToggleColaboradorStatus(e, veiculo, colab)}
                  className={cn(
                    'mt-2 inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold border transition-all cursor-pointer hover:opacity-85',
                    cfg.badgeClass
                  )}
                  title="Clique para alternar presença / falta"
                >
                  <StatusIcon className="w-3 h-3" />
                  <span>{cfg.label}</span>
                </button>
              </div>
            );
          };

          return (
            <Card
              key={veiculo.id}
              className={cn(
                'rounded-3xl border transition-all duration-200 overflow-hidden bg-card/60 backdrop-blur-md hover:shadow-xl',
                faltasCount > 0 ? 'border-rose-500/30' : 'border-border/70'
              )}
            >
              {/* Header do Card */}
              <div className="p-4 border-b border-border/50 bg-gradient-to-r from-muted/20 via-transparent to-transparent flex items-center justify-between gap-3">
                <div className="flex items-center gap-2.5">
                  <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary font-black">
                    <Car className="w-5 h-5" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="font-extrabold text-sm sm:text-base text-foreground tracking-tight">
                        {veiculo.prefixo}
                      </h3>
                      <Badge
                        variant="outline"
                        className="text-[10px] py-0 px-1.5 border-border/70 font-mono text-muted-foreground"
                      >
                        {veiculo.placa}
                      </Badge>
                    </div>
                    <span className="text-[11px] text-muted-foreground font-medium">
                      {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                    </span>
                  </div>
                </div>

                <div className="text-right">
                  <span
                    className={cn(
                      'inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold border',
                      faltasCount > 0
                        ? 'bg-rose-500/10 text-rose-400 border-rose-500/30'
                        : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                    )}
                  >
                    {faltasCount > 0 ? (
                      <>
                        <AlertTriangle className="w-3.5 h-3.5" />
                        <span>{faltasCount} Falta{faltasCount > 1 ? 's' : ''}</span>
                      </>
                    ) : (
                      <>
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        <span>Completo</span>
                      </>
                    )}
                  </span>
                </div>
              </div>

              {/* Habitáculo / Representação das Posições do Veículo */}
              <div className="p-4 space-y-4">
                {/* Equipe 1: Dianteira (Motorista & Frente Direito) */}
                <div>
                  <div className="flex items-center justify-between mb-2 px-1">
                    <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1">
                      <Users className="w-3 h-3 text-emerald-400" />
                      Frente · {veiculo.equipe1Codigo || 'Equipe 1'}
                    </span>
                    <span className="text-[10px] text-muted-foreground/70">Cabine Dianteira</span>
                  </div>
                  <div className="grid grid-cols-2 gap-2.5">
                    {renderSeat(veiculo.assentos?.motorista, 'Motorista', 'Assento Motorista', 'esq')}
                    {renderSeat(veiculo.assentos?.frenteDir, 'Operador', 'Assento Dianteiro Dir', 'dir')}
                  </div>
                </div>

                {/* Divisor do habitáculo do carro */}
                <div className="relative flex items-center justify-center">
                  <div className="w-full border-t border-dashed border-border/60" />
                  <span className="absolute bg-card px-2 text-[9px] font-semibold text-muted-foreground/60 uppercase tracking-widest">
                    Bancos Traseiros
                  </span>
                </div>

                {/* Equipe 2: Traseira (Traseiro Esquerdo & Traseiro Direito) */}
                <div>
                  <div className="flex items-center justify-between mb-2 px-1">
                    <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1">
                      <Users className="w-3 h-3 text-teal-400" />
                      Atrás · {veiculo.equipe2Codigo || 'Equipe 2'}
                    </span>
                    <span className="text-[10px] text-muted-foreground/70">Cabine Traseira</span>
                  </div>
                  <div className="grid grid-cols-2 gap-2.5">
                    {renderSeat(veiculo.assentos?.trasEsq, 'Operador', 'Assento Traseiro Esq', 'esq')}
                    {renderSeat(veiculo.assentos?.trasDir, 'Operador', 'Assento Traseiro Dir', 'dir')}
                  </div>
                </div>
              </div>

              {/* Rodapé com botão de Gerenciar / Justificar */}
              <div className="p-3 bg-muted/20 border-t border-border/50 flex items-center justify-between gap-2">
                <span className="text-[11px] text-muted-foreground">
                  Toque na foto para marcar falta rápida
                </span>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setSelectedVehicleForModal(veiculo)}
                  className="text-xs h-8 px-3 rounded-xl gap-1.5 border-border/70 hover:bg-card"
                >
                  <Eye className="w-3.5 h-3.5" />
                  Detalhes & Justificativa
                </Button>
              </div>
            </Card>
          );
        })}
      </div>

      {veiculosFiltrados.length === 0 && (
        <div className="py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20 space-y-3">
          <Car className="w-10 h-10 text-muted-foreground/50 mx-auto" />
          <h4 className="font-bold text-base text-foreground">Nenhum veículo encontrado</h4>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            Verifique o filtro de unidade operacional ou termo de busca pesquisado.
          </p>
        </div>
      )}

      {/* Modal de Detalhes e Justificativa de Presença */}
      {selectedVehicleForModal && (
        <AttendanceModal
          isOpen={Boolean(selectedVehicleForModal)}
          onClose={() => setSelectedVehicleForModal(null)}
          veiculo={selectedVehicleForModal}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarPresenca={(dados) => {
            if (onUpdateStatus && selectedVehicleForModal) {
              Object.entries(dados).forEach(([posicao, info]: [string, any]) => {
                if (info?.status) {
                  const colab = (selectedVehicleForModal.assentos as any)?.[posicao];
                  if (colab) {
                    onUpdateStatus(
                      selectedVehicleForModal.id,
                      colab.id,
                      info.status,
                      info.motivo,
                      info.observacao,
                      info.substituto
                    );
                  }
                }
              });
            }
            setSelectedVehicleForModal(null);
          }}
        />
      )}
    </div>
  );
};

