import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  Clock,
  Sparkles,
  Phone,
  UserCheck,
  UserX,
  RotateCcw,
  Check,
  X,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSelectVeiculo?: (veiculo: Veiculo) => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; bg: string; text: string; border: string }> = {
  presente: { label: 'Presente', bg: 'bg-emerald-500/15', text: 'text-emerald-400', border: 'border-emerald-500/30' },
  falta: { label: 'Falta', bg: 'bg-rose-500/15', text: 'text-rose-400', border: 'border-rose-500/30' },
  substituto: { label: 'Substituto', bg: 'bg-amber-500/15', text: 'text-amber-400', border: 'border-amber-500/30' },
};

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateColaboradorStatus,
  onSelectVeiculo,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [veiculoModal, setVeiculoModal] = useState<Veiculo | null>(null);

  // Estado para o Popover / Modal Rápido de troca de Status ao clicar na foto
  const [quickStatusTarget, setQuickStatusTarget] = useState<{
    colaborador: Colaborador;
    veiculoPrefixo: string;
    novoStatus: StatusPresenca;
    motivoFalta?: MotivoFalta;
    observacao?: string;
    substitutoId?: string;
    substitutoNome?: string;
  } | null>(null);

  const getStatusVeiculo = (veiculo: Veiculo) => {
    if (!veiculo || !veiculo.assentos) return { status: 'completo', countFaltas: 0, countTotal: 0 };
    const assentos = [
      veiculo.assentos.motorista,
      veiculo.assentos.frenteDir,
      veiculo.assentos.trasEsq,
      veiculo.assentos.trasDir,
    ].filter(Boolean);

    const countFaltas = assentos.filter((c) => c?.status === 'falta').length;
    return {
      status: countFaltas > 0 ? 'incompleto' : 'completo',
      countFaltas,
      countTotal: assentos.length,
    };
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    const { status } = getStatusVeiculo(v);
    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'completos' && status === 'completo') ||
      (statusFilter === 'incompletos' && status === 'incompleto');

    const searchLower = searchTerm.toLowerCase();
    const assentosLista = v.assentos
      ? [v.assentos.motorista, v.assentos.frenteDir, v.assentos.trasEsq, v.assentos.trasDir].filter(Boolean)
      : [];

    const matchSearch =
      !searchTerm ||
      (v.prefixo || '').toLowerCase().includes(searchLower) ||
      (v.placa || '').toLowerCase().includes(searchLower) ||
      (v.modelo || '').toLowerCase().includes(searchLower) ||
      (v.equipe1Codigo || '').toLowerCase().includes(searchLower) ||
      (v.equipe2Codigo || '').toLowerCase().includes(searchLower) ||
      assentosLista.some((c) => (c?.nome || '').toLowerCase().includes(searchLower));

    return matchRegional && matchStatus && matchSearch;
  });

  const handleOpenQuickStatus = (e: React.MouseEvent, colab: Colaborador, veiculoPrefixo: string) => {
    e.stopPropagation();
    setQuickStatusTarget({
      colaborador: colab,
      veiculoPrefixo,
      novoStatus: colab.status || 'presente',
      motivoFalta: colab.motivoFalta || 'Atestado Médico',
      observacao: colab.observacao || '',
      substitutoId: colab.substitutoId || '',
      substitutoNome: colab.substitutoNome || '',
    });
  };

  const handleSalvarQuickStatus = () => {
    if (!quickStatusTarget || !onUpdateColaboradorStatus) {
      setQuickStatusTarget(null);
      return;
    }

    const { colaborador, novoStatus, motivoFalta, observacao, substitutoId, substitutoNome } = quickStatusTarget;

    onUpdateColaboradorStatus(
      colaborador.id,
      novoStatus,
      novoStatus === 'falta' ? motivoFalta : undefined,
      observacao,
      novoStatus === 'substituto' ? substitutoId : undefined,
      novoStatus === 'substituto' ? substitutoNome : undefined
    );

    setQuickStatusTarget(null);
  };

  // Renderizador de cada Assento com Destaque no Quadrado da Foto Clicável
  const renderAssento = (
    colab: Colaborador | undefined,
    posicaoTitulo: string,
    veiculo: Veiculo
  ) => {
    if (!colab) {
      return (
        <div className="flex items-center gap-3 p-3 rounded-2xl border border-dashed border-border/40 bg-card/20">
          <div className="w-12 h-12 rounded-2xl border border-dashed border-border/60 bg-muted/20 flex items-center justify-center text-muted-foreground shrink-0 text-xs font-semibold">
            Vazio
          </div>
          <div className="flex-1 min-w-0">
            <span className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider block">
              {posicaoTitulo}
            </span>
            <span className="text-xs text-muted-foreground/80 italic">Posto não ocupado</span>
          </div>
        </div>
      );
    }

    const statusStyle = statusBadgeConfig[colab.status] || statusBadgeConfig.presente;

    return (
      <div
        className={cn(
          'group relative flex items-center gap-3.5 p-3 rounded-2xl border transition-all duration-200',
          colab.status === 'falta'
            ? 'border-rose-500/40 bg-rose-500/5 hover:border-rose-500/70 hover:bg-rose-500/10'
            : colab.status === 'substituto'
            ? 'border-amber-500/40 bg-amber-500/5 hover:border-amber-500/70 hover:bg-amber-500/10'
            : 'border-border/70 bg-card/60 hover:border-emerald-500/50 hover:bg-card/90'
        )}
      >
        {/* QUADRADO DA FOTO CLICÁVEL COM FEEDBACK VISUAL E BOTÃO DE STATUS */}
        <button
          type="button"
          onClick={(e) => handleOpenQuickStatus(e, colab, veiculo.prefixo)}
          title={`Clique para definir Falta, Presença ou Substituição de ${colab.nome}`}
          className={cn(
            'relative w-14 h-14 rounded-2xl overflow-hidden shrink-0 border-2 transition-transform duration-150 active:scale-95 shadow-md flex items-center justify-center cursor-pointer group/foto',
            colab.status === 'falta'
              ? 'border-rose-500 ring-2 ring-rose-500/30'
              : colab.status === 'substituto'
              ? 'border-amber-500 ring-2 ring-amber-500/30'
              : 'border-emerald-500/80 ring-2 ring-emerald-500/20'
          )}
        >
          {colab.foto ? (
            <img
              src={colab.foto}
              alt={colab.nome}
              className="w-full h-full object-cover group-hover/foto:scale-105 transition-transform duration-200"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-muted to-muted/80 flex items-center justify-center font-bold text-sm text-foreground">
              {getIniciais(colab.nome)}
            </div>
          )}

          {/* Overlay Hover na Foto instruindo ação */}
          <div className="absolute inset-0 bg-black/60 opacity-0 group-hover/foto:opacity-100 transition-opacity duration-150 flex flex-col items-center justify-center text-white text-[10px] font-bold p-1 text-center leading-tight">
            <span>Alterar</span>
            <span className="text-[9px] text-emerald-300 font-medium">Status</span>
          </div>

          {/* Ícone fixo de status no canto da foto */}
          <span className="absolute bottom-0.5 right-0.5 p-0.5 rounded-full bg-background/90 shadow-sm border border-border/80">
            {colab.status === 'falta' ? (
              <XCircle className="w-3.5 h-3.5 text-rose-500" />
            ) : colab.status === 'substituto' ? (
              <HelpCircle className="w-3.5 h-3.5 text-amber-500" />
            ) : (
              <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
            )}
          </span>
        </button>

        {/* Detalhes do Colaborador */}
        <div className="flex-1 min-w-0 space-y-0.5">
          <div className="flex items-center justify-between gap-1">
            <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">
              {posicaoTitulo}
            </span>

            {/* Badge de Status Clicável também */}
            <button
              type="button"
              onClick={(e) => handleOpenQuickStatus(e, colab, veiculo.prefixo)}
              className={cn(
                'px-2 py-0.5 rounded-full border text-[11px] font-bold transition-all hover:scale-105 active:scale-95 cursor-pointer',
                statusStyle.bg,
                statusStyle.text,
                statusStyle.border
              )}
            >
              {statusStyle.label}
            </button>
          </div>

          <p className="text-sm font-bold text-foreground truncate">{colab.nome}</p>

          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <span className="truncate">{colab.cargo}</span>
            {colab.matricula && (
              <>
                <span className="opacity-40">•</span>
                <span className="font-mono text-[11px] tabular-nums">{colab.matricula}</span>
              </>
            )}
          </div>

          {colab.status === 'falta' && colab.motivoFalta && (
            <p className="text-[11px] font-semibold text-rose-400 truncate flex items-center gap-1 pt-0.5">
              <span className="w-1.5 h-1.5 rounded-full bg-rose-500 shrink-0" />
              {colab.motivoFalta}
            </p>
          )}

          {colab.status === 'substituto' && colab.substitutoNome && (
            <p className="text-[11px] font-semibold text-amber-400 truncate flex items-center gap-1 pt-0.5">
              <span className="w-1.5 h-1.5 rounded-full bg-amber-500 shrink-0" />
              Subst: {colab.substitutoNome}
            </p>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtro e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-4 rounded-3xl border border-border/80 shadow-md backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por prefixo, placa, equipe ou nome do colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-10 text-xs sm:text-sm bg-background/50 border-border/70 rounded-2xl"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-bold border transition-all cursor-pointer',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-bold border transition-all cursor-pointer',
              statusFilter === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Completos
          </button>
          <button
            type="button"
            onClick={() => setStatusFilter('incompletos')}
            className={cn(
              'px-3.5 py-2 rounded-xl text-xs font-bold border transition-all cursor-pointer',
              statusFilter === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/70 text-muted-foreground hover:bg-muted/40'
            )}
          >
            Com Falta
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-3xl border border-dashed border-border/80 bg-card/30">
            <Car className="w-10 h-10 text-muted-foreground mx-auto mb-3 opacity-50" />
            <p className="text-base font-bold text-foreground">Nenhum veículo encontrado</p>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Tente redefinir os filtros de busca ou regional selecionada para ver mais registros.
            </p>
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const { status, countFaltas } = getStatusVeiculo(veiculo);

            return (
              <div
                key={veiculo.id}
                className={cn(
                  'group rounded-3xl border bg-card/70 backdrop-blur-md shadow-xl transition-all duration-200 overflow-hidden flex flex-col',
                  status === 'incompleto'
                    ? 'border-rose-500/40 hover:border-rose-500/70 shadow-rose-950/10'
                    : 'border-border/80 hover:border-emerald-500/40 shadow-emerald-950/5'
                )}
              >
                {/* Cabeçalho do Card do Veículo */}
                <div className="p-4 sm:p-5 border-b border-border/60 bg-gradient-to-r from-muted/20 to-transparent flex items-center justify-between gap-3">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="font-black text-base tracking-tight text-foreground">
                        {veiculo.prefixo}
                      </span>
                      <Badge
                        variant="outline"
                        className={cn(
                          'text-[10px] py-0 px-2 font-bold',
                          status === 'incompleto'
                            ? 'bg-rose-500/15 text-rose-400 border-rose-500/30'
                            : 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30'
                        )}
                      >
                        {status === 'incompleto' ? `${countFaltas} Falta(s)` : 'Completo'}
                      </Badge>
                    </div>

                    <div className="flex items-center gap-2 text-xs text-muted-foreground font-mono">
                      <span>{veiculo.placa}</span>
                      <span className="opacity-40">•</span>
                      <span>{veiculo.modelo}</span>
                    </div>
                  </div>

                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => {
                      setVeiculoModal(veiculo);
                      onSelectVeiculo?.(veiculo);
                    }}
                    className="h-8 px-3 rounded-xl border-border/80 hover:border-emerald-500/60 hover:text-emerald-400 text-xs font-semibold gap-1.5"
                  >
                    <Eye className="w-3.5 h-3.5" />
                    <span>Detalhar</span>
                  </Button>
                </div>

                {/* Corpo do Veículo: 4 Assentos (Clique na Foto para alterar presença/falta/substituto) */}
                <div className="p-4 sm:p-5 space-y-4 flex-1">
                  {/* Equipe 1 (Frente) */}
                  <div className="space-y-2.5">
                    <div className="flex items-center justify-between text-xs font-semibold text-muted-foreground px-1">
                      <span className="flex items-center gap-1.5 text-emerald-400">
                        <Users className="w-3.5 h-3.5" />
                        {veiculo.equipe1Codigo || 'Equipe 1 (Frente)'}
                      </span>
                      <span className="text-[10px] text-muted-foreground/70 font-mono">Assentos Dianteiros</span>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                      {renderAssento(veiculo.assentos?.motorista, 'Motorista', veiculo)}
                      {renderAssento(veiculo.assentos?.frenteDir, 'Ajudante Frente', veiculo)}
                    </div>
                  </div>

                  {/* Equipe 2 (Traseira) */}
                  <div className="space-y-2.5 pt-2 border-t border-border/40">
                    <div className="flex items-center justify-between text-xs font-semibold text-muted-foreground px-1">
                      <span className="flex items-center gap-1.5 text-teal-400">
                        <Users className="w-3.5 h-3.5" />
                        {veiculo.equipe2Codigo || 'Equipe 2 (Traseira)'}
                      </span>
                      <span className="text-[10px] text-muted-foreground/70 font-mono">Assentos Traseiros</span>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                      {renderAssento(veiculo.assentos?.trasEsq, 'Ajudante Trás Esq.', veiculo)}
                      {renderAssento(veiculo.assentos?.trasDir, 'Ajudante Trás Dir.', veiculo)}
                    </div>
                  </div>
                </div>

                {/* Rodapé informativo */}
                <div className="px-4 py-2.5 bg-muted/10 border-t border-border/40 flex items-center justify-between text-[11px] text-muted-foreground">
                  <span className="flex items-center gap-1">
                    <Clock className="w-3.5 h-3.5 opacity-60" />
                    Regional: <strong className="text-foreground capitalize">{veiculo.regional.replace('_', ' ')}</strong>
                  </span>
                  <span className="text-[10px] opacity-75">Clique na foto para alterar presença</span>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* MODAL RÁPIDO AO CLICAR NO QUADRADO DA FOTO DO COLABORADOR */}
      {quickStatusTarget && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
          onClick={() => setQuickStatusTarget(null)}
        >
          <div
            className="relative w-full max-w-md bg-card border border-border/80 rounded-3xl shadow-2xl p-5 space-y-4 animate-in zoom-in-95 duration-150"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header com Foto e Nome */}
            <div className="flex items-start justify-between gap-3 pb-3 border-b border-border/60">
              <div className="flex items-center gap-3">
                <div className="w-14 h-14 rounded-2xl overflow-hidden border-2 border-primary/50 shadow-md shrink-0">
                  {quickStatusTarget.colaborador.foto ? (
                    <img
                      src={quickStatusTarget.colaborador.foto}
                      alt={quickStatusTarget.colaborador.nome}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <div className="w-full h-full bg-muted flex items-center justify-center font-bold text-sm">
                      {getIniciais(quickStatusTarget.colaborador.nome)}
                    </div>
                  )}
                </div>

                <div>
                  <h3 className="text-base font-bold text-foreground leading-tight">
                    {quickStatusTarget.colaborador.nome}
                  </h3>
                  <p className="text-xs text-muted-foreground mt-0.5">{quickTargetCargoSubtitle(quickStatusTarget)}</p>
                  <p className="text-[11px] text-emerald-400 font-semibold">{quickStatusTarget.veiculoPrefixo}</p>
                </div>
              </div>

              <button
                type="button"
                onClick={() => setQuickStatusTarget(null)}
                className="p-1 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* SELEÇÃO DO STATUS (PRESENTE, FALTA OU SUBSTITUIÇÃO) */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block">
                Selecione o Status Operacional
              </label>

              <div className="grid grid-cols-3 gap-2">
                {/* Presente */}
                <button
                  type="button"
                  onClick={() => setQuickStatusTarget((prev) => prev ? { ...prev, novoStatus: 'presente' } : null)}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                    quickStatusTarget.novoStatus === 'presente'
                      ? 'border-emerald-500 bg-emerald-500/15 text-emerald-400 font-bold shadow-md'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:border-emerald-500/40'
                  )}
                >
                  <UserCheck className="w-5 h-5" />
                  <span className="text-xs">Presente</span>
                </button>

                {/* Falta */}
                <button
                  type="button"
                  onClick={() => setQuickStatusTarget((prev) => prev ? { ...prev, novoStatus: 'falta' } : null)}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                    quickStatusTarget.novoStatus === 'falta'
                      ? 'border-rose-500 bg-rose-500/15 text-rose-400 font-bold shadow-md'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:border-rose-500/40'
                  )}
                >
                  <UserX className="w-5 h-5" />
                  <span className="text-xs">Falta</span>
                </button>

                {/* Substituto */}
                <button
                  type="button"
                  onClick={() => setQuickStatusTarget((prev) => prev ? { ...prev, novoStatus: 'substituto' } : null)}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border-2 transition-all cursor-pointer',
                    quickStatusTarget.novoStatus === 'substituto'
                      ? 'border-amber-500 bg-amber-500/15 text-amber-400 font-bold shadow-md'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:border-amber-500/40'
                  )}
                >
                  <RotateCcw className="w-5 h-5" />
                  <span className="text-xs">Substituto</span>
                </button>
              </div>
            </div>

            {/* SE FOR FALTA: ESCOLHA DO MOTIVO */}
            {quickStatusTarget.novoStatus === 'falta' && (
              <div className="space-y-2 p-3 rounded-2xl bg-rose-500/5 border border-rose-500/20 animate-in fade-in-50">
                <label className="text-xs font-bold text-rose-400 block">
                  Motivo da Falta
                </label>
                <select
                  value={quickStatusTarget.motivoFalta || 'Atestado Médico'}
                  onChange={(e) =>
                    setQuickStatusTarget((prev) =>
                      prev ? { ...prev, motivoFalta: e.target.value as MotivoFalta } : null
                    )
                  }
                  className="w-full h-10 px-3 rounded-xl border border-rose-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
                >
                  {MOTIVOS_FALTA.map((m) => (
                    <option key={m} value={m}>
                      {m}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* SE FOR SUBSTITUTO: SELEÇÃO DO COLABORADOR RESERVA */}
            {quickStatusTarget.novoStatus === 'substituto' && (
              <div className="space-y-2 p-3 rounded-2xl bg-amber-500/5 border border-amber-500/20 animate-in fade-in-50">
                <label className="text-xs font-bold text-amber-400 block">
                  Selecione o Substituto do Banco de Reserva
                </label>
                <select
                  value={quickStatusTarget.substitutoId || ''}
                  onChange={(e) => {
                    const selId = e.target.value;
                    const r = colaboradoresReserva.find((res) => res.id === selId);
                    setQuickStatusTarget((prev) =>
                      prev
                        ? {
                            ...prev,
                            substitutoId: selId,
                            substitutoNome: r ? r.nome : '',
                          }
                        : null
                    );
                  }}
                  className="w-full h-10 px-3 rounded-xl border border-amber-500/30 bg-background text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
                >
                  <option value="">Selecione um substituto...</option>
                  {colaboradoresReserva.map((res) => (
                    <option key={res.id} value={res.id}>
                      {res.nome} ({res.cargo})
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Observações Opcionais */}
            <div className="space-y-1">
              <label className="text-xs font-semibold text-muted-foreground block">
                Observação (Opcional)
              </label>
              <Input
                placeholder="Ex: Avisou com antecedência / consulta agendada"
                value={quickStatusTarget.observacao || ''}
                onChange={(e) =>
                  setQuickStatusTarget((prev) =>
                    prev ? { ...prev, observacao: e.target.value } : null
                  )
                }
                className="h-9 text-xs rounded-xl"
              />
            </div>

            {/* Ações */}
            <div className="flex items-center justify-end gap-2 pt-2 border-t border-border/60">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => setQuickStatusTarget(null)}
                className="rounded-xl"
              >
                Cancelar
              </Button>
              <Button
                type="button"
                size="sm"
                onClick={handleSalvarQuickStatus}
                className="gap-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold"
              >
                <Check className="w-4 h-4" />
                Confirmar
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Completo de Gestão de Presença de Veículo */}
      {veiculoModal && (
        <AttendanceModal
          isOpen={!!veiculoModal}
          onClose={() => setVeiculoModal(null)}
          veiculo={veiculoModal}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={(colabId, novoStatus, motivo, obs, subId, subNome) => {
            if (onUpdateColaboradorStatus) {
              onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, subId, subNome);
            }
          }}
        />
      )}
    </div>
  );
};

function quickTargetCargoSubtitle(target: { colaborador: Colaborador }): string {
  const c = target.colaborador;
  return `${c.cargo || 'Operador'}${c.matricula ? ` • Matrícula ${c.matricula}` : ''}`;
}

