import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Users,
  Compass,
  Sparkles,
  ShieldCheck,
  Disc,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva: Colaborador[];
  selectedRegional: Regional;
  onUpdateColaboradorStatus: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
  onSaveTeamChanges?: (veiculoId: string, assentosAtualizados: Veiculo['assentos']) => void;
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [modalColab, setModalColab] = useState<{
    colab: Colaborador;
    veiculo: Veiculo;
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
  } | null>(null);

  const getIniciais = (nome?: string) => {
    if (!nome) return 'CO';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
    return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    const searchLower = searchTerm.toLowerCase();
    const assentosLista = [
      v.assentos?.motorista,
      v.assentos?.frenteDir,
      v.assentos?.trasEsq,
      v.assentos?.trasDir,
    ].filter(Boolean) as Colaborador[];

    const matchSearch =
      !searchTerm ||
      (v.prefixo && v.prefixo.toLowerCase().includes(searchLower)) ||
      (v.placa && v.placa.toLowerCase().includes(searchLower)) ||
      (v.modelo && v.modelo.toLowerCase().includes(searchLower)) ||
      assentosLista.some(
        (c) =>
          c.nome?.toLowerCase().includes(searchLower) ||
          c.cargo?.toLowerCase().includes(searchLower) ||
          c.matricula?.toLowerCase().includes(searchLower)
      );

    const temFalta = assentosLista.some((c) => c.status === 'falta');
    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'completos' && !temFalta) ||
      (statusFilter === 'incompletos' && temFalta);

    return matchRegional && matchSearch && matchStatus;
  });

  const handleOpenAttendance = (
    colab: Colaborador,
    veiculo: Veiculo,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir'
  ) => {
    setModalColab({ colab, veiculo, posicao });
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/70 backdrop-blur-md p-3.5 rounded-2xl border border-border/70 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo, placa ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-10 text-xs sm:text-sm bg-background/60 border-border/60 rounded-xl focus-visible:ring-emerald-500/30"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="inline-flex rounded-xl p-1 bg-muted/60 border border-border/40 text-xs">
            <button
              type="button"
              onClick={() => setStatusFilter('todos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-semibold transition-all cursor-pointer',
                statusFilter === 'todos'
                  ? 'bg-card text-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos ({veiculos?.length || 0})
            </button>
            <button
              type="button"
              onClick={() => setStatusFilter('completos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-semibold transition-all cursor-pointer',
                statusFilter === 'completos'
                  ? 'bg-emerald-600 text-white shadow-sm'
                  : 'text-muted-foreground hover:text-emerald-400'
              )}
            >
              Completos
            </button>
            <button
              type="button"
              onClick={() => setStatusFilter('incompletos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-semibold transition-all cursor-pointer',
                statusFilter === 'incompletos'
                  ? 'bg-rose-600 text-white shadow-sm'
                  : 'text-muted-foreground hover:text-rose-400'
              )}
            >
              Com Faltas
            </button>
          </div>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="text-center py-16 rounded-3xl border border-dashed border-border/80 bg-card/30">
          <Car className="w-12 h-12 text-muted-foreground mx-auto mb-3 opacity-40 animate-pulse" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
            Tente redefinir os filtros de busca ou alterar a unidade regional selecionada no menu superior.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentosLista = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean) as Colaborador[];

            const faltasCount = assentosLista.filter((c) => c.status === 'falta').length;
            const subsCount = assentosLista.filter((c) => c.status === 'substituto').length;
            const temDesfalque = faltasCount > 0;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'relative overflow-hidden rounded-3xl border transition-all duration-200 shadow-md',
                  temDesfalque
                    ? 'border-rose-500/40 bg-gradient-to-b from-card via-card to-rose-950/10'
                    : 'border-border/80 bg-gradient-to-b from-card via-card to-emerald-950/5 hover:border-emerald-500/40'
                )}
              >
                {/* Header do Veículo */}
                <div className="px-5 py-4 border-b border-border/60 flex items-center justify-between gap-3 bg-muted/20">
                  <div className="flex items-center gap-3">
                    <div
                      className={cn(
                        'w-10 h-10 rounded-2xl flex items-center justify-center font-black text-sm shrink-0 border shadow-sm',
                        temDesfalque
                          ? 'bg-rose-500/15 border-rose-500/30 text-rose-400'
                          : 'bg-emerald-500/15 border-emerald-500/30 text-emerald-400'
                      )}
                    >
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-base tracking-tight text-foreground">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-[11px] font-mono font-semibold px-2 py-0.5 rounded-md bg-muted text-muted-foreground border border-border/50">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground flex items-center gap-2 mt-0.5">
                        <span>{veiculo.modelo}</span>
                        <span>•</span>
                        <span className="capitalize">{veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</span>
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {temDesfalque ? (
                      <Badge variant="destructive" className="gap-1 px-2.5 py-1 text-xs">
                        <AlertTriangle className="w-3.5 h-3.5" />
                        <span>{faltasCount} {faltasCount === 1 ? 'falta' : 'faltas'}</span>
                      </Badge>
                    ) : subsCount > 0 ? (
                      <Badge className="gap-1 px-2.5 py-1 text-xs bg-amber-500/20 text-amber-300 border-amber-500/30 border">
                        <Users className="w-3.5 h-3.5" />
                        <span>{subsCount} substituto</span>
                      </Badge>
                    ) : (
                      <Badge variant="success" className="gap-1 px-2.5 py-1 text-xs">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        <span>Completo</span>
                      </Badge>
                    )}
                  </div>
                </div>

                <CardContent className="p-4 sm:p-5 space-y-4">
                  {/* CABINE DO CARRO (Layout Imersivo: Interior do Veículo) */}
                  <div className="relative rounded-3xl border-2 border-border/70 bg-gradient-to-b from-muted/50 via-card to-muted/40 p-4 sm:p-5 shadow-inner">
                    {/* Linha do Para-brisa / Frente do Carro */}
                    <div className="relative mb-5">
                      <div className="h-6 w-3/4 mx-auto rounded-t-2xl border-t-2 border-x-2 border-border/80 bg-gradient-to-b from-sky-500/10 to-transparent flex items-center justify-center">
                        <div className="flex items-center gap-1.5 text-[10px] uppercase font-black tracking-widest text-muted-foreground/70">
                          <Compass className="w-3 h-3 text-emerald-400" />
                          <span>Frente do Veículo • Para-brisa</span>
                        </div>
                      </div>
                      <div className="w-full h-[1px] bg-border/80 shadow-sm" />

                      {/* Retrovisores externos estilizados */}
                      <div className="absolute -left-3 -top-1 w-2.5 h-6 rounded-l-md bg-muted border border-border/80 shadow-sm" />
                      <div className="absolute -right-3 -top-1 w-2.5 h-6 rounded-r-md bg-muted border border-border/80 shadow-sm" />
                    </div>

                    <div className="space-y-4">
                      {/* FILEIRA DIANTEIRA: Motorista (Esq) & Frente Dir (Dir) -> EQUIPE 1 */}
                      <div>
                        <div className="flex items-center justify-between mb-2 px-1">
                          <span className="text-[11px] font-bold uppercase tracking-wider text-emerald-400 flex items-center gap-1.5">
                            <span className="w-2 h-2 rounded-full bg-emerald-400 inline-block" />
                            Fileira da Frente • {veiculo.equipe1Codigo || 'Equipe 1'}
                          </span>
                          <span className="text-[10px] text-muted-foreground font-medium">
                            Clique no card/foto para gerenciar falta
                          </span>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {/* Assento: Motorista */}
                          <SeatCard
                            colaborador={veiculo.assentos?.motorista}
                            posicaoLabel="Motorista"
                            isMotorista
                            equipeNum={1}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.motorista &&
                              handleOpenAttendance(veiculo.assentos.motorista, veiculo, 'motorista')
                            }
                          />

                          {/* Assento: Frente Direita */}
                          <SeatCard
                            colaborador={veiculo.assentos?.frenteDir}
                            posicaoLabel="Passageiro Dianteiro"
                            isMotorista={false}
                            equipeNum={1}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.frenteDir &&
                              handleOpenAttendance(veiculo.assentos.frenteDir, veiculo, 'frenteDir')
                            }
                          />
                        </div>
                      </div>

                      {/* Divisor do Interior / Corredor entre bancos */}
                      <div className="relative py-1 flex items-center justify-center">
                        <div className="w-full border-t border-dashed border-border/60" />
                        <span className="absolute bg-card px-2.5 text-[9px] font-bold uppercase tracking-wider text-muted-foreground/60 border border-border/50 rounded-full">
                          Espaço Interno / Cabine
                        </span>
                      </div>

                      {/* FILEIRA TRASEIRA: Trás Esq & Trás Dir -> EQUIPE 2 */}
                      <div>
                        <div className="flex items-center justify-between mb-2 px-1">
                          <span className="text-[11px] font-bold uppercase tracking-wider text-teal-400 flex items-center gap-1.5">
                            <span className="w-2 h-2 rounded-full bg-teal-400 inline-block" />
                            Fileira Traseira • {veiculo.equipe2Codigo || 'Equipe 2'}
                          </span>
                          <span className="text-[10px] text-muted-foreground font-medium">
                            Banco de trás
                          </span>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {/* Assento: Trás Esquerda */}
                          <SeatCard
                            colaborador={veiculo.assentos?.trasEsq}
                            posicaoLabel="Passageiro Traseiro Esq."
                            isMotorista={false}
                            equipeNum={2}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.trasEsq &&
                              handleOpenAttendance(veiculo.assentos.trasEsq, veiculo, 'trasEsq')
                            }
                          />

                          {/* Assento: Trás Direita */}
                          <SeatCard
                            colaborador={veiculo.assentos?.trasDir}
                            posicaoLabel="Passageiro Traseiro Dir."
                            isMotorista={false}
                            equipeNum={2}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.trasDir &&
                              handleOpenAttendance(veiculo.assentos.trasDir, veiculo, 'trasDir')
                            }
                          />
                        </div>
                      </div>
                    </div>

                    {/* Traseira do Carro */}
                    <div className="mt-5 pt-2 flex items-center justify-center">
                      <div className="h-2 w-2/3 mx-auto rounded-b-xl border-b-2 border-x-2 border-border/70 bg-muted/40" />
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Falta / Presença / Substituição */}
      {modalColab && (
        <AttendanceModal
          isOpen={!!modalColab}
          onClose={() => setModalColab(null)}
          colaborador={modalColab.colab}
          veiculo={modalColab.veiculo}
          posicao={modalColab.posicao}
          colaboradoresReserva={colaboradoresReserva}
          onSalvar={(colabId, novoStatus, motivo, obs, substitutoId) => {
            onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, substitutoId);
            setModalColab(null);
          }}
        />
      )}
    </div>
  );
};

/* Componente do Card de Assento de Dentro do Carro com Foco no Quadrado da Foto */
interface SeatCardProps {
  colaborador?: Colaborador;
  posicaoLabel: string;
  isMotorista?: boolean;
  equipeNum: 1 | 2;
  getIniciais: (nome?: string) => string;
  onClick: () => void;
}

const SeatCard: React.FC<SeatCardProps> = ({
  colaborador,
  posicaoLabel,
  isMotorista = false,
  equipeNum,
  getIniciais,
  onClick,
}) => {
  const [imageError, setImageError] = useState(false);

  if (!colaborador) {
    return (
      <div className="p-3.5 rounded-2xl border border-dashed border-border/80 bg-card/40 flex items-center gap-3">
        <div className="w-14 h-14 rounded-xl bg-muted/60 border border-border/60 flex items-center justify-center text-xs text-muted-foreground font-semibold">
          Vago
        </div>
        <div>
          <p className="text-xs font-bold text-muted-foreground">{posicaoLabel}</p>
          <span className="text-[10px] text-muted-foreground/80">Assento desocupado</span>
        </div>
      </div>
    );
  }

  const isFalta = colaborador.status === 'falta';
  const isSubstituto = colaborador.status === 'substituto';
  const isPresente = colaborador.status === 'presente' || !colaborador.status;

  return (
    <div
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      className={cn(
        'group relative p-3 rounded-2xl border transition-all duration-150 cursor-pointer text-left select-none shadow-sm flex items-center gap-3.5',
        'hover:shadow-md hover:scale-[1.01] active:scale-[0.99] focus:outline-none focus:ring-2 focus:ring-emerald-500/40',
        isFalta
          ? 'bg-rose-500/10 border-rose-500/50 hover:bg-rose-500/15'
          : isSubstituto
          ? 'bg-amber-500/10 border-amber-500/50 hover:bg-amber-500/15'
          : 'bg-card/90 border-border/70 hover:border-emerald-500/40 hover:bg-card'
      )}
    >
      {/* QUADRADO DA FOTO COM DESTAQUE TOTAL E CLICÁVEL */}
      <div className="relative shrink-0">
        <div
          className={cn(
            'w-16 h-16 rounded-2xl overflow-hidden border-2 shadow-md flex items-center justify-center transition-all group-hover:ring-2',
            isFalta
              ? 'border-rose-500 ring-rose-500/40 bg-rose-950/30'
              : isSubstituto
              ? 'border-amber-500 ring-amber-500/40 bg-amber-950/30'
              : 'border-emerald-500/70 ring-emerald-500/30 bg-muted/60'
          )}
        >
          {colaborador.foto && !imageError ? (
            <img
              src={colaborador.foto}
              alt={colaborador.nome}
              onError={() => setImageError(true)}
              className={cn(
                'w-full h-full object-cover transition-transform duration-200 group-hover:scale-110',
                isFalta && 'grayscale contrast-125 opacity-70'
              )}
            />
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center bg-muted text-foreground font-black text-sm">
              <span>{getIniciais(colaborador.nome)}</span>
            </div>
          )}
        </div>

        {/* Indicador de Falta / Presença sobre a foto */}
        <div className="absolute -bottom-1 -right-1">
          {isFalta ? (
            <div className="w-5 h-5 rounded-full bg-rose-600 text-white flex items-center justify-center shadow-md ring-2 ring-card">
              <XCircle className="w-3.5 h-3.5" />
            </div>
          ) : isSubstituto ? (
            <div className="w-5 h-5 rounded-full bg-amber-500 text-black font-black text-[10px] flex items-center justify-center shadow-md ring-2 ring-card">
              S
            </div>
          ) : (
            <div className="w-5 h-5 rounded-full bg-emerald-500 text-white flex items-center justify-center shadow-md ring-2 ring-card">
              <CheckCircle2 className="w-3.5 h-3.5" />
            </div>
          )}
        </div>

        {/* Ícone de volante para o motorista no canto superior esquerdo da foto */}
        {isMotorista && (
          <div
            title="Motorista designado"
            className="absolute -top-1.5 -left-1.5 w-5 h-5 rounded-full bg-slate-900 border border-slate-700 text-amber-400 flex items-center justify-center shadow-sm"
          >
            <Disc className="w-3 h-3 animate-spin-slow" />
          </div>
        )}
      </div>

      {/* Dados do Colaborador no Assento */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1.5">
          <span
            className={cn(
              'text-[9px] font-black uppercase tracking-wider px-1.5 py-0.5 rounded',
              equipeNum === 1
                ? 'bg-emerald-500/15 text-emerald-400'
                : 'bg-teal-500/15 text-teal-400'
            )}
          >
            {isMotorista ? 'Motorista' : posicaoLabel}
          </span>
          {colaborador.matricula && (
            <span className="text-[10px] text-muted-foreground font-mono">
              #{colaborador.matricula}
            </span>
          )}
        </div>

        <p className="font-bold text-xs sm:text-sm text-foreground truncate mt-0.5 group-hover:text-emerald-400 transition-colors">
          {colaborador.nome}
        </p>

        <p className="text-[11px] text-muted-foreground truncate">
          {colaborador.cargo || 'Operador Florestal'}
        </p>

        {/* Motivo ou Status Extra */}
        {isFalta && (
          <p className="text-[10px] font-semibold text-rose-400 truncate mt-0.5 flex items-center gap-1">
            <span className="w-1.5 h-1.5 rounded-full bg-rose-500 shrink-0" />
            {colaborador.motivoFalta || 'Falta Registrada'}
          </p>
        )}

        {isSubstituto && colaborador.substitutoNome && (
          <p className="text-[10px] font-semibold text-amber-400 truncate mt-0.5 flex items-center gap-1">
            <span className="w-1.5 h-1.5 rounded-full bg-amber-500 shrink-0" />
            Subst: {colaborador.substitutoNome}
          </p>
        )}
      </div>

      {/* Botão sutil de clique rápido */}
      <div className="shrink-0 self-center hidden sm:flex items-center">
        <span
          className={cn(
            'text-[10px] font-bold px-2 py-1 rounded-lg border transition-all',
            isFalta
              ? 'border-rose-500/30 text-rose-400 bg-rose-500/10'
              : isSubstituto
              ? 'border-amber-500/30 text-amber-400 bg-amber-500/10'
              : 'border-border/60 text-muted-foreground group-hover:border-emerald-500/40 group-hover:text-emerald-400'
          )}
        >
          {isFalta ? 'Falta' : isSubstituto ? 'Substituto' : 'Presente'}
        </span>
      </div>
    </div>
  );
};

