import React, { useState } from 'react';
import {
  X,
  UserCheck,
  UserX,
  Users,
  CheckCircle2,
  AlertTriangle,
  Car,
  FileText,
  HelpCircle,
  Briefcase,
  Search,
} from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Badge } from './ui/badge';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador;
  veiculo: Veiculo;
  posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
  colaboradoresReserva: Colaborador[];
  onSalvar: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  posicao,
  colaboradoresReserva = [],
  onSalvar,
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta>(colaborador.motivoFalta || 'Atestado Médico');
  const [observacao, setObservacao] = useState<string>(colaborador.observacao || '');
  const [substitutoSelecionadoId, setSubstitutoSelecionadoId] = useState<string>(
    colaborador.substitutoId || ''
  );
  const [filtroReserva, setFiltroReserva] = useState('');
  const [fotoError, setFotoError] = useState(false);

  if (!isOpen) return null;

  const handleConfirmar = () => {
    onSalvar(
      colaborador.id,
      status,
      status === 'falta' ? motivo : undefined,
      observacao,
      status === 'substituto' ? substitutoSelecionadoId : undefined
    );
    onClose();
  };

  const reservasDisponiveis = (colaboradoresReserva || []).filter((r) => {
    if (!filtroReserva) return true;
    const q = filtroReserva.toLowerCase();
    return (
      (r.nome && r.nome.toLowerCase().includes(q)) ||
      (r.cargo && r.cargo.toLowerCase().includes(q)) ||
      (r.matricula && r.matricula.toLowerCase().includes(q))
    );
  });

  const posicaoNome =
    posicao === 'motorista'
      ? 'Motorista (Dianteiro Esq.)'
      : posicao === 'frenteDir'
      ? 'Passageiro Dianteiro Dir.'
      : posicao === 'trasEsq'
      ? 'Passageiro Traseiro Esq.'
      : 'Passageiro Traseiro Dir.';

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-xl bg-emerald-500/15 text-emerald-400 border border-emerald-500/30 flex items-center justify-center">
              <Car className="w-4 h-4" />
            </div>
            <div>
              <h2 className="text-sm font-bold text-foreground">Alterar Frequência no Veículo</h2>
              <p className="text-[11px] text-muted-foreground">
                {veiculo.prefixo} • {posicaoNome}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Corpo */}
        <div className="p-6 space-y-5 max-h-[80vh] overflow-y-auto">
          {/* Card do Colaborador em foco */}
          <div className="p-4 rounded-2xl border border-border/70 bg-muted/30 flex items-center gap-4">
            <div className="w-16 h-16 rounded-2xl overflow-hidden border-2 border-emerald-500/60 shadow-md shrink-0 bg-muted flex items-center justify-center">
              {colaborador.foto && !fotoError ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  onError={() => setFotoError(true)}
                  className="w-full h-full object-cover"
                />
              ) : (
                <span className="font-bold text-sm text-foreground">
                  {colaborador.nome.substring(0, 2).toUpperCase()}
                </span>
              )}
            </div>

            <div className="min-w-0 flex-1">
              <p className="font-bold text-sm text-foreground truncate">{colaborador.nome}</p>
              <p className="text-xs text-muted-foreground truncate">{colaborador.cargo}</p>
              <div className="flex items-center gap-2 mt-1">
                <span className="text-[10px] font-mono text-muted-foreground">
                  Matrícula: {colaborador.matricula || '---'}
                </span>
                <span className="text-[10px] text-muted-foreground">•</span>
                <span className="text-[10px] text-emerald-400 font-semibold">
                  Equipe {colaborador.equipeNumero || (posicao === 'motorista' || posicao === 'frenteDir' ? 1 : 2)}
                </span>
              </div>
            </div>
          </div>

          {/* Seleção do Status (Presente / Falta / Substituto) */}
          <div className="space-y-2">
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block">
              Selecione a Situação do Colaborador:
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                  status === 'presente'
                    ? 'bg-emerald-500/20 border-emerald-500 text-emerald-300 ring-2 ring-emerald-500/30'
                    : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <UserCheck className="w-5 h-5 text-emerald-400" />
                <span>Presente</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                  status === 'falta'
                    ? 'bg-rose-500/20 border-rose-500 text-rose-300 ring-2 ring-rose-500/30'
                    : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <UserX className="w-5 h-5 text-rose-400" />
                <span>Falta</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                  status === 'substituto'
                    ? 'bg-amber-500/20 border-amber-500 text-amber-300 ring-2 ring-amber-500/30'
                    : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <Users className="w-5 h-5 text-amber-400" />
                <span>Substituir</span>
              </button>
            </div>
          </div>

          {/* Opções quando for Falta */}
          {status === 'falta' && (
            <div className="space-y-3 p-4 rounded-2xl border border-rose-500/30 bg-rose-500/5 animate-in fade-in duration-200">
              <label className="text-xs font-semibold text-rose-300 uppercase tracking-wider block">
                Motivo da Falta
              </label>
              <div className="grid grid-cols-2 gap-2">
                {MOTIVOS_FALTA.map((m) => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setMotivo(m)}
                    className={cn(
                      'p-2.5 rounded-xl border text-left text-xs font-medium transition-all cursor-pointer',
                      motivo === m
                        ? 'bg-rose-500/25 border-rose-500 text-rose-200 font-bold'
                        : 'border-border/60 bg-card/60 text-muted-foreground hover:bg-card'
                    )}
                  >
                    {m}
                  </button>
                ))}
              </div>

              <div>
                <label className="text-[11px] font-semibold text-muted-foreground block mb-1">
                  Observações ou Detalhes adicionais (opcional)
                </label>
                <Input
                  placeholder="Ex: Avisou a liderança, atestado de 2 dias..."
                  value={observacao}
                  onChange={(e) => setObservacao(e.target.value)}
                  className="h-9 text-xs"
                />
              </div>
            </div>
          )}

          {/* Opções quando for Substituto */}
          {status === 'substituto' && (
            <div className="space-y-3 p-4 rounded-2xl border border-amber-500/30 bg-amber-500/5 animate-in fade-in duration-200">
              <label className="text-xs font-semibold text-amber-300 uppercase tracking-wider block">
                Escolha o Colaborador Reserva para Assumir o Assento
              </label>

              <div className="relative">
                <Search className="w-3.5 h-3.5 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
                <Input
                  placeholder="Buscar no banco de reservas..."
                  value={filtroReserva}
                  onChange={(e) => setFiltroReserva(e.target.value)}
                  className="pl-8 h-8 text-xs bg-card/80"
                />
              </div>

              <div className="max-h-48 overflow-y-auto space-y-2 pr-1">
                {reservasDisponiveis.length === 0 ? (
                  <p className="text-xs text-muted-foreground text-center py-4">
                    Nenhum colaborador reserva encontrado.
                  </p>
                ) : (
                  reservasDisponiveis.map((reserva) => {
                    const isSelected = substitutoSelecionadoId === reserva.id;
                    return (
                      <div
                        key={reserva.id}
                        onClick={() => setSubstitutoSelecionadoId(reserva.id)}
                        className={cn(
                          'p-2.5 rounded-xl border flex items-center justify-between gap-3 cursor-pointer transition-all',
                          isSelected
                            ? 'bg-amber-500/20 border-amber-500 text-amber-200'
                            : 'border-border/60 bg-card/60 hover:bg-card text-foreground'
                        )}
                      >
                        <div className="flex items-center gap-2.5 min-w-0">
                          <div className="w-8 h-8 rounded-lg overflow-hidden border border-border/80 shrink-0 bg-muted flex items-center justify-center text-xs font-bold">
                            {reserva.foto ? (
                              <img src={reserva.foto} alt={reserva.nome} className="w-full h-full object-cover" />
                            ) : (
                              reserva.nome.substring(0, 2).toUpperCase()
                            )}
                          </div>
                          <div className="min-w-0">
                            <p className="font-bold text-xs truncate">{reserva.nome}</p>
                            <p className="text-[10px] text-muted-foreground truncate">{reserva.cargo}</p>
                          </div>
                        </div>

                        {isSelected && <CheckCircle2 className="w-4 h-4 text-amber-400 shrink-0" />}
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          )}
        </div>

        {/* Rodapé com Ações */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-border/60 bg-muted/10">
          <Button type="button" variant="outline" size="sm" onClick={onClose} className="rounded-xl">
            Cancelar
          </Button>
          <Button
            type="button"
            size="sm"
            onClick={handleConfirmar}
            className="rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-semibold gap-1.5 shadow-md"
          >
            <CheckCircle2 className="w-4 h-4" />
            Salvar Registro
          </Button>
        </div>
      </div>
    </div>
  );
};

files.oldContent:
import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Users,
  Compass,
  Sparkles,
  ShieldCheck,
  Disc,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva: Colaborador[];
  selectedRegional: Regional;
  onUpdateColaboradorStatus: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
  onSaveTeamChanges?: (veiculoId: string, assentosAtualizados: Veiculo['assentos']) => void;
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [modalColab, setModalColab] = useState<{
    colab: Colaborador;
    veiculo: Veiculo;
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
  } | null>(null);

  const getIniciais = (nome?: string) => {
    if (!nome) return 'CO';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
    return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    const searchLower = searchTerm.toLowerCase();
    const assentosLista = [
      v.assentos?.motorista,
      v.assentos?.frenteDir,
      v.assentos?.trasEsq,
      v.assentos?.trasDir,
    ].filter(Boolean) as Colaborador[];

    const matchSearch =
      !searchTerm ||
      (v.prefixo && v.prefixo.toLowerCase().includes(searchLower)) ||
      (v.placa && v.placa.toLowerCase().includes(searchLower)) ||
      (v.modelo && v.modelo.toLowerCase().includes(searchLower)) ||
      assentosLista.some(
        (c) =>
          c.nome?.toLowerCase().includes(searchLower) ||
          c.cargo?.toLowerCase().includes(searchLower) ||
          c.matricula?.toLowerCase().includes(searchLower)
      );

    const temFalta = assentosLista.some((c) => c.status === 'falta');
    const matchStatus =
      statusFilter === 'todos' ||
      (statusFilter === 'completos' && !temFalta) ||
      (statusFilter === 'incompletos' && temFalta);

    return matchRegional && matchSearch && matchStatus;
  });

  const handleOpenAttendance = (
    colab: Colaborador,
    veiculo: Veiculo,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir'
  ) => {
    setModalColab({ colab, veiculo, posicao });
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/70 backdrop-blur-md p-3.5 rounded-2xl border border-border/70 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo, placa ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-10 text-xs sm:text-sm bg-background/60 border-border/60 rounded-xl focus-visible:ring-emerald-500/30"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="inline-flex rounded-xl p-1 bg-muted/60 border border-border/40 text-xs">
            <button
              type="button"
              onClick={() => setStatusFilter('todos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-semibold transition-all cursor-pointer',
                statusFilter === 'todos'
                  ? 'bg-card text-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos ({veiculos?.length || 0})
            </button>
            <button
              type="button"
              onClick={() => setStatusFilter('completos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-semibold transition-all cursor-pointer',
                statusFilter === 'completos'
                  ? 'bg-emerald-600 text-white shadow-sm'
                  : 'text-muted-foreground hover:text-emerald-400'
              )}
            >
              Completos
            </button>
            <button
              type="button"
              onClick={() => setStatusFilter('incompletos')}
              className={cn(
                'px-3 py-1.5 rounded-lg font-semibold transition-all cursor-pointer',
                statusFilter === 'incompletos'
                  ? 'bg-rose-600 text-white shadow-sm'
                  : 'text-muted-foreground hover:text-rose-400'
              )}
            >
              Com Faltas
            </button>
          </div>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="text-center py-16 rounded-3xl border border-dashed border-border/80 bg-card/30">
          <Car className="w-12 h-12 text-muted-foreground mx-auto mb-3 opacity-40 animate-pulse" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
            Tente redefinir os filtros de busca ou alterar a unidade regional selecionada no menu superior.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentosLista = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean) as Colaborador[];

            const faltasCount = assentosLista.filter((c) => c.status === 'falta').length;
            const subsCount = assentosLista.filter((c) => c.status === 'substituto').length;
            const temDesfalque = faltasCount > 0;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'relative overflow-hidden rounded-3xl border transition-all duration-200 shadow-md',
                  temDesfalque
                    ? 'border-rose-500/40 bg-gradient-to-b from-card via-card to-rose-950/10'
                    : 'border-border/80 bg-gradient-to-b from-card via-card to-emerald-950/5 hover:border-emerald-500/40'
                )}
              >
                {/* Header do Veículo */}
                <div className="px-5 py-4 border-b border-border/60 flex items-center justify-between gap-3 bg-muted/20">
                  <div className="flex items-center gap-3">
                    <div
                      className={cn(
                        'w-10 h-10 rounded-2xl flex items-center justify-center font-black text-sm shrink-0 border shadow-sm',
                        temDesfalque
                          ? 'bg-rose-500/15 border-rose-500/30 text-rose-400'
                          : 'bg-emerald-500/15 border-emerald-500/30 text-emerald-400'
                      )}
                    >
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-base tracking-tight text-foreground">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-[11px] font-mono font-semibold px-2 py-0.5 rounded-md bg-muted text-muted-foreground border border-border/50">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground flex items-center gap-2 mt-0.5">
                        <span>{veiculo.modelo}</span>
                        <span>•</span>
                        <span className="capitalize">{veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</span>
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {temDesfalque ? (
                      <Badge variant="destructive" className="gap-1 px-2.5 py-1 text-xs">
                        <AlertTriangle className="w-3.5 h-3.5" />
                        <span>{faltasCount} {faltasCount === 1 ? 'falta' : 'faltas'}</span>
                      </Badge>
                    ) : subsCount > 0 ? (
                      <Badge className="gap-1 px-2.5 py-1 text-xs bg-amber-500/20 text-amber-300 border-amber-500/30 border">
                        <Users className="w-3.5 h-3.5" />
                        <span>{subsCount} substituto</span>
                      </Badge>
                    ) : (
                      <Badge variant="success" className="gap-1 px-2.5 py-1 text-xs">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        <span>Completo</span>
                      </Badge>
                    )}
                  </div>
                </div>

                <CardContent className="p-4 sm:p-5 space-y-4">
                  {/* CABINE DO CARRO (Layout Imersivo: Interior do Veículo) */}
                  <div className="relative rounded-3xl border-2 border-border/70 bg-gradient-to-b from-muted/50 via-card to-muted/40 p-4 sm:p-5 shadow-inner">
                    {/* Linha do Para-brisa / Frente do Carro */}
                    <div className="relative mb-5">
                      <div className="h-6 w-3/4 mx-auto rounded-t-2xl border-t-2 border-x-2 border-border/80 bg-gradient-to-b from-sky-500/10 to-transparent flex items-center justify-center">
                        <div className="flex items-center gap-1.5 text-[10px] uppercase font-black tracking-widest text-muted-foreground/70">
                          <Compass className="w-3 h-3 text-emerald-400" />
                          <span>Frente do Veículo • Para-brisa</span>
                        </div>
                      </div>
                      <div className="w-full h-[1px] bg-border/80 shadow-sm" />

                      {/* Retrovisores externos estilizados */}
                      <div className="absolute -left-3 -top-1 w-2.5 h-6 rounded-l-md bg-muted border border-border/80 shadow-sm" />
                      <div className="absolute -right-3 -top-1 w-2.5 h-6 rounded-r-md bg-muted border border-border/80 shadow-sm" />
                    </div>

                    <div className="space-y-4">
                      {/* FILEIRA DIANTEIRA: Motorista (Esq) & Frente Dir (Dir) -> EQUIPE 1 */}
                      <div>
                        <div className="flex items-center justify-between mb-2 px-1">
                          <span className="text-[11px] font-bold uppercase tracking-wider text-emerald-400 flex items-center gap-1.5">
                            <span className="w-2 h-2 rounded-full bg-emerald-400 inline-block" />
                            Fileira da Frente • {veiculo.equipe1Codigo || 'Equipe 1'}
                          </span>
                          <span className="text-[10px] text-muted-foreground font-medium">
                            Clique no card/foto para gerenciar falta
                          </span>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {/* Assento: Motorista */}
                          <SeatCard
                            colaborador={veiculo.assentos?.motorista}
                            posicaoLabel="Motorista"
                            isMotorista
                            equipeNum={1}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.motorista &&
                              handleOpenAttendance(veiculo.assentos.motorista, veiculo, 'motorista')
                            }
                          />

                          {/* Assento: Frente Direita */}
                          <SeatCard
                            colaborador={veiculo.assentos?.frenteDir}
                            posicaoLabel="Passageiro Dianteiro"
                            isMotorista={false}
                            equipeNum={1}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.frenteDir &&
                              handleOpenAttendance(veiculo.assentos.frenteDir, veiculo, 'frenteDir')
                            }
                          />
                        </div>
                      </div>

                      {/* Divisor do Interior / Corredor entre bancos */}
                      <div className="relative py-1 flex items-center justify-center">
                        <div className="w-full border-t border-dashed border-border/60" />
                        <span className="absolute bg-card px-2.5 text-[9px] font-bold uppercase tracking-wider text-muted-foreground/60 border border-border/50 rounded-full">
                          Espaço Interno / Cabine
                        </span>
                      </div>

                      {/* FILEIRA TRASEIRA: Trás Esq & Trás Dir -> EQUIPE 2 */}
                      <div>
                        <div className="flex items-center justify-between mb-2 px-1">
                          <span className="text-[11px] font-bold uppercase tracking-wider text-teal-400 flex items-center gap-1.5">
                            <span className="w-2 h-2 rounded-full bg-teal-400 inline-block" />
                            Fileira Traseira • {veiculo.equipe2Codigo || 'Equipe 2'}
                          </span>
                          <span className="text-[10px] text-muted-foreground font-medium">
                            Banco de trás
                          </span>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {/* Assento: Trás Esquerda */}
                          <SeatCard
                            colaborador={veiculo.assentos?.trasEsq}
                            posicaoLabel="Passageiro Traseiro Esq."
                            isMotorista={false}
                            equipeNum={2}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.trasEsq &&
                              handleOpenAttendance(veiculo.assentos.trasEsq, veiculo, 'trasEsq')
                            }
                          />

                          {/* Assento: Trás Direita */}
                          <SeatCard
                            colaborador={veiculo.assentos?.trasDir}
                            posicaoLabel="Passageiro Traseiro Dir."
                            isMotorista={false}
                            equipeNum={2}
                            getIniciais={getIniciais}
                            onClick={() =>
                              veiculo.assentos?.trasDir &&
                              handleOpenAttendance(veiculo.assentos.trasDir, veiculo, 'trasDir')
                            }
                          />
                        </div>
                      </div>
                    </div>

                    {/* Traseira do Carro */}
                    <div className="mt-5 pt-2 flex items-center justify-center">
                      <div className="h-2 w-2/3 mx-auto rounded-b-xl border-b-2 border-x-2 border-border/70 bg-muted/40" />
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Falta / Presença / Substituição */}
      {modalColab && (
        <AttendanceModal
          isOpen={!!modalColab}
          onClose={() => setModalColab(null)}
          colaborador={modalColab.colab}
          veiculo={modalColab.veiculo}
          posicao={modalColab.posicao}
          colaboradoresReserva={colaboradoresReserva}
          onSalvar={(colabId, novoStatus, motivo, obs, substitutoId) => {
            onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, substitutoId);
            setModalColab(null);
          }}
        />
      )}
    </div>
  );
};

/* Componente do Card de Assento de Dentro do Carro com Foco no Quadrado da Foto */
interface SeatCardProps {
  colaborador?: Colaborador;
  posicaoLabel: string;
  isMotorista?: boolean;
  equipeNum: 1 | 2;
  getIniciais: (nome?: string) => string;
  onClick: () => void;
}

const SeatCard: React.FC<SeatCardProps> = ({
  colaborador,
  posicaoLabel,
  isMotorista = false,
  equipeNum,
  getIniciais,
  onClick,
}) => {
  const [imageError, setImageError] = useState(false);

  if (!colaborador) {
    return (
      <div className="p-3.5 rounded-2xl border border-dashed border-border/80 bg-card/40 flex items-center gap-3">
        <div className="w-14 h-14 rounded-xl bg-muted/60 border border-border/60 flex items-center justify-center text-xs text-muted-foreground font-semibold">
          Vago
        </div>
        <div>
          <p className="text-xs font-bold text-muted-foreground">{posicaoLabel}</p>
          <span className="text-[10px] text-muted-foreground/80">Assento desocupado</span>
        </div>
      </div>
    );
  }

  const isFalta = colaborador.status === 'falta';
  const isSubstituto = colaborador.status === 'substituto';
  const isPresente = colaborador.status === 'presente' || !colaborador.status;

  return (
    <div
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      className={cn(
        'group relative p-3 rounded-2xl border transition-all duration-150 cursor-pointer text-left select-none shadow-sm flex items-center gap-3.5',
        'hover:shadow-md hover:scale-[1.01] active:scale-[0.99] focus:outline-none focus:ring-2 focus:ring-emerald-500/40',
        isFalta
          ? 'bg-rose-500/10 border-rose-500/50 hover:bg-rose-500/15'
          : isSubstituto
          ? 'bg-amber-500/10 border-amber-500/50 hover:bg-amber-500/15'
          : 'bg-card/90 border-border/70 hover:border-emerald-500/40 hover:bg-card'
      )}
    >
      {/* QUADRADO DA FOTO COM DESTAQUE TOTAL E CLICÁVEL */}
      <div className="relative shrink-0">
        <div
          className={cn(
            'w-16 h-16 rounded-2xl overflow-hidden border-2 shadow-md flex items-center justify-center transition-all group-hover:ring-2',
            isFalta
              ? 'border-rose-500 ring-rose-500/40 bg-rose-950/30'
              : isSubstituto
              ? 'border-amber-500 ring-amber-500/40 bg-amber-950/30'
              : 'border-emerald-500/70 ring-emerald-500/30 bg-muted/60'
          )}
        >
          {colaborador.foto && !imageError ? (
            <img
              src={colaborador.foto}
              alt={colaborador.nome}
              onError={() => setImageError(true)}
              className={cn(
                'w-full h-full object-cover transition-transform duration-200 group-hover:scale-110',
                isFalta && 'grayscale contrast-125 opacity-70'
              )}
            />
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center bg-muted text-foreground font-black text-sm">
              <span>{getIniciais(colaborador.nome)}</span>
            </div>
          )}
        </div>

        {/* Indicador de Falta / Presença sobre a foto */}
        <div className="absolute -bottom-1 -right-1">
          {isFalta ? (
            <div className="w-5 h-5 rounded-full bg-rose-600 text-white flex items-center justify-center shadow-md ring-2 ring-card">
              <XCircle className="w-3.5 h-3.5" />
            </div>
          ) : isSubstituto ? (
            <div className="w-5 h-5 rounded-full bg-amber-500 text-black font-black text-[10px] flex items-center justify-center shadow-md ring-2 ring-card">
              S
            </div>
          ) : (
            <div className="w-5 h-5 rounded-full bg-emerald-500 text-white flex items-center justify-center shadow-md ring-2 ring-card">
              <CheckCircle2 className="w-3.5 h-3.5" />
            </div>
          )}
        </div>

        {/* Ícone de volante para o motorista no canto superior esquerdo da foto */}
        {isMotorista && (
          <div
            title="Motorista designado"
            className="absolute -top-1.5 -left-1.5 w-5 h-5 rounded-full bg-slate-900 border border-slate-700 text-amber-400 flex items-center justify-center shadow-sm"
          >
            <Disc className="w-3 h-3 animate-spin-slow" />
          </div>
        )}
      </div>

      {/* Dados do Colaborador no Assento */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1.5">
          <span
            className={cn(
              'text-[9px] font-black uppercase tracking-wider px-1.5 py-0.5 rounded',
              equipeNum === 1
                ? 'bg-emerald-500/15 text-emerald-400'
                : 'bg-teal-500/15 text-teal-400'
            )}
          >
            {isMotorista ? 'Motorista' : posicaoLabel}
          </span>
          {colaborador.matricula && (
            <span className="text-[10px] text-muted-foreground font-mono">
              #{colaborador.matricula}
            </span>
          )}
        </div>

        <p className="font-bold text-xs sm:text-sm text-foreground truncate mt-0.5 group-hover:text-emerald-400 transition-colors">
          {colaborador.nome}
        </p>

        <p className="text-[11px] text-muted-foreground truncate">
          {colaborador.cargo || 'Operador Florestal'}
        </p>

        {/* Motivo ou Status Extra */}
        {isFalta && (
          <p className="text-[10px] font-semibold text-rose-400 truncate mt-0.5 flex items-center gap-1">
            <span className="w-1.5 h-1.5 rounded-full bg-rose-500 shrink-0" />
            {colaborador.motivoFalta || 'Falta Registrada'}
          </p>
        )}

        {isSubstituto && colaborador.substitutoNome && (
          <p className="text-[10px] font-semibold text-amber-400 truncate mt-0.5 flex items-center gap-1">
            <span className="w-1.5 h-1.5 rounded-full bg-amber-500 shrink-0" />
            Subst: {colaborador.substitutoNome}
          </p>
        )}
      </div>

      {/* Botão sutil de clique rápido */}
      <div className="shrink-0 self-center hidden sm:flex items-center">
        <span
          className={cn(
            'text-[10px] font-bold px-2 py-1 rounded-lg border transition-all',
            isFalta
              ? 'border-rose-500/30 text-rose-400 bg-rose-500/10'
              : isSubstituto
              ? 'border-amber-500/30 text-amber-400 bg-amber-500/10'
              : 'border-border/60 text-muted-foreground group-hover:border-emerald-500/40 group-hover:text-emerald-400'
          )}
        >
          {isFalta ? 'Falta' : isSubstituto ? 'Substituto' : 'Presente'}
        </span>
      </div>
    </div>
  );
};

files.newContent:
import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Users,
  Compass,
  Sparkles,
  Phone,
  UserCheck,
  UserX,
  RefreshCw,
  Clock,
  ChevronRight,
  ShieldAlert,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSubstituirColaborador?: (
    colabTitularId: string,
    colabSubstituto: Colaborador
  ) => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; bg: string; text: string; border: string; icon: any }> = {
  presente: {
    label: 'Presente',
    bg: 'bg-emerald-500/15',
    text: 'text-emerald-400',
    border: 'border-emerald-500/30',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    bg: 'bg-rose-500/15',
    text: 'text-rose-400',
    border: 'border-rose-500/30',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    bg: 'bg-amber-500/15',
    text: 'text-amber-400',
    border: 'border-amber-500/30',
    icon: AlertTriangle,
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onSubstituirColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [filterStatus, setFilterStatus] = useState<'todos' | 'completos' | 'desfalque'>('todos');

  // Estado para o modal de presença/substituição
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoDoColaborador, setVeiculoDoColaborador] = useState<Veiculo | null>(null);
  const [modalPresencaAberto, setModalPresencaAberto] = useState(false);

  const handleAbrirPresenca = (colab: Colaborador, veiculo: Veiculo) => {
    setColaboradorSelecionado(colab);
    setVeiculoDoColaborador(veiculo);
    setModalPresencaAberto(true);
  };

  const handleSalvarPresenca = (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, substitutoId, substitutoNome);
    }
    setModalPresencaAberto(false);
  };

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = filterRegional === 'todas' || v.regional === filterRegional;

    const termo = search.toLowerCase();
    const assentosLista = v.assentos
      ? [v.assentos.motorista, v.assentos.frenteDir, v.assentos.trasEsq, v.assentos.trasDir].filter(Boolean)
      : [];

    const matchSearch =
      !search ||
      v.prefixo.toLowerCase().includes(termo) ||
      v.placa.toLowerCase().includes(termo) ||
      v.modelo.toLowerCase().includes(termo) ||
      assentosLista.some(
        (c) =>
          c.nome.toLowerCase().includes(termo) ||
          c.cargo.toLowerCase().includes(termo) ||
          c.matricula.toLowerCase().includes(termo)
      );

    const temFalta = assentosLista.some((c) => c.status === 'falta');
    let matchStatus = true;
    if (filterStatus === 'completos') matchStatus = !temFalta;
    if (filterStatus === 'desfalque') matchStatus = temFalta;

    return matchRegional && matchSearch && matchStatus;
  });

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-3.5 rounded-2xl border border-border/60 backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo por prefixo, placa ou nome do operador..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-10 text-xs bg-background/60 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={filterRegional}
            onChange={(e) => setFilterRegional(e.target.value as any)}
            className="h-10 px-3 rounded-xl border border-border/60 bg-background/60 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Unidades</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>

          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
            className="h-10 px-3 rounded-xl border border-border/60 bg-background/60 text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Veículos</option>
            <option value="completos">Equipes Completas</option>
            <option value="desfalque">Com Falta / Desfalque</option>
          </select>
        </div>
      </div>

      {/* Grid de Veículos com Visão Superior (Top-down Car View) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20">
            <Car className="w-10 h-10 text-muted-foreground mx-auto mb-3 opacity-40 animate-pulse" />
            <h3 className="text-base font-semibold text-foreground">Nenhum veículo encontrado</h3>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Não encontramos nenhum veículo correspondente aos filtros de pesquisa atuais.
            </p>
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const assentos = veiculo.assentos;
            const motorista = assentos?.motorista;
            const frenteDir = assentos?.frenteDir;
            const trasEsq = assentos?.trasEsq;
            const trasDir = assentos?.trasDir;

            const todosAssentos = [motorista, frenteDir, trasEsq, trasDir].filter(Boolean) as Colaborador[];
            const faltasCount = todosAssentos.filter((c) => c.status === 'falta').length;
            const substitutosCount = todosAssentos.filter((c) => c.status === 'substituto').length;
            const temDesfalque = faltasCount > 0;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'relative rounded-3xl border transition-all duration-200 overflow-hidden shadow-xl hover:shadow-2xl',
                  temDesfalque
                    ? 'border-rose-500/40 bg-gradient-to-b from-card via-card to-rose-950/10'
                    : 'border-border/70 bg-gradient-to-b from-card to-card/70'
                )}
              >
                {/* Cabeçalho do Veículo */}
                <div className="px-5 py-4 border-b border-border/50 bg-muted/20 flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div
                      className={cn(
                        'w-10 h-10 rounded-2xl flex items-center justify-center font-bold text-xs shadow-md border',
                        temDesfalque
                          ? 'bg-rose-500/15 border-rose-500/30 text-rose-400'
                          : 'bg-emerald-500/15 border-emerald-500/30 text-emerald-400'
                      )}
                    >
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-base tracking-tight text-foreground">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-[11px] font-semibold font-mono px-2 py-0.5 rounded-md bg-background/80 border border-border/80 text-muted-foreground uppercase">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground flex items-center gap-1.5 mt-0.5">
                        <span>{veiculo.modelo}</span>
                        <span>•</span>
                        <span className="capitalize">
                          {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                        </span>
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-1.5">
                    {temDesfalque ? (
                      <Badge
                        variant="destructive"
                        className="gap-1 text-[11px] font-bold px-2.5 py-1 rounded-full shadow-sm"
                      >
                        <ShieldAlert className="w-3.5 h-3.5" />
                        {faltasCount} {faltasCount === 1 ? 'Falta' : 'Faltas'}
                      </Badge>
                    ) : (
                      <Badge
                        variant="outline"
                        className="gap-1 text-[11px] font-bold px-2.5 py-1 rounded-full bg-emerald-500/10 text-emerald-400 border-emerald-500/30 shadow-sm"
                      >
                        <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                        Completo
                      </Badge>
                    )}
                  </div>
                </div>

                {/* VISÃO DE CIMA DO CARRO (TOP-DOWN VEHICLE VIEW) */}
                <div className="p-4 sm:p-5">
                  <div className="flex items-center justify-between text-xs font-semibold text-muted-foreground mb-3 px-1">
                    <span className="flex items-center gap-1.5">
                      <Compass className="w-3.5 h-3.5 text-emerald-400" />
                      Visão Superior da Cabine
                    </span>
                    <span className="text-[11px] text-muted-foreground/80">
                      Toque na foto para definir falta ou substituição
                    </span>
                  </div>

                  {/* Carroceria Estilizada Vista de Cima */}
                  <div className="relative mx-auto max-w-xl rounded-[2.5rem] p-3 sm:p-4 bg-gradient-to-b from-slate-900/90 via-slate-900/60 to-slate-950/90 border-2 border-slate-700/60 shadow-2xl overflow-hidden">
                    {/* Retrovisores Externos Vistos de Cima */}
                    <div className="absolute top-16 -left-1.5 w-3 h-7 rounded-l-full bg-slate-700 border border-slate-600 shadow-md" />
                    <div className="absolute top-16 -right-1.5 w-3 h-7 rounded-r-full bg-slate-700 border border-slate-600 shadow-md" />

                    {/* Para-brisa Dianteiro Arredondado com Reflexo */}
                    <div className="relative mb-3.5 mx-auto w-11/12 rounded-t-[2rem] rounded-b-xl h-11 bg-gradient-to-b from-sky-400/20 via-sky-500/10 to-transparent border-t-2 border-x-2 border-sky-400/30 flex items-center justify-between px-6 shadow-inner">
                      {/* Pequeno Volante Minimalista no lado esquerdo (motorista) */}
                      <div className="flex items-center gap-1.5">
                        <div className="w-6 h-6 rounded-full border-2 border-amber-400/80 bg-slate-950/80 flex items-center justify-center shadow-md">
                          <div className="w-2 h-2 rounded-full bg-amber-400/90" />
                        </div>
                        <span className="text-[10px] font-bold text-amber-300 tracking-wider uppercase">Frente</span>
                      </div>
                      <span className="text-[10px] text-muted-foreground/60 font-mono tracking-widest uppercase">
                        Para-brisa
                      </span>
                    </div>

                    {/* Espaço Interno da Cabine: 2 Fileiras de Assentos */}
                    <div className="space-y-3.5">
                      {/* FILEIRA 1 (DIANTEIRA) - Equipe 1 */}
                      <div>
                        <div className="flex items-center justify-between px-2 mb-1.5">
                          <span className="text-[11px] font-bold tracking-tight text-emerald-400 flex items-center gap-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                            {veiculo.equipe1Codigo || 'Equipe 1 (Frente)'}
                          </span>
                          <span className="text-[10px] font-medium text-muted-foreground">Assentos 1 & 2</span>
                        </div>

                        <div className="grid grid-cols-2 gap-3 sm:gap-4">
                          {/* Motorista (Frente Esquerda) */}
                          {motorista && (
                            <AssentoCarroCard
                              colaborador={motorista}
                              posicaoLabel="Motorista"
                              isDriver={true}
                              onClick={() => handleAbrirPresenca(motorista, veiculo)}
                            />
                          )}

                          {/* Frente Direita (Carona Dianteiro) */}
                          {frenteDir && (
                            <AssentoCarroCard
                              colaborador={frenteDir}
                              posicaoLabel="Passageiro Diant."
                              isDriver={false}
                              onClick={() => handleAbrirPresenca(frenteDir, veiculo)}
                            />
                          )}
                        </div>
                      </div>

                      {/* Divisor sutil do vão central dos bancos */}
                      <div className="relative flex items-center justify-center my-1">
                        <div className="w-full border-t border-slate-700/60" />
                        <span className="absolute px-3 text-[10px] uppercase font-bold tracking-widest text-slate-400 bg-slate-900 border border-slate-700/70 rounded-full">
                          Corredor Central
                        </span>
                      </div>

                      {/* FILEIRA 2 (TRASEIRA) - Equipe 2 */}
                      <div>
                        <div className="flex items-center justify-between px-2 mb-1.5">
                          <span className="text-[11px] font-bold tracking-tight text-teal-400 flex items-center gap-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-teal-400" />
                            {veiculo.equipe2Codigo || 'Equipe 2 (Traseira)'}
                          </span>
                          <span className="text-[10px] font-medium text-muted-foreground">Assentos 3 & 4</span>
                        </div>

                        <div className="grid grid-cols-2 gap-3 sm:gap-4">
                          {/* Traseira Esquerda */}
                          {trasEsq && (
                            <AssentoCarroCard
                              colaborador={trasEsq}
                              posicaoLabel="Traseiro Esq."
                              isDriver={false}
                              onClick={() => handleAbrirPresenca(trasEsq, veiculo)}
                            />
                          )}

                          {/* Traseira Direita */}
                          {trasDir && (
                            <AssentoCarroCard
                              colaborador={trasDir}
                              posicaoLabel="Traseiro Dir."
                              isDriver={false}
                              onClick={() => handleAbrirPresenca(trasDir, veiculo)}
                            />
                          )}
                        </div>
                      </div>
                    </div>

                    {/* Vidro Traseiro Arredondado */}
                    <div className="mt-3.5 mx-auto w-11/12 rounded-b-[2rem] rounded-t-xl h-8 bg-gradient-to-t from-sky-400/15 via-sky-500/5 to-transparent border-b-2 border-x-2 border-sky-400/30 flex items-center justify-center shadow-inner">
                      <span className="text-[10px] text-muted-foreground/60 font-mono tracking-widest uppercase">
                        Traseira / Bagageiro
                      </span>
                    </div>
                  </div>
                </div>
              </Card>
            );
          })
        )}
      </div>

      {/* Modal de Gestão de Faltas & Substituição */}
      {colaboradorSelecionado && veiculoDoColaborador && (
        <AttendanceModal
          isOpen={modalPresencaAberto}
          onClose={() => setModalPresencaAberto(false)}
          colaborador={colaboradorSelecionado}
          veiculoPrefixo={veiculoDoColaborador.prefixo}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={handleSalvarPresenca}
        />
      )}
    </div>
  );
};

/* COMPONENTE INTERNO: ASSENTO VISTO DE CIMA DO CARRO COM A FOTO EM DESTAQUE */
interface AssentoCarroCardProps {
  colaborador: Colaborador;
  posicaoLabel: string;
  isDriver?: boolean;
  onClick: () => void;
}

const AssentoCarroCard: React.FC<AssentoCarroCardProps> = ({
  colaborador,
  posicaoLabel,
  isDriver = false,
  onClick,
}) => {
  const statusInfo = statusBadgeConfig[colaborador.status] || statusBadgeConfig.presente;
  const StatusIcon = statusInfo.icon;
  const isFalta = colaborador.status === 'falta';
  const isSubstituto = colaborador.status === 'substituto';

  return (
    <div
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      className={cn(
        'group relative rounded-2xl p-2.5 sm:p-3 cursor-pointer select-none transition-all duration-200 text-left',
        'border shadow-lg hover:shadow-xl hover:scale-[1.02] active:scale-[0.98]',
        // Simulação do contorno anatômico de um assento automotivo visto de cima
        'bg-slate-900/90 hover:bg-slate-850',
        isFalta
          ? 'border-rose-500/50 bg-rose-950/20 ring-2 ring-rose-500/20'
          : isSubstituto
          ? 'border-amber-500/50 bg-amber-950/20 ring-2 ring-amber-500/20'
          : 'border-slate-700 hover:border-emerald-500/50'
      )}
    >
      {/* Encosto de Cabeça do Assento Automotivo (Topo Visto de Cima) */}
      <div className="w-12 h-2.5 mx-auto mb-2 rounded-t-lg bg-slate-800 border-t border-x border-slate-600/60 shadow-sm" />

      {/* Conteúdo do Assento */}
      <div className="flex items-center gap-3">
        {/* Quadrado / Avatar com FOTO DO COLABORADOR */}
        <div className="relative shrink-0">
          <div
            className={cn(
              'w-14 h-14 sm:w-16 sm:h-16 rounded-xl overflow-hidden border-2 shadow-md transition-all duration-200 flex items-center justify-center',
              isFalta
                ? 'border-rose-500 ring-2 ring-rose-500/30'
                : isSubstituto
                ? 'border-amber-400 ring-2 ring-amber-400/30'
                : 'border-emerald-500 ring-2 ring-emerald-500/20'
            )}
          >
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className={cn(
                  'w-full h-full object-cover transition-transform duration-200 group-hover:scale-110',
                  isFalta && 'grayscale opacity-60'
                )}
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full bg-slate-800 text-foreground font-bold text-base flex items-center justify-center">
                {getIniciais(colaborador.nome)}
              </div>
            )}
          </div>

          {/* Badge Ícone de Status sobre a foto */}
          <div
            className={cn(
              'absolute -bottom-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center border-2 border-slate-900 shadow-md',
              statusInfo.bg,
              statusInfo.border,
              statusInfo.text
            )}
          >
            <StatusIcon className="w-3 h-3" />
          </div>
        </div>

        {/* Dados do Colaborador no Assento */}
        <div className="min-w-0 flex-1 space-y-1">
          <div className="flex items-center gap-1.5">
            <span
              className={cn(
                'text-[10px] font-bold uppercase px-1.5 py-0.5 rounded tracking-wider',
                isDriver
                  ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30'
                  : 'bg-slate-800 text-slate-300 border border-slate-700'
              )}
            >
              {posicaoLabel}
            </span>
          </div>

          <h4
            className={cn(
              'text-xs sm:text-sm font-bold truncate leading-tight transition-colors group-hover:text-emerald-300',
              isFalta ? 'text-rose-300 line-through' : 'text-foreground'
            )}
          >
            {colaborador.nome}
          </h4>

          <p className="text-[11px] text-muted-foreground truncate">{colaborador.cargo}</p>

          {/* Status ou Substituto */}
          <div className="pt-0.5">
            {isFalta && colaborador.motivoFalta ? (
              <span className="text-[10px] font-semibold text-rose-400 bg-rose-500/10 px-1.5 py-0.5 rounded border border-rose-500/20 block truncate">
                {colaborador.motivoFalta}
              </span>
            ) : isSubstituto && colaborador.substitutoNome ? (
              <span className="text-[10px] font-semibold text-amber-300 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20 block truncate">
                Subst: {colaborador.substitutoNome}
              </span>
            ) : (
              <span className="text-[10px] font-medium text-emerald-400/90 flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                Escalado no Posto
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Ação de Hover Rápida */}
      <div className="mt-2 pt-1.5 border-t border-slate-800 flex items-center justify-between text-[10px] text-muted-foreground group-hover:text-emerald-400 transition-colors">
        <span>Matrícula: {colaborador.matricula || '---'}</span>
        <span className="font-semibold flex items-center gap-0.5">
          Alterar <ChevronRight className="w-3 h-3 transition-transform group-hover:translate-x-0.5" />
        </span>
      </div>
    </div>
  );
};

