import React, { useState } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Search,
  Filter,
  Eye,
  Disc,
  Users,
  Compass,
  Sparkles,
  UserCheck,
  UserX,
  Phone,
  ShieldAlert,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; dot: string; border: string; bg: string; text: string }> = {
  presente: {
    label: 'Presente',
    dot: 'bg-emerald-400',
    border: 'border-emerald-500/40',
    bg: 'bg-emerald-950/40',
    text: 'text-emerald-300',
  },
  falta: {
    label: 'Falta',
    dot: 'bg-rose-500 animate-pulse',
    border: 'border-rose-500/50',
    bg: 'bg-rose-950/40',
    text: 'text-rose-300',
  },
  substituto: {
    label: 'Substituto',
    dot: 'bg-amber-400',
    border: 'border-amber-500/40',
    bg: 'bg-amber-950/40',
    text: 'text-amber-300',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<{
    colaborador: Colaborador;
    veiculo: Veiculo;
    posicao: string;
  } | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    const matchBusca =
      !busca ||
      v.prefixo?.toLowerCase().includes(busca.toLowerCase()) ||
      v.placa?.toLowerCase().includes(busca.toLowerCase()) ||
      v.modelo?.toLowerCase().includes(busca.toLowerCase()) ||
      v.assentos?.motorista?.nome?.toLowerCase().includes(busca.toLowerCase()) ||
      v.assentos?.frenteDir?.nome?.toLowerCase().includes(busca.toLowerCase()) ||
      v.assentos?.trasEsq?.nome?.toLowerCase().includes(busca.toLowerCase()) ||
      v.assentos?.trasDir?.nome?.toLowerCase().includes(busca.toLowerCase());

    const assentosLista = [
      v.assentos?.motorista,
      v.assentos?.frenteDir,
      v.assentos?.trasEsq,
      v.assentos?.trasDir,
    ].filter(Boolean);

    const temFalta = assentosLista.some((c) => c?.status === 'falta');

    if (filtroStatus === 'completos') return matchRegional && matchBusca && !temFalta;
    if (filtroStatus === 'incompletos') return matchRegional && matchBusca && temFalta;
    return matchRegional && matchBusca;
  });

  const renderAssentoLimpo = (
    colab: Colaborador | undefined,
    veiculo: Veiculo,
    posicaoNome: string,
    siglaPosicao: string,
    equipeTag: string,
    isMotorista: boolean = false
  ) => {
    if (!colab) {
      return (
        <div className="h-full min-h-[148px] rounded-2xl border border-dashed border-border/50 bg-background/30 flex flex-col items-center justify-center p-3 text-center transition-all">
          <span className="text-[10px] font-bold text-muted-foreground tracking-wider uppercase mb-1">
            {siglaPosicao}
          </span>
          <p className="text-xs text-muted-foreground/70">Vago</p>
        </div>
      );
    }

    const cfg = statusBadgeConfig[colab.status] || statusBadgeConfig.presente;
    const isFalta = colab.status === 'falta';

    return (
      <div
        onClick={() => setColaboradorSelecionado({ colaborador: colab, veiculo, posicao: posicaoNome })}
        className={cn(
          'group relative rounded-2xl border transition-all duration-200 cursor-pointer overflow-hidden p-3.5 flex flex-col justify-between select-none',
          'hover:shadow-lg hover:-translate-y-0.5',
          isFalta
            ? 'bg-rose-950/15 border-rose-500/40 hover:border-rose-500/70 hover:bg-rose-950/25'
            : colab.status === 'substituto'
            ? 'bg-amber-950/15 border-amber-500/40 hover:border-amber-500/70 hover:bg-amber-950/25'
            : 'bg-card/70 border-border/70 hover:border-emerald-500/50 hover:bg-card'
        )}
      >
        {/* Topo do assento: Cargo/Posição e Status limpo */}
        <div className="flex items-center justify-between gap-1.5 mb-2.5">
          <div className="flex items-center gap-1.5">
            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
              {siglaPosicao}
            </span>
            {isMotorista && (
              <span className="text-[9px] font-bold text-emerald-400 bg-emerald-500/10 px-1.5 py-0.5 rounded-md border border-emerald-500/20">
                Condutor
              </span>
            )}
          </div>

          <div
            className={cn(
              'flex items-center gap-1.5 px-2 py-0.5 rounded-full border text-[10px] font-medium transition-colors',
              cfg.bg,
              cfg.border,
              cfg.text
            )}
          >
            <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', cfg.dot)} />
            <span>{cfg.label}</span>
          </div>
        </div>

        {/* Centro: Foto limpa e destaque humano */}
        <div className="flex items-center gap-3">
          <div className="relative shrink-0">
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className={cn(
                  'w-13 h-13 sm:w-14 sm:h-14 rounded-2xl object-cover ring-2 transition-transform duration-200 group-hover:scale-105 shadow-sm',
                  isFalta
                    ? 'ring-rose-500/60 grayscale-[35%]'
                    : colab.status === 'substituto'
                    ? 'ring-amber-500/60'
                    : 'ring-emerald-500/50'
                )}
              />
            ) : (
              <div
                className={cn(
                  'w-13 h-13 sm:w-14 sm:h-14 rounded-2xl ring-2 flex items-center justify-center font-bold text-sm tracking-tight transition-transform duration-200 group-hover:scale-105 shadow-sm',
                  isFalta
                    ? 'ring-rose-500/60 bg-rose-950/50 text-rose-300'
                    : colab.status === 'substituto'
                    ? 'ring-amber-500/60 bg-amber-950/50 text-amber-300'
                    : 'ring-emerald-500/50 bg-secondary text-foreground'
                )}
              >
                {getIniciais(colab.nome)}
              </div>
            )}

            {/* Micro badge sobreposto discreto */}
            <span
              className={cn(
                'absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-background flex items-center justify-center text-[8px] font-bold',
                isFalta ? 'bg-rose-500 text-white' : 'bg-emerald-500 text-white'
              )}
            >
              {isFalta ? '✕' : '✓'}
            </span>
          </div>

          <div className="min-w-0 flex-1 space-y-0.5">
            <h4 className="text-xs sm:text-sm font-bold text-foreground leading-snug truncate group-hover:text-emerald-400 transition-colors">
              {colab.nome}
            </h4>
            <p className="text-[11px] text-muted-foreground truncate">{colab.cargo}</p>
            {colab.matricula && (
              <p className="text-[10px] text-muted-foreground/70 font-mono tabular-nums">
                Mat: {colab.matricula}
              </p>
            )}
          </div>
        </div>

        {/* Rodapé: Motivo da falta limpo ou botão sutil */}
        <div className="mt-2.5 pt-2 border-t border-border/40 flex items-center justify-between text-[10px]">
          <span className="text-muted-foreground/80 font-medium truncate">
            {isFalta
              ? colab.motivoFalta || 'Falta registrada'
              : colab.status === 'substituto'
              ? colab.substitutoNome ? `Subst.: ${colab.substitutoNome}` : 'Substituição ativa'
              : equipeTag}
          </span>
          <span className="text-emerald-400/90 font-semibold group-hover:underline shrink-0">
            Alterar status
          </span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Busca e Filtros Limpa */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/50 p-3 rounded-2xl border border-border/60 backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por placa, prefixo, colaborador ou cargo..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-10 text-xs bg-background/50 border-border/60 rounded-xl focus-visible:ring-emerald-500/30"
          />
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          <button
            type="button"
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'px-3 py-1.5 rounded-xl border text-xs font-semibold whitespace-nowrap transition-all cursor-pointer',
              filtroStatus === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/50'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('completos')}
            className={cn(
              'px-3 py-1.5 rounded-xl border text-xs font-semibold whitespace-nowrap transition-all cursor-pointer',
              filtroStatus === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/50'
            )}
          >
            100% Presentes
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('incompletos')}
            className={cn(
              'px-3 py-1.5 rounded-xl border text-xs font-semibold whitespace-nowrap transition-all cursor-pointer',
              filtroStatus === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted/50'
            )}
          >
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grid Principal de Veículos */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-3xl border border-dashed border-border/70 bg-card/20 p-8">
            <Car className="w-12 h-12 text-muted-foreground/40 mx-auto mb-3" />
            <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Nenhum posto operacional corresponde aos filtros selecionados. Tente ajustar o texto de busca ou selecione outra regional.
            </p>
            {onNovaEquipeClick && (
              <Button
                size="sm"
                onClick={onNovaEquipeClick}
                className="mt-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-xs font-semibold"
              >
                Cadastrar Novo Veículo
              </Button>
            )}
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const todosPresentes =
              veiculo.assentos?.motorista?.status !== 'falta' &&
              veiculo.assentos?.frenteDir?.status !== 'falta' &&
              veiculo.assentos?.trasEsq?.status !== 'falta' &&
              veiculo.assentos?.trasDir?.status !== 'falta';

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'rounded-3xl border transition-all duration-300 overflow-hidden shadow-lg',
                  todosPresentes
                    ? 'border-border/70 bg-card/60 hover:border-emerald-500/40'
                    : 'border-rose-500/30 bg-card/80 hover:border-rose-500/50'
                )}
              >
                {/* Header Elegante do Veículo */}
                <div className="p-4 sm:p-5 border-b border-border/40 bg-gradient-to-r from-muted/30 via-transparent to-transparent flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center text-emerald-400 shrink-0">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-sm sm:text-base text-foreground tracking-tight">
                          {veiculo.prefixo}
                        </span>
                        <Badge
                          variant="outline"
                          className={cn(
                            'text-[10px] py-0 px-2 font-semibold',
                            todosPresentes
                              ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                              : 'bg-rose-500/10 text-rose-400 border-rose-500/30'
                          )}
                        >
                          {todosPresentes ? 'Operação Completa' : 'Atenção / Desfalque'}
                        </Badge>
                      </div>
                      <p className="text-xs text-muted-foreground flex items-center gap-2 mt-0.5">
                        <span className="font-mono">{veiculo.placa}</span>
                        <span>•</span>
                        <span>{veiculo.modelo}</span>
                        <span>•</span>
                        <span className="capitalize">
                          {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                        </span>
                      </p>
                    </div>
                  </div>

                  <span className="text-[11px] font-semibold text-muted-foreground/80 hidden sm:inline-block">
                    Vista Superior da Cabine
                  </span>
                </div>

                <CardContent className="p-4 sm:p-5">
                  {/* Planta do Carro com Visual Limpo e Elegante */}
                  <div className="relative rounded-2xl border border-border/60 bg-gradient-to-b from-muted/20 via-card/40 to-muted/20 p-4 sm:p-5">
                    {/* Indicador de Frente do Veículo */}
                    <div className="flex items-center justify-center gap-2 mb-4 pb-2 border-b border-border/40">
                      <Compass className="w-3.5 h-3.5 text-emerald-400/80" />
                      <span className="text-[10px] font-bold text-muted-foreground tracking-widest uppercase">
                        Frente do Veículo (Para-brisa)
                      </span>
                    </div>

                    <div className="space-y-4">
                      {/* Fileira da Frente: Motorista & Frente Direita (Equipe 1) */}
                      <div>
                        <div className="flex items-center justify-between text-[11px] font-semibold text-muted-foreground mb-2 px-1">
                          <span className="text-emerald-400">Equipe 1 (Frente)</span>
                          <span className="text-[10px] text-muted-foreground/70">Cabine Dianteira</span>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {renderAssentoLimpo(
                            veiculo.assentos?.motorista,
                            veiculo,
                            'Motorista',
                            'Assento 1 (Esq)',
                            'Equipe 1',
                            true
                          )}
                          {renderAssentoLimpo(
                            veiculo.assentos?.frenteDir,
                            veiculo,
                            'Frente Direita',
                            'Assento 2 (Dir)',
                            'Equipe 1',
                            false
                          )}
                        </div>
                      </div>

                      {/* Divisor suave de fileira */}
                      <div className="relative my-2">
                        <div className="absolute inset-0 flex items-center">
                          <div className="w-full border-t border-border/40" />
                        </div>
                        <div className="relative flex justify-center">
                          <span className="bg-card px-2.5 text-[9px] uppercase tracking-wider font-bold text-muted-foreground/60 rounded-full border border-border/40">
                            Fileira Traseira
                          </span>
                        </div>
                      </div>

                      {/* Fileira Traseira: Trás Esquerda & Trás Direita (Equipe 2) */}
                      <div>
                        <div className="flex items-center justify-between text-[11px] font-semibold text-muted-foreground mb-2 px-1">
                          <span className="text-teal-400">Equipe 2 (Trás)</span>
                          <span className="text-[10px] text-muted-foreground/70">Cabine Traseira</span>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {renderAssentoLimpo(
                            veiculo.assentos?.trasEsq,
                            veiculo,
                            'Trás Esquerda',
                            'Assento 3 (Esq)',
                            'Equipe 2',
                            false
                          )}
                          {renderAssentoLimpo(
                            veiculo.assentos?.trasDir,
                            veiculo,
                            'Trás Direita',
                            'Assento 4 (Dir)',
                            'Equipe 2',
                            false
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })
        )}
      </div>

      {/* Modal Interativo de Marcação de Presença / Falta */}
      {colaboradorSelecionado && (
        <AttendanceModal
          colaborador={colaboradorSelecionado.colaborador}
          veiculo={colaboradorSelecionado.veiculo}
          posicao={colaboradorSelecionado.posicao}
          colaboradoresReserva={colaboradoresReserva}
          isOpen={!!colaboradorSelecionado}
          onClose={() => setColaboradorSelecionado(null)}
          onSalvar={(novoStatus, motivo, obs, substitutoId) => {
            if (onUpdateColaboradorStatus && colaboradorSelecionado?.colaborador?.id) {
              onUpdateColaboradorStatus(
                colaboradorSelecionado.colaborador.id,
                novoStatus,
                motivo,
                obs,
                substitutoId
              );
            }
            setColaboradorSelecionado(null);
          }}
        />
      )}
    </div>
  );
};

