import React, { useState, useEffect } from 'react';
import {
  X,
  UserCheck,
  UserX,
  RefreshCw,
  AlertTriangle,
  FileText,
  CheckCircle2,
  Phone,
  Briefcase,
  Layers,
  Car,
  MapPin,
} from 'lucide-react';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador | null;
  veiculo: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSaveStatus: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSaveStatus,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta>('Falta Injustificada');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState('');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || 'Falta Injustificada');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
    }
  }, [colaborador, isOpen]);

  if (!isOpen || !colaborador) return null;

  const handleSalvar = () => {
    let subNome: string | undefined = undefined;
    if (status === 'substituto' && substitutoId) {
      const achado = colaboradoresReserva.find((r) => r.id === substitutoId);
      subNome = achado ? achado.nome : undefined;
    }

    onSaveStatus(
      colaborador.id,
      status,
      status === 'falta' ? motivo : undefined,
      observacao,
      status === 'substituto' ? substitutoId : undefined,
      subNome
    );
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-150"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Top Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-3">
            <div className="relative w-12 h-12 rounded-full overflow-hidden border-2 border-border shadow-md shrink-0 bg-muted flex items-center justify-center">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <span className="text-sm font-bold text-muted-foreground">
                  {colaborador.nome.substring(0, 2).toUpperCase()}
                </span>
              )}
            </div>

            <div>
              <h2 className="text-base font-bold text-foreground leading-tight">
                {colaborador.nome}
              </h2>
              <p className="text-xs text-muted-foreground flex items-center gap-2 mt-0.5">
                <span>{colaborador.cargo}</span>
                {colaborador.matricula && (
                  <>
                    <span className="opacity-40">·</span>
                    <span className="font-mono tabular-nums">Mat: {colaborador.matricula}</span>
                  </>
                )}
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Informações do Assento no Veículo */}
        {veiculo && (
          <div className="px-6 py-2.5 bg-muted/10 border-b border-border/40 flex items-center justify-between text-xs text-muted-foreground">
            <span className="flex items-center gap-1.5 font-medium">
              <Car className="w-3.5 h-3.5 text-primary" />
              {veiculo.prefixo} ({veiculo.placa})
            </span>
            <span className="flex items-center gap-1.5 font-medium">
              <MapPin className="w-3.5 h-3.5 text-emerald-400" />
              {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
            </span>
          </div>
        )}

        {/* Corpo de Seleção de Presença */}
        <div className="p-6 space-y-5">
          <div>
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-2">
              Selecione a Situação no Assento
            </label>

            <div className="grid grid-cols-3 gap-2.5">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all gap-1.5 cursor-pointer',
                  status === 'presente'
                    ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400 ring-2 ring-emerald-500/30'
                    : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <UserCheck className="w-5 h-5" />
                <span>Presente</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all gap-1.5 cursor-pointer',
                  status === 'falta'
                    ? 'bg-rose-500/20 border-rose-500 text-rose-400 ring-2 ring-rose-500/30'
                    : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <UserX className="w-5 h-5" />
                <span>Falta</span>
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all gap-1.5 cursor-pointer',
                  status === 'substituto'
                    ? 'bg-amber-500/20 border-amber-500 text-amber-400 ring-2 ring-amber-500/30'
                    : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                )}
              >
                <RefreshCw className="w-5 h-5" />
                <span>Substituto</span>
              </button>
            </div>
          </div>

          {/* Opções específicas para FALTA */}
          {status === 'falta' && (
            <div className="space-y-3 p-4 rounded-2xl bg-rose-950/20 border border-rose-500/30 animate-in fade-in duration-150">
              <label className="text-xs font-bold text-rose-300 uppercase tracking-wider block">
                Motivo da Ausência
              </label>

              <div className="grid grid-cols-2 gap-2">
                {MOTIVOS_FALTA.map((mot) => (
                  <button
                    key={mot}
                    type="button"
                    onClick={() => setMotivo(mot)}
                    className={cn(
                      'text-left p-2.5 rounded-xl border text-xs font-semibold transition-all cursor-pointer',
                      motivo === mot
                        ? 'bg-rose-500/30 border-rose-400 text-rose-200 shadow-sm'
                        : 'border-rose-500/20 text-rose-300/70 hover:bg-rose-500/10'
                    )}
                  >
                    {mot}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Opções específicas para SUBSTITUTO */}
          {status === 'substituto' && (
            <div className="space-y-3 p-4 rounded-2xl bg-amber-950/20 border border-amber-500/30 animate-in fade-in duration-150">
              <label className="text-xs font-bold text-amber-300 uppercase tracking-wider block">
                Escolher Colaborador do Banco de Reserva
              </label>

              <select
                value={substitutoId}
                onChange={(e) => setSubstitutoId(e.target.value)}
                className="w-full h-10 px-3 rounded-xl border border-amber-500/40 bg-card text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30 cursor-pointer"
              >
                <option value="">-- Selecione o Substituto da Reserva --</option>
                {colaboradoresReserva.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.nome} - {r.cargo} (Mat: {r.matricula || 'S/N'})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Observações Opcionais */}
          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
              Observações Adicionais (Opcional)
            </label>
            <Input
              placeholder="Ex: Avisou a liderança às 06h30; atestado entregue."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              className="text-xs"
            />
          </div>
        </div>

        {/* Rodapé de Ações */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-border/60 bg-muted/10">
          <Button type="button" variant="outline" onClick={onClose} className="rounded-xl text-xs font-semibold">
            Cancelar
          </Button>
          <Button
            type="button"
            onClick={handleSalvar}
            className="rounded-xl text-xs font-bold gap-2 bg-emerald-600 hover:bg-emerald-500 text-white shadow-md"
          >
            <CheckCircle2 className="w-4 h-4" />
            Salvar Registro
          </Button>
        </div>
      </div>
    </div>
  );
};

