import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  UserCheck,
  UserX,
  RefreshCw,
  FileText,
  ShieldAlert,
  Car,
  Calendar,
  Sparkles,
} from 'lucide-react';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador;
  veiculoPrefixo: string;
  veiculoPlaca: string;
  posicaoNome: string;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus: (
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculoPrefixo,
  veiculoPlaca,
  posicaoNome,
  colaboradoresReserva = [],
  onSalvarStatus,
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(
    colaborador.motivoFalta || 'Atestado Médico'
  );
  const [observacao, setObservacao] = useState<string>(colaborador.observacao || '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador.substitutoId || '');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSalvarStatus(
      status,
      status === 'falta' ? motivo : undefined,
      observacao,
      status === 'substituto' ? substitutoId : undefined
    );
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Top Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
              <Car className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <h2 className="text-base font-bold text-foreground">Registro de Faltas & Presença</h2>
