import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  Sparkles,
  UserCheck,
  UserX,
  RefreshCw,
  AlertTriangle,
  Info,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Card } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
  onSubstituirColaborador?: (colabIdOriginal: string, substitutoId: string) => void;
}

const statusConfig: Record<
  StatusPresenca,
  { label: string; badgeClass: string; ringClass: string; icon: any; dotColor: string }
> = {
  presente: {
    label: 'Presente',
    badgeClass: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30',
    ringClass: 'ring-emerald-500/40 border-emerald-500/40',
    icon: CheckCircle2,
    dotColor: 'bg-emerald-400',
  },
  falta: {
    label: 'Falta',
    badgeClass: 'bg-rose-500/20 text-rose-300 border-rose-500/40',
    ringClass: 'ring-rose-500/50 border-rose-500/60 shadow-rose-950/40',
    icon: XCircle,
    dotColor: 'bg-rose-400 animate-pulse',
  },
  substituto: {
    label: 'Substituto',
    badgeClass: 'bg-amber-500/20 text-amber-300 border-amber-500/40',
    ringClass: 'ring-amber-500/40 border-amber-500/40',
    icon: HelpCircle,
    dotColor: 'bg-amber-400',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateColaboradorStatus,
  onSubstituirColaborador,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [modalColaborador, setModalColaborador] = useState<{
    colaborador: Colaborador;
    veiculo: Veiculo;
    posicaoNome: string;
  } | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;

      // Filtro Regional
      if (selectedRegional !== 'todas' && v.regional !== selectedRegional) {
        return false;
      }

      // Filtro por termo digitado
      const termo = searchTerm.toLowerCase().trim();
      if (termo) {
        const assentos = [
          v.assentos?.motorista?.nome,
          v.assentos?.frenteDir?.nome,
          v.assentos?.trasEsq?.nome,
          v.assentos?.trasDir?.nome,
        ]
          .filter(Boolean)
          .map((n) => (n || '').toLowerCase());

        const matchPrefixo = (v.prefixo || '').toLowerCase().includes(termo);
        const matchPlaca = (v.placa || '').toLowerCase().includes(termo);
        const matchModelo = (v.modelo || '').toLowerCase().includes(termo);
        const matchEquipes =
          (v.equipe1Codigo || '').toLowerCase().includes(termo) ||
          (v.equipe2Codigo || '').toLowerCase().includes(termo);
        const matchColabs = assentos.some((nome) => nome.includes(termo));

        if (!matchPrefixo && !matchPlaca && !matchModelo && !matchEquipes && !matchColabs) {
          return false;
        }
      }

      // Filtro por completude
      if (filtroStatus !== 'todos') {
        const assentosArray = [
          v.assentos?.motorista,
          v.assentos?.frenteDir,
          v.assentos?.trasEsq,
          v.assentos?.trasDir,
        ].filter(Boolean);

        const temFalta = assentosArray.some((c) => c?.status === 'falta');
        if (filtroStatus === 'completos' && temFalta) return false;
        if (filtroStatus === 'incompletos' && !temFalta) return false;
      }

      return true;
    });
  }, [veiculos, selectedRegional, searchTerm, filtroStatus]);

  const handleSeatClick = (colab: Colaborador | undefined, veiculo: Veiculo, posicaoNome: string) => {
    if (!colab) return;
    setModalColaborador({
      colaborador: colab,
      veiculo,
      posicaoNome,
    });
  };

  const renderSeat = (
    colab: Colaborador | undefined,
    veiculo: Veiculo,
    posicao: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir',
    posicaoLabel: string,
    isDriver: boolean = false
  ) => {
    if (!colab) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-2xl border border-dashed border-border/40 bg-card/20 min-h-[148px]">
          <span className="text-[11px] font-medium text-muted-foreground">Assento Vago</span>
        </div>
      );
    }

    const cfg = statusConfig[colab.status || 'presente'];
    const StatusIcon = cfg.icon;
    const isFalta = colab.status === 'falta';

    return (
      <div
        role="button"
        tabIndex={0}
        onClick={() => handleSeatClick(colab, veiculo, posicaoLabel)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleSeatClick(colab, veiculo, posicaoLabel);
          }
        }}
        className={cn(
          'group relative flex flex-col items-center justify-between p-2.5 rounded-2xl border text-center transition-all duration-200 select-none cursor-pointer',
          'bg-gradient-to-b from-card/90 via-card/80 to-card/60 backdrop-blur-sm shadow-sm',
          'hover:shadow-md hover:-translate-y-0.5 hover:border-primary/40 focus:outline-none focus:ring-2 focus:ring-primary/40',
          isFalta
            ? 'border-rose-500/50 bg-rose-950/15 ring-1 ring-rose-500/30'
            : 'border-border/70 hover:border-emerald-500/40'
        )}
        title={`Clique para alterar presença de ${colab.nome}`}
      >
        {/* Marcador de Posição / Volante */}
        <div className="w-full flex items-center justify-between gap-1 mb-1.5 px-0.5">
          <span className="text-[10px] uppercase font-bold tracking-wider text-muted-foreground/80 flex items-center gap-1">
            {isDriver && (
              <svg
                className="w-3.5 h-3.5 text-emerald-400 inline shrink-0"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <circle cx="12" cy="12" r="10" />
                <path d="M12 2a14.5 14.5 0 0 0 0 20" />
                <path d="M2 12h20" />
              </svg>
            )}
            {posicaoLabel}
          </span>
          <span className={cn('w-2 h-2 rounded-full shrink-0 shadow-sm', cfg.dotColor)} />
        </div>

        {/* Foto do Colaborador com Encosto de Banco */}
        <div className="relative my-1">
          {/* Formato de encosto de cabeça automotivo */}
          <div className="absolute -inset-1 rounded-2xl bg-gradient-to-b from-muted/50 to-muted/20 border border-border/40 -z-0 pointer-events-none" />

          <div
            className={cn(
              'relative z-10 w-14 h-14 sm:w-16 sm:h-16 rounded-xl overflow-hidden border-2 shadow-inner transition-transform group-hover:scale-105',
              cfg.ringClass,
              isFalta && 'grayscale-[35%]'
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover object-top"
                loading="lazy"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center bg-muted/60 text-foreground font-bold text-sm tracking-wide">
                {getIniciais(colab.nome)}
              </div>
            )}

            {/* Ícone sutil no canto da foto */}
            <div
              className={cn(
                'absolute bottom-0 right-0 p-0.5 rounded-tl-lg backdrop-blur-md',
                isFalta ? 'bg-rose-950/80 text-rose-300' : 'bg-background/80 text-emerald-400'
              )}
            >
              <StatusIcon className="w-3.5 h-3.5" />
            </div>
          </div>
        </div>

        {/* Nome e Cargo */}
        <div className="w-full mt-1.5 space-y-0.5 min-w-0">
          <p className="text-xs font-bold text-foreground truncate px-1" title={colab.nome}>
            {colab.nome}
          </p>
          <p className="text-[10px] text-muted-foreground truncate px-1">
            {colab.cargo || 'Operador Florestal'}
          </p>
        </div>

        {/* Badge do Status / Motivo de Falta */}
        <div className="mt-1.5 w-full">
          {isFalta ? (
            <div className="w-full py-0.5 px-1.5 rounded-lg bg-rose-500/15 border border-rose-500/30 text-[10px] font-bold text-rose-300 truncate">
              {colab.motivoFalta || 'Falta Registrada'}
            </div>
          ) : colab.status === 'substituto' ? (
            <div className="w-full py-0.5 px-1.5 rounded-lg bg-amber-500/15 border border-amber-500/30 text-[10px] font-bold text-amber-300 truncate">
              Subst. {colab.substitutoNome ? `(${colab.substitutoNome.split(' ')[0]})` : ''}
            </div>
          ) : (
            <div className="w-full py-0.5 px-1.5 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-[10px] font-semibold text-emerald-400 flex items-center justify-center gap-1">
              <span>Presente</span>
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca de Veículos */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/70 backdrop-blur-md p-3 rounded-2xl border border-border/60 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Buscar por prefixo, placa, modelo, equipe ou nome do operador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-4 py-2 text-xs rounded-xl bg-background/60 border border-border/60 text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 focus:border-primary transition-all"
          />
        </div>

        <div className="flex items-center gap-1.5 shrink-0">
          <Button
            type="button"
            size="sm"
            variant={filtroStatus === 'todos' ? 'default' : 'outline'}
            onClick={() => setFiltroStatus('todos')}
            className="h-8 text-xs font-semibold px-3 rounded-xl"
          >
            Todos ({veiculos.length})
          </Button>
          <Button
            type="button"
            size="sm"
            variant={filtroStatus === 'completos' ? 'default' : 'outline'}
            onClick={() => setFiltroStatus('completos')}
            className={cn(
              'h-8 text-xs font-semibold px-3 rounded-xl',
              filtroStatus === 'completos' && 'bg-emerald-600 hover:bg-emerald-500 text-white border-transparent'
            )}
          >
            100% Presentes
          </Button>
          <Button
            type="button"
            size="sm"
            variant={filtroStatus === 'incompletos' ? 'destructive' : 'outline'}
            onClick={() => setFiltroStatus('incompletos')}
            className="h-8 text-xs font-semibold px-3 rounded-xl"
          >
            Com Faltas
          </Button>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-16 text-center rounded-3xl border border-dashed border-border/80 bg-card/30">
          <Car className="w-10 h-10 text-muted-foreground/50 mx-auto mb-3" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
            Não há registros correspondentes aos filtros selecionados. Tente ajustar a busca ou alterar a unidade.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentosLista = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean);

            const totalOperadores = assentosLista.length;
            const totalPresentes = assentosLista.filter(
              (c) => c?.status === 'presente' || c?.status === 'substituto'
            ).length;
            const totalFaltas = assentosLista.filter((c) => c?.status === 'falta').length;
            const isIncompleto = totalFaltas > 0;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'relative rounded-3xl border transition-all duration-300 overflow-hidden shadow-lg hover:shadow-xl',
                  isIncompleto
                    ? 'border-rose-500/35 bg-gradient-to-b from-card/95 via-card/85 to-rose-950/10'
                    : 'border-border/80 bg-gradient-to-b from-card/95 via-card/85 to-card/75'
                )}
              >
                {/* Cabeçalho do Cartão de Veículo */}
                <div className="p-4 sm:p-5 border-b border-border/60 bg-muted/20 flex items-start justify-between gap-3">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-extrabold text-base tracking-tight text-foreground flex items-center gap-2">
                        <Car className="w-4 h-4 text-emerald-400" />
                        {veiculo.prefixo}
                      </span>

                      {/* Placa Padrão Mercosul */}
                      <span className="inline-flex items-center px-2 py-0.5 rounded border border-blue-600/40 bg-zinc-900 text-[10px] font-mono font-bold tracking-wider text-zinc-100 shadow-sm">
                        <span className="w-1.5 h-1.5 rounded-full bg-blue-500 mr-1.5" />
                        {veiculo.placa}
                      </span>
                    </div>

                    <div className="flex items-center gap-2 text-xs text-muted-foreground flex-wrap">
                      <span>{veiculo.modelo || 'Hilux 4x4 Florestal'}</span>
                      <span className="opacity-40">•</span>
                      <span className="flex items-center gap-1 font-medium text-foreground/80">
                        <MapPin className="w-3 h-3 text-emerald-400" />
                        {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                      </span>
                    </div>
                  </div>

                  {/* Status do Veículo */}
                  <Badge
                    variant="outline"
                    className={cn(
                      'text-xs font-bold py-1 px-2.5 rounded-full shadow-sm',
                      isIncompleto
                        ? 'bg-rose-500/15 text-rose-300 border-rose-500/40'
                        : 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30'
                    )}
                  >
                    {isIncompleto ? `${totalFaltas} Falta${totalFaltas > 1 ? 's' : ''}` : '4/4 Completo'}
                  </Badge>
                </div>

                {/* Estrutura Superior do Carro (Layout Top-Down da Cabine) */}
                <div className="p-4 sm:p-5">
                  <div className="relative mx-auto max-w-[340px] rounded-[32px] border-2 border-border/80 bg-gradient-to-b from-zinc-900/90 via-zinc-900/80 to-zinc-950/90 p-4 shadow-2xl overflow-hidden">
                    {/* Linha decorativa de capô frontal com efeito de vidro do para-brisa */}
                    <div className="relative mb-3 pt-1 pb-2 flex flex-col items-center justify-center">
                      {/* Retrovisores externos */}
                      <div className="absolute top-1 left-0 w-3 h-1.5 rounded-l-full bg-muted-foreground/40 border border-border/50" />
                      <div className="absolute top-1 right-0 w-3 h-1.5 rounded-r-full bg-muted-foreground/40 border border-border/50" />

                      {/* Para-brisa curvado frontal */}
                      <div className="w-11/12 h-3 rounded-t-xl bg-gradient-to-b from-sky-400/20 via-sky-400/10 to-transparent border-t border-sky-400/30 shadow-inner" />
                      <span className="text-[9px] font-bold tracking-widest uppercase text-muted-foreground/70 mt-1">
                        Frente do Veículo (Cabine Dupla)
                      </span>
                    </div>

                    {/* Bloco 1: Dianteira (Equipe 1) */}
                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between px-1">
                        <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-400 flex items-center gap-1">
                          <Users className="w-3 h-3" />
                          Equipe 1 ({veiculo.equipe1Codigo || 'Frente 01'})
                        </span>
                        <span className="text-[9px] text-muted-foreground font-medium">Bancos Dianteiros</span>
                      </div>

                      <div className="grid grid-cols-2 gap-2.5">
                        {renderSeat(veiculo.assentos?.motorista, veiculo, 'motorista', 'Motorista', true)}
                        {renderSeat(veiculo.assentos?.frenteDir, veiculo, 'frente_dir', 'Passageiro')}
                      </div>
                    </div>

                    {/* Coluna Central / Divisória da Cabine */}
                    <div className="my-3 flex items-center justify-center gap-2">
                      <div className="h-[1px] flex-1 bg-border/40" />
                      <div className="px-2 py-0.5 rounded-full bg-muted/40 border border-border/40 text-[9px] font-mono text-muted-foreground">
                        Coluna B
                      </div>
                      <div className="h-[1px] flex-1 bg-border/40" />
                    </div>

                    {/* Bloco 2: Traseira (Equipe 2) */}
                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between px-1">
                        <span className="text-[10px] font-bold uppercase tracking-wider text-teal-400 flex items-center gap-1">
                          <Users className="w-3 h-3" />
                          Equipe 2 ({veiculo.equipe2Codigo || 'Frente 02'})
                        </span>
                        <span className="text-[9px] text-muted-foreground font-medium">Bancos Traseiros</span>
                      </div>

                      <div className="grid grid-cols-2 gap-2.5">
                        {renderSeat(veiculo.assentos?.trasEsq, veiculo, 'tras_esq', 'Traseiro Esq.')}
                        {renderSeat(veiculo.assentos?.trasDir, veiculo, 'tras_dir', 'Traseiro Dir.')}
                      </div>
                    </div>

                    {/* Traseira / Caçamba */}
                    <div className="mt-3 pt-2 border-t border-border/40 text-center">
                      <div className="w-3/4 mx-auto h-2 rounded-b-lg bg-muted/20 border-b border-border/40 mb-1" />
                      <span className="text-[9px] font-semibold text-muted-foreground/60 tracking-wider">
                        Caçamba Florestal & Equipamentos
                      </span>
                    </div>
                  </div>

                  {/* Dica de Ação */}
                  <p className="text-[11px] text-center text-muted-foreground mt-3 flex items-center justify-center gap-1.5">
                    <Info className="w-3.5 h-3.5 text-primary/70 shrink-0" />
                    Clique no assento de um colaborador para marcar falta ou troca
                  </p>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Presença do Colaborador Clicado */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={!!modalColaborador}
          onClose={() => setModalColaborador(null)}
          colaborador={modalColaborador.colaborador}
          veiculoPrefixo={modalColaborador.veiculo.prefixo}
          veiculoPlaca={modalColaborador.veiculo.placa}
          posicaoNome={modalColaborador.posicaoNome}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={(novoStatus, motivo, obs, substitutoId) => {
            if (onUpdateColaboradorStatus) {
              onUpdateColaboradorStatus(
                modalColaborador.colaborador.id,
                novoStatus,
                motivo,
                obs,
                substitutoId
              );
            }
            setModalColaborador(null);
          }}
        />
      )}
    </div>
  );
};

