import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  Users,
  Compass,
  MapPin,
  RefreshCw,
  Eye,
  Disc,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateAssentoStatus?: (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substituto?: {
      id: string;
      nome: string;
      matricula: string;
      cargo: string;
    }
  ) => void;
  onSalvarStatus?: (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
}

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateAssentoStatus,
  onSalvarStatus,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<string>('todos');

  const [modalColab, setModalColab] = useState<{
    veiculo: Veiculo;
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
    posicaoNome: string;
    colaborador: Colaborador;
  } | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional =
        selectedRegional === 'todas' || v.regional === selectedRegional;
      if (!matchRegional) return false;

      const termo = busca.toLowerCase();
      const matchBusca =
        !termo ||
        v.prefixo?.toLowerCase().includes(termo) ||
        v.placa?.toLowerCase().includes(termo) ||
        v.modelo?.toLowerCase().includes(termo) ||
        v.equipe1Codigo?.toLowerCase().includes(termo) ||
        v.equipe2Codigo?.toLowerCase().includes(termo) ||
        v.assentos?.motorista?.nome?.toLowerCase().includes(termo) ||
        v.assentos?.frenteDir?.nome?.toLowerCase().includes(termo) ||
        v.assentos?.trasEsq?.nome?.toLowerCase().includes(termo) ||
        v.assentos?.trasDir?.nome?.toLowerCase().includes(termo);

      if (!matchBusca) return false;

      if (filtroStatus === 'todos') return true;
      const assentosArray = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ];
      if (filtroStatus === 'faltas') {
        return assentosArray.some((c) => c?.status === 'falta');
      }
      if (filtroStatus === 'substitutos') {
        return assentosArray.some((c) => c?.status === 'substituto');
      }
      if (filtroStatus === 'completos') {
        return assentosArray.every((c) => c?.status === 'presente');
      }
      return true;
    });
  }, [veiculos, selectedRegional, busca, filtroStatus]);

  const handleSalvarStatusModal = (
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => {
    if (!modalColab) return;
    const { veiculo, posicao } = modalColab;

    const subObj = substitutoId
      ? colaboradoresReserva.find((r) => r.id === substitutoId)
      : undefined;

    if (onUpdateAssentoStatus) {
      onUpdateAssentoStatus(
        veiculo.id,
        posicao,
        novoStatus,
        motivo,
        obs,
        subObj
          ? {
              id: subObj.id,
              nome: subObj.nome,
              matricula: subObj.matricula,
              cargo: subObj.cargo,
            }
          : undefined
      );
    } else if (onSalvarStatus) {
      onSalvarStatus(veiculo.id, posicao, novoStatus, motivo, obs, substitutoId);
    }

    setModalColab(null);
  };

  const renderAssentoCard = (
    veiculo: Veiculo,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    colaborador?: Colaborador,
    labelPosicao = 'Posição'
  ) => {
    const isPresente = colaborador?.status === 'presente' || !colaborador?.status;
    const isFalta = colaborador?.status === 'falta';
    const isSub = colaborador?.status === 'substituto';

    return (
      <div
        onClick={() => {
          if (colaborador) {
            setModalColab({
              veiculo,
              posicao,
              posicaoNome: labelPosicao,
              colaborador,
            });
          }
        }}
        className={cn(
          'group relative p-2.5 rounded-2xl border transition-all duration-200 cursor-pointer text-left select-none',
          'hover:shadow-md hover:scale-[1.01] active:scale-[0.99]',
          isPresente && 'bg-emerald-950/10 border-emerald-500/20 hover:border-emerald-500/40',
          isFalta && 'bg-rose-950/20 border-rose-500/40 hover:border-rose-500/60 shadow-sm shadow-rose-950/20',
          isSub && 'bg-amber-950/20 border-amber-500/40 hover:border-amber-500/60 shadow-sm shadow-amber-950/20',
          !colaborador && 'bg-muted/10 border-border/40 opacity-60 pointer-events-none'
        )}
      >
        <div className="flex items-center gap-2.5">
          {/* Avatar foto / iniciais */}
          <div className="relative w-11 h-11 rounded-xl overflow-hidden shrink-0 border border-border/70 bg-muted/60 shadow-inner">
            {colaborador?.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover object-top"
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center text-xs font-bold text-muted-foreground">
                {getIniciais(colaborador?.nome)}
              </div>
            )}

            {/* Badge de status no cantinho */}
            <span
              className={cn(
                'absolute bottom-0 right-0 w-3.5 h-3.5 rounded-tl-lg flex items-center justify-center text-[8px] font-bold',
                isPresente && 'bg-emerald-500 text-white',
                isFalta && 'bg-rose-500 text-white',
                isSub && 'bg-amber-500 text-black'
              )}
            >
              {isPresente && '✓'}
              {isFalta && '✕'}
              {isSub && '↻'}
            </span>
          </div>

          {/* Dados do Colaborador */}
          <div className="min-w-0 flex-1">
            <div className="flex items-center justify-between gap-1">
              <span className="text-[10px] uppercase font-bold tracking-wider text-muted-foreground truncate">
                {labelPosicao}
              </span>
              <span
                className={cn(
                  'text-[10px] font-bold px-1.5 py-0.2 rounded-md tabular-nums',
                  isPresente && 'text-emerald-400 bg-emerald-500/10',
                  isFalta && 'text-rose-300 bg-rose-500/20',
                  isSub && 'text-amber-300 bg-amber-500/20'
                )}
              >
                {isPresente && 'Presente'}
                {isFalta && 'Falta'}
                {isSub && 'Substituto'}
              </span>
            </div>

            <p className="text-xs font-bold text-foreground truncate mt-0.5">
              {colaborador?.nome || 'Não alocado'}
            </p>

            <p className="text-[11px] text-muted-foreground truncate">
              {colaborador?.cargo || 'Operador'}
            </p>
          </div>
        </div>

        {/* Motivo de falta ou nome do substituto caso ativo */}
        {isFalta && colaborador?.motivoFalta && (
          <div className="mt-1.5 pt-1.5 border-t border-rose-500/20 text-[10px] text-rose-300 flex items-center gap-1 truncate font-medium">
            <span>Motivo:</span>
            <span className="truncate">{colaborador.motivoFalta}</span>
          </div>
        )}

        {isSub && colaborador?.substitutoNome && (
          <div className="mt-1.5 pt-1.5 border-t border-amber-500/20 text-[10px] text-amber-300 flex items-center gap-1 truncate font-medium">
            <span>Subst. por:</span>
            <span className="truncate font-bold">{colaborador.substitutoNome}</span>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-5">
      {/* Barra de Filtro e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3 rounded-2xl border border-border/60 shadow-sm">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            placeholder="Buscar veículo, placa, equipe ou operador..."
            className="pl-9 h-9 text-xs rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
          {[
            { id: 'todos', label: 'Todos' },
            { id: 'faltas', label: 'Com Faltas' },
            { id: 'substitutos', label: 'Com Substituição' },
            { id: 'completos', label: '100% Presentes' },
          ].map((f) => (
            <button
              key={f.id}
              type="button"
              onClick={() => setFiltroStatus(f.id)}
              className={cn(
                'px-3 py-1.5 rounded-xl border text-xs font-semibold whitespace-nowrap transition-all cursor-pointer',
                filtroStatus === f.id
                  ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                  : 'bg-muted/30 border-border/50 text-muted-foreground hover:bg-muted/60 hover:text-foreground'
              )}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="p-12 text-center rounded-2xl border border-border/60 bg-card/40">
          <Car className="w-10 h-10 text-muted-foreground mx-auto mb-2 opacity-40" />
          <p className="text-sm font-semibold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground mt-1">Ajuste os filtros ou o termo de busca.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-5">
          {veiculosFiltrados.map((veiculo) => (
            <div
              key={veiculo.id}
              className="group relative rounded-3xl border border-border/70 bg-card/70 backdrop-blur-md shadow-lg overflow-hidden transition-all hover:border-emerald-500/30"
            >
              {/* Header do Card do Veículo */}
              <div className="px-5 py-3.5 border-b border-border/50 bg-gradient-to-r from-muted/40 via-muted/20 to-transparent flex items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
                    <Car className="w-4 h-4 text-emerald-400" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-extrabold text-sm sm:text-base text-foreground tracking-tight">
                        {veiculo.prefixo}
                      </span>
                      <span className="px-2 py-0.5 rounded-md bg-muted text-[11px] font-mono font-bold text-foreground border border-border/80">
                        {veiculo.placa}
                      </span>
                    </div>
                    <p className="text-[11px] text-muted-foreground">
                      {veiculo.modelo} ({veiculo.ano || '2024'}) •{' '}
                      {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="text-[10px] font-mono border-emerald-500/30 text-emerald-400 bg-emerald-500/5">
                    {veiculo.equipe1Codigo} / {veiculo.equipe2Codigo}
                  </Badge>
                </div>
              </div>

              {/* Habitáculo do Veículo / Layout de 4 Lugares */}
              <div className="p-4 sm:p-5">
                <div className="rounded-2xl border border-border/60 bg-muted/10 p-3 sm:p-4 space-y-4">
                  {/* Linha da Frente (Motorista e Frente Dir) */}
                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between text-[11px] font-bold text-muted-foreground px-1">
                      <span className="flex items-center gap-1.5">
                        <Compass className="w-3 h-3 text-emerald-400" /> Cabine Frontal (Equipe {veiculo.equipe1Codigo})
                      </span>
                      <span className="text-[10px] text-muted-foreground">Frente</span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                      {renderAssentoCard(
                        veiculo,
                        'motorista',
                        veiculo.assentos?.motorista,
                        'Motorista'
                      )}
                      {renderAssentoCard(
                        veiculo,
                        'frenteDir',
                        veiculo.assentos?.frenteDir,
                        'Passageiro Frontal'
                      )}
                    </div>
                  </div>

                  {/* Linha Traseira (Traseiro Esq e Traseiro Dir) */}
                  <div className="space-y-1.5 pt-2 border-t border-border/40">
                    <div className="flex items-center justify-between text-[11px] font-bold text-muted-foreground px-1">
                      <span className="flex items-center gap-1.5">
                        <Users className="w-3 h-3 text-teal-400" /> Cabine Traseira (Equipe {veiculo.equipe2Codigo})
                      </span>
                      <span className="text-[10px] text-muted-foreground">Atrás</span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                      {renderAssentoCard(
                        veiculo,
                        'trasEsq',
                        veiculo.assentos?.trasEsq,
                        'Traseiro Esquerdo'
                      )}
                      {renderAssentoCard(
                        veiculo,
                        'trasDir',
                        veiculo.assentos?.trasDir,
                        'Traseiro Direito'
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal de Presença & Falta */}
      {modalColab && (
        <AttendanceModal
          isOpen={Boolean(modalColab)}
          onClose={() => setModalColab(null)}
          colaborador={modalColab.colaborador}
          veiculoPrefixo={modalColab.veiculo.prefixo}
          veiculoPlaca={modalColab.veiculo.placa}
          posicaoNome={modalColab.posicaoNome}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={handleSalvarStatusModal}
        />
      )}
    </div>
  );
};

