import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  Sparkles,
  ShieldAlert,
  ChevronRight,
  Disc,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const statusColorMap: Record<StatusPresenca, {
  badgeBg: string;
  badgeText: string;
  badgeBorder: string;
  dotColor: string;
  seatRing: string;
  glow: string;
  label: string;
}> = {
  presente: {
    badgeBg: 'bg-emerald-500/10',
    badgeText: 'text-emerald-400',
    badgeBorder: 'border-emerald-500/25',
    dotColor: 'bg-emerald-400',
    seatRing: 'ring-emerald-500/50 border-emerald-500/40',
    glow: 'shadow-[0_0_12px_rgba(16,185,129,0.18)]',
    label: 'Presente',
  },
  falta: {
    badgeBg: 'bg-rose-500/10',
    badgeText: 'text-rose-400',
    badgeBorder: 'border-rose-500/25',
    dotColor: 'bg-rose-400',
    seatRing: 'ring-rose-500/60 border-rose-500/50',
    glow: 'shadow-[0_0_14px_rgba(244,63,94,0.22)]',
    label: 'Falta',
  },
  substituto: {
    badgeBg: 'bg-amber-500/10',
    badgeText: 'text-amber-400',
    badgeBorder: 'border-amber-500/25',
    dotColor: 'bg-amber-400',
    seatRing: 'ring-amber-500/60 border-amber-500/50',
    glow: 'shadow-[0_0_12px_rgba(245,158,11,0.2)]',
    label: 'Substituto',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ').filter(Boolean);
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
}) => {
  const [selectedColaborador, setSelectedColaborador] = useState<Colaborador | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<StatusPresenca | 'todos'>('todos');

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional =
        selectedRegional === 'todas' || v.regional === selectedRegional;

      const assentosLista = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean) as Colaborador[];

      const matchBusca =
        !busca ||
        (v.prefixo || '').toLowerCase().includes(busca.toLowerCase()) ||
        (v.placa || '').toLowerCase().includes(busca.toLowerCase()) ||
        (v.modelo || '').toLowerCase().includes(busca.toLowerCase()) ||
        assentosLista.some((c) =>
          (c.nome || '').toLowerCase().includes(busca.toLowerCase()) ||
          (c.cargo || '').toLowerCase().includes(busca.toLowerCase()) ||
          (c.matricula || '').toLowerCase().includes(busca.toLowerCase())
        );

      const matchStatus =
        filtroStatus === 'todos' ||
        assentosLista.some((c) => c.status === filtroStatus);

      return matchRegional && matchBusca && matchStatus;
    });
  }, [veiculos, selectedRegional, busca, filtroStatus]);

  const handleOpenModal = (colab: Colaborador) => {
    if (!colab) return;
    setSelectedColaborador(colab);
    setModalOpen(true);
  };

  const handleSaveModal = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    onUpdateColaboradorStatus?.(
      colaboradorId,
      novoStatus,
      motivoFalta,
      observacao,
      substitutoId,
      substitutoNome
    );
    setModalOpen(false);
    setSelectedColaborador(null);
  };

  // Componente que renderiza cada assento visto de cima
  const SeatTopView = ({
    colaborador,
    posicao,
    labelPosicao,
    isDriver = false,
  }: {
    colaborador?: Colaborador;
    posicao: string;
    labelPosicao: string;
    isDriver?: boolean;
  }) => {
    if (!colaborador) {
      return (
        <div className="relative flex flex-col items-center justify-center p-3 rounded-2xl bg-neutral-900/60 border border-dashed border-neutral-800 text-neutral-500 text-[11px] min-h-[148px]">
          <span className="text-[10px] uppercase font-bold tracking-wider opacity-60">
            {labelPosicao}
          </span>
          <span className="text-xs mt-1 font-medium">Vago</span>
        </div>
      );
    }

    const cfg = statusColorMap[colaborador.status || 'presente'];

    return (
      <div
        onClick={() => handleOpenModal(colaborador)}
        className={cn(
          'group relative flex flex-col items-center p-2.5 rounded-2xl cursor-pointer select-none transition-all duration-200',
          'bg-gradient-to-b from-neutral-900/90 via-neutral-900/70 to-neutral-950/95',
          'border border-neutral-800/90 hover:border-neutral-700 hover:bg-neutral-800/60',
          'hover:shadow-lg active:scale-[0.98]',
          cfg.glow
        )}
      >
        {/* Encosto do banco visto de cima (formato ergonômico de assento automotivo) */}
        <div className="absolute top-2 w-14 h-3 rounded-t-full bg-neutral-800/80 border border-neutral-700/60 z-0 opacity-70 group-hover:opacity-100 transition-opacity" />

        {/* Tag do posto (ex: Motorista / Carona) */}
        <div className="w-full flex items-center justify-between gap-1 z-10 mb-1.5 px-0.5">
          <span className="text-[9px] font-bold uppercase tracking-wider text-neutral-400 flex items-center gap-1">
            {isDriver && <Disc className="w-2.5 h-2.5 text-emerald-400 animate-pulse" />}
            {labelPosicao}
          </span>

          <span
            className={cn(
              'inline-flex items-center gap-1 text-[9px] font-semibold px-1.5 py-0.5 rounded-full border',
              cfg.badgeBg,
              cfg.badgeText,
              cfg.badgeBorder
            )}
          >
            <span className={cn('w-1.5 h-1.5 rounded-full', cfg.dotColor)} />
            {cfg.label}
          </span>
        </div>

        {/* Foto do colaborador visto do teto do carro (vista de cima para os assentos) */}
        <div className="relative my-1 z-10">
          <div
            className={cn(
              'relative w-16 h-16 sm:w-18 sm:h-18 rounded-2xl overflow-hidden border-2 transition-all duration-200',
              'bg-neutral-800 shadow-md flex items-center justify-center',
              cfg.seatRing,
              'group-hover:scale-105'
            )}
          >
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover object-top"
                loading="lazy"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : null}

            {/* Iniciais em fallback elegante caso não haja foto */}
            <div
              className={cn(
                'absolute inset-0 flex items-center justify-center text-sm font-black text-neutral-200 uppercase bg-neutral-800',
                colaborador.foto ? 'opacity-0' : 'opacity-100'
              )}
            >
              {getIniciais(colaborador.nome)}
            </div>

            {/* Ícone de status no cantinho inferior direito da foto */}
            <div className="absolute bottom-1 right-1">
              {colaborador.status === 'presente' && (
                <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 drop-shadow" />
              )}
              {colaborador.status === 'falta' && (
                <XCircle className="w-3.5 h-3.5 text-rose-400 drop-shadow" />
              )}
              {colaborador.status === 'substituto' && (
                <HelpCircle className="w-3.5 h-3.5 text-amber-400 drop-shadow" />
              )}
            </div>

            {/* Efeito sutil de vidro/cockpit */}
            <div className="absolute inset-0 bg-gradient-to-tr from-black/30 via-transparent to-white/10 pointer-events-none" />
          </div>

          {/* Cinto de segurança sutil estilizado indicando ocupação no assento */}
          <div className="absolute -bottom-1 -left-1 w-2.5 h-2.5 rounded-full bg-neutral-900 border border-neutral-700 flex items-center justify-center shadow-xs">
            <span className="w-1 h-1 rounded-full bg-neutral-400" />
          </div>
        </div>

        {/* Informações nominais e operacionais limpas */}
        <div className="w-full text-center mt-1 z-10 px-0.5">
          <p className="text-xs font-bold text-neutral-100 truncate group-hover:text-emerald-300 transition-colors">
            {colaborador.nome}
          </p>
          <p className="text-[10px] text-neutral-400 truncate">
            {colaborador.cargo}
          </p>
          {colaborador.status === 'falta' && colaborador.motivoFalta && (
            <p className="text-[9px] font-semibold text-rose-300 truncate mt-0.5">
              {colaborador.motivoFalta}
            </p>
          )}
          {colaborador.status === 'substituto' && colaborador.substitutoNome && (
            <p className="text-[9px] font-semibold text-amber-300 truncate mt-0.5">
              Subst: {colaborador.substitutoNome}
            </p>
          )}
        </div>

        {/* Dica de clique na foto */}
        <span className="text-[8px] font-medium text-neutral-500 group-hover:text-neutral-300 mt-1 transition-colors">
          Toque p/ editar
        </span>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtro e Busca com Design Craft UI */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3 rounded-2xl border border-border/60 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar por prefixo, placa, nome do operador ou cargo..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/50 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex items-center gap-1 bg-background/40 p-1 rounded-xl border border-border/50 text-xs font-medium">
            <span className="text-muted-foreground text-[11px] px-2 flex items-center gap-1">
              <Filter className="w-3 h-3" /> Status:
            </span>
            {(['todos', 'presente', 'falta', 'substituto'] as const).map((st) => (
              <button
                key={st}
                type="button"
                onClick={() => setFiltroStatus(st)}
                className={cn(
                  'px-2.5 py-1 rounded-lg text-xs capitalize transition-all cursor-pointer',
                  filtroStatus === st
                    ? 'bg-neutral-800 text-foreground font-semibold shadow-xs border border-border/80'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/30'
                )}
              >
                {st}
              </button>
            ))}
          </div>

          <div className="text-xs text-muted-foreground px-2 py-1 rounded-lg bg-background/30 border border-border/40 font-mono tabular-nums">
            {veiculosFiltrados.length} {veiculosFiltrados.length === 1 ? 'veículo' : 'veículos'}
          </div>
        </div>
      </div>

      {/* Grid de Veículos Vista Superior (Top-Down Car View) */}
      {veiculosFiltrados.length === 0 ? (
        <div className="text-center py-16 px-4 rounded-3xl border border-dashed border-border/70 bg-card/20 backdrop-blur-sm">
          <Car className="w-12 h-12 text-muted-foreground mx-auto mb-3 opacity-40 animate-pulse" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
            Não foram localizados veículos ou colaboradores com os filtros aplicados. Altere os termos da busca acima.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = veiculo.assentos;
            const motorista = assentos?.motorista;
            const carona = assentos?.frenteDir;
            const trasEsq = assentos?.trasEsq;
            const trasDir = assentos?.trasDir;

            const ocupantes = [motorista, carona, trasEsq, trasDir].filter(Boolean) as Colaborador[];
            const faltasCount = ocupantes.filter((c) => c.status === 'falta').length;
            const substitutosCount = ocupantes.filter((c) => c.status === 'substituto').length;
            const presentesCount = ocupantes.filter((c) => c.status === 'presente').length;

            return (
              <div
                key={veiculo.id}
                className="relative rounded-3xl border border-border/80 bg-card/75 backdrop-blur-xl shadow-xl hover:shadow-2xl transition-all duration-300 overflow-hidden flex flex-col"
              >
                {/* Cabeçalho do Cartão de Veículo */}
                <div className="p-4 sm:px-5 pb-3 border-b border-border/50 bg-gradient-to-r from-neutral-900/80 via-neutral-900/40 to-transparent flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center text-emerald-400 shrink-0 shadow-inner">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="text-base font-extrabold text-foreground tracking-tight">
                          {veiculo.prefixo}
                        </h3>
                        <span className="font-mono text-xs px-2 py-0.5 rounded-md bg-neutral-800 text-neutral-300 border border-neutral-700/60 font-semibold tracking-wider">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground flex items-center gap-2 mt-0.5">
                        <span>{veiculo.modelo}</span>
                        <span>•</span>
                        <span className="flex items-center gap-1 font-medium text-neutral-300">
                          <MapPin className="w-3 h-3 text-emerald-400" />
                          {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                        </span>
                      </p>
                    </div>
                  </div>

                  {/* Resumo do Status de Faltas */}
                  <div className="flex items-center gap-1.5 flex-wrap justify-end">
                    {faltasCount > 0 ? (
                      <Badge variant="outline" className="text-[10px] bg-rose-500/15 text-rose-300 border-rose-500/30 font-bold px-2 py-0.5">
                        {faltasCount} {faltasCount === 1 ? 'Falta' : 'Faltas'}
                      </Badge>
                    ) : (
                      <Badge variant="outline" className="text-[10px] bg-emerald-500/15 text-emerald-300 border-emerald-500/30 font-bold px-2 py-0.5">
                        Equipe 100%
                      </Badge>
                    )}
                    {substitutosCount > 0 && (
                      <Badge variant="outline" className="text-[10px] bg-amber-500/15 text-amber-300 border-amber-500/30 font-bold px-2 py-0.5">
                        {substitutosCount} Subst.
                      </Badge>
                    )}
                  </div>
                </div>

                {/* VISUALIZAÇÃO AÉREA (TOP-DOWN CAR CABIN) */}
                <div className="p-4 sm:p-5 flex-1 flex flex-col justify-center">
                  <div className="relative mx-auto w-full max-w-md rounded-3xl bg-neutral-950/90 border border-neutral-800/90 shadow-2xl p-4 sm:p-5 overflow-hidden">
                    {/* Linhas da silhueta do carro visto de cima */}
                    <div className="absolute inset-x-6 top-0 h-4 rounded-b-3xl border-b-2 border-emerald-500/30 bg-emerald-500/5 pointer-events-none" />

                    {/* Capô / Parabrisa dianteiro curvo (Frente do Carro) */}
                    <div className="flex items-center justify-between px-3 py-1.5 mb-3 rounded-xl bg-neutral-900/90 border border-neutral-800 text-[10px] text-neutral-400">
                      <div className="flex items-center gap-1.5">
                        <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
                        <span className="font-semibold text-neutral-300 uppercase tracking-widest text-[9px]">
                          Frente do Veículo (Parabrisa)
                        </span>
                      </div>
                      <div className="flex items-center gap-1 text-[9px] text-neutral-500 font-mono">
                        <span>EQ. 1</span>
                        <span>•</span>
                        <span>{veiculo.equipe1Codigo || 'Frente'}</span>
                      </div>
                    </div>

                    {/* Espelhos retrovisores externos sutis na lateral */}
                    <div className="absolute -left-1.5 top-14 w-2 h-6 rounded-l-md bg-neutral-800 border-l border-y border-neutral-700 pointer-events-none" />
                    <div className="absolute -right-1.5 top-14 w-2 h-6 rounded-r-md bg-neutral-800 border-r border-y border-neutral-700 pointer-events-none" />

                    {/* Cockpit / Cabine Interna - FILEIRA DA FRENTE (Motorista & Carona) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 relative z-10 mb-4">
                      {/* Assento do Motorista */}
                      <SeatTopView
                        colaborador={motorista}
                        posicao="motorista"
                        labelPosicao="Motorista"
                        isDriver={true}
                      />

                      {/* Assento Carona Frente Direita */}
                      <SeatTopView
                        colaborador={carona}
                        posicao="frente_dir"
                        labelPosicao="Carona Dianteiro"
                      />
                    </div>

                    {/* Console central / Divisória do Veículo */}
                    <div className="relative my-2 py-1.5 flex items-center justify-center">
                      <div className="absolute inset-x-0 h-px bg-gradient-to-r from-transparent via-neutral-700/60 to-transparent" />
                      <div className="relative px-3 py-0.5 rounded-full bg-neutral-900 border border-neutral-800 text-[9px] font-mono font-semibold text-neutral-400 uppercase tracking-wider">
                        Equipe 2 • Fileira Traseira
                      </div>
                    </div>

                    {/* Cockpit / Cabine Interna - FILEIRA TRASEIRA (Atrás do Motorista & Atrás do Carona) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 relative z-10 mt-3">
                      {/* Assento Traseiro Esquerdo */}
                      <SeatTopView
                        colaborador={trasEsq}
                        posicao="tras_esq"
                        labelPosicao="Traseiro Esq."
                      />

                      {/* Assento Traseiro Direito */}
                      <SeatTopView
                        colaborador={trasDir}
                        posicao="tras_dir"
                        labelPosicao="Traseiro Dir."
                      />
                    </div>

                    {/* Traseira / Porta-Malas do Veículo */}
                    <div className="mt-3 text-center">
                      <div className="h-1.5 w-1/3 mx-auto rounded-full bg-neutral-800/80 border border-neutral-700/50" />
                      <span className="text-[9px] font-mono text-neutral-500 uppercase tracking-widest block mt-1">
                        Traseira / Caçamba Florestal
                      </span>
                    </div>
                  </div>
                </div>

                {/* Rodapé Informativo Rápido */}
                <div className="px-5 py-2.5 bg-neutral-950/60 border-t border-border/40 text-[11px] text-muted-foreground flex items-center justify-between">
                  <span className="text-[10px] text-neutral-400">
                    Toque na foto de qualquer operador para lançar Falta ou Substituição
                  </span>
                  <div className="flex items-center gap-2 font-mono text-[10px]">
                    <span className="text-emerald-400 font-bold">{presentesCount} Pres.</span>
                    <span className="text-neutral-600">|</span>
                    <span className="text-rose-400 font-bold">{faltasCount} Falt.</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Presença, Falta e Substitutos com segurança null-checked */}
      {selectedColaborador && (
        <AttendanceModal
          isOpen={modalOpen}
          colaborador={selectedColaborador}
          colaboradoresReserva={colaboradoresReserva}
          onClose={() => {
            setModalOpen(false);
            setSelectedColaborador(null);
          }}
          onSave={handleSaveModal}
        />
      )}
    </div>
  );
};

