import React, { useState, useEffect } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  RefreshCw,
  FileText,
  Car,
  UserCheck,
} from 'lucide-react';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  veiculoPrefixo?: string;
  veiculoPlaca?: string;
  posicaoNome?: string;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus: (
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculoPrefixo = '',
  veiculoPlaca = '',
  posicaoNome = 'Assento',
  colaboradoresReserva = [],
  onSalvarStatus,
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador?.status ?? 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(
    colaborador?.motivoFalta ?? 'Atestado Médico'
  );
  const [observacao, setObservacao] = useState<string>(colaborador?.observacao ?? '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador?.substitutoId ?? '');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || 'Atestado Médico');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSalvarStatus(
      status,
      status === 'falta' ? motivo : undefined,
      observacao,
      status === 'substituto' ? substitutoId : undefined
    );
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden max-h-[90vh] flex flex-col"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Top Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
              <Car className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <h2 className="text-base font-bold text-foreground">Registro de Faltas & Presença</h2>
              <p className="text-xs text-muted-foreground flex items-center gap-1.5">
                <span>{veiculoPrefixo}</span>
                {veiculoPlaca && (
                  <>
                    <span>•</span>
                    <span>Placa {veiculoPlaca}</span>
                  </>
                )}
                <span>•</span>
                <span className="text-foreground font-semibold">{posicaoNome}</span>
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Informações do Colaborador & Formulário */}
        <div className="p-6 space-y-6 overflow-y-auto flex-1">
          <div className="flex items-center gap-4 p-3.5 rounded-2xl bg-muted/30 border border-border/60">
            <div className="relative w-14 h-14 rounded-2xl overflow-hidden border-2 border-border shadow-sm shrink-0 bg-muted">
              {colaborador?.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador?.nome ?? 'Colaborador'}
                  className="w-full h-full object-cover object-top"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center font-bold text-muted-foreground">
                  {getIniciais(colaborador?.nome)}
                </div>
              )}
            </div>

            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-2">
                <p className="text-sm font-bold text-foreground truncate">{colaborador?.nome || 'Operador Florestal'}</p>
                <Badge variant="outline" className="text-[10px] py-0 px-1.5 font-mono">
                  Eq. {colaborador?.equipeNumero || 1}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground">{colaborador?.cargo || 'Operador Florestal'}</p>
              <p className="text-[11px] font-mono text-muted-foreground mt-0.5">
                Matrícula: {colaborador?.matricula || '---'}
              </p>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Seletor Rápido de Status */}
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground block mb-2">
                Status Operacional de Hoje
              </label>

              <div className="grid grid-cols-3 gap-2.5">
                <button
                  type="button"
                  onClick={() => setStatus('presente')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                    status === 'presente'
                      ? 'bg-emerald-500/15 border-emerald-500 text-emerald-400 shadow-sm ring-1 ring-emerald-500/30'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                  )}
                >
                  <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                  <span>Presente</span>
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('falta')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                    status === 'falta'
                      ? 'bg-rose-500/20 border-rose-500 text-rose-300 shadow-sm ring-1 ring-rose-500/40'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                  )}
                >
                  <XCircle className="w-5 h-5 text-rose-400" />
                  <span>Marcar Falta</span>
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('substituto')}
                  className={cn(
                    'flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl border text-xs font-bold transition-all cursor-pointer',
                    status === 'substituto'
                      ? 'bg-amber-500/20 border-amber-500 text-amber-300 shadow-sm ring-1 ring-amber-500/40'
                      : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                  )}
                >
                  <RefreshCw className="w-5 h-5 text-amber-400" />
                  <span>Substituição</span>
                </button>
              </div>
            </div>

            {/* Campos Condicionais: Se Falta */}
            {status === 'falta' && (
              <div className="space-y-3.5 p-4 rounded-2xl bg-rose-950/20 border border-rose-500/30 animate-in fade-in duration-200">
                <div className="flex items-center gap-2 text-rose-400 text-xs font-bold">
                  <AlertTriangle className="w-4 h-4" />
                  <span>Motivo da Ausência</span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {MOTIVOS_FALTA.map((m) => (
                    <button
                      key={m}
                      type="button"
                      onClick={() => setMotivo(m)}
                      className={cn(
                        'text-left px-3 py-2 rounded-xl text-xs font-medium border transition-all cursor-pointer',
                        motivo === m
                          ? 'bg-rose-500/20 border-rose-500/70 text-rose-200 font-bold ring-1 ring-rose-500/30'
                          : 'border-border/60 bg-muted/10 text-muted-foreground hover:bg-muted/30 hover:text-foreground'
                      )}
                    >
                      {m}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Campos Condicionais: Se Substituto */}
            {status === 'substituto' && (
              <div className="space-y-3.5 p-4 rounded-2xl bg-amber-950/20 border border-amber-500/30 animate-in fade-in duration-200">
                <div className="flex items-center gap-2 text-amber-400 text-xs font-bold">
                  <UserCheck className="w-4 h-4" />
                  <span>Selecione o Colaborador Reserva para Assumir o Posto</span>
                </div>

                <select
                  value={substitutoId}
                  onChange={(e) => setSubstitutoId(e.target.value)}
                  className="w-full h-10 rounded-xl border border-input bg-card px-3 py-2 text-sm text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <option value="">Selecione um substituto disponível...</option>
                  {(colaboradoresReserva || []).map((res) => (
                    <option key={res.id} value={res.id}>
                      {res.nome} — {res.cargo} ({res.matricula || 'Sem matrícula'})
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Observações Opcionais */}
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-muted-foreground flex items-center gap-1.5">
                <FileText className="w-3.5 h-3.5" />
                <span>Observação / Justificativa adicional</span>
              </label>
              <textarea
                value={observacao}
                onChange={(e) => setObservacao(e.target.value)}
                placeholder="Ex: Avisou liderança às 06h30; Atestado será entregue até amanhã..."
                rows={3}
                className="w-full rounded-xl border border-input bg-card/60 px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring resize-none"
              />
            </div>

            {/* Ações */}
            <div className="flex items-center justify-end gap-3 pt-2 border-t border-border/40">
              <Button type="button" variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button type="submit" className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-sm">
                Salvar Alterações
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

