import React, { useState, useEffect } from 'react';
import {
  X,
  UserCheck,
  UserX,
  UserPlus,
  AlertTriangle,
  Calendar,
  FileText,
  CheckCircle2,
  AlertCircle,
  HelpCircle,
  ArrowRight,
  Shield,
  Phone,
  Briefcase,
} from 'lucide-react';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  colaborador: Colaborador | null;
  colaboradoresReserva?: Colaborador[];
  onClose: () => void;
  onSave?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSalvar?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ').filter(Boolean);
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  colaborador,
  colaboradoresReserva = [],
  onClose,
  onSave,
  onSalvar,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivoFalta, setMotivoFalta] = useState<MotivoFalta | ''>('');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState<string>('');
  const [substitutoNome, setSubstitutoNome] = useState<string>('');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivoFalta(colaborador.motivoFalta || '');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
      setSubstitutoNome(colaborador.substitutoNome || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSubstitutoSelect = (id: string) => {
    setSubstitutoId(id);
    const sub = colaboradoresReserva.find((r) => r && r.id === id);
    if (sub) {
      setSubstitutoNome(sub.nome || '');
    } else {
      setSubstitutoNome('');
    }
  };

  const handleSalvar = (e: React.FormEvent) => {
    e.preventDefault();
    if (!colaborador?.id) return;

    const payloadStatus: StatusPresenca = status;
    const payloadMotivo: MotivoFalta | undefined =
      status === 'falta' && motivoFalta ? (motivoFalta as MotivoFalta) : undefined;
    const payloadObs = observacao.trim() || undefined;
    const payloadSubId = status === 'substituto' ? substitutoId || undefined : undefined;
    const payloadSubNome = status === 'substituto' ? substitutoNome || undefined : undefined;

    if (typeof onSave === 'function') {
      onSave(
        colaborador.id,
        payloadStatus,
        payloadMotivo,
        payloadObs,
        payloadSubId,
        payloadSubNome
      );
    } else if (typeof onSalvar === 'function') {
      onSalvar(
        colaborador.id,
        payloadStatus,
        payloadMotivo,
        payloadObs,
        payloadSubId,
        payloadSubNome
      );
    }
  };

  const statusOptions: Array<{
    value: StatusPresenca;
    label: string;
    icon: React.ElementType;
    desc: string;
    color: string;
    border: string;
  }> = [
    {
      value: 'presente',
      label: 'Presente',
      icon: UserCheck,
      desc: 'Operador em campo e apto para atividade',
      color: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/40',
      border: 'hover:border-emerald-500/50',
    },
    {
      value: 'falta',
      label: 'Registrar Falta',
      icon: UserX,
      desc: 'Ausência confirmada (justificada ou não)',
      color: 'bg-rose-500/15 text-rose-400 border-rose-500/40',
      border: 'hover:border-rose-500/50',
    },
    {
      value: 'substituto',
      label: 'Substituição',
      icon: UserPlus,
      desc: 'Alocar reserva no lugar do titular',
      color: 'bg-amber-500/15 text-amber-400 border-amber-500/40',
      border: 'hover:border-amber-500/50',
    },
  ];

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho do Modal com Perfil do Colaborador Visto no Assento */}
        <div className="px-6 py-5 border-b border-border/60 bg-gradient-to-r from-muted/40 via-card to-card flex items-center justify-between gap-4">
          <div className="flex items-center gap-3.5">
            <div className="relative w-14 h-14 rounded-2xl overflow-hidden border-2 border-primary/30 bg-neutral-800 shadow-md shrink-0 flex items-center justify-center">
              {colaborador?.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover object-top"
                  onError={(e) => {
                    (e.target as HTMLImageElement).style.display = 'none';
                  }}
                />
              ) : null}
              <div
                className={cn(
                  'absolute inset-0 flex items-center justify-center text-sm font-black text-neutral-300 uppercase bg-neutral-800',
                  colaborador?.foto ? 'opacity-0' : 'opacity-100'
                )}
              >
                {getIniciais(colaborador?.nome)}
              </div>
            </div>

            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-foreground">
                  {colaborador?.nome || 'Colaborador'}
                </h3>
                <Badge variant="outline" className="text-[10px] py-0 px-1.5 border-border/70 text-muted-foreground font-mono">
                  Matrícula: {colaborador?.matricula || '-'}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground flex items-center gap-2 mt-0.5">
                <span className="flex items-center gap-1">
                  <Briefcase className="w-3 h-3 text-muted-foreground" />
                  {colaborador?.cargo || 'Operador'}
                </span>
                {colaborador?.telefone && (
                  <>
                    <span>•</span>
                    <span className="flex items-center gap-1 font-mono text-[11px]">
                      <Phone className="w-3 h-3 text-muted-foreground" />
                      {colaborador.telefone}
                    </span>
                  </>
                )}
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Corpo do Formulário */}
        <form onSubmit={handleSalvar} className="p-6 space-y-5">
          {/* Seleção do Status Principal */}
          <div className="space-y-2">
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block">
              Selecione a Situação do Posto
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
              {statusOptions.map((opt) => {
                const Icon = opt.icon;
                const isSelected = status === opt.value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() => setStatus(opt.value)}
                    className={cn(
                      'flex flex-col items-center justify-center p-3 rounded-2xl border text-center transition-all cursor-pointer',
                      isSelected
                        ? opt.color + ' ring-2 ring-primary/40 shadow-sm'
                        : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 ' + opt.border
                    )}
                  >
                    <Icon className="w-5 h-5 mb-1.5" />
                    <span className="text-xs font-bold">{opt.label}</span>
                    <span className="text-[10px] opacity-75 mt-0.5 line-clamp-1">{opt.desc}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Campo Condicional: Motivo de Falta */}
          {status === 'falta' && (
            <div className="space-y-2 p-3.5 rounded-2xl bg-rose-500/5 border border-rose-500/25 animate-in fade-in-50 duration-150">
              <label className="text-xs font-bold text-rose-300 uppercase tracking-wider flex items-center gap-1.5">
                <AlertCircle className="w-3.5 h-3.5 text-rose-400" />
                Motivo da Ausência / Falta
              </label>
              <select
                value={motivoFalta}
                onChange={(e) => setMotivoFalta(e.target.value as MotivoFalta)}
                required
                className="w-full h-10 px-3 rounded-xl border border-rose-500/30 bg-background/80 text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/40"
              >
                <option value="">Selecione o motivo da falta...</option>
                {MOTIVOS_FALTA.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Campo Condicional: Escolha de Substituto */}
          {status === 'substituto' && (
            <div className="space-y-2 p-3.5 rounded-2xl bg-amber-500/5 border border-amber-500/25 animate-in fade-in-50 duration-150">
              <label className="text-xs font-bold text-amber-300 uppercase tracking-wider flex items-center gap-1.5">
                <UserPlus className="w-3.5 h-3.5 text-amber-400" />
                Colaborador do Banco de Reserva
              </label>
              <select
                value={substitutoId}
                onChange={(e) => handleSubstitutoSelect(e.target.value)}
                required
                className="w-full h-10 px-3 rounded-xl border border-amber-500/30 bg-background/80 text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
              >
                <option value="">Selecione o colaborador substituto...</option>
                {(colaboradoresReserva || []).map((res) => (
                  <option key={res.id} value={res.id}>
                    {res.nome} — {res.cargo} ({res.matricula || 'Sem mat.'})
                  </option>
                ))}
              </select>

              {substitutoNome && (
                <div className="text-[11px] text-amber-400 font-medium mt-1 flex items-center gap-1">
                  <span>Substituição vinculada a:</span>
                  <strong className="text-foreground">{substitutoNome}</strong>
                </div>
              )}
            </div>
          )}

          {/* Observações de Campo */}
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block">
              Observação / Parecer Operacional (Opcional)
            </label>
            <textarea
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              placeholder="Ex: Liberado pelo gestor de campo para consulta médica às 14h..."
              rows={2}
              className="w-full p-3 rounded-xl border border-border/70 bg-background/50 text-xs text-foreground placeholder:text-muted-foreground/60 focus:outline-none focus:ring-2 focus:ring-primary/30 resize-none"
            />
          </div>

          {/* Botões de Ação */}
          <div className="flex items-center justify-end gap-2.5 pt-3 border-t border-border/60">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onClose}
              className="rounded-xl text-xs"
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              size="sm"
              className="rounded-xl text-xs font-bold gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white shadow-sm"
            >
              <CheckCircle2 className="w-4 h-4" />
              Salvar Alterações
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

