import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  Calendar,
  AlertTriangle,
  RotateCcw,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Card } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onQuickStatusChange?: (colabId: string, novoStatus: StatusPresenca) => void;
}

const statusVisualMap = {
  presente: {
    label: 'PRESENTE',
    border: 'border-emerald-500 shadow-md shadow-emerald-500/20 ring-1 ring-emerald-500/40',
    badge: 'bg-emerald-500 text-white font-extrabold',
    bg: 'bg-emerald-950/40 hover:bg-emerald-950/60',
    seatPill: 'bg-emerald-500/25 text-emerald-300 border-emerald-500/40',
    accentText: 'text-emerald-400',
    icon: <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />,
    lightBar: 'bg-emerald-500',
  },
  falta: {
    label: 'FALTA',
    border: 'border-rose-500 shadow-lg shadow-rose-500/30 ring-2 ring-rose-500/60 animate-pulse',
    badge: 'bg-rose-600 text-white font-extrabold shadow-sm',
    bg: 'bg-rose-950/50 hover:bg-rose-950/70',
    seatPill: 'bg-rose-500/30 text-rose-300 border-rose-500/50',
    accentText: 'text-rose-400 font-bold',
    icon: <XCircle className="w-3.5 h-3.5 text-rose-400 shrink-0" />,
    lightBar: 'bg-rose-500',
  },
  substituto: {
    label: 'SUBSTITUTO',
    border: 'border-amber-500 shadow-md shadow-amber-500/25 ring-1 ring-amber-500/50',
    badge: 'bg-amber-500 text-slate-950 font-black',
    bg: 'bg-amber-950/40 hover:bg-amber-950/60',
    seatPill: 'bg-amber-500/25 text-amber-300 border-amber-500/40',
    accentText: 'text-amber-400',
    icon: <HelpCircle className="w-3.5 h-3.5 text-amber-400 shrink-0" />,
    lightBar: 'bg-amber-500',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateColaboradorStatus,
  onQuickStatusChange,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'com_falta' | 'completos'>('todos');
  const [modalColaborador, setModalColaborador] = useState<{
    colaborador: Colaborador;
    veiculo: Veiculo;
  } | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;

      // Filtro de Regional
      if (selectedRegional !== 'todas' && v.regional !== selectedRegional) {
        return false;
      }

      // Filtro de Busca
      const matchSearch =
        !searchTerm ||
        v.prefixo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.placa?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.equipe1Codigo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.equipe2Codigo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.assentos?.motorista?.nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.assentos?.frenteDir?.nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.assentos?.trasEsq?.nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.assentos?.trasDir?.nome?.toLowerCase().includes(searchTerm.toLowerCase());

      if (!matchSearch) return false;

      // Filtro de Status
      const assentosArray = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      const temFalta = assentosArray.some((c) => c?.status === 'falta');

      if (statusFilter === 'com_falta') return temFalta;
      if (statusFilter === 'completos') return !temFalta;

      return true;
    });
  }, [veiculos, selectedRegional, searchTerm, statusFilter]);

  const handleSeatClick = (colaborador: Colaborador, veiculo: Veiculo) => {
    setModalColaborador({ colaborador, veiculo });
  };

  const handleSaveModal = (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, substitutoId, substitutoNome);
    }
    setModalColaborador(null);
  };

  return (
    <div className="space-y-6">
      {/* Controles de Busca e Filtro */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/80 p-3 rounded-2xl border border-border/80 shadow-md backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-emerald-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo, placa, equipe ou nome do colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 h-10 text-xs sm:text-sm bg-background/70 border-border/70 rounded-xl focus:ring-emerald-500/40"
          />
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          <Button
            type="button"
            size="sm"
            variant={statusFilter === 'todos' ? 'default' : 'outline'}
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'text-xs rounded-xl h-9 px-3',
              statusFilter === 'todos' ? 'bg-primary font-bold' : 'text-muted-foreground'
            )}
          >
            Todos ({veiculos.length})
          </Button>

          <Button
            type="button"
            size="sm"
            variant={statusFilter === 'com_falta' ? 'destructive' : 'outline'}
            onClick={() => setStatusFilter('com_falta')}
            className={cn(
              'text-xs rounded-xl h-9 px-3 gap-1.5',
              statusFilter === 'com_falta' ? 'font-bold shadow-md' : 'text-rose-400 border-rose-500/30 hover:bg-rose-500/10'
            )}
          >
            <AlertTriangle className="w-3.5 h-3.5" />
            Com Falta
          </Button>

          <Button
            type="button"
            size="sm"
            variant={statusFilter === 'completos' ? 'default' : 'outline'}
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'text-xs rounded-xl h-9 px-3 gap-1.5',
              statusFilter === 'completos' ? 'bg-emerald-600 font-bold' : 'text-emerald-400 border-emerald-500/30 hover:bg-emerald-500/10'
            )}
          >
            <CheckCircle2 className="w-3.5 h-3.5" />
            Completos
          </Button>
        </div>
      </div>

      {/* Grid de Veículos com Visão Superior (Top View Cabine) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-3xl border border-dashed border-border/80 bg-card/30">
            <Car className="w-12 h-12 text-muted-foreground mx-auto mb-3 opacity-40 animate-pulse" />
            <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Tente alterar os termos de busca ou remover os filtros para visualizar a frota operacional.
            </p>
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const assentos = veiculo?.assentos;
            const motorista = assentos?.motorista;
            const passageiro = assentos?.frenteDir;
            const trasEsq = assentos?.trasEsq;
            const trasDir = assentos?.trasDir;

            const listaColaboradores = [motorista, passageiro, trasEsq, trasDir].filter(Boolean);
            const totalFaltas = listaColaboradores.filter((c) => c?.status === 'falta').length;
            const totalPresentes = listaColaboradores.filter((c) => c?.status === 'presente' || c?.status === 'substituto').length;
            const temDesfalque = totalFaltas > 0;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'relative overflow-hidden rounded-3xl border-2 transition-all duration-300 shadow-xl bg-gradient-to-b from-card/95 via-card/85 to-background/95',
                  temDesfalque
                    ? 'border-rose-500/50 shadow-rose-950/20'
                    : 'border-border/80 hover:border-emerald-500/40 hover:shadow-2xl'
                )}
              >
                {/* Faixa Superior com Informações do Veículo */}
                <div className="px-4 py-3.5 border-b border-border/80 bg-gradient-to-r from-muted/60 via-card to-muted/40 flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2.5 min-w-0">
                    <div className={cn(
                      'w-9 h-9 rounded-2xl flex items-center justify-center shrink-0 border shadow-inner',
                      temDesfalque
                        ? 'bg-rose-500/15 border-rose-500/30 text-rose-400'
                        : 'bg-emerald-500/15 border-emerald-500/30 text-emerald-400'
                    )}>
                      <Car className="w-5 h-5" />
                    </div>
                    <div className="min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-sm sm:text-base text-foreground tracking-tight truncate">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-[10px] px-2 py-0.5 rounded-md font-mono font-bold bg-background/80 border border-border/80 text-muted-foreground uppercase">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground flex items-center gap-1.5 mt-0.5">
                        <MapPin className="w-3 h-3 text-emerald-400 shrink-0" />
                        <span>{veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</span>
                        <span className="opacity-40">•</span>
                        <span>{veiculo.modelo}</span>
                      </p>
                    </div>
                  </div>

                  <div className="flex flex-col items-end shrink-0 gap-1">
                    <Badge
                      variant="outline"
                      className={cn(
                        'text-[10px] font-extrabold px-2.5 py-0.5 border',
                        temDesfalque
                          ? 'bg-rose-500/20 text-rose-300 border-rose-500/50'
                          : 'bg-emerald-500/20 text-emerald-300 border-emerald-500/50'
                      )}
                    >
                      {temDesfalque ? `${totalFaltas} DESFALQUE` : 'COMPLETO'}
                    </Badge>
                    <span className="text-[10px] text-muted-foreground font-semibold tabular-nums">
                      {totalPresentes}/4 a bordo
                    </span>
                  </div>
                </div>

                {/* Estrutura do Carro em Visão Superior (Top View Cockpit) */}
                <div className="p-4 sm:p-5">
                  <div className="relative mx-auto max-w-[340px] rounded-[36px] border-2 border-border/80 bg-gradient-to-b from-slate-900/90 via-slate-950 to-black p-3.5 shadow-2xl overflow-hidden">
                    {/* Linha Guia Frontal do Parabrisa (Visão Superior Frontal) */}
                    <div className="relative mb-3 flex flex-col items-center">
                      <div className="w-full flex items-center justify-between px-4 pb-1 text-[10px] font-bold text-muted-foreground/70 uppercase tracking-wider">
                        <span className="flex items-center gap-1 text-emerald-400">
                          <Compass className="w-3 h-3" /> FRENTE
                        </span>
                        <span>PARABRISA</span>
                        <span className="text-emerald-400">VOLANTE ✇</span>
                      </div>
                      <div className="w-full h-2.5 rounded-full bg-gradient-to-r from-emerald-500/30 via-teal-400/50 to-emerald-500/30 border border-emerald-400/40 shadow-inner" />
                    </div>

                    {/* ASSENTOS DIANTEIROS (MOTORISTA / PASSAGEIRO) */}
                    <div className="mb-2">
                      <div className="flex items-center justify-between px-2 mb-1.5">
                        <span className="text-[10px] font-bold tracking-wider text-emerald-400/90 flex items-center gap-1 uppercase">
                          <Users className="w-3 h-3" /> FRENTE • {veiculo.equipe1Codigo || 'EQUIPE 1'}
                        </span>
                        <span className="text-[9px] text-muted-foreground">CABINE DIANTEIRA</span>
                      </div>

                      <div className="grid grid-cols-2 gap-2.5">
                        {renderAssentoCard(motorista, 'Motorista', veiculo, () => handleSeatClick(motorista!, veiculo))}
                        {renderAssentoCard(passageiro, 'Acompanhante', veiculo, () => handleSeatClick(passageiro!, veiculo))}
                      </div>
                    </div>

                    {/* Divisor Central / Console de Bordo */}
                    <div className="my-2 flex items-center justify-center gap-2">
                      <div className="h-[1px] flex-1 bg-border/60" />
                      <div className="px-2 py-0.5 rounded-md bg-card/60 border border-border/60 text-[9px] font-mono text-muted-foreground uppercase">
                        Console Central
                      </div>
                      <div className="h-[1px] flex-1 bg-border/60" />
                    </div>

                    {/* ASSENTOS TRASEIROS */}
                    <div>
                      <div className="flex items-center justify-between px-2 mb-1.5">
                        <span className="text-[10px] font-bold tracking-wider text-teal-400/90 flex items-center gap-1 uppercase">
                          <Users className="w-3 h-3" /> TRÁS • {veiculo.equipe2Codigo || 'EQUIPE 2'}
                        </span>
                        <span className="text-[9px] text-muted-foreground">BANCO TRASEIRO</span>
                      </div>

                      <div className="grid grid-cols-2 gap-2.5">
                        {renderAssentoCard(trasEsq, 'Traseiro Esq.', veiculo, () => handleSeatClick(trasEsq!, veiculo))}
                        {renderAssentoCard(trasDir, 'Traseiro Dir.', veiculo, () => handleSeatClick(trasDir!, veiculo))}
                      </div>
                    </div>

                    {/* Traseira do Veículo */}
                    <div className="mt-3 pt-2 border-t border-border/40 flex items-center justify-between px-3 text-[9px] text-muted-foreground/80">
                      <div className="w-2 h-2 rounded-full bg-rose-500/80 shadow-sm shadow-rose-500" />
                      <span className="tracking-widest uppercase font-mono">PORTA-MALAS / TRASEIRA</span>
                      <div className="w-2 h-2 rounded-full bg-rose-500/80 shadow-sm shadow-rose-500" />
                    </div>
                  </div>
                </div>

                {/* Rodapé do Cartão */}
                <div className="px-4 py-2.5 border-t border-border/60 bg-muted/20 flex items-center justify-between text-xs">
                  <span className="text-muted-foreground text-[11px]">
                    Toque no operador para gerenciar presença
                  </span>
                  <div className="flex items-center gap-2">
                    <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-emerald-400">
                      <span className="w-2 h-2 rounded-full bg-emerald-400" /> {totalPresentes}
                    </span>
                    {totalFaltas > 0 && (
                      <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-rose-400">
                        <span className="w-2 h-2 rounded-full bg-rose-500 animate-ping" /> {totalFaltas} falta
                      </span>
                    )}
                  </div>
                </div>
              </Card>
            );
          })
        )}
      </div>

      {/* Modal de Gestão de Presença/Falta */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={!!modalColaborador}
          onClose={() => setModalColaborador(null)}
          colaborador={modalColaborador.colaborador}
          veiculo={modalColaborador.veiculo}
          colaboradoresReserva={colaboradoresReserva}
          onSalvarStatus={handleSaveModal}
        />
      )}
    </div>
  );
};

// Renderizador dos Assentos Individuais com Ênfase na Foto e Alta Legibilidade (sem matrícula)
function renderAssentoCard(
  colab: Colaborador | undefined,
  posicaoLabel: string,
  veiculo: Veiculo,
  onClick: () => void
) {
  if (!colab) {
    return (
      <div className="rounded-2xl border-2 border-dashed border-border/50 bg-card/20 p-3 flex flex-col items-center justify-center min-h-[140px] text-center">
        <span className="text-[10px] text-muted-foreground uppercase font-bold tracking-wider">{posicaoLabel}</span>
        <span className="text-xs text-muted-foreground/70 mt-1 italic">Vago</span>
      </div>
    );
  }

  const status = colab.status || 'presente';
  const cfg = statusVisualMap[status] || statusVisualMap.presente;

  return (
    <div
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          onClick();
        }
      }}
      className={cn(
        'group relative rounded-2xl border-2 p-2.5 flex flex-col items-center text-center transition-all duration-200 cursor-pointer select-none overflow-hidden',
        cfg.bg,
        cfg.border,
        'hover:scale-[1.02] active:scale-[0.98]'
      )}
    >
      {/* Barra de cor no topo do assento */}
      <div className={cn('absolute top-0 left-0 right-0 h-1', cfg.lightBar)} />

      {/* Rótulo da Posição do Assento */}
      <div className="w-full flex items-center justify-between mb-1.5 px-0.5">
        <span className={cn('text-[9px] font-extrabold uppercase px-1.5 py-0.2 rounded border', cfg.seatPill)}>
          {posicaoLabel}
        </span>
        <span className={cn('text-[9px] px-1.5 py-0.2 rounded-full font-black tracking-wider uppercase', cfg.badge)}>
          {cfg.label}
        </span>
      </div>

      {/* Foto com Visão de Cima / Borda de Alta Visibilidade */}
      <div className="relative my-1">
        <div
          className={cn(
            'w-14 h-14 sm:w-16 sm:h-16 rounded-full overflow-hidden border-2 shadow-lg transition-transform duration-200 group-hover:scale-105 shrink-0 bg-slate-800 flex items-center justify-center',
            status === 'presente'
              ? 'border-emerald-400 ring-2 ring-emerald-500/40'
              : status === 'falta'
              ? 'border-rose-500 ring-4 ring-rose-500/50'
              : 'border-amber-400 ring-2 ring-amber-500/40'
          )}
        >
          {colab.foto ? (
            <img
              src={colab.foto}
              alt={colab.nome}
              className="w-full h-full object-cover object-center"
              onError={(e) => {
                // Fallback elegante se falhar o carregamento
                (e.target as HTMLImageElement).style.display = 'none';
              }}
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-slate-700 to-slate-900 text-foreground font-black text-sm">
              {getIniciais(colab.nome)}
            </div>
          )}
        </div>

        {/* Indicador de Status com Ícone Sobreposto */}
        <div
          className={cn(
            'absolute -bottom-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center border-2 border-background shadow-md',
            status === 'presente' ? 'bg-emerald-500' : status === 'falta' ? 'bg-rose-600' : 'bg-amber-500'
          )}
        >
          {status === 'presente' ? (
            <CheckCircle2 className="w-3 h-3 text-white" />
          ) : status === 'falta' ? (
            <XCircle className="w-3 h-3 text-white" />
          ) : (
            <HelpCircle className="w-3 h-3 text-slate-950 font-bold" />
          )}
        </div>
      </div>

      {/* Nome e Cargo (sem matrícula) */}
      <div className="w-full mt-1 min-w-0">
        <p className="text-xs font-black text-foreground truncate group-hover:text-emerald-300 transition-colors">
          {colab.nome}
        </p>
        <p className="text-[10px] text-muted-foreground truncate font-medium">
          {colab.cargo || 'Operador'}
        </p>

        {/* Substituto ou Motivo da Falta */}
        {status === 'falta' && colab.motivoFalta && (
          <div className="mt-1 px-1.5 py-0.5 rounded bg-rose-500/20 border border-rose-500/40 text-[9px] font-bold text-rose-300 truncate">
            {colab.motivoFalta}
          </div>
        )}

        {status === 'substituto' && colab.substitutoNome && (
          <div className="mt-1 px-1.5 py-0.5 rounded bg-amber-500/20 border border-amber-500/40 text-[9px] font-bold text-amber-300 truncate">
            Subst: {colab.substitutoNome}
          </div>
        )}
      </div>

      {/* Dica de Toque ao Passar o Mouse */}
      <div className="mt-1.5 text-[9px] text-muted-foreground/80 font-medium group-hover:text-emerald-400 transition-colors">
        Clique p/ alterar
      </div>
    </div>
  );
}

