import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  RefreshCw,
  AlertTriangle,
  User,
  Check,
  FileText,
  UserCheck,
  Phone,
  Briefcase,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador | null;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSubstituir?: (
    colaboradorOriginal: Colaborador,
    colaboradorReserva: Colaborador,
    motivo?: MotivoFalta,
    observacao?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  colaboradoresReserva = [],
  onSalvarStatus,
  onSubstituir,
}) => {
  if (!isOpen || !colaborador) return null;

  const [status, setStatus] = useState<StatusPresenca>(colaborador?.status || 'presente');
  const [motivoFalta, setMotivoFalta] = useState<MotivoFalta | undefined>(
    colaborador?.motivoFalta || 'Atestado Médico'
  );
  const [observacao, setObservacao] = useState<string>(colaborador?.observacao || '');
  const [substitutoSelecionadoId, setSubstitutoSelecionadoId] = useState<string>('');

  const handleSalvar = () => {
    if (status === 'substituto' && substitutoSelecionadoId) {
      const reserva = colaboradoresReserva.find((r) => r.id === substitutoSelecionadoId);
      if (reserva && onSubstituir) {
        onSubstituir(colaborador, reserva, motivoFalta, observacao);
        onClose();
        return;
      }
    }

    if (onSalvarStatus) {
      const sub = colaboradoresReserva.find((r) => r.id === substitutoSelecionadoId);
      onSalvarStatus(
        colaborador.id,
        status,
        status === 'falta' || status === 'substituto' ? motivoFalta : undefined,
        observacao,
        sub?.id,
        sub?.nome
      );
    }
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-slate-900 border-2 border-slate-700 rounded-3xl shadow-2xl overflow-hidden text-slate-100"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho do Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-800 bg-slate-950/90">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/20 border-2 border-emerald-400 flex items-center justify-center text-emerald-400">
              <User className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-black text-white tracking-tight">
                Apontamento de Presença & Escala
              </h3>
              <p className="text-xs text-slate-400">
                Atualize a situação do operador no veículo
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 space-y-5">
          {/* Card de Identificação do Colaborador com Alto Contraste */}
          <div className="flex items-center gap-4 p-3.5 rounded-2xl bg-slate-950 border-2 border-slate-800">
            <div className="w-14 h-14 rounded-2xl overflow-hidden bg-slate-800 border-2 border-slate-600 flex items-center justify-center shrink-0">
              {colaborador?.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <User className="w-6 h-6 text-slate-400" />
              )}
            </div>

            <div className="min-w-0 flex-1">
              <h4 className="text-base font-black text-white truncate">
                {colaborador?.nome}
              </h4>
              <p className="text-xs font-semibold text-slate-300">
                {colaborador?.cargo}
              </p>
              <div className="flex items-center gap-2 mt-1">
                {colaborador?.matricula && (
                  <span className="text-[11px] font-mono font-bold text-slate-400 bg-slate-900 px-2 py-0.5 rounded border border-slate-700">
                    Matrícula: {colaborador.matricula}
                  </span>
                )}
                {colaborador?.telefone && (
                  <span className="text-[11px] text-slate-400 flex items-center gap-1">
                    <Phone className="w-3 h-3 text-slate-500" />
                    {colaborador.telefone}
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Seleção de Status com Cores Vibrantes e Bem Visíveis */}
          <div>
            <label className="text-xs font-black uppercase tracking-wider text-slate-300 block mb-2">
              Selecione o Status Operacional
            </label>
            <div className="grid grid-cols-3 gap-2.5">
              {/* Opção Presente */}
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer font-bold',
                  status === 'presente'
                    ? 'bg-emerald-500 text-white border-emerald-300 shadow-lg shadow-emerald-500/25 ring-2 ring-emerald-400/40'
                    : 'bg-slate-950/70 border-slate-700/80 text-slate-300 hover:border-emerald-500/50 hover:bg-slate-950'
                )}
              >
                <CheckCircle2 className={cn('w-6 h-6 mb-1', status === 'presente' ? 'text-white' : 'text-emerald-400')} />
                <span className="text-xs">PRESENTE</span>
              </button>

              {/* Opção Falta */}
              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer font-bold',
                  status === 'falta'
                    ? 'bg-rose-600 text-white border-rose-300 shadow-lg shadow-rose-600/30 ring-2 ring-rose-400/40'
                    : 'bg-slate-950/70 border-slate-700/80 text-slate-300 hover:border-rose-500/50 hover:bg-slate-950'
                )}
              >
                <XCircle className={cn('w-6 h-6 mb-1', status === 'falta' ? 'text-white' : 'text-rose-400')} />
                <span className="text-xs">FALTA</span>
              </button>

              {/* Opção Substituto */}
              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer font-bold',
                  status === 'substituto'
                    ? 'bg-amber-500 text-slate-950 border-amber-200 shadow-lg shadow-amber-500/25 ring-2 ring-amber-400/40'
                    : 'bg-slate-950/70 border-slate-700/80 text-slate-300 hover:border-amber-500/50 hover:bg-slate-950'
                )}
              >
                <RefreshCw className={cn('w-6 h-6 mb-1', status === 'substituto' ? 'text-slate-950' : 'text-amber-400')} />
                <span className="text-xs">SUBSTITUTO</span>
              </button>
            </div>
          </div>

          {/* Motivo da Falta (se status for Falta ou Substituto) */}
          {(status === 'falta' || status === 'substituto') && (
            <div className="space-y-2 p-4 rounded-2xl bg-slate-950 border-2 border-slate-800">
              <label className="text-xs font-black uppercase tracking-wider text-rose-300 block">
                Motivo da Ausência / Falta
              </label>
              <select
                value={motivoFalta}
                onChange={(e) => setMotivoFalta(e.target.value as MotivoFalta)}
                className="w-full h-11 px-3 rounded-xl border-2 border-slate-700 bg-slate-900 text-sm font-semibold text-white focus:outline-none focus:border-rose-400"
              >
                {MOTIVOS_FALTA.map((motivo) => (
                  <option key={motivo} value={motivo}>
                    {motivo}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Selecionar Substituto do Banco de Reserva */}
          {status === 'substituto' && (
            <div className="space-y-2 p-4 rounded-2xl bg-amber-950/30 border-2 border-amber-500/40">
              <label className="text-xs font-black uppercase tracking-wider text-amber-300 block">
                Selecionar Colaborador Reserva
              </label>
              <select
                value={substitutoSelecionadoId}
                onChange={(e) => setSubstitutoSelecionadoId(e.target.value)}
                className="w-full h-11 px-3 rounded-xl border-2 border-amber-500/50 bg-slate-900 text-sm font-semibold text-white focus:outline-none focus:border-amber-400"
              >
                <option value="">Selecione um substituto disponível...</option>
                {colaboradoresReserva.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.nome} ({r.cargo})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Campo de Observação Opcional */}
          <div>
            <label className="text-xs font-semibold text-slate-400 block mb-1.5">
              Observação Adicional (Opcional)
            </label>
            <input
              type="text"
              placeholder="Ex: Atestado entregue ao RH, retorno previsto amanhã..."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              className="w-full h-10 px-3.5 rounded-xl border-2 border-slate-800 bg-slate-950 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-emerald-400"
            />
          </div>
        </div>

        {/* Ações do Rodapé */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-slate-800 bg-slate-950/90">
          <Button
            type="button"
            variant="outline"
            onClick={onClose}
            className="border-slate-700 text-slate-300 hover:text-white hover:bg-slate-800 font-bold"
          >
            Cancelar
          </Button>
          <Button
            type="button"
            onClick={handleSalvar}
            className="bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-black gap-2 shadow-lg shadow-emerald-500/20"
          >
            <Check className="w-4 h-4" strokeWidth={3} />
            Confirmar Apontamento
          </Button>
        </div>
      </div>
    </div>
  );
};

