import React, { useState, useEffect } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  HelpCircle,
  AlertTriangle,
  UserCheck,
  FileText,
  User,
  ShieldAlert,
  Car,
  MapPin,
} from 'lucide-react';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  veiculo?: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSalvarStatus,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivoFalta, setMotivoFalta] = useState<MotivoFalta | undefined>(undefined);
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState('');
  const [substitutoNome, setSubstitutoNome] = useState('');

  // Sincroniza o estado interno sempre que o colaborador selecionado mudar
  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivoFalta(colaborador.motivoFalta);
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
      setSubstitutoNome(colaborador.substitutoNome || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSubstitutoSelect = (id: string) => {
    setSubstitutoId(id);
    const sub = (colaboradoresReserva || []).find((c) => c?.id === id);
    if (sub) {
      setSubstitutoNome(sub.nome);
    } else {
      setSubstitutoNome('');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSalvarStatus && colaborador?.id) {
      onSalvarStatus(
        colaborador.id,
        status,
        status === 'falta' ? motivoFalta : undefined,
        observacao,
        status === 'substituto' ? substitutoId : undefined,
        status === 'substituto' ? substitutoNome : undefined
      );
    }
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg bg-card border-2 border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho do Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/80 bg-gradient-to-r from-muted/50 to-card">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 flex items-center justify-center shadow-inner">
              <UserCheck className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold text-foreground">
                Apontamento de Presença
              </h2>
              <p className="text-xs text-muted-foreground">
                Atualize a frequência e motivos operacionais
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Informações em Destaque do Colaborador (sem matrícula) */}
        <div className="p-6 space-y-5">
          <div className="flex items-center gap-4 p-4 rounded-2xl bg-muted/30 border border-border/80">
            {/* Foto de alta visibilidade */}
            <div className="relative shrink-0">
              <div className="w-16 h-16 rounded-full overflow-hidden border-2 border-emerald-400 ring-2 ring-emerald-500/30 shadow-md bg-slate-800 flex items-center justify-center">
                {colaborador.foto ? (
                  <img
                    src={colaborador.foto}
                    alt={colaborador.nome}
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      (e.target as HTMLImageElement).style.display = 'none';
                    }}
                  />
                ) : (
                  <span className="font-extrabold text-foreground text-sm">
                    {getIniciais(colaborador.nome)}
                  </span>
                )}
              </div>
            </div>

            <div className="flex-1 min-w-0">
              <h3 className="text-base font-extrabold text-foreground truncate">
                {colaborador.nome}
              </h3>
              <p className="text-xs text-muted-foreground font-medium mt-0.5">
                {colaborador.cargo || 'Operador Florestal'}
              </p>

              {veiculo && (
                <div className="flex items-center gap-2 mt-2 text-[11px] text-muted-foreground font-medium">
                  <span className="flex items-center gap-1 text-emerald-400">
                    <Car className="w-3.5 h-3.5" />
                    {veiculo.prefixo}
                  </span>
                  <span>•</span>
                  <span>{veiculo.placa}</span>
                  <span>•</span>
                  <span>{veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}</span>
                </div>
              )}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Seletor Visual de Status */}
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground block mb-2">
                Status de Hoje
              </label>
              <div className="grid grid-cols-3 gap-2.5">
                <button
                  type="button"
                  onClick={() => setStatus('presente')}
                  className={cn(
                    'flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all font-bold text-xs gap-1.5',
                    status === 'presente'
                      ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400 shadow-md ring-2 ring-emerald-500/30'
                      : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                  )}
                >
                  <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                  Presente
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('falta')}
                  className={cn(
                    'flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all font-bold text-xs gap-1.5',
                    status === 'falta'
                      ? 'bg-rose-500/20 border-rose-500 text-rose-400 shadow-md ring-2 ring-rose-500/30'
                      : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                  )}
                >
                  <XCircle className="w-5 h-5 text-rose-400" />
                  Falta
                </button>

                <button
                  type="button"
                  onClick={() => setStatus('substituto')}
                  className={cn(
                    'flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all font-bold text-xs gap-1.5',
                    status === 'substituto'
                      ? 'bg-amber-500/20 border-amber-500 text-amber-400 shadow-md ring-2 ring-amber-500/30'
                      : 'border-border/80 text-muted-foreground hover:bg-muted/40'
                  )}
                >
                  <HelpCircle className="w-5 h-5 text-amber-400" />
                  Substituto
                </button>
              </div>
            </div>

            {/* Campos Condicionais para Falta */}
            {status === 'falta' && (
              <div className="space-y-2 p-3.5 rounded-2xl border border-rose-500/30 bg-rose-950/20 animate-in fade-in duration-150">
                <label className="text-xs font-bold text-rose-300 flex items-center gap-1.5">
                  <ShieldAlert className="w-4 h-4 text-rose-400" />
                  Motivo da Falta (Obrigatório)
                </label>
                <select
                  value={motivoFalta || ''}
                  onChange={(e) => setMotivoFalta(e.target.value as MotivoFalta)}
                  className="w-full h-10 px-3 rounded-xl border border-rose-500/40 bg-card text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/40"
                  required
                >
                  <option value="">Selecione o motivo da ausência...</option>
                  {MOTIVOS_FALTA.map((motivo) => (
                    <option key={motivo} value={motivo}>
                      {motivo}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Campos Condicionais para Substituto */}
            {status === 'substituto' && (
              <div className="space-y-3 p-3.5 rounded-2xl border border-amber-500/30 bg-amber-950/20 animate-in fade-in duration-150">
                <label className="text-xs font-bold text-amber-300 flex items-center gap-1.5">
                  <User className="w-4 h-4 text-amber-400" />
                  Selecionar Substituto (Banco de Reserva)
                </label>

                {colaboradoresReserva.length > 0 ? (
                  <select
                    value={substitutoId}
                    onChange={(e) => handleSubstitutoSelect(e.target.value)}
                    className="w-full h-10 px-3 rounded-xl border border-amber-500/40 bg-card text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                  >
                    <option value="">Escolher do Banco de Reserva...</option>
                    {colaboradoresReserva.map((res) => (
                      <option key={res.id} value={res.id}>
                        {res.nome} - {res.cargo}
                      </option>
                    ))}
                  </select>
                ) : (
                  <div className="text-xs text-amber-300/80 italic">
                    Nenhum colaborador reserva cadastrado. Digite o nome abaixo:
                  </div>
                )}

                <input
                  type="text"
                  placeholder="Ou digite o nome do substituto..."
                  value={substitutoNome}
                  onChange={(e) => setSubstitutoNome(e.target.value)}
                  className="w-full h-10 px-3 rounded-xl border border-amber-500/40 bg-card text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                />
              </div>
            )}

            {/* Observações Operacionais */}
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground block mb-1.5 flex items-center gap-1.5">
                <FileText className="w-3.5 h-3.5 text-muted-foreground" />
                Observações Operacionais
              </label>
              <textarea
                rows={2}
                placeholder="Detalhes adicionais, horário de contato ou alinhamento..."
                value={observacao}
                onChange={(e) => setObservacao(e.target.value)}
                className="w-full p-3 rounded-xl border border-border/80 bg-background/50 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 resize-none"
              />
            </div>

            {/* Botões de Ação */}
            <div className="flex items-center justify-end gap-3 pt-3 border-t border-border/80">
              <Button type="button" variant="outline" onClick={onClose} className="rounded-xl text-xs">
                Cancelar
              </Button>
              <Button
                type="submit"
                className="gap-2 rounded-xl text-xs font-bold bg-emerald-600 hover:bg-emerald-500 text-white shadow-md"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar Apontamento
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

