import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  ShieldCheck,
  Flame,
  UserCheck,
  UserX,
  AlertTriangle,
  RotateCcw,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSubstituirColaborador?: (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    colaboradorSubstituto: Colaborador
  ) => void;
}

const statusColorMap: Record<StatusPresenca, {
  border: string;
  bgBadge: string;
  badgeText: string;
  label: string;
  avatarRing: string;
}> = {
  presente: {
    border: 'border-emerald-500/50 hover:border-emerald-400',
    bgBadge: 'bg-emerald-500/20 text-emerald-300 border-emerald-500/30',
    badgeText: 'Presente',
    avatarRing: 'ring-emerald-500/40',
  },
  falta: {
    border: 'border-rose-500/50 hover:border-rose-400',
    bgBadge: 'bg-rose-500/20 text-rose-300 border-rose-500/30',
    badgeText: 'Falta',
    avatarRing: 'ring-rose-500/50',
  },
  substituto: {
    border: 'border-amber-500/50 hover:border-amber-400',
    bgBadge: 'bg-amber-500/20 text-amber-300 border-amber-500/30',
    badgeText: 'Substituto',
    avatarRing: 'ring-amber-500/40',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onSubstituirColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [modalOpen, setModalOpen] = useState(false);
  const [activeColab, setActiveColab] = useState<{
    colaborador: Colaborador;
    veiculoId: string;
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
  } | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional =
        selectedRegional === 'todas' || v.regional === selectedRegional;

      const matchSearch =
        !search ||
        v.prefixo?.toLowerCase().includes(search.toLowerCase()) ||
        v.placa?.toLowerCase().includes(search.toLowerCase()) ||
        v.modelo?.toLowerCase().includes(search.toLowerCase()) ||
        [v.assentos?.motorista, v.assentos?.frenteDir, v.assentos?.trasEsq, v.assentos?.trasDir].some(
          (c) => c && c.nome?.toLowerCase().includes(search.toLowerCase())
        );

      const assentosArray = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      const temFalta = assentosArray.some((c) => c?.status === 'falta');

      const matchStatus =
        filterStatus === 'todos' ||
        (filterStatus === 'completos' && !temFalta) ||
        (filterStatus === 'incompletos' && temFalta);

      return matchRegional && matchSearch && matchStatus;
    });
  }, [veiculos, selectedRegional, search, filterStatus]);

