            className="text-xs h-9 rounded-xl"
          >
            Todos ({veiculos.length})
          </Button>
          <Button
            type="button"
            size="sm"
            variant={filterStatus === 'completos' ? 'default' : 'outline'}
            onClick={() => setFilterStatus('completos')}
            className="text-xs h-9 rounded-xl"
          >
            Completos
          </Button>
          <Button
            type="button"
            size="sm"
            variant={filterStatus === 'incompletos' ? 'default' : 'outline'}
            onClick={() => setFilterStatus('incompletos')}
            className="text-xs h-9 rounded-xl text-rose-400"
          >
            Com Falta
          </Button>
        </div>
      </div>

      {/* Grid de Veículos */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
        {veiculosFiltrados.length === 0 ? (
          <div className="col-span-full py-16 text-center rounded-2xl border border-dashed border-border/70 bg-card/20">
            <Car className="w-10 h-10 text-muted-foreground mx-auto mb-3 opacity-40" />
            <p className="text-base font-semibold text-foreground">Nenhum veículo encontrado</p>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
              Verifique os filtros selecionados ou digite outro termo de pesquisa.
            </p>
          </div>
        ) : (
          veiculosFiltrados.map((veiculo) => {
            const assentosArray = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean);

            const totalPresentes = assentosArray.filter(
              (c) => c?.status === 'presente' || c?.status === 'substituto'
            ).length;
            const totalFaltas = assentosArray.filter((c) => c?.status === 'falta').length;

            return (
              <Card
                key={veiculo.id}
                className="overflow-hidden border border-border/70 bg-card/50 hover:bg-card/70 transition-all rounded-2xl shadow-lg flex flex-col justify-between"
              >
                {/* Cabeçalho do Cartão do Veículo */}
                <div className="p-4 pb-3 border-b border-border/40 bg-muted/15 flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="font-extrabold text-sm text-foreground tracking-tight">
                        {veiculo.prefixo}
                      </span>
                      <span className="px-2 py-0.5 rounded-md text-[11px] font-mono font-bold bg-muted text-muted-foreground border border-border/60">
                        {veiculo.placa}
                      </span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5 truncate">
                      {veiculo.modelo}
                    </p>
                  </div>

                  <div className="flex items-center gap-1.5 shrink-0">
                    <span
                      className={cn(
                        'px-2 py-0.5 rounded-full text-[10px] font-semibold border tabular-nums',
                        totalFaltas > 0
                          ? 'bg-rose-500/15 text-rose-300 border-rose-500/30'
                          : 'bg-emerald-500/15 text-emerald-300 border-emerald-500/30'
                      )}
                    >
                      {totalPresentes}/4 ativos
                    </span>
                  </div>
                </div>

                {/* Habitáculo do Carro (Visão Superior Limpa sem Textos de Frente/Traseira/Porta-malas) */}
                <div className="p-4 flex-1 flex flex-col justify-center">
                  <div className="relative rounded-2xl border border-border/60 bg-gradient-to-b from-muted/20 via-background/40 to-muted/20 p-3 shadow-inner">
                    {/* Linha Frontal (Condutor + Passageiro Dianteiro) */}
                    <div className="grid grid-cols-2 gap-2.5 mb-2.5">
                      <div>
                        {renderSeat(veiculo.assentos?.motorista, veiculo.id, 'motorista', true)}
                      </div>
                      <div>
                        {renderSeat(veiculo.assentos?.frenteDir, veiculo.id, 'frenteDir', false)}
                      </div>
                    </div>

                    {/* Divisor Central Sutil da Cabine */}
                    <div className="relative my-2 flex items-center justify-center">
                      <div className="w-full border-t border-dashed border-border/40" />
                      <div className="absolute w-2 h-2 rounded-full bg-border/50" />
                    </div>

                    {/* Linha Traseira (Passageiros Traseiros) */}
                    <div className="grid grid-cols-2 gap-2.5">
                      <div>
                        {renderSeat(veiculo.assentos?.trasEsq, veiculo.id, 'trasEsq', false)}
                      </div>
                      <div>
                        {renderSeat(veiculo.assentos?.trasDir, veiculo.id, 'trasDir', false)}
                      </div>
                    </div>
                  </div>
                </div>

                {/* Rodapé com Informações da Regional e Equipe */}
                <div className="px-4 py-2.5 bg-muted/20 border-t border-border/40 flex items-center justify-between text-[11px] text-muted-foreground">
                  <span className="flex items-center gap-1.5">
                    <MapPin className="w-3.5 h-3.5 opacity-60 text-emerald-400" />
                    {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                  </span>
                  <span className="font-medium text-foreground/80">
                    {veiculo.equipe1Codigo || 'Frente Florestal'}
                  </span>
                </div>
              </Card>
            );
          })
        )}
      </div>

      {/* Modal de Gestão de Presença & Troca de Posição */}
      {modalOpen && activeColab && (
        <AttendanceModal
          isOpen={modalOpen}
          onClose={() => {
            setModalOpen(false);
            setActiveColab(null);
          }}
          colaborador={activeColab.colaborador}
          veiculoId={activeColab.veiculoId}
          posicao={activeColab.posicao}
          colaboradoresReserva={colaboradoresReserva}
          onUpdateStatus={(colabId, novoStatus, motivo, obs, subId, subNome) => {
            onUpdateColaboradorStatus?.(colabId, novoStatus, motivo, obs, subId, subNome);
            setModalOpen(false);
            setActiveColab(null);
          }}
          onSubstituir={(veicId, pos, substituto) => {
            onSubstituirColaborador?.(veicId, pos, substituto);
            setModalOpen(false);
            setActiveColab(null);
          }}
        />
      )}
    </div>
  );
};

