import React, { useState, useEffect } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  HelpCircle,
  User,
  AlertTriangle,
  Calendar,
  Save,
  Check,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador?: Colaborador | null;
  veiculo?: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSave?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSave,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta | ''>('');
  const [observacao, setObservacao] = useState<string>('');
  const [substitutoId, setSubstitutoId] = useState<string>('');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || '');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
    }
  }, [colaborador]);

  if (!isOpen || !colaborador) return null;

  const handleSalvar = (e: React.FormEvent) => {
    e.preventDefault();
    if (!colaborador?.id) return;

    if (onSave) {
      onSave(
        colaborador.id,
        status,
        status === 'falta' && motivo ? (motivo as MotivoFalta) : undefined,
        observacao.trim() || undefined,
        status === 'substituto' && substitutoId ? substitutoId : undefined
      );
    }
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-md bg-card border border-border rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho do Modal */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border">
          <div>
            <h2 className="text-base font-bold text-foreground">Apontamento de Presença</h2>
            <p className="text-xs text-muted-foreground">{veiculo?.prefixo || 'Veículo'}</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Informações do Colaborador com foto centralizada e nome abaixo da foto */}
        <div className="px-6 pt-5 pb-3 border-b border-border/50 bg-muted/20 flex flex-col items-center text-center">
          <div className="w-20 h-20 rounded-full overflow-hidden border-2 border-emerald-500/50 bg-muted flex items-center justify-center shadow-md mb-2">
            {colaborador?.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <span className="text-xl font-black text-foreground/80">
                {getIniciais(colaborador?.nome)}
              </span>
            )}
          </div>
          <h3 className="font-bold text-base text-foreground">{colaborador?.nome}</h3>
          <p className="text-xs text-muted-foreground mt-0.5">{colaborador?.cargo || 'Operador'}</p>
        </div>

        {/* Formulário de Ação */}
        <form onSubmit={handleSalvar} className="p-6 space-y-4">
          <div>
            <label className="text-xs font-semibold text-muted-foreground block mb-2">
              Status do Colaborador
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'presente'
                    ? 'bg-emerald-500/20 border-emerald-500 text-emerald-300 ring-2 ring-emerald-500/20'
                    : 'border-border/70 text-muted-foreground hover:bg-muted'
                )}
              >
                <CheckCircle2 className="w-5 h-5 mb-1 text-emerald-400" />
                Presente
              </button>

              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'falta'
                    ? 'bg-rose-500/20 border-rose-500 text-rose-300 ring-2 ring-rose-500/20'
                    : 'border-border/70 text-muted-foreground hover:bg-muted'
                )}
              >
                <XCircle className="w-5 h-5 mb-1 text-rose-400" />
                Falta
              </button>

              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center p-3 rounded-2xl border text-xs font-bold transition-all',
                  status === 'substituto'
                    ? 'bg-amber-500/20 border-amber-500 text-amber-300 ring-2 ring-amber-500/20'
                    : 'border-border/70 text-muted-foreground hover:bg-muted'
                )}
              >
                <HelpCircle className="w-5 h-5 mb-1 text-amber-400" />
                Substituto
              </button>
            </div>
          </div>

          {/* Opções condicionais para Falta */}
          {status === 'falta' && (
            <div className="space-y-3 pt-2 animate-in fade-in">
              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">
                  Motivo da Falta
                </label>
                <select
                  value={motivo}
                  onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
                  className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
                  required
                >
                  <option value="">Selecione o motivo...</option>
                  {MOTIVOS_FALTA.map((m) => (
                    <option key={m} value={m}>
                      {m}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">
                  Observação Adicional (Opcional)
                </label>
                <textarea
                  value={observacao}
                  onChange={(e) => setObservacao(e.target.value)}
                  placeholder="Detalhes sobre a falta, atestado ou contato feito..."
                  rows={2}
                  className="w-full p-2.5 rounded-xl border border-border/80 bg-background text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30 resize-none"
                />
              </div>
            </div>
          )}

          {/* Opções condicionais para Substituto */}
          {status === 'substituto' && (
            <div className="space-y-3 pt-2 animate-in fade-in">
              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">
                  Selecionar Substituto do Banco de Reserva
                </label>
                <select
                  value={substitutoId}
                  onChange={(e) => setSubstitutoId(e.target.value)}
                  className="w-full h-10 px-3 rounded-xl border border-border/80 bg-background text-xs font-medium text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30"
                >
                  <option value="">Selecione o substituto...</option>
                  {(colaboradoresReserva || []).map((res) => (
                    <option key={res.id} value={res.id}>
                      {res.nome} ({res.cargo})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">
                  Observação da Substituição
                </label>
                <textarea
                  value={observacao}
                  onChange={(e) => setObservacao(e.target.value)}
                  placeholder="Informações sobre a cobertura de posto..."
                  rows={2}
                  className="w-full p-2.5 rounded-xl border border-border/80 bg-background text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/30 resize-none"
                />
              </div>
            </div>
          )}

          <div className="flex items-center justify-end gap-2.5 pt-4 border-t border-border mt-4">
            <Button type="button" variant="outline" size="sm" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              size="sm"
              className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold"
            >
              <Check className="w-4 h-4" />
              Salvar Status
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

