import React, { useState, useEffect, useMemo } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  UserCheck,
  UserCheck2,
  Users,
  Search,
  Phone,
  Briefcase,
  AlertCircle,
  FileText,
  UserMinus,
  Sparkles,
  ChevronRight,
  ShieldAlert,
  ArrowRightLeft,
  Check,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador | null;
  veiculo?: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus?: (
    colabId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSave?: (
    colabId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSalvarStatus,
  onSave,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta | ''>('');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState<string>('');
  const [substitutoNome, setSubstitutoNome] = useState<string>('');
  const [buscaSubstituto, setBuscaSubstituto] = useState('');
  const [modoManual, setModoManual] = useState(false);
  const [nomeManual, setNomeManual] = useState('');

  // Sincronizar estado ao abrir ou trocar de colaborador
  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || '');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
      setSubstitutoNome(colaborador.substitutoNome || '');
      setBuscaSubstituto('');
      setModoManual(false);
      setNomeManual('');
    }
  }, [colaborador, isOpen]);

  // Lista de candidatos a substitutos (excluindo o próprio colaborador atual)
  const listaCandidatos = useMemo(() => {
    const todos: Colaborador[] = Array.isArray(colaboradoresReserva) ? [...colaboradoresReserva] : [];
    return todos.filter((c) => c && c.id !== colaborador?.id);
  }, [colaboradoresReserva, colaborador]);

  // Filtro de substitutos por busca
  const substitutosFiltrados = useMemo(() => {
    if (!buscaSubstituto.trim()) return listaCandidatos;
    const termo = buscaSubstituto.toLowerCase().trim();
    return listaCandidatos.filter(
      (c) =>
        (c.nome || '').toLowerCase().includes(termo) ||
        (c.cargo || '').toLowerCase().includes(termo) ||
        (c.telefone || '').includes(termo)
    );
  }, [listaCandidatos, buscaSubstituto]);

  if (!isOpen || !colaborador) return null;

  const handleSelecionarSubstituto = (sub: Colaborador) => {
    setSubstitutoId(sub.id);
    setSubstitutoNome(sub.nome);
    setModoManual(false);
  };

  const handleRemoverSubstituto = () => {
    setSubstitutoId('');
    setSubstitutoNome('');
    setNomeManual('');
  };

  const handleSalvar = (e: React.FormEvent) => {
    e.preventDefault();
    if (!colaborador) return;

    const nomeFinalSubstituto = modoManual && nomeManual.trim() ? nomeManual.trim() : substitutoNome;
    const idFinalSubstituto = modoManual ? `manual-${Date.now()}` : substitutoId;

    const salvarFn = onSalvarStatus || onSave;
    if (salvarFn) {
      salvarFn(
        colaborador.id,
        status,
        status !== 'presente' && motivo ? (motivo as MotivoFalta) : undefined,
        observacao.trim() || undefined,
        status === 'substituto' ? idFinalSubstituto : undefined,
        status === 'substituto' ? nomeFinalSubstituto : undefined
      );
    }
    onClose();
  };

  const substitutoEscolhidoObj = listaCandidatos.find((c) => c.id === substitutoId);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-xl max-h-[92vh] flex flex-col bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary shrink-0">
              <Users className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <h2 className="text-base font-bold text-foreground">Registro de Frequência</h2>
              <p className="text-xs text-muted-foreground">
                {veiculo?.prefixo ? `${veiculo.prefixo} • ` : ''}Atualize o status do colaborador
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Corpo com scroll suave */}
        <form onSubmit={handleSalvar} className="flex-1 overflow-y-auto p-5 sm:p-6 space-y-5">
          {/* Cartão do Colaborador Selecionado */}
          <div className="flex items-center gap-4 p-3.5 rounded-2xl border border-border/60 bg-muted/30">
            <div className="relative w-14 h-14 rounded-2xl overflow-hidden border-2 border-border/80 bg-zinc-900 shrink-0 shadow-sm">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-zinc-300 font-black text-base bg-emerald-950/40">
                  {getIniciais(colaborador.nome)}
                </div>
              )}
            </div>
            <div className="min-w-0 flex-1">
              <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-400">
                Colaborador Titular
              </span>
              <h3 className="font-bold text-base text-foreground truncate">{colaborador.nome}</h3>
              <p className="text-xs text-muted-foreground truncate flex items-center gap-1.5 mt-0.5">
                <Briefcase className="w-3 h-3 text-muted-foreground/70" />
                {colaborador.cargo || 'Operador Florestal'}
              </p>
            </div>
          </div>

          {/* Seleção do Status Principal */}
          <div>
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-2">
              Status da Presença Hoje
            </label>
            <div className="grid grid-cols-3 gap-2.5">
              {/* Opção Presente */}
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer text-center gap-2',
                  status === 'presente'
                    ? 'border-emerald-500 bg-emerald-500/15 text-emerald-300 shadow-md shadow-emerald-500/10'
                    : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                )}
              >
                <div className={cn(
                  'w-8 h-8 rounded-xl flex items-center justify-center',
                  status === 'presente' ? 'bg-emerald-500 text-white shadow-sm' : 'bg-muted/50 text-muted-foreground'
                )}>
                  <CheckCircle2 className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-xs font-bold block">Presente</span>
                  <span className="text-[10px] opacity-75">Em operação</span>
                </div>
              </button>

              {/* Opção Falta */}
              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer text-center gap-2',
                  status === 'falta'
                    ? 'border-rose-500 bg-rose-500/15 text-rose-300 shadow-md shadow-rose-500/10'
