import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  ChevronRight,
  UserCheck,
  AlertTriangle,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; dotColor: string; badgeClass: string }> = {
  presente: {
    label: 'Presente',
    dotColor: 'bg-emerald-400',
    badgeClass: 'bg-emerald-500/20 text-emerald-300 border-emerald-500/30',
  },
  falta: {
    label: 'Falta',
    dotColor: 'bg-rose-400',
    badgeClass: 'bg-rose-500/20 text-rose-300 border-rose-500/30',
  },
  substituto: {
    label: 'Substituto',
    dotColor: 'bg-amber-400',
    badgeClass: 'bg-amber-500/20 text-amber-300 border-amber-500/30',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'OP';
  const partes = nome.trim().split(' ').filter(Boolean);
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length - 1][0]).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [filtroRegional, setFiltroRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;

      const assentosLista = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean) as Colaborador[];

      const matchRegional = filtroRegional === 'todas' || v.regional === filtroRegional;

      const matchBusca =
        !busca ||
        v.prefixo?.toLowerCase().includes(busca.toLowerCase()) ||
        v.placa?.toLowerCase().includes(busca.toLowerCase()) ||
        v.modelo?.toLowerCase().includes(busca.toLowerCase()) ||
        assentosLista.some((c) => c?.nome?.toLowerCase().includes(busca.toLowerCase()));

      const temFalta = assentosLista.some((c) => c?.status === 'falta');
      const matchStatus =
        filtroStatus === 'todos' ||
        (filtroStatus === 'completos' && !temFalta) ||
        (filtroStatus === 'incompletos' && temFalta);

      return matchRegional && matchBusca && matchStatus;
    });
  }, [veiculos, busca, filtroRegional, filtroStatus]);

  const handleSalvarPresenca = (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(colabId, novoStatus, motivo, obs, substitutoId, substitutoNome);
    }
    setColaboradorSelecionado(null);
  };

  const renderAssento = (
    colaborador?: Colaborador,
    labelPosicao?: string,
    ehLadoMotorista: boolean = false
  ) => {
    if (!colaborador) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed border-border/60 bg-muted/20 min-h-[140px]">
          <span className="text-xs text-muted-foreground font-medium">Assento Livre</span>
        </div>
      );
    }

    const cfg = statusConfig[colaborador.status] || statusConfig.presente;
    const ehFalta = colaborador.status === 'falta';
    const ehSubstituto = colaborador.status === 'substituto';

    return (
      <div
        onClick={() => setColaboradorSelecionado(colaborador)}
        className={cn(
          'group relative flex flex-col items-center justify-between p-3 rounded-2xl border cursor-pointer select-none transition-all duration-200',
          'bg-gradient-to-b from-card/90 via-card/60 to-card/95 hover:shadow-xl hover:scale-[1.02] active:scale-[0.98]',
          ehFalta
            ? 'border-rose-500/50 hover:border-rose-500 bg-rose-500/[0.04]'
            : ehSubstituto
            ? 'border-amber-500/50 hover:border-amber-500 bg-amber-500/[0.04]'
            : 'border-emerald-500/40 hover:border-emerald-400 bg-emerald-500/[0.03]'
        )}
      >
        {/* Status indicator pill superior */}
        <div className="w-full flex items-center justify-between gap-1 mb-2">
          <Badge
            variant="outline"
            className={cn('text-[10px] font-bold py-0.5 px-2 border leading-none tracking-tight', cfg.badgeClass)}
          >
            <span className={cn('w-1.5 h-1.5 rounded-full mr-1 shrink-0 animate-pulse', cfg.dotColor)} />
            {cfg.label}
          </Badge>
          <span className="text-[10px] font-semibold text-muted-foreground opacity-70 group-hover:opacity-100 transition-opacity">
            Editar
          </span>
        </div>

        {/* Foto Ampliada do Colaborador (Visualização Superior / Banco do Veículo) */}
        <div className="relative my-1">
          <div
            className={cn(
              'w-20 h-20 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-2 shadow-md transition-all duration-200 flex items-center justify-center bg-muted/70',
              ehFalta
                ? 'border-rose-500 ring-4 ring-rose-500/20'
                : ehSubstituto
                ? 'border-amber-500 ring-4 ring-amber-500/20'
                : 'border-emerald-500 ring-4 ring-emerald-500/20'
            )}
          >
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                onError={(e) => {
                  (e.target as HTMLElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full flex flex-col items-center justify-center font-black text-xl text-foreground/80 bg-gradient-to-br from-muted to-muted/40">
                {getIniciais(colaborador.nome)}
              </div>
            )}
          </div>

          {/* Ícone de status fixado na foto */}
          <div className="absolute -bottom-1 -right-1 rounded-full bg-background p-0.5 shadow-md">
            {ehFalta ? (
              <XCircle className="w-5 h-5 text-rose-500 fill-rose-500/20" />
            ) : ehSubstituto ? (
              <HelpCircle className="w-5 h-5 text-amber-500 fill-amber-500/20" />
            ) : (
              <CheckCircle2 className="w-5 h-5 text-emerald-500 fill-emerald-500/20" />
            )}
          </div>
        </div>

        {/* Nome do Colaborador logo abaixo da foto */}
        <div className="w-full text-center mt-2 space-y-0.5">
          <p className="font-bold text-xs sm:text-sm text-foreground line-clamp-1 group-hover:text-emerald-400 transition-colors">
            {colaborador.nome || 'Operador'}
          </p>
          <p className="text-[11px] text-muted-foreground line-clamp-1">
            {colaborador.cargo || 'Operador de Campo'}
          </p>

          {colaborador.substitutoNome && (
            <p className="text-[10px] text-amber-300 font-semibold mt-0.5 line-clamp-1">
              Sub: {colaborador.substitutoNome}
            </p>
          )}

          {ehFalta && colaborador.motivoFalta && (
            <p className="text-[10px] text-rose-300 font-medium line-clamp-1">
              {colaborador.motivoFalta}
            </p>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-5">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/70 p-3.5 rounded-2xl border border-border/70 backdrop-blur-md">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3.5 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo, placa ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-10 text-xs bg-background/50 border-border/60 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={filtroStatus}
            onChange={(e) => setFiltroStatus(e.target.value as any)}
            className="h-10 px-3 rounded-xl border border-border/70 bg-background/60 text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todos">Todos os Veículos</option>
            <option value="completos">Equipes 100% Presentes</option>
            <option value="incompletos">Com Ausências / Faltas</option>
          </select>

          <select
            value={filtroRegional}
            onChange={(e) => setFiltroRegional(e.target.value as any)}
            className="h-10 px-3 rounded-xl border border-border/70 bg-background/60 text-xs font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          >
            <option value="todas">Todas as Regionais</option>
            <option value="ribas">Ribas do Rio Pardo</option>
            <option value="agua_clara">Água Clara</option>
          </select>
        </div>
      </div>

      {/* Grid de Veículos com visão dos colaboradores dentro do veículo */}
      {veiculosFiltrados.length === 0 ? (
        <div className="p-12 text-center rounded-3xl border border-dashed border-border/80 bg-card/30">
          <Car className="w-10 h-10 text-muted-foreground mx-auto mb-2 opacity-50" />
          <p className="text-base font-bold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground mt-1">Ajuste os filtros de busca para encontrar as equipes da frota.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-5">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = veiculo.assentos || {};
            const motorista = assentos.motorista;
            const frenteDir = assentos.frenteDir;
            const trasEsq = assentos.trasEsq;
            const trasDir = assentos.trasDir;

            const todosAssentos = [motorista, frenteDir, trasEsq, trasDir].filter(Boolean) as Colaborador[];
            const totalFaltas = todosAssentos.filter((c) => c.status === 'falta').length;
            const totalSubstitutos = todosAssentos.filter((c) => c.status === 'substituto').length;
            const totalPresentes = todosAssentos.filter((c) => c.status === 'presente').length;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'rounded-3xl border transition-all duration-200 overflow-hidden shadow-lg',
                  totalFaltas > 0
                    ? 'border-rose-500/30 bg-card/70'
                    : 'border-border/70 bg-card/50'
                )}
              >
                {/* Header do Card do Veículo */}
                <div className="px-5 py-4 border-b border-border/50 bg-gradient-to-r from-muted/40 via-muted/20 to-transparent flex items-center justify-between gap-3 flex-wrap">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center shrink-0">
                      <Car className="w-5 h-5 text-emerald-400" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-base tracking-tight text-foreground">
                          {veiculo.prefixo}
                        </span>
                        <Badge variant="outline" className="text-[10px] font-mono font-bold py-0.5 px-2 bg-background/60">
                          {veiculo.placa}
                        </Badge>
                      </div>
                      <p className="text-xs text-muted-foreground flex items-center gap-1.5 mt-0.5">
                        <MapPin className="w-3 h-3 text-emerald-400" />
                        {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                        <span>·</span>
                        <span>{veiculo.modelo}</span>
                      </p>
                    </div>
                  </div>

                  {/* Resumo da Equipe */}
                  <div className="flex items-center gap-1.5">
                    {totalFaltas > 0 ? (
                      <Badge variant="outline" className="bg-rose-500/15 border-rose-500/30 text-rose-300 font-bold text-xs py-1 px-2.5">
                        <AlertTriangle className="w-3 h-3 mr-1" />
                        {totalFaltas} Ausência{totalFaltas > 1 ? 's' : ''}
                      </Badge>
                    ) : (
                      <Badge variant="outline" className="bg-emerald-500/15 border-emerald-500/30 text-emerald-300 font-bold text-xs py-1 px-2.5">
                        <CheckCircle2 className="w-3 h-3 mr-1" />
                        Equipe Completa
                      </Badge>
                    )}
                  </div>
                </div>

                {/* Estrutura Superior do Carro com os Bancos e Colaboradores */}
                <CardContent className="p-4 sm:p-5">
                  <div className="relative rounded-3xl border border-border/70 bg-gradient-to-b from-muted/25 via-background/40 to-muted/25 p-4 sm:p-5 shadow-inner">
                    {/* Linha da Frente (2 colaboradores sentados à frente) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 mb-4">
                      {renderAssento(motorista, 'Condutor', true)}
                      {renderAssento(frenteDir, 'Passageiro Dianteiro', false)}
                    </div>

                    {/* Divisor sutil entre cabine dianteira e traseira */}
                    <div className="relative my-3 flex items-center justify-center">
                      <div className="w-full border-t border-border/40" />
                      <span className="absolute bg-card px-3 py-0.5 rounded-full border border-border/50 text-[10px] font-semibold text-muted-foreground/70 uppercase tracking-widest">
                        Cabine
                      </span>
                    </div>

                    {/* Linha Traseira (2 colaboradores sentados atrás) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4">
                      {renderAssento(trasEsq, 'Traseiro Esquerdo', false)}
                      {renderAssento(trasDir, 'Traseiro Direito', false)}
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Presença ao Clicar na Foto do Colaborador */}
      {colaboradorSelecionado && (
        <AttendanceModal
          isOpen={!!colaboradorSelecionado}
          onClose={() => setColaboradorSelecionado(null)}
          colaborador={colaboradorSelecionado}
          colaboradoresReserva={colaboradoresReserva}
          onSave={handleSalvarPresenca}
        />
      )}
    </div>
  );
};

