          'group relative flex flex-col items-center justify-between p-3 rounded-2xl border transition-all cursor-pointer text-center select-none min-h-[145px]',
          colab.status === 'falta'
            ? 'border-rose-500/40 bg-rose-950/15 hover:border-rose-500/70'
            : colab.status === 'substituto'
            ? 'border-amber-500/40 bg-amber-950/15 hover:border-amber-500/70'
            : 'border-border/70 bg-card/70 hover:border-emerald-500/50 hover:bg-muted/40 shadow-sm'
        )}
      >
        {/* Foto Ampliada em Vista Superior */}
        <div className="relative mt-0.5">
          <div
            className={cn(
              'w-16 h-16 sm:w-18 sm:h-18 rounded-2xl overflow-hidden border-2 shadow-md transition-transform group-hover:scale-105 bg-zinc-900',
              colab.status === 'falta'
                ? 'border-rose-500/80 ring-2 ring-rose-500/20'
                : colab.status === 'substituto'
                ? 'border-amber-500/80 ring-2 ring-amber-500/20'
                : 'border-emerald-500/70 ring-2 ring-emerald-500/10'
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className={cn(
                  'w-full h-full object-cover transition-opacity',
                  colab.status === 'falta' && 'opacity-40 grayscale'
                )}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center font-black text-sm text-zinc-300 bg-emerald-950/40">
                {getIniciais(colab.nome)}
              </div>
            )}
          </div>

          {/* Indicador de Status Rápido no Canto */}
          <span
            className={cn(
              'absolute -top-1 -right-1 w-4 h-4 rounded-full border-2 border-card flex items-center justify-center shrink-0',
              badge.dot
            )}
          />
        </div>

        {/* Nome do Colaborador Imediatamente Abaixo da Foto */}
        <div className="w-full mt-2 space-y-0.5">
          <p
            className={cn(
              'text-xs font-bold truncate transition-colors px-1',
              colab.status === 'falta'
                ? 'text-rose-300 line-through'
                : 'text-foreground group-hover:text-emerald-300'
            )}
            title={colab.nome}
          >
            {colab.nome}
          </p>
          <p className="text-[10px] text-muted-foreground truncate px-1">
            {colab.cargo || 'Operador'}
          </p>
        </div>

        {/* Badge de Status / Substituto */}
        <div className="w-full mt-1.5 pt-1.5 border-t border-border/40">
          <span
            className={cn(
              'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold border',
              badge.bg
            )}
          >
            <span className={cn('w-1.5 h-1.5 rounded-full', badge.dot)} />
            {colab.status === 'substituto' && colab.substitutoNome
              ? `Subst: ${colab.substitutoNome.split(' ')[0]}`
              : badge.label}
          </span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-5">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 p-3 rounded-2xl border border-border/60">
        <div className="relative flex-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
          <Input
            placeholder="Buscar veículo, placa ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/60 border-border/70 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 bg-background/60 p-1 rounded-xl border border-border/70">
            <button
              type="button"
              onClick={() => setFiltroStatus('todos')}
              className={cn(
                'px-2.5 py-1 text-xs font-medium rounded-lg transition-all',
                filtroStatus === 'todos'
                  ? 'bg-primary text-primary-foreground shadow-sm font-bold'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos ({veiculos.length})
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('completos')}
              className={cn(
                'px-2.5 py-1 text-xs font-medium rounded-lg transition-all',
                filtroStatus === 'completos'
                  ? 'bg-emerald-600 text-white shadow-sm font-bold'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Completos
            </button>
            <button
              type="button"
              onClick={() => setFiltroStatus('incompletos')}
              className={cn(
                'px-2.5 py-1 text-xs font-medium rounded-lg transition-all',
                filtroStatus === 'incompletos'
                  ? 'bg-rose-600 text-white shadow-sm font-bold'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Com Falta
            </button>
          </div>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="py-14 text-center rounded-3xl border border-dashed border-border/80 bg-card/30 space-y-2">
          <Car className="w-9 h-9 text-muted-foreground/60 mx-auto" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            Ajuste a busca ou troque o filtro regional para visualizar outros carros da frota.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {veiculosFiltrados.map((v) => {
            const eq1Falta =
              v.assentos?.motorista?.status === 'falta' || v.assentos?.frenteDir?.status === 'falta';
            const eq2Falta =
              v.assentos?.trasEsq?.status === 'falta' || v.assentos?.trasDir?.status === 'falta';

            return (
              <Card
                key={v.id}
                className="rounded-3xl border border-border/80 bg-card/80 backdrop-blur-md shadow-lg overflow-hidden flex flex-col justify-between"
              >
                {/* Header do Card */}
                <div className="p-4 border-b border-border/60 bg-gradient-to-r from-muted/30 to-muted/10 flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2.5 min-w-0">
                    <div className="w-9 h-9 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400 shrink-0">
                      <Car className="w-5 h-5" />
                    </div>
                    <div className="min-w-0">
                      <h3 className="font-black text-sm text-foreground truncate">{v.prefixo}</h3>
                      <p className="text-[11px] text-muted-foreground flex items-center gap-1 truncate">
                        <span>{v.modelo}</span>
                        <span>•</span>
                        <span className="font-semibold text-foreground">{v.placa}</span>
                      </p>
                    </div>
                  </div>

                  <Badge
                    variant="outline"
                    className={cn(
                      'text-[10px] font-bold px-2 py-0.5 border shrink-0',
                      v.regional === 'ribas'
                        ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-300'
                        : 'bg-teal-500/10 border-teal-500/30 text-teal-300'
                    )}
                  >
                    {v.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                  </Badge>
                </div>

                {/* Habitáculo do Carro (Visão Superior) */}
                <div className="p-4 space-y-4">
                  {/* Seção Frontal (Equipe 1) */}
                  <div className="space-y-2">
                    <div className="flex items-center justify-between px-1">
                      <span className="text-[11px] font-bold text-muted-foreground tracking-wide flex items-center gap-1.5">
                        <Users className="w-3.5 h-3.5 text-emerald-400" />
                        {v.equipe1Codigo || 'Equipe 1 (Frente)'}
                      </span>
                      {eq1Falta && (
                        <span className="text-[10px] font-bold text-rose-400 bg-rose-500/10 border border-rose-500/20 px-1.5 py-0.2 rounded-md">
                          Desfalque
                        </span>
                      )}
                    </div>

                    <div className="grid grid-cols-2 gap-2.5">
                      {renderAssentoCockpit(v.assentos?.motorista, v, 'Motorista')}
                      {renderAssentoCockpit(v.assentos?.frenteDir, v, 'Passageiro')}
                    </div>
                  </div>

                  {/* Seção Traseira (Equipe 2) */}
                  <div className="space-y-2 pt-2 border-t border-border/50">
                    <div className="flex items-center justify-between px-1">
                      <span className="text-[11px] font-bold text-muted-foreground tracking-wide flex items-center gap-1.5">
                        <Users className="w-3.5 h-3.5 text-teal-400" />
                        {v.equipe2Codigo || 'Equipe 2 (Traseira)'}
                      </span>
                      {eq2Falta && (
                        <span className="text-[10px] font-bold text-rose-400 bg-rose-500/10 border border-rose-500/20 px-1.5 py-0.2 rounded-md">
                          Desfalque
                        </span>
                      )}
                    </div>

                    <div className="grid grid-cols-2 gap-2.5">
                      {renderAssentoCockpit(v.assentos?.trasEsq, v, 'Traseiro Esq.')}
                      {renderAssentoCockpit(v.assentos?.trasDir, v, 'Traseiro Dir.')}
                    </div>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Alteração de Frequência / Substituição */}
      <AttendanceModal
        isOpen={modalAberto}
        onClose={() => setModalAberto(false)}
        colaborador={colaboradorAtivo}
        veiculo={veiculoAtivo}
        colaboradoresReserva={colaboradoresReserva}
        onSalvarStatus={handleSalvarPresenca}
      />
    </div>
  );
};

