                  </span>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {veiculosFiltrados.length === 0 && (
        <div className="flex flex-col items-center justify-center p-12 text-center rounded-2xl border border-dashed border-border bg-card/40">
          <Car className="w-10 h-10 text-muted-foreground mb-3 opacity-40" />
          <h3 className="text-base font-semibold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm">
