                          {colab.dataAdmissao}
                        </td>
                        <td className="px-4 py-3 text-center">
                          <Badge
                            variant={colab.totalFaltas > 3 ? 'destructive' : 'secondary'}
                            className="tabular-nums font-bold"
                          >
                            {colab.totalFaltas} {colab.totalFaltas === 1 ? 'falta' : 'faltas'}
                          </Badge>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

