      { nome: 'Roberto Alves Santos', funcao: 'Operador de Carregadeira', unidade: 'Água Clara', dataAdmissao: '22/02/2021', totalFaltas: 2, regionalKey: 'agua_clara' },
    ]
  },
];

// Função universal de download compatível com Excel (BOM UTF-8, delimitador ;)
function baixarPlanilhaCSV(linhas: Array<Record<string, string | number>>, nomeArquivo: string) {
  if (!linhas || linhas.length === 0) return;
  const colunas = Object.keys(linhas[0]);
  const cabecalho = colunas.join(';');
  const dados = linhas.map((linha) =>
    colunas
      .map((col) => {
        const valor = String(linha[col] ?? '').replace(/"/g, '""');
        return `"${valor}"`;
      })
      .join(';')
  );

  const conteudoCSV = '\uFEFF' + [cabecalho, ...dados].join('\r\n');
  const blob = new Blob([conteudoCSV], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `${nomeArquivo}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(new Date().getMonth());
  const [exportando, setExportando] = useState(false);

  // Extrair colaboradores com unidade e data de admissão
  const todosColaboradores = useMemo(() => {
    const lista: Array<{
      id: string;
      nome: string;
      cargo: string;
      unidade: string;
      dataAdmissao: string;
