    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  // Colaboradores que faltaram hoje
  const faltantesHoje = useMemo(() => {
    return todosColaboradores.filter((c) => {
      const matchRegional = selectedRegional === 'todas' || c.regional === selectedRegional;
      return matchRegional && c.status === 'falta';
    });
  }, [todosColaboradores, selectedRegional]);

  // Histórico do mês selecionado filtrado por regional
  const faltasHistoricoMes = useMemo(() => {
    const registroMes = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === mesSelecionado);
    if (!registroMes) return [];
    if (selectedRegional === 'todas') return registroMes.faltas;
    return registroMes.faltas.filter((f) => f.regionalKey === selectedRegional);
  }, [mesSelecionado, selectedRegional]);

  const handleExportarExcelHoje = async () => {
    setExportando(true);
    try {
      // Tenta usar a biblioteca XLSX se disponível dinamicamente, ou fallback nativo
      let exportadoViaXLSX = false;
      try {
        const XLSX = await import('xlsx');
        if (XLSX && XLSX.utils) {
          const dadosPlanilha = todosColaboradores
            .filter((c) => selectedRegional === 'todas' || c.regional === selectedRegional)
            .map((c) => ({
              'Nome Completo': c.nome,
              'Unidade': c.unidade,
              'Função / Cargo': c.cargo,
              'Data de Admissão': c.dataAdmissao,
              'Status Hoje': c.status.toUpperCase(),
              'Motivo da Falta': c.motivo,
              'Veículo Prefixo': c.veiculo,
              'Placa': c.placa,
              'Equipe': c.equipe,
            }));

          const ws = XLSX.utils.json_to_sheet(dadosPlanilha);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, 'Presença e Faltas');
          XLSX.writeFile(wb, `Controle_Faltas_${new Date().toISOString().split('T')[0]}.xlsx`);
          exportadoViaXLSX = true;
        }
      } catch {
        // Fallback nativo
      }

      if (!exportadoViaXLSX) {
        const dadosCSV = todosColaboradores
          .filter((c) => selectedRegional === 'todas' || c.regional === selectedRegional)
