                <FileUp className="w-8 h-8 text-emerald-400" />
                <div>
                  <p className="text-xs font-semibold text-foreground">
                    Clique abaixo para selecionar a planilha
                  </p>
                  <p className="text-[11px] text-muted-foreground mt-0.5">
                    Colunas aceitas: Nome, Função/Cargo, Unidade, Data de Admissão, Telefone
                  </p>
                </div>
                <input
                  ref={excelInputRef}
                  type="file"
                  accept=".csv,.txt,.xlsx"
                  onChange={handleUploadExcelArquivo}
                  className="hidden"
                />
                <Button
                  type="button"
                  onClick={() => excelInputRef.current?.click()}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs"
                >
                  Selecionar Arquivo do Computador
                </Button>
                {excelArquivoNome && (
                  <span className="text-xs text-emerald-400 font-semibold">{excelArquivoNome}</span>
                )}
              </div>

              {isProcessandoExcel && (
                <div className="flex items-center justify-center gap-2 p-3 text-xs text-muted-foreground">
                  <Loader2 className="w-4 h-4 animate-spin text-emerald-400" />
                  <span>Processando linhas da planilha...</span>
                </div>
              )}

              {excelErro && (
                <div className="p-3 rounded-xl border border-rose-500/30 bg-rose-500/10 text-rose-300 text-xs flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                  <span>{excelErro}</span>
                </div>
              )}

              {excelPreview.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-xs">
                    <span className="font-semibold text-foreground">
                      Prévia dos Colaboradores ({excelPreview.length} encontrados):
                    </span>
                    <Badge variant="outline" className="border-emerald-500/40 text-emerald-400 bg-emerald-500/10">
                      Pronto para salvar
                    </Badge>
                  </div>
                  <div className="max-h-48 overflow-y-auto rounded-xl border border-border/50 divide-y divide-border/30 bg-muted/20 text-xs">
                    {excelPreview.slice(0, 10).map((p, i) => (
                      <div key={i} className="p-2 flex items-center justify-between">
                        <div>
                          <span className="font-bold text-foreground">{p.nome}</span>
                          <span className="text-muted-foreground ml-2">({p.cargo})</span>
                        </div>
                        <span className="text-muted-foreground text-[11px]">{p.unidade}</span>
                      </div>
                    ))}
                    {excelPreview.length > 10 && (
                      <div className="p-2 text-center text-[11px] text-muted-foreground font-medium">
                        + {excelPreview.length - 10} outros colaboradores...
                      </div>
                    )}
                  </div>
                </div>
              )}

              {excelImportSucesso && (
                <div className="p-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-300 text-xs flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 shrink-0 text-emerald-400" />
                  <span>Colaboradores importados com sucesso para o banco de dados!</span>
                </div>
              )}

              <div className="flex items-center justify-between pt-3 border-t border-border/40">
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={baixarModeloExcel}
                  className="text-xs text-muted-foreground hover:text-foreground"
                >
                  <Download className="w-3.5 h-3.5 mr-1" />
                  Baixar Modelo de Exemplo (.csv)
                </Button>

                <div className="flex gap-2">
                  <Button type="button" variant="outline" onClick={() => setModalExcelAberto(false)}>
                    Fechar
                  </Button>
                  <Button
                    type="button"
                    onClick={handleConfirmarImportacao}
                    disabled={excelPreview.length === 0 || excelImportSucesso}
                    className="bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs"
                  >
                    Confirmar e Importar
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {fotoModalAberta && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in"
          onClick={() => setFotoModalAberta(null)}
        >
          <div className="relative max-w-sm w-full bg-card rounded-2xl p-4 border border-border/80 shadow-2xl text-center space-y-3" onClick={(e) => e.stopPropagation()}>
            <img
              src={fotoModalAberta.url}
              alt={fotoModalAberta.nome}
              className="w-48 h-48 rounded-2xl object-cover mx-auto border-2 border-emerald-500/40 shadow-lg"
            />
            <div>
              <h3 className="font-bold text-foreground text-base">{fotoModalAberta.nome}</h3>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setFotoModalAberta(null)}
              className="w-full"
            >
              Fechar
            </Button>
          </div>
        </div>
      )}
    </div>
  );
};

