  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);
  const [authPronta, setAuthPronta] = useState(false);
  const [sincronizando, setSincronizando] = useState(false);
  const [usuarioEmail, setUsuarioEmail] = useState<string | null>(null);

  // Failsafe rápido para autenticação - evita tela branca e timeout do host
  useEffect(() => {
    let montado = true;

    const timer = setTimeout(() => {
      if (montado && !authPronta) {
        setAuthPronta(true);
      }
    }, 600);

    const verificarSessao = async () => {
      try {
        const { data } = await supabase.auth.getSession();
        if (montado) {
          if (data?.session?.user?.email) {
            setUsuarioEmail(data.session.user.email);
          }
          setAuthPronta(true);
        }
      } catch (err) {
        console.warn('Supabase auth getSession fallback:', err);
        if (montado) {
          setAuthPronta(true);
        }
      }
    };

    verificarSessao();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (montado) {
        setUsuarioEmail(session?.user?.email ?? null);
        setAuthPronta(true);
      }
    });

    return () => {
      montado = false;
      clearTimeout(timer);
      subscription?.unsubscribe();
    };
  }, [authPronta]);

