import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  Calendar,
  AlertCircle,
  Clock,
  ArrowRightLeft,
  Shield,
  Layers,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional | string;
  onUpdateStatus?: (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substituto?: Colaborador
  ) => void;
}

const statusBadgeStyles: Record<StatusPresenca, { label: string; badgeClass: string; icon: any }> = {
  presente: {
    label: 'Presente',
    badgeClass: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    badgeClass: 'bg-rose-500/20 text-rose-400 border-rose-500/30',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    badgeClass: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    icon: ArrowRightLeft,
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateStatus,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');
  const [modalColaborador, setModalColaborador] = useState<{
    isOpen: boolean;
    veiculoId: string;
    veiculoPrefixo: string;
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
    posicaoLabel: string;
    colaborador: Colaborador;
  } | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional =
        selectedRegional === 'todas' || !selectedRegional || v.regional === selectedRegional;

      const termo = search.toLowerCase().trim();
      const matchSearch =
        !termo ||
        v.prefixo?.toLowerCase().includes(termo) ||
        v.placa?.toLowerCase().includes(termo) ||
        v.equipe1Codigo?.toLowerCase().includes(termo) ||
        v.equipe2Codigo?.toLowerCase().includes(termo) ||
        v.assentos?.motorista?.nome?.toLowerCase().includes(termo) ||
        v.assentos?.frenteDir?.nome?.toLowerCase().includes(termo) ||
        v.assentos?.trasEsq?.nome?.toLowerCase().includes(termo) ||
        v.assentos?.trasDir?.nome?.toLowerCase().includes(termo);

      const assentosLista = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      const temFalta = assentosLista.some((c) => c?.status === 'falta');
      const matchStatus =
        filterStatus === 'todos' ||
        (filterStatus === 'incompletos' && temFalta) ||
        (filterStatus === 'completos' && !temFalta);

      return matchRegional && matchSearch && matchStatus;
    });
  }, [veiculos, selectedRegional, search, filterStatus]);

  const abrirModalPresenca = (
    veiculo: Veiculo,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    posicaoLabel: string,
    colaborador?: Colaborador
  ) => {
    if (!colaborador) return;
    setModalColaborador({
      isOpen: true,
      veiculoId: veiculo.id,
      veiculoPrefixo: veiculo.prefixo,
      posicao,
      posicaoLabel,
      colaborador,
    });
  };

  const renderAssentoColaborador = (
    veiculo: Veiculo,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    posicaoLabel: string,
    colaborador?: Colaborador
  ) => {
    if (!colaborador) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-xl border border-dashed border-border/60 bg-muted/20 text-muted-foreground text-center">
          <HelpCircle className="w-5 h-5 mb-1 opacity-50" />
          <span className="text-[11px] font-medium">Assento Vago</span>
        </div>
      );
    }

    const config = statusBadgeStyles[colaborador.status || 'presente'] || statusBadgeStyles.presente;
    const StatusIcon = config.icon;

    return (
      <button
        type="button"
        onClick={() => abrirModalPresenca(veiculo, posicao, posicaoLabel, colaborador)}
        className={cn(
          'w-full group text-left rounded-xl p-3 border transition-all duration-200 cursor-pointer relative overflow-hidden',
          'bg-card/90 hover:bg-card hover:border-emerald-500/50 hover:shadow-md focus:outline-none focus:ring-2 focus:ring-emerald-500/30',
          colaborador.status === 'falta'
            ? 'border-rose-500/30 bg-rose-500/5'
            : colaborador.status === 'substituto'
            ? 'border-amber-500/30 bg-amber-500/5'
            : 'border-border/60'
        )}
      >
        <div className="flex items-center justify-between gap-1 mb-2">
          <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
            {posicaoLabel}
          </span>
          <span
            className={cn(
              'inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-semibold border',
              config.badgeClass
            )}
          >
            <StatusIcon className="w-3 h-3 shrink-0" />
            <span>{config.label}</span>
          </span>
        </div>

        {/* Foto Ampliada em Destaque Central com Nome Abaixo */}
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-2">
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-16 h-16 sm:w-20 sm:h-20 rounded-2xl object-cover border-2 border-emerald-500/30 shadow-md group-hover:border-emerald-500/70 transition-colors"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-16 h-16 sm:w-20 sm:h-20 rounded-2xl bg-gradient-to-br from-muted to-muted/60 border-2 border-border/80 flex items-center justify-center text-foreground font-black text-lg shadow-inner group-hover:border-emerald-500/50 transition-colors">
                {getIniciais(colaborador.nome)}
              </div>
            )}

            <div
              className={cn(
                'absolute -bottom-1 -right-1 w-5 h-5 rounded-full border-2 border-card flex items-center justify-center shadow',
                colaborador.status === 'presente'
                  ? 'bg-emerald-500 text-white'
                  : colaborador.status === 'falta'
                  ? 'bg-rose-500 text-white'
                  : 'bg-amber-500 text-white'
              )}
            >
              <StatusIcon className="w-3 h-3" />
            </div>
          </div>

          {/* Nome e Cargo Posicionados Diretamente Abaixo da Foto */}
          <h4 className="text-xs sm:text-sm font-bold text-foreground line-clamp-1 w-full leading-tight">
            {colaborador.nome}
          </h4>
          <p className="text-[11px] text-muted-foreground line-clamp-1 mt-0.5 font-medium">
            {colaborador.cargo || 'Operador Florestal'}
          </p>

          {colaborador.substitutoNome && (
            <p className="text-[10px] text-amber-400 mt-1 line-clamp-1 font-semibold flex items-center gap-1">
              <ArrowRightLeft className="w-2.5 h-2.5" />
              Subst: {colaborador.substitutoNome}
            </p>
          )}

          {colaborador.motivoFalta && colaborador.status === 'falta' && (
            <p className="text-[10px] text-rose-400 mt-1 line-clamp-1 font-semibold flex items-center gap-1">
              <AlertCircle className="w-2.5 h-2.5" />
              {colaborador.motivoFalta}
            </p>
          )}
        </div>
      </button>
    );
  };

  return (
    <div className="space-y-4">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-2xl border border-border/60 bg-card/60 backdrop-blur-md shadow-sm">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por prefixo, placa, equipe ou nome do colaborador..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-10 bg-background/80"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setFilterStatus('todos')}
            className={cn(
              'px-3 py-2 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              filterStatus === 'todos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border text-muted-foreground hover:bg-muted/40'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            type="button"
            onClick={() => setFilterStatus('completos')}
            className={cn(
              'px-3 py-2 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              filterStatus === 'completos'
                ? 'bg-emerald-600 text-white border-emerald-500 shadow-sm'
                : 'border-border text-muted-foreground hover:bg-muted/40'
            )}
          >
            100% Presentes
          </button>
          <button
            type="button"
            onClick={() => setFilterStatus('incompletos')}
            className={cn(
              'px-3 py-2 rounded-xl text-xs font-semibold border transition-all cursor-pointer',
              filterStatus === 'incompletos'
                ? 'bg-rose-600 text-white border-rose-500 shadow-sm'
                : 'border-border text-muted-foreground hover:bg-muted/40'
            )}
          >
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border/80 p-12 text-center bg-card/40 space-y-3">
          <Car className="w-12 h-12 text-muted-foreground mx-auto opacity-50" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            Não localizamos veículos com os filtros aplicados. Tente ajustar os termos de busca ou mudar a unidade.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {veiculosFiltrados.map((veiculo) => {
            const assentosLista = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean);

            const totalPresentes = assentosLista.filter(
              (c) => c?.status === 'presente' || c?.status === 'substituto'
            ).length;
            const totalFaltas = assentosLista.filter((c) => c?.status === 'falta').length;

            return (
              <Card
                key={veiculo.id}
                className="overflow-hidden border-border/80 bg-card/70 backdrop-blur-md shadow-lg hover:border-emerald-500/40 transition-all"
              >
                {/* Header do Card com Prefixo, Placa e Resumo */}
                <div className="px-5 py-3.5 border-b border-border/50 bg-gradient-to-r from-muted/40 via-card to-card flex items-center justify-between gap-3 flex-wrap">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center shrink-0 shadow-inner">
                      <Car className="w-5 h-5 text-emerald-400" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="text-base font-extrabold text-foreground tracking-tight">
                          {veiculo.prefixo}
                        </span>
                        <Badge variant="outline" className="text-[10px] py-0 px-1.5 uppercase font-mono">
                          {veiculo.placa}
                        </Badge>
                      </div>
                      <span className="text-[11px] text-muted-foreground font-medium flex items-center gap-1.5">
                        <MapPin className="w-3 h-3 text-emerald-400" />
                        {veiculo.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'}
                        <span className="opacity-40">·</span>
                        {veiculo.modelo}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <span
                      className={cn(
                        'px-2.5 py-1 rounded-full text-xs font-bold border tabular-nums',
                        totalFaltas === 0
                          ? 'bg-emerald-500/15 border-emerald-500/30 text-emerald-400'
                          : 'bg-rose-500/15 border-rose-500/30 text-rose-400'
                      )}
                    >
                      {totalPresentes}/4 Operadores
                    </span>
                  </div>
                </div>

                <CardContent className="p-4 space-y-4">
                  {/* Seção Equipe 1 (Dianteira) */}
                  <div className="space-y-2">
                    <div className="flex items-center justify-between text-xs border-b border-border/40 pb-1">
                      <span className="font-bold text-foreground flex items-center gap-1.5">
                        <Layers className="w-3.5 h-3.5 text-emerald-400" />
                        Equipe 1 ({veiculo.equipe1Codigo || 'Dianteira'})
                      </span>
                      <span className="text-[11px] text-muted-foreground">Cabine Dianteira</span>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      {renderAssentoColaborador(
                        veiculo,
                        'motorista',
                        'Motorista',
                        veiculo.assentos?.motorista
                      )}
                      {renderAssentoColaborador(
                        veiculo,
                        'frenteDir',
                        'Ajudante Frente',
                        veiculo.assentos?.frenteDir
                      )}
                    </div>
                  </div>

                  {/* Seção Equipe 2 (Traseira) */}
                  <div className="space-y-2">
                    <div className="flex items-center justify-between text-xs border-b border-border/40 pb-1">
                      <span className="font-bold text-foreground flex items-center gap-1.5">
                        <Layers className="w-3.5 h-3.5 text-teal-400" />
                        Equipe 2 ({veiculo.equipe2Codigo || 'Traseira'})
                      </span>
                      <span className="text-[11px] text-muted-foreground">Cabine Traseira</span>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      {renderAssentoColaborador(
                        veiculo,
                        'trasEsq',
                        'Operador Trás Esq',
                        veiculo.assentos?.trasEsq
                      )}
                      {renderAssentoColaborador(
                        veiculo,
                        'trasDir',
                        'Operador Trás Dir',
                        veiculo.assentos?.trasDir
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal Interativo de Marcação de Presença / Falta / Substituição */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={modalColaborador.isOpen}
          onClose={() => setModalColaborador(null)}
          colaborador={modalColaborador.colaborador}
          veiculoPrefixo={modalColaborador.veiculoPrefixo}
          posicaoLabel={modalColaborador.posicaoLabel}
          colaboradoresReserva={colaboradoresReserva}
          onSave={(status, motivo, obs, substituto) => {
            onUpdateStatus?.(
              modalColaborador.veiculoId,
              modalColaborador.posicao,
              status,
              motivo,
              obs,
              substituto
            );
            setModalColaborador(null);
          }}
        />
      )}
    </div>
  );
};

