export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [selectedMes, setSelectedMes] = useState<number>(new Date().getMonth());
  const [exportando, setExportando] = useState(false);

  const todosColaboradores = useMemo(() => {
    const list: Array<{
      id: string;
      nome: string;
      funcao: string;
      unidade: string;
      dataAdmissao: string;
      status: string;
      motivoFalta?: string;
      veiculo: string;
      regional: Regional;
    }> = [];

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ];
      assentos.forEach((c) => {
        if (!c) return;
        list.push({
          id: c.id,
          nome: c.nome || 'Não informado',
          funcao: c.cargo || 'Operador',
          unidade: c.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: c.dataAdmissao || '10/02/2023',
          status: c.status || 'presente',
          motivoFalta: c.motivoFalta,
          veiculo: `${v.prefixo} (${v.placa})`,
          regional: v.regional,
        });
      });
    });

    (colaboradoresReserva || []).forEach((c) => {
      if (!c) return;
      list.push({
        id: c.id,
        nome: c.nome || 'Não informado',
        funcao: c.cargo || 'Reserva Operacional',
        unidade: c.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: c.dataAdmissao || '05/06/2023',
        status: c.status || 'presente',
        motivoFalta: c.motivoFalta,
        veiculo: 'Banco de Reserva',
        regional: 'ribas',
      });
    });

    return list;
  }, [veiculos, colaboradoresReserva]);

  const rankingFaltas = useMemo(() => {
    const historicoMes = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === selectedMes);
    if (!historicoMes) return [];

    return historicoMes.faltas.filter((item) => {
      if (selectedRegional === 'todas') return true;
      return item.regionalKey === selectedRegional;
    });
  }, [selectedMes, selectedRegional]);

  const baixarPlanilhaExcelNativa = (linhas: Array<Record<string, string | number>>, nomeArquivo: string) => {
    if (!linhas || linhas.length === 0) return;
    const colunas = Object.keys(linhas[0]);
    const escapeCsv = (valor: any) => {
      const str = String(valor ?? '').replace(/"/g, '""');
      return `"${str}"`;
    };

    const cabecalho = colunas.map(escapeCsv).join(';');
    const corpo = linhas
      .map((row) => colunas.map((col) => escapeCsv(row[col])).join(';'))
      .join('\r\n');

    const csvContent = '\uFEFF' + cabecalho + '\r\n' + corpo;
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', nomeArquivo);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportarPlanilhaGeral = () => {
    setExportando(true);
    try {
      const dataStr = selectedDate.toISOString().split('T')[0];
      const dadosFiltrados = todosColaboradores.filter(
        (c) => selectedRegional === 'todas' || c.regional === selectedRegional
      );

      const linhas = dadosFiltrados.map((c) => ({
        Nome: c.nome,
        Unidade: c.unidade,
        Função: c.funcao,
        'Data de Admissão': c.dataAdmissao,
        Status: c.status.toUpperCase(),
        'Motivo da Falta': c.motivoFalta || '-',
        Veículo: c.veiculo,
        'Data do Registro': selectedDate.toLocaleDateString('pt-BR'),
      }));

      baixarPlanilhaExcelNativa(
        linhas,
        `Controle_Faltas_${selectedRegional}_${dataStr}.csv`
      );
    } finally {
      setTimeout(() => setExportando(false), 500);
    }
  };

  const handleExportarHistoricoMes = () => {
    setExportando(true);
    try {
      const mesNome = MESES[selectedMes];
      const linhas = rankingFaltas.map((item, index) => ({
        Ranking: index + 1,
        Nome: item.nome,
        Unidade: item.unidade,
        Função: item.funcao,
        'Data de Admissão': item.dataAdmissao,
        'Total de Faltas': item.totalFaltas,
        Mês: mesNome,
      }));

      baixarPlanilhaExcelNativa(
        linhas,
        `Historico_Faltas_${mesNome}_2026_${selectedRegional}.csv`
      );
    } finally {
      setTimeout(() => setExportando(false), 500);
    }
  };

  return (
    <div className="w-full space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 p-5 rounded-2xl border border-border/60 bg-card/60 backdrop-blur-md shadow-xl">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-400">
              <FileSpreadsheet className="w-5 h-5" />
            </div>
            <h2 className="text-xl font-bold tracking-tight text-foreground">
              Relatórios e Histórico de Faltas
            </h2>
          </div>
          <p className="text-xs text-muted-foreground">
            Exportação para Excel com Nome, Unidade, Função e Data de Admissão em padrão tabular.
          </p>
        </div>

        <div className="flex items-center gap-2.5 flex-wrap">
          <Button
            onClick={handleExportarPlanilhaGeral}
            disabled={exportando}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-md shadow-emerald-950/20"
          >
            <Download className="w-4 h-4" />
            <span>Exportar Escala do Dia (Excel)</span>
          </Button>

          <Button
            variant="outline"
            onClick={() => window.print()}
            className="gap-2 border-border/80 hover:bg-muted"
          >
            <Printer className="w-4 h-4 text-muted-foreground" />
            <span>Imprimir</span>
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="border-border/60 bg-card/40 backdrop-blur-md">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs">Filtro de Regional Ativo</CardDescription>
            <CardTitle className="text-base flex items-center gap-2 text-foreground">
              <MapPin className="w-4 h-4 text-emerald-400" />
              {regionalLabel[selectedRegional] || 'Todas as Unidades'}
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-0">
            <span className="text-xs text-muted-foreground">
              {todosColaboradores.filter((c) => selectedRegional === 'todas' || c.regional === selectedRegional).length} colaboradores monitorados
            </span>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-card/40 backdrop-blur-md">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs">Data da Escala Atual</CardDescription>
            <CardTitle className="text-base flex items-center gap-2 text-foreground">
              <Calendar className="w-4 h-4 text-emerald-400" />
              {selectedDate.toLocaleDateString('pt-BR', { dateStyle: 'long' })}
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-0">
            <span className="text-xs text-emerald-400 font-medium flex items-center gap-1">
              <CheckCircle2 className="w-3.5 h-3.5" />
              Sincronizado e pronto para download
            </span>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-card/40 backdrop-blur-md">
          <CardHeader className="pb-2">
            <CardDescription className="text-xs">Mês Selecionado para Histórico</CardDescription>
            <CardTitle className="text-base flex items-center gap-2 text-foreground">
              <BarChart3 className="w-4 h-4 text-teal-400" />
              {MESES[selectedMes]} de 2026
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-0">
            <span className="text-xs text-muted-foreground">
              {rankingFaltas.length} colaboradores com faltas registradas no mês
            </span>
          </CardContent>
        </Card>
      </div>

      <Card className="border-border/60 bg-card/60 backdrop-blur-md">
        <CardHeader className="border-b border-border/40 pb-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-base text-foreground flex items-center gap-2">
                <AlertCircle className="w-4 h-4 text-rose-400" />
                Histórico Mensal de Faltas — Ranking Consolidado
              </CardTitle>
              <CardDescription className="text-xs mt-1">
                Visualização auditada com Nome, Unidade, Função, Data de Admissão e Total de Faltas.
              </CardDescription>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <div className="flex items-center gap-1.5 bg-muted/40 p-1 rounded-xl border border-border/50">
                <select
                  value={selectedMes}
                  onChange={(e) => setSelectedMes(Number(e.target.value))}
                  className="bg-transparent text-xs font-semibold px-2 py-1 rounded-lg border-none focus:outline-none text-foreground"
                >
                  {MESES.map((mes, idx) => (
                    <option key={mes} value={idx} className="bg-popover text-foreground">
                      {mes} / 2026
                    </option>
                  ))}
                </select>
              </div>

              <Button
                variant="outline"
                size="sm"
                onClick={handleExportarHistoricoMes}
                disabled={exportando || rankingFaltas.length === 0}
                className="gap-2 border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/10 text-xs font-semibold"
              >
                <FileDown className="w-3.5 h-3.5" />
                <span>Exportar Mês ({MESES[selectedMes]})</span>
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-0">
          {rankingFaltas.length === 0 ? (
            <div className="p-10 text-center space-y-2">
              <CheckCircle2 className="w-10 h-10 text-emerald-400 mx-auto opacity-70" />
              <p className="text-sm font-semibold text-foreground">
                Nenhum registro de falta para o filtro selecionado
              </p>
              <p className="text-xs text-muted-foreground">
                Nenhum colaborador acumulou faltas neste mês em {regionalLabel[selectedRegional]}.
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="border-b border-border/50 bg-muted/20 text-muted-foreground font-semibold">
                    <th className="py-3 px-4 w-12 text-center">#</th>
                    <th className="py-3 px-4">Nome do Colaborador</th>
                    <th className="py-3 px-4">Unidade</th>
                    <th className="py-3 px-4">Função</th>
                    <th className="py-3 px-4">Data de Admissão</th>
                    <th className="py-3 px-4 text-center">Total de Faltas</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/30">
                  {rankingFaltas.map((item, index) => (
                    <tr
                      key={`${item.nome}-${index}`}
                      className="hover:bg-muted/30 transition-colors"
                    >
                      <td className="py-3 px-4 text-center font-bold text-muted-foreground tabular-nums">
                        {index + 1}º
                      </td>
                      <td className="py-3 px-4 font-semibold text-foreground">
                        {item.nome}
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-1.5 text-muted-foreground">
                          <Building2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                          <span>{item.unidade}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-1.5 text-muted-foreground">
                          <Briefcase className="w-3.5 h-3.5 text-teal-400 shrink-0" />
                          <span>{item.funcao}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-1.5 text-muted-foreground tabular-nums">
                          <CalendarDays className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                          <span>{item.dataAdmissao}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4 text-center">
                        <Badge
                          variant="destructive"
                          className="tabular-nums font-bold px-2 py-0.5 bg-rose-500/20 text-rose-400 border border-rose-500/30"
                        >
                          {item.totalFaltas} {item.totalFaltas === 1 ? 'falta' : 'faltas'}
                        </Badge>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

