export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(new Date().getMonth());
  const [filtroRegionalRelatorio, setFiltroRegionalRelatorio] = useState<Regional>(selectedRegional);
  const [isExporting, setIsExporting] = useState(false);

  const dadosMesAtual = useMemo(() => {
    const dados = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === mesSelecionado) || HISTORICO_MENSAL_FALTAS[0];
    if (filtroRegionalRelatorio === 'todas') {
      return dados.faltas;
    }
    return dados.faltas.filter((f) => f.regionalKey === filtroRegionalRelatorio);
  }, [mesSelecionado, filtroRegionalRelatorio]);

  const totalFaltasMes = useMemo(() => {
    return dadosMesAtual.reduce((acc, curr) => acc + curr.totalFaltas, 0);
  }, [dadosMesAtual]);

  const handleExportarExcel = async () => {
    setIsExporting(true);
    try {
      const colunas = [
        ['Nome do Colaborador', 'Unidade', 'Função / Cargo', 'Data de Admissão', 'Total de Faltas', 'Mês de Referência'],
        ...dadosMesAtual.map((f) => [
          f.nome,
          f.unidade,
          f.funcao,
          f.dataAdmissao,
          f.totalFaltas,
          MESES[mesSelecionado]
        ])
      ];

      try {
        // @ts-ignore
        const XLSX = await import('xlsx');
        if (XLSX && XLSX.utils && XLSX.writeFile) {
          const ws = XLSX.utils.aoa_to_sheet(colunas);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, `Faltas_${MESES[mesSelecionado]}`);
          XLSX.writeFile(wb, `Relatorio_Faltas_${MESES[mesSelecionado]}_${new Date().getFullYear()}.xlsx`);
          setIsExporting(false);
          return;
        }
      } catch {
        // fallback para download CSV limpo
      }

      const csvContent = '\uFEFF' + colunas.map((row) => row.map((cell) => `"${cell}"`).join(';')).join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute('download', `Relatorio_Faltas_${MESES[mesSelecionado]}_${new Date().getFullYear()}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } finally {
      setIsExporting(false);
    }
  };

  const handleImprimir = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <FileSpreadsheet className="w-5 h-5 text-emerald-400" />
            Relatório de Faltas e Histórico Mensal
          </h2>
          <p className="text-xs text-muted-foreground mt-1">
            Visualização consolidada com nome, unidade, função, admissão e ranking de faltas.
          </p>
        </div>

        <div className="flex items-center gap-2.5 flex-wrap">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleImprimir}
            className="gap-2 border-border/80 hover:bg-muted"
          >
            <Printer className="w-4 h-4 text-muted-foreground" />
            <span>Imprimir</span>
          </Button>

          <Button
            type="button"
            size="sm"
            onClick={handleExportarExcel}
            disabled={isExporting}
            className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white shadow-sm"
          >
            <Download className="w-4 h-4" />
            <span>{isExporting ? 'Exportando...' : 'Exportar Planilha Excel'}</span>
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="p-4 md:col-span-3">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-4 border-b border-border/40">
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4 text-emerald-400" />
              <span className="text-sm font-semibold text-foreground">Selecione o Mês:</span>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <select
                value={mesSelecionado}
                onChange={(e) => setMesSelecionado(Number(e.target.value))}
                className="h-9 px-3 rounded-xl border border-input bg-card/60 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
              >
                {MESES.map((mes, index) => (
                  <option key={mes} value={index}>
                    {mes}
                  </option>
                ))}
              </select>

              <select
                value={filtroRegionalRelatorio}
                onChange={(e) => setFiltroRegionalRelatorio(e.target.value as Regional)}
                className="h-9 px-3 rounded-xl border border-input bg-card/60 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
              >
                <option value="todas">Todas as Unidades</option>
                <option value="ribas">Ribas do Rio Pardo</option>
                <option value="agua_clara">Água Clara</option>
              </select>
            </div>
          </div>

          <div className="overflow-x-auto mt-4">
            <table className="w-full text-left text-xs border-collapse">
              <thead>
                <tr className="border-b border-border/50 text-muted-foreground uppercase text-[10px] tracking-wider font-semibold">
                  <th className="py-2.5 px-3">Colaborador</th>
                  <th className="py-2.5 px-3">Unidade</th>
                  <th className="py-2.5 px-3">Função / Cargo</th>
                  <th className="py-2.5 px-3">Data de Admissão</th>
                  <th className="py-2.5 px-3 text-right">Faltas no Mês</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/30">
                {dadosMesAtual.map((item, idx) => (
                  <tr key={`${item.nome}-${idx}`} className="hover:bg-muted/30 transition-colors">
                    <td className="py-3 px-3">
                      <div className="font-semibold text-foreground">{item.nome}</div>
                    </td>
                    <td className="py-3 px-3">
                      <div className="flex items-center gap-1.5 text-muted-foreground">
                        <Building2 className="w-3.5 h-3.5 text-emerald-400" />
                        <span>{item.unidade}</span>
                      </div>
                    </td>
                    <td className="py-3 px-3">
                      <div className="flex items-center gap-1.5 text-muted-foreground">
                        <Briefcase className="w-3.5 h-3.5 text-teal-400" />
                        <span>{item.funcao}</span>
                      </div>
                    </td>
                    <td className="py-3 px-3">
                      <div className="flex items-center gap-1.5 text-muted-foreground">
                        <CalendarDays className="w-3.5 h-3.5 text-muted-foreground" />
                        <span className="tabular-nums">{item.dataAdmissao}</span>
                      </div>
                    </td>
                    <td className="py-3 px-3 text-right">
                      <Badge
                        variant="destructive"
                        className={cn(
                          'tabular-nums font-bold px-2 py-0.5',
                          item.totalFaltas > 3 ? 'bg-rose-500/20 text-rose-400 border border-rose-500/30' : 'bg-amber-500/20 text-amber-400 border border-amber-500/30'
                        )}
                      >
                        {item.totalFaltas} {item.totalFaltas === 1 ? 'falta' : 'faltas'}
                      </Badge>
                    </td>
                  </tr>
                ))}
                {dadosMesAtual.length === 0 && (
                  <tr>
                    <td colSpan={5} className="py-8 text-center text-muted-foreground">
                      Nenhum registro de falta no período selecionado.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </Card>

        <div className="space-y-4">
          <Card className="p-4 bg-gradient-to-br from-card/80 to-card/40">
            <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">
              Resumo do Mês
            </h3>
            <div className="space-y-3">
              <div>
                <p className="text-2xl font-black text-rose-400 tabular-nums">{totalFaltasMes}</p>
                <p className="text-xs text-muted-foreground">Faltas totais computadas</p>
              </div>
              <div className="pt-3 border-t border-border/40">
                <p className="text-xs text-muted-foreground mb-1">Mês de Referência:</p>
                <Badge variant="outline" className="text-xs border-emerald-500/30 text-emerald-400">
                  {MESES[mesSelecionado]}
                </Badge>
              </div>
              <div>
                <p className="text-xs text-muted-foreground mb-1">Unidade filtrada:</p>
                <p className="text-xs font-medium text-foreground">{regionalLabel[filtroRegionalRelatorio]}</p>
              </div>
            </div>
          </Card>

          <Card className="p-4 border-dashed border-border/80 bg-muted/10">
            <div className="flex items-start gap-2.5">
              <AlertCircle className="w-4 h-4 text-emerald-400 shrink-0 mt-0.5" />
              <div className="text-xs text-muted-foreground">
                <p className="font-semibold text-foreground mb-1">Colunas Obrigatórias</p>
                A exportação inclui formalmente: Nome Completo, Unidade, Função/Cargo e Data de Admissão.
              </div>
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
};

