import React, { useState, useEffect, useMemo } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  UserCheck,
  UserCheck2,
  Users,
  Search,
  Phone,
  Briefcase,
  AlertCircle,
  FileText,
  UserMinus,
  Sparkles,
  ChevronRight,
  ShieldAlert,
  ArrowRightLeft,
  Check,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador | null;
  veiculo?: Veiculo | null;
  colaboradoresReserva?: Colaborador[];
  onSalvarStatus?: (
    colabId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
  onSave?: (
    colabId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSalvarStatus,
  onSave,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta | ''>('');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState<string>('');
  const [substitutoNome, setSubstitutoNome] = useState<string>('');
  const [buscaSubstituto, setBuscaSubstituto] = useState('');
  const [modoManual, setModoManual] = useState(false);
  const [nomeManual, setNomeManual] = useState('');

  // Sincronizar estado ao abrir ou trocar de colaborador
  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || '');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
      setSubstitutoNome(colaborador.substitutoNome || '');
      setBuscaSubstituto('');
      setModoManual(false);
      setNomeManual('');
    }
  }, [colaborador, isOpen]);

  // Lista de candidatos a substitutos (excluindo o próprio colaborador atual)
  const listaCandidatos = useMemo(() => {
    const todos: Colaborador[] = Array.isArray(colaboradoresReserva) ? [...colaboradoresReserva] : [];
    return todos.filter((c) => c && c.id !== colaborador?.id);
  }, [colaboradoresReserva, colaborador]);

  // Filtro de substitutos por busca
  const substitutosFiltrados = useMemo(() => {
    if (!buscaSubstituto.trim()) return listaCandidatos;
    const termo = buscaSubstituto.toLowerCase().trim();
    return listaCandidatos.filter(
      (c) =>
        (c.nome || '').toLowerCase().includes(termo) ||
        (c.cargo || '').toLowerCase().includes(termo) ||
        (c.telefone || '').includes(termo)
    );
  }, [listaCandidatos, buscaSubstituto]);

  if (!isOpen || !colaborador) return null;

  const handleSelecionarSubstituto = (sub: Colaborador) => {
    setSubstitutoId(sub.id);
    setSubstitutoNome(sub.nome);
    setModoManual(false);
  };

  const handleRemoverSubstituto = () => {
    setSubstitutoId('');
    setSubstitutoNome('');
    setNomeManual('');
  };

  const handleSalvar = (e: React.FormEvent) => {
    e.preventDefault();
    if (!colaborador) return;

    const nomeFinalSubstituto = modoManual && nomeManual.trim() ? nomeManual.trim() : substitutoNome;
    const idFinalSubstituto = modoManual ? `manual-${Date.now()}` : substitutoId;

    const salvarFn = onSalvarStatus || onSave;
    if (salvarFn) {
      salvarFn(
        colaborador.id,
        status,
        status !== 'presente' && motivo ? (motivo as MotivoFalta) : undefined,
        observacao.trim() || undefined,
        status === 'substituto' ? idFinalSubstituto : undefined,
        status === 'substituto' ? nomeFinalSubstituto : undefined
      );
    }
    onClose();
  };

  const substitutoEscolhidoObj = listaCandidatos.find((c) => c.id === substitutoId);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-xl max-h-[92vh] flex flex-col bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cabeçalho */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/60 bg-muted/20 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary shrink-0">
              <Users className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <h2 className="text-base font-bold text-foreground">Registro de Frequência</h2>
              <p className="text-xs text-muted-foreground">
                {veiculo?.prefixo ? `${veiculo.prefixo} • ` : ''}Atualize o status do colaborador
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Corpo com scroll suave */}
        <form onSubmit={handleSalvar} className="flex-1 overflow-y-auto p-5 sm:p-6 space-y-5">
          {/* Cartão do Colaborador Selecionado */}
          <div className="flex items-center gap-4 p-3.5 rounded-2xl border border-border/60 bg-muted/30">
            <div className="relative w-14 h-14 rounded-2xl overflow-hidden border-2 border-border/80 bg-zinc-900 shrink-0 shadow-sm">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-zinc-300 font-black text-base bg-emerald-950/40">
                  {getIniciais(colaborador.nome)}
                </div>
              )}
            </div>
            <div className="min-w-0 flex-1">
              <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-400">
                Colaborador Titular
              </span>
              <h3 className="font-bold text-base text-foreground truncate">{colaborador.nome}</h3>
              <p className="text-xs text-muted-foreground truncate flex items-center gap-1.5 mt-0.5">
                <Briefcase className="w-3 h-3 text-muted-foreground/70" />
                {colaborador.cargo || 'Operador Florestal'}
              </p>
            </div>
          </div>

          {/* Seleção do Status Principal */}
          <div>
            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block mb-2">
              Status da Presença Hoje
            </label>
            <div className="grid grid-cols-3 gap-2.5">
              {/* Opção Presente */}
              <button
                type="button"
                onClick={() => setStatus('presente')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer text-center gap-2',
                  status === 'presente'
                    ? 'border-emerald-500 bg-emerald-500/15 text-emerald-300 shadow-md shadow-emerald-500/10'
                    : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                )}
              >
                <div className={cn(
                  'w-8 h-8 rounded-xl flex items-center justify-center',
                  status === 'presente' ? 'bg-emerald-500 text-white shadow-sm' : 'bg-muted/50 text-muted-foreground'
                )}>
                  <CheckCircle2 className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-xs font-bold block">Presente</span>
                  <span className="text-[10px] opacity-75">Em operação</span>
                </div>
              </button>

              {/* Opção Falta */}
              <button
                type="button"
                onClick={() => setStatus('falta')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer text-center gap-2',
                  status === 'falta'
                    ? 'border-rose-500 bg-rose-500/15 text-rose-300 shadow-md shadow-rose-500/10'
                    : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                )}
              >
                <div className={cn(
                  'w-8 h-8 rounded-xl flex items-center justify-center',
                  status === 'falta' ? 'bg-rose-500 text-white shadow-sm' : 'bg-muted/50 text-muted-foreground'
                )}>
                  <XCircle className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-xs font-bold block">Falta</span>
                  <span className="text-[10px] opacity-75">Sem substituto</span>
                </div>
              </button>

              {/* Opção Substituição */}
              <button
                type="button"
                onClick={() => setStatus('substituto')}
                className={cn(
                  'flex flex-col items-center justify-center p-3.5 rounded-2xl border-2 transition-all cursor-pointer text-center gap-2',
                  status === 'substituto'
                    ? 'border-amber-500 bg-amber-500/15 text-amber-300 shadow-md shadow-amber-500/10 ring-1 ring-amber-500/30'
                    : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                )}
              >
                <div className={cn(
                  'w-8 h-8 rounded-xl flex items-center justify-center',
                  status === 'substituto' ? 'bg-amber-500 text-white shadow-sm' : 'bg-muted/50 text-muted-foreground'
                )}>
                  <ArrowRightLeft className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-xs font-bold block">Substituição</span>
                  <span className="text-[10px] opacity-75">Outro operador</span>
                </div>
              </button>
            </div>
          </div>

          {/* SEÇÃO DINÂMICA: SELEÇÃO DE SUBSTITUTO MELHORADA */}
          {status === 'substituto' && (
            <div className="space-y-4 pt-2 pb-1 border-t border-border/50 animate-in fade-in-50 duration-200">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <ArrowRightLeft className="w-4 h-4 text-amber-400" />
                  <label className="text-xs font-bold text-amber-400 uppercase tracking-wider">
                    Selecionar Operador Substituto
                  </label>
                </div>
                <button
                  type="button"
                  onClick={() => setModoManual(!modoManual)}
                  className="text-[11px] font-semibold text-emerald-400 hover:text-emerald-300 transition-colors underline-offset-2 hover:underline"
                >
                  {modoManual ? 'Ver lista do banco de reserva' : 'Inserir manualmente'}
                </button>
              </div>

              {/* Card de Substituto já Escolhido */}
              {(substitutoNome || (modoManual && nomeManual)) && (
                <div className="flex items-center justify-between p-3.5 rounded-2xl bg-amber-500/10 border border-amber-500/30">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className="w-11 h-11 rounded-xl bg-amber-500/20 border border-amber-500/40 flex items-center justify-center text-amber-300 font-bold overflow-hidden shrink-0">
                      {substitutoEscolhidoObj?.foto ? (
                        <img
                          src={substitutoEscolhidoObj.foto}
                          alt={substitutoEscolhidoObj.nome}
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        getIniciais(modoManual ? nomeManual : substitutoNome)
                      )}
                    </div>
                    <div className="min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-bold uppercase tracking-wider text-amber-400">
                          Substituto Definido
                        </span>
                        <Check className="w-3.5 h-3.5 text-emerald-400" />
                      </div>
                      <p className="font-bold text-sm text-foreground truncate">
                        {modoManual ? nomeManual : substitutoNome}
                      </p>
                      <p className="text-[11px] text-muted-foreground truncate">
                        {substitutoEscolhidoObj?.cargo || 'Colaborador Substituto'}
                      </p>
                    </div>
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={handleRemoverSubstituto}
                    className="text-xs text-rose-400 hover:text-rose-300 hover:bg-rose-500/10 h-8 px-2.5 rounded-lg shrink-0 ml-2"
                  >
                    Trocar
                  </Button>
                </div>
              )}

              {/* Modo Manual */}
              {modoManual ? (
                <div className="space-y-2 p-3.5 rounded-2xl border border-border/70 bg-muted/20">
                  <label className="text-xs font-medium text-foreground block">
                    Nome Completo do Substituto ou Terceirizado
                  </label>
                  <Input
                    type="text"
                    placeholder="Ex: João Ferreira da Silva"
                    value={nomeManual}
                    onChange={(e) => setNomeManual(e.target.value)}
                    className="h-10 text-xs bg-background"
                  />
                  <p className="text-[11px] text-muted-foreground">
                    Utilize essa opção caso o operador substituto ainda não esteja cadastrado na frota.
                  </p>
                </div>
              ) : (
                /* Modo Seleção por Lista e Busca */
                <div className="space-y-3 p-3.5 rounded-2xl border border-border/70 bg-muted/15">
                  {/* Campo de Busca Rápida */}
                  <div className="relative">
                    <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
                    <Input
                      type="text"
                      placeholder="Buscar por nome, cargo ou telefone..."
                      value={buscaSubstituto}
                      onChange={(e) => setBuscaSubstituto(e.target.value)}
                      className="pl-9 pr-8 h-9 text-xs bg-background/80 border-border/70 rounded-xl"
                    />
                    {buscaSubstituto && (
                      <button
                        type="button"
                        onClick={() => setBuscaSubstituto('')}
                        className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                      >
                        <X className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>

                  {/* Header informativo da lista */}
                  <div className="flex items-center justify-between text-[11px] text-muted-foreground px-1">
                    <span>Banco de Reserva & Operadores</span>
                    <span className="font-semibold text-foreground tabular-nums">
                      {substitutosFiltrados.length} disponível(is)
                    </span>
                  </div>

                  {/* Lista com Rolagem Otimizada */}
                  <div className="max-h-52 overflow-y-auto space-y-1.5 pr-1 -mr-1">
                    {substitutosFiltrados.length === 0 ? (
                      <div className="p-6 text-center text-muted-foreground text-xs rounded-xl border border-dashed border-border/60 bg-muted/10">
                        <Users className="w-6 h-6 mx-auto mb-1.5 opacity-40" />
                        <p className="font-medium text-foreground">Nenhum colaborador encontrado</p>
                        <p className="text-[11px] mt-0.5">Tente outro termo ou clique em "Inserir manualmente".</p>
                      </div>
                    ) : (
                      substitutosFiltrados.map((sub) => {
                        const isSelected = substitutoId === sub.id;

                        return (
                          <div
                            key={sub.id}
                            onClick={() => handleSelecionarSubstituto(sub)}
                            className={cn(
                              'group flex items-center justify-between p-2.5 rounded-xl border transition-all cursor-pointer text-left',
                              isSelected
                                ? 'border-amber-500 bg-amber-500/15 shadow-sm'
                                : 'border-border/50 bg-card/60 hover:border-emerald-500/50 hover:bg-muted/40'
                            )}
                          >
                            <div className="flex items-center gap-3 min-w-0">
                              <div className="relative w-10 h-10 rounded-xl overflow-hidden bg-zinc-900 border border-border/80 shrink-0">
                                {sub.foto ? (
                                  <img
                                    src={sub.foto}
                                    alt={sub.nome}
                                    className="w-full h-full object-cover"
                                  />
                                ) : (
                                  <div className="w-full h-full flex items-center justify-center text-xs font-bold text-zinc-300 bg-emerald-950/40">
                                    {getIniciais(sub.nome)}
                                  </div>
                                )}
                              </div>
                              <div className="min-w-0">
                                <p className="font-bold text-xs text-foreground truncate group-hover:text-emerald-400 transition-colors">
                                  {sub.nome}
                                </p>
                                <div className="flex items-center gap-2 text-[10px] text-muted-foreground truncate mt-0.5">
                                  <span className="truncate">{sub.cargo || 'Operador'}</span>
                                  {sub.telefone && (
                                    <>
                                      <span>•</span>
                                      <span className="tabular-nums">{sub.telefone}</span>
                                    </>
                                  )}
                                </div>
                              </div>
                            </div>

                            <div className="shrink-0 ml-2">
                              {isSelected ? (
                                <Badge className="bg-amber-500 text-white font-bold text-[10px] px-2 py-0.5">
                                  Escolhido
                                </Badge>
                              ) : (
                                <Button
                                  type="button"
                                  size="sm"
                                  variant="ghost"
                                  className="h-7 px-2.5 text-xs text-muted-foreground group-hover:text-foreground group-hover:bg-background/80 rounded-lg"
                                >
                                  Selecionar
                                </Button>
                              )}
                            </div>
                          </div>
                        );
                      })
                    )}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Motivo da Falta / Substituição */}
          {status !== 'presente' && (
            <div className="space-y-2 pt-2 border-t border-border/50 animate-in fade-in-50 duration-150">
              <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider block">
                Motivo da {status === 'substituto' ? 'Substituição' : 'Ausência'}
              </label>
              <div className="grid grid-cols-2 gap-2">
                {MOTIVOS_FALTA.map((m) => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setMotivo(m)}
                    className={cn(
                      'px-3 py-2 text-xs font-semibold rounded-xl border text-left transition-all',
                      motivo === m
                        ? 'border-emerald-500 bg-emerald-500/15 text-emerald-300 font-bold'
                        : 'border-border/60 bg-muted/20 text-muted-foreground hover:bg-muted/40 hover:text-foreground'
                    )}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Campo de Observações Adicionais */}
          <div className="space-y-2 pt-2 border-t border-border/50">
            <div className="flex items-center justify-between">
              <label className="text-xs font-bold text-muted-foreground uppercase tracking-wider">
                Observações Operacionais
              </label>
              <span className="text-[10px] text-muted-foreground">Opcional</span>
            </div>
            <textarea
              rows={2}
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              placeholder="Ex: Entrou em contato informando retorno previsto para amanhã..."
              className="w-full p-3 rounded-xl border border-input bg-card/60 text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 resize-none transition-all placeholder:text-muted-foreground"
            />
          </div>

          {/* Rodapé / Ações */}
          <div className="flex items-center justify-end gap-3 pt-4 border-t border-border/60">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              className="rounded-xl text-xs h-10 px-4"
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              className="rounded-xl text-xs font-bold h-10 px-6 bg-emerald-600 hover:bg-emerald-500 text-white gap-2 shadow-md shadow-emerald-950/40"
            >
              <CheckCircle2 className="w-4 h-4" />
              Salvar Alterações
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

