import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  Calendar,
  AlertTriangle,
  UserCheck,
  ChevronRight,
  Sparkles,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const statusConfig: Record<
  StatusPresenca,
  { label: string; bg: string; text: string; border: string; icon: React.ComponentType<{ className?: string }> }
> = {
  presente: {
    label: 'Presente',
    bg: 'bg-emerald-500/15',
    text: 'text-emerald-400',
    border: 'border-emerald-500/30',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    bg: 'bg-rose-500/15',
    text: 'text-rose-400',
    border: 'border-rose-500/30',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    bg: 'bg-amber-500/15',
    text: 'text-amber-400',
    border: 'border-amber-500/30',
    icon: UserCheck,
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateColaboradorStatus,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoDoColaborador, setVeiculoDoColaborador] = useState<Veiculo | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((veiculo) => {
      if (!veiculo) return false;

      const matchRegional =
        selectedRegional === 'todas' || veiculo.regional === selectedRegional;

      const termo = searchTerm.toLowerCase().trim();
      if (!termo) return matchRegional;

      const matchPrefixo = veiculo.prefixo?.toLowerCase().includes(termo);
      const matchPlaca = veiculo.placa?.toLowerCase().includes(termo);
      const matchModelo = veiculo.modelo?.toLowerCase().includes(termo);
      const matchEquipe1 = veiculo.equipe1Codigo?.toLowerCase().includes(termo);
      const matchEquipe2 = veiculo.equipe2Codigo?.toLowerCase().includes(termo);

      const assentos = [
        veiculo.assentos?.motorista,
        veiculo.assentos?.frenteDir,
        veiculo.assentos?.trasEsq,
        veiculo.assentos?.trasDir,
      ];

      const matchColaborador = assentos.some(
        (c) =>
          c?.nome?.toLowerCase().includes(termo) ||
          c?.cargo?.toLowerCase().includes(termo) ||
          c?.substitutoNome?.toLowerCase().includes(termo)
      );

      return matchRegional && (matchPrefixo || matchPlaca || matchModelo || matchEquipe1 || matchEquipe2 || matchColaborador);
    });
  }, [veiculos, selectedRegional, searchTerm]);

  const handleAbrirPresenca = (colab: Colaborador, veic: Veiculo) => {
    setColaboradorSelecionado(colab);
    setVeiculoDoColaborador(veic);
  };

  const handleSalvarPresenca = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    onUpdateColaboradorStatus?.(colaboradorId, novoStatus, motivo, observacao, substitutoId);
    setColaboradorSelecionado(null);
    setVeiculoDoColaborador(null);
  };

  return (
    <div className="space-y-4">
      {/* Barra de Busca e Filtros Rápidos */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/60 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Buscar por veículo, placa, equipe ou nome do colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border/70 text-sm focus-visible:ring-emerald-500/30"
          />
        </div>
        <div className="flex items-center gap-2 text-xs text-muted-foreground self-end sm:self-auto px-1">
          <span>Total exibido:</span>
          <span className="font-bold text-foreground tabular-nums bg-muted/60 px-2 py-0.5 rounded-md">
            {veiculosFiltrados.length} {veiculosFiltrados.length === 1 ? 'veículo' : 'veículos'}
          </span>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border/80 bg-card/40 p-12 text-center flex flex-col items-center justify-center space-y-3">
          <div className="w-12 h-12 rounded-2xl bg-muted/60 flex items-center justify-center text-muted-foreground">
            <Car className="w-6 h-6" />
          </div>
          <div className="space-y-1">
            <h3 className="font-semibold text-foreground text-sm">Nenhum veículo encontrado</h3>
            <p className="text-xs text-muted-foreground max-w-sm">
              Não encontramos resultados para a busca ou filtro selecionado. Tente alterar os termos.
            </p>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((veiculo) => {
            const assentosLista: Array<{
              colab: Colaborador;
              posicaoTexto: string;
              equipeNumero: 1 | 2;
            }> = [
              {
                colab: veiculo.assentos?.motorista,
                posicaoTexto: 'Motorista (Equipe 1)',
                equipeNumero: 1,
              },
              {
                colab: veiculo.assentos?.frenteDir,
                posicaoTexto: 'Frente Dir. (Equipe 1)',
                equipeNumero: 1,
              },
              {
                colab: veiculo.assentos?.trasEsq,
                posicaoTexto: 'Traseira Esq. (Equipe 2)',
                equipeNumero: 2,
              },
              {
                colab: veiculo.assentos?.trasDir,
                posicaoTexto: 'Traseira Dir. (Equipe 2)',
                equipeNumero: 2,
              },
            ].filter((item) => Boolean(item.colab));

            const totalAssentos = assentosLista.length;
            const presentes = assentosLista.filter(
              (a) => a.colab.status === 'presente' || a.colab.status === 'substituto'
            ).length;
            const faltas = assentosLista.filter((a) => a.colab.status === 'falta').length;

            return (
              <Card
                key={veiculo.id}
                className="overflow-hidden border border-border/70 bg-card/70 hover:border-emerald-500/40 hover:shadow-lg transition-all duration-200 flex flex-col justify-between"
              >
                {/* Cabeçalho do Card */}
                <div className="p-4 border-b border-border/40 bg-gradient-to-r from-muted/30 to-muted/10 space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className="w-8 h-8 rounded-xl bg-emerald-500/15 border border-emerald-500/25 flex items-center justify-center text-emerald-400">
                        <Car className="w-4 h-4" />
                      </div>
                      <div>
                        <div className="flex items-center gap-1.5">
                          <span className="font-black text-foreground text-sm tracking-tight">
                            {veiculo.prefixo}
                          </span>
                          <span className="text-[11px] font-semibold text-muted-foreground uppercase bg-muted/60 px-1.5 py-0.5 rounded">
                            {veiculo.placa}
                          </span>
                        </div>
                        <p className="text-[11px] text-muted-foreground">{veiculo.modelo}</p>
                      </div>
                    </div>

                    <Badge
                      variant="outline"
                      className={cn(
                        'text-[10px] font-bold border',
                        veiculo.regional === 'ribas'
                          ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                          : 'bg-teal-500/10 text-teal-400 border-teal-500/30'
                      )}
                    >
                      {veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                    </Badge>
                  </div>

                  {/* Badges de Equipes e Lotação */}
                  <div className="flex items-center justify-between pt-1 text-[11px]">
                    <div className="flex items-center gap-1.5">
                      <span className="text-muted-foreground">Equipes:</span>
                      <span className="font-semibold text-foreground bg-card px-2 py-0.5 rounded-md border border-border/60">
                        {veiculo.equipe1Codigo} & {veiculo.equipe2Codigo}
                      </span>
                    </div>

                    <div className="flex items-center gap-1.5 font-medium">
                      <span className="text-muted-foreground">Lotação:</span>
                      <span
                        className={cn(
                          'tabular-nums font-bold px-1.5 py-0.5 rounded',
                          faltas > 0
                            ? 'bg-rose-500/15 text-rose-400 border border-rose-500/25'
                            : 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/25'
                        )}
                      >
                        {presentes}/{totalAssentos}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Lista de Colaboradores e Assentos */}
                <CardContent className="p-3.5 space-y-2 flex-1">
                  {assentosLista.map(({ colab, posicaoTexto }) => {
                    const st = statusConfig[colab.status] || statusConfig.presente;
                    const StatusIcon = st.icon;

                    return (
                      <div
                        key={colab.id}
                        onClick={() => handleAbrirPresenca(colab, veiculo)}
                        className={cn(
                          'group flex items-center justify-between p-2.5 rounded-xl border transition-all cursor-pointer',
                          'bg-card hover:bg-muted/40 hover:border-emerald-500/30 shadow-xs'
                        )}
                      >
                        <div className="flex items-center gap-3 min-w-0">
                          {/* Foto Ampliada em Destaque */}
                          <div className="relative shrink-0">
                            {colab.foto ? (
                              <img
                                src={colab.foto}
                                alt={colab.nome}
                                className="w-12 h-12 rounded-xl object-cover ring-2 ring-border/80 group-hover:ring-emerald-500/50 transition-all shadow-sm"
                              />
                            ) : (
                              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-muted/80 to-muted/40 border border-border/80 flex items-center justify-center font-bold text-xs text-muted-foreground group-hover:border-emerald-500/50 shadow-sm">
                                {getIniciais(colab.nome)}
                              </div>
                            )}
                            <span
                              className={cn(
                                'absolute -bottom-1 -right-1 w-3.5 h-3.5 rounded-full ring-2 ring-card flex items-center justify-center',
                                colab.status === 'presente'
                                  ? 'bg-emerald-500'
                                  : colab.status === 'falta'
                                  ? 'bg-rose-500'
                                  : 'bg-amber-500'
                              )}
                            />
                          </div>

                          <div className="min-w-0">
                            <p className="text-xs font-bold text-foreground truncate group-hover:text-emerald-400 transition-colors">
                              {colab.nome}
                            </p>
                            <p className="text-[11px] text-muted-foreground truncate">
                              {colab.cargo}
                            </p>
                            <p className="text-[10px] text-muted-foreground/75 truncate mt-0.5">
                              {posicaoTexto}
                            </p>
                            {colab.status === 'substituto' && colab.substitutoNome && (
                              <p className="text-[10px] text-amber-400 font-semibold truncate flex items-center gap-1 mt-0.5">
                                <UserCheck className="w-3 h-3 shrink-0" />
                                Substituto: {colab.substitutoNome}
                              </p>
                            )}
                          </div>
                        </div>

                        {/* Status e Botão Interativo */}
                        <div className="flex items-center gap-1.5 shrink-0 ml-2">
                          <span
                            className={cn(
                              'inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-lg border',
                              st.bg,
                              st.text,
                              st.border
                            )}
                          >
                            <StatusIcon className="w-3 h-3" />
                            <span className="hidden sm:inline">{st.label}</span>
                          </span>
                          <ChevronRight className="w-4 h-4 text-muted-foreground/60 group-hover:text-foreground group-hover:translate-x-0.5 transition-all" />
                        </div>
                      </div>
                    );
                  })}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal Interativo de Frequência / Presença / Substituição */}
      {colaboradorSelecionado && veiculoDoColaborador && (
        <AttendanceModal
          isOpen={Boolean(colaboradorSelecionado)}
          onClose={() => {
            setColaboradorSelecionado(null);
            setVeiculoDoColaborador(null);
          }}
          colaborador={colaboradorSelecionado}
          veiculo={veiculoDoColaborador}
          colaboradoresReserva={colaboradoresReserva}
          onSalvar={handleSalvarPresenca}
        />
      )}
    </div>
  );
};

