export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(new Date().getMonth());
  const [filtroRegionalRelatorio, setFiltroRegionalRelatorio] = useState<Regional>(selectedRegional);
  const [isExporting, setIsExporting] = useState(false);

  const dadosMesAtual = useMemo(() => {
    const dados = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === mesSelecionado) || HISTORICO_MENSAL_FALTAS[0];
    if (filtroRegionalRelatorio === 'todas') {
      return dados.faltas;
    }
    return dados.faltas.filter((f) => f.regionalKey === filtroRegionalRelatorio);
  }, [mesSelecionado, filtroRegionalRelatorio]);

  const totalFaltasMes = useMemo(() => {
    return dadosMesAtual.reduce((acc, curr) => acc + curr.totalFaltas, 0);
  }, [dadosMesAtual]);

  const handleExportarExcel = async () => {
    setIsExporting(true);
    try {
      const colunas = [
        ['Nome do Colaborador', 'Unidade', 'Função / Cargo', 'Data de Admissão', 'Total de Faltas', 'Mês de Referência'],
        ...dadosMesAtual.map((f) => [
          f.nome,
          f.unidade,
          f.funcao,
          f.dataAdmissao,
          f.totalFaltas,
          MESES[mesSelecionado]
        ])
      ];

      try {
        // @ts-ignore
        const XLSX = await import('xlsx');
        if (XLSX && XLSX.utils && XLSX.writeFile) {
          const ws = XLSX.utils.aoa_to_sheet(colunas);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, `Faltas_${MESES[mesSelecionado]}`);
          XLSX.writeFile(wb, `Relatorio_Faltas_${MESES[mesSelecionado]}_${new Date().getFullYear()}.xlsx`);
          setIsExporting(false);
          return;
        }
      } catch {
        // fallback para download CSV limpo
      }

      const csvContent = '\uFEFF' + colunas.map((row) => row.map((cell) => `"${cell}"`).join(';')).join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute('download', `Relatorio_Faltas_${MESES[mesSelecionado]}_${new Date().getFullYear()}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } finally {
      setIsExporting(false);
    }
  };

  const handleImprimir = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
