import React, { useState, useEffect, useMemo } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  UserCheck,
  UserCheck2,
  Users,
  Search,
  Phone,
  Briefcase,
  AlertCircle,
  FileText,
  MapPin,
  Clock,
  Sparkles,
} from 'lucide-react';
import { Colaborador, StatusPresenca, MotivoFalta, Veiculo } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador | null;
  veiculo?: Veiculo | null;
  colaboradoresReserva: Colaborador[];
  onSalvar: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const statusOptions: Array<{
  value: StatusPresenca;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  color: string;
  desc: string;
}> = [
  {
    value: 'presente',
    label: 'Presente',
    icon: CheckCircle2,
    color: 'emerald',
    desc: 'Operador apto e em campo no veículo',
  },
  {
    value: 'falta',
    label: 'Falta / Ausência',
    icon: XCircle,
    color: 'rose',
    desc: 'Operador ausente (atestado, falta, folga)',
  },
  {
    value: 'substituto',
    label: 'Substituição Ativa',
    icon: UserCheck2,
    color: 'amber',
    desc: 'Posto preenchido por colaborador reserva',
  },
];

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSalvar,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta>('Atestado Médico');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState('');
  const [buscaSubstituto, setBuscaSubstituto] = useState('');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || 'Atestado Médico');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
      setBuscaSubstituto('');
    }
  }, [colaborador, isOpen]);

  const reservasDisponiveis = useMemo(() => {
    return (colaboradoresReserva || []).filter((c) => {
      if (!c) return false;
      const term = buscaSubstituto.toLowerCase().trim();
      if (!term) return true;
      return (
        (c.nome || '').toLowerCase().includes(term) ||
        (c.cargo || '').toLowerCase().includes(term) ||
        (c.telefone || '').toLowerCase().includes(term)
      );
    });
  }, [colaboradoresReserva, buscaSubstituto]);

  const substitutoSelecionado = useMemo(() => {
    if (!substitutoId) return null;
    return (colaboradoresReserva || []).find((c) => c?.id === substitutoId) || null;
  }, [colaboradoresReserva, substitutoId]);

  if (!isOpen || !colaborador) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSalvar(
      colaborador.id,
      status,
      status === 'falta' ? motivo : undefined,
      observacao.trim() || undefined,
      status === 'substituto' ? substitutoId || undefined : undefined
    );
    onClose();
  };

  const getIniciais = (nome?: string) => {
    if (!nome) return 'OP';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].slice(0, 2).toUpperCase();
    return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="relative w-full max-w-xl max-h-[92vh] flex flex-col rounded-2xl border border-border/80 bg-card shadow-2xl overflow-hidden">
        {/* Top Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border/60 bg-muted/30">
          <div className="flex items-center gap-3">
            <div className="relative">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-12 h-12 rounded-xl object-cover border border-border/60 shadow-sm"
                />
              ) : (
                <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-emerald-600 to-teal-800 text-white font-bold flex items-center justify-center text-sm shadow-sm">
                  {getIniciais(colaborador.nome)}
                </div>
              )}
              <span
                className={cn(
                  'absolute -bottom-1 -right-1 w-3.5 h-3.5 rounded-full border-2 border-card',
                  colaborador.status === 'presente'
                    ? 'bg-emerald-500'
                    : colaborador.status === 'falta'
                    ? 'bg-rose-500'
                    : 'bg-amber-500'
                )}
              />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-foreground leading-tight">
                  {colaborador.nome}
                </h3>
                <Badge variant="outline" className="text-[10px] py-0 px-1.5 border-border">
                  Equipe {colaborador.equipeNumero || 1}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground flex items-center gap-1.5 mt-0.5">
                <Briefcase className="w-3.5 h-3.5" />
                <span>{colaborador.cargo}</span>
                {veiculo?.prefixo && (
                  <>
                    <span className="opacity-50">·</span>
                    <span>{veiculo.prefixo}</span>
                  </>
                )}
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="rounded-xl p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Modal Form Body */}
        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-5 space-y-5">
          {/* Status Selection Cards */}
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
              Situação do Operador no Turno
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
              {statusOptions.map((opt) => {
                const Icon = opt.icon;
                const isSelected = status === opt.value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() => setStatus(opt.value)}
                    className={cn(
                      'p-3 rounded-xl border text-left transition-all flex flex-col justify-between gap-2 cursor-pointer',
                      isSelected
                        ? opt.color === 'emerald'
                          ? 'border-emerald-500 bg-emerald-500/10 text-emerald-300 ring-2 ring-emerald-500/20'
                          : opt.color === 'rose'
                          ? 'border-rose-500 bg-rose-500/10 text-rose-300 ring-2 ring-rose-500/20'
                          : 'border-amber-500 bg-amber-500/10 text-amber-300 ring-2 ring-amber-500/20'
                        : 'border-border/60 bg-card/40 hover:bg-muted/40 text-muted-foreground hover:border-border'
                    )}
                  >
                    <div className="flex items-center justify-between">
                      <Icon className={cn('w-4 h-4', isSelected ? 'text-current' : 'text-muted-foreground')} />
                      {isSelected && (
                        <span className="w-2 h-2 rounded-full bg-current animate-pulse" />
                      )}
                    </div>
                    <div>
                      <p className="font-semibold text-xs text-foreground">{opt.label}</p>
                      <p className="text-[10px] text-muted-foreground line-clamp-2 mt-0.5">{opt.desc}</p>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Conditional: Falta / Ausência */}
          {status === 'falta' && (
            <div className="p-3.5 rounded-xl border border-rose-500/25 bg-rose-500/5 space-y-3 animate-in fade-in-50 duration-150">
              <div className="flex items-center gap-2 text-rose-300 text-xs font-semibold">
                <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                <span>Classificação do Motivo da Ausência</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {MOTIVOS_FALTA.map((m) => (
                  <label
                    key={m}
                    className={cn(
                      'flex items-center gap-2 p-2.5 rounded-lg border text-xs cursor-pointer transition-all',
                      motivo === m
                        ? 'border-rose-500 bg-rose-500/15 text-rose-200 font-medium'
                        : 'border-border/60 bg-card/40 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <input
                      type="radio"
                      name="motivoFalta"
                      value={m}
                      checked={motivo === m}
                      onChange={() => setMotivo(m)}
                      className="text-rose-500 focus:ring-rose-500 rounded"
                    />
                    <span>{m}</span>
                  </label>
                ))}
              </div>
            </div>
          )}

          {/* Conditional: Substituto Selection */}
          {status === 'substituto' && (
            <div className="p-4 rounded-xl border border-amber-500/30 bg-amber-500/5 space-y-3 animate-in fade-in-50 duration-150">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-amber-300 text-xs font-semibold">
                  <UserCheck2 className="w-4 h-4 shrink-0 text-amber-400" />
                  <span>Selecionar Operador do Banco de Reserva</span>
                </div>
                <Badge variant="outline" className="text-[10px] text-amber-400 border-amber-500/30">
                  {reservasDisponiveis.length} disponíveis
                </Badge>
              </div>

              {/* Substituto Atual Selecionado */}
              {substitutoSelecionado && (
                <div className="flex items-center justify-between p-2.5 rounded-lg bg-amber-500/15 border border-amber-500/40 text-xs">
                  <div className="flex items-center gap-2">
                    <CheckCircle2 className="w-4 h-4 text-amber-400" />
                    <div>
                      <p className="font-semibold text-foreground">{substitutoSelecionado.nome}</p>
                      <p className="text-[11px] text-muted-foreground">{substitutoSelecionado.cargo}</p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => setSubstitutoId('')}
                    className="text-[11px] text-muted-foreground hover:text-rose-400 px-2 py-1 rounded hover:bg-rose-500/10 transition-colors"
                  >
                    Trocar
                  </button>
                </div>
              )}

              {/* Campo de Busca Rápida */}
              <div className="relative">
                <Search className="absolute left-3 top-2.5 w-3.5 h-3.5 text-muted-foreground" />
                <input
                  type="text"
                  placeholder="Pesquisar por nome, cargo ou telefone..."
                  value={buscaSubstituto}
                  onChange={(e) => setBuscaSubstituto(e.target.value)}
                  className="w-full h-9 pl-9 pr-3 rounded-lg border border-border/80 bg-background text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                />
              </div>

              {/* Lista de Reservas Disponíveis */}
              <div className="max-h-44 overflow-y-auto space-y-1.5 pr-1">
                {reservasDisponiveis.length === 0 ? (
                  <div className="text-center py-4 text-xs text-muted-foreground">
                    Nenhum colaborador reserva encontrado.
                  </div>
                ) : (
                  reservasDisponiveis.map((r) => {
                    const isPicked = substitutoId === r.id;
                    return (
                      <div
                        key={r.id}
                        onClick={() => setSubstitutoId(r.id)}
                        className={cn(
                          'p-2.5 rounded-lg border flex items-center justify-between gap-2 cursor-pointer transition-all text-xs',
                          isPicked
                            ? 'border-amber-500 bg-amber-500/20 text-amber-200'
                            : 'border-border/60 bg-card/60 hover:bg-muted/40 hover:border-amber-500/40'
                        )}
                      >
                        <div className="flex items-center gap-2.5">
                          <div className="w-8 h-8 rounded-lg bg-muted flex items-center justify-center font-bold text-[11px] text-muted-foreground shrink-0">
                            {getIniciais(r.nome)}
                          </div>
                          <div>
                            <p className="font-semibold text-foreground">{r.nome}</p>
                            <p className="text-[11px] text-muted-foreground">{r.cargo}</p>
                          </div>
                        </div>

                        <div className="flex items-center gap-2 shrink-0">
                          {r.telefone && (
                            <span className="text-[10px] text-muted-foreground tabular-nums flex items-center gap-1">
                              <Phone className="w-3 h-3" />
                              {r.telefone}
                            </span>
                          )}
                          <Button
                            type="button"
                            size="sm"
                            variant={isPicked ? 'default' : 'outline'}
                            className={cn(
                              'h-7 px-2.5 text-[11px]',
                              isPicked ? 'bg-amber-600 hover:bg-amber-500 text-white' : ''
                            )}
                          >
                            {isPicked ? 'Escolhido' : 'Selecionar'}
                          </Button>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          )}

          {/* Observações Operacionais */}
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-foreground flex items-center gap-1.5">
              <FileText className="w-3.5 h-3.5 text-muted-foreground" />
              Observações do Registro (Opcional)
            </label>
            <textarea
              rows={2}
              placeholder="Descreva detalhes como atestado CID, autorização do encarregado ou motivo de remanejamento..."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              className="w-full p-2.5 rounded-xl border border-border/80 bg-background text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 resize-none"
            />
          </div>

          {/* Botões do Rodapé */}
          <div className="pt-2 flex items-center justify-end gap-2 border-t border-border/50">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onClose}
              className="h-9 px-4 text-xs"
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              size="sm"
              className="h-9 px-5 text-xs bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-sm"
            >
              Salvar Alteração
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

files.oldContent:
import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  Users,
  Compass,
  MapPin,
  Calendar,
  AlertTriangle,
  UserCheck,
  ChevronRight,
  Sparkles,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  selectedDate?: Date;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const statusConfig: Record<
  StatusPresenca,
  { label: string; bg: string; text: string; border: string; icon: React.ComponentType<{ className?: string }> }
> = {
  presente: {
    label: 'Presente',
    bg: 'bg-emerald-500/15',
    text: 'text-emerald-400',
    border: 'border-emerald-500/30',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    bg: 'bg-rose-500/15',
    text: 'text-rose-400',
    border: 'border-rose-500/30',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    bg: 'bg-amber-500/15',
    text: 'text-amber-400',
    border: 'border-amber-500/30',
    icon: UserCheck,
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
  onUpdateColaboradorStatus,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoDoColaborador, setVeiculoDoColaborador] = useState<Veiculo | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((veiculo) => {
      if (!veiculo) return false;

      const matchRegional =
        selectedRegional === 'todas' || veiculo.regional === selectedRegional;

      const termo = searchTerm.toLowerCase().trim();
      if (!termo) return matchRegional;

      const matchPrefixo = veiculo.prefixo?.toLowerCase().includes(termo);
      const matchPlaca = veiculo.placa?.toLowerCase().includes(termo);
      const matchModelo = veiculo.modelo?.toLowerCase().includes(termo);
      const matchEquipe1 = veiculo.equipe1Codigo?.toLowerCase().includes(termo);
      const matchEquipe2 = veiculo.equipe2Codigo?.toLowerCase().includes(termo);

      const assentos = [
        veiculo.assentos?.motorista,
        veiculo.assentos?.frenteDir,
        veiculo.assentos?.trasEsq,
        veiculo.assentos?.trasDir,
      ];

      const matchColaborador = assentos.some(
        (c) =>
          c?.nome?.toLowerCase().includes(termo) ||
          c?.cargo?.toLowerCase().includes(termo) ||
          c?.substitutoNome?.toLowerCase().includes(termo)
      );

      return matchRegional && (matchPrefixo || matchPlaca || matchModelo || matchEquipe1 || matchEquipe2 || matchColaborador);
    });
  }, [veiculos, selectedRegional, searchTerm]);

  const handleAbrirPresenca = (colab: Colaborador, veic: Veiculo) => {
    setColaboradorSelecionado(colab);
    setVeiculoDoColaborador(veic);
  };

  const handleSalvarPresenca = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    onUpdateColaboradorStatus?.(colaboradorId, novoStatus, motivo, observacao, substitutoId);
    setColaboradorSelecionado(null);
    setVeiculoDoColaborador(null);
  };

  return (
    <div className="space-y-4">
      {/* Barra de Busca e Filtros Rápidos */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3.5 rounded-2xl border border-border/60 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Buscar por veículo, placa, equipe ou nome do colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-10 bg-background/80 border-border/70 text-sm focus-visible:ring-emerald-500/30"
          />
        </div>
        <div className="flex items-center gap-2 text-xs text-muted-foreground self-end sm:self-auto px-1">
          <span>Total exibido:</span>
          <span className="font-bold text-foreground tabular-nums bg-muted/60 px-2 py-0.5 rounded-md">
            {veiculosFiltrados.length} {veiculosFiltrados.length === 1 ? 'veículo' : 'veículos'}
          </span>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border/80 bg-card/40 p-12 text-center flex flex-col items-center justify-center space-y-3">
          <div className="w-12 h-12 rounded-2xl bg-muted/60 flex items-center justify-center text-muted-foreground">
            <Car className="w-6 h-6" />
          </div>
          <div className="space-y-1">
            <h3 className="font-semibold text-foreground text-sm">Nenhum veículo encontrado</h3>
            <p className="text-xs text-muted-foreground max-w-sm">
              Não encontramos resultados para a busca ou filtro selecionado. Tente alterar os termos.
            </p>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((veiculo) => {
            const assentosLista: Array<{
              colab: Colaborador;
              posicaoTexto: string;
              equipeNumero: 1 | 2;
            }> = [
              {
                colab: veiculo.assentos?.motorista,
                posicaoTexto: 'Motorista (Equipe 1)',
                equipeNumero: 1,
              },
              {
                colab: veiculo.assentos?.frenteDir,
                posicaoTexto: 'Frente Dir. (Equipe 1)',
                equipeNumero: 1,
              },
              {
                colab: veiculo.assentos?.trasEsq,
                posicaoTexto: 'Traseira Esq. (Equipe 2)',
                equipeNumero: 2,
              },
              {
                colab: veiculo.assentos?.trasDir,
                posicaoTexto: 'Traseira Dir. (Equipe 2)',
                equipeNumero: 2,
              },
            ].filter((item) => Boolean(item.colab));

            const totalAssentos = assentosLista.length;
            const presentes = assentosLista.filter(
              (a) => a.colab.status === 'presente' || a.colab.status === 'substituto'
            ).length;
            const faltas = assentosLista.filter((a) => a.colab.status === 'falta').length;

            return (
              <Card
                key={veiculo.id}
                className="overflow-hidden border border-border/70 bg-card/70 hover:border-emerald-500/40 hover:shadow-lg transition-all duration-200 flex flex-col justify-between"
              >
                {/* Cabeçalho do Card */}
                <div className="p-4 border-b border-border/40 bg-gradient-to-r from-muted/30 to-muted/10 space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className="w-8 h-8 rounded-xl bg-emerald-500/15 border border-emerald-500/25 flex items-center justify-center text-emerald-400">
                        <Car className="w-4 h-4" />
                      </div>
                      <div>
                        <div className="flex items-center gap-1.5">
                          <span className="font-black text-foreground text-sm tracking-tight">
                            {veiculo.prefixo}
                          </span>
                          <span className="text-[11px] font-semibold text-muted-foreground uppercase bg-muted/60 px-1.5 py-0.5 rounded">
                            {veiculo.placa}
                          </span>
                        </div>
                        <p className="text-[11px] text-muted-foreground">{veiculo.modelo}</p>
                      </div>
                    </div>

                    <Badge
                      variant="outline"
                      className={cn(
                        'text-[10px] font-bold border',
                        veiculo.regional === 'ribas'
                          ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                          : 'bg-teal-500/10 text-teal-400 border-teal-500/30'
                      )}
                    >
                      {veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                    </Badge>
                  </div>

                  {/* Badges de Equipes e Lotação */}
                  <div className="flex items-center justify-between pt-1 text-[11px]">
                    <div className="flex items-center gap-1.5">
                      <span className="text-muted-foreground">Equipes:</span>
                      <span className="font-semibold text-foreground bg-card px-2 py-0.5 rounded-md border border-border/60">
                        {veiculo.equipe1Codigo} & {veiculo.equipe2Codigo}
                      </span>
                    </div>

                    <div className="flex items-center gap-1.5 font-medium">
                      <span className="text-muted-foreground">Lotação:</span>
                      <span
                        className={cn(
                          'tabular-nums font-bold px-1.5 py-0.5 rounded',
                          faltas > 0
                            ? 'bg-rose-500/15 text-rose-400 border border-rose-500/25'
                            : 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/25'
                        )}
                      >
                        {presentes}/{totalAssentos}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Lista de Colaboradores e Assentos */}
                <CardContent className="p-3.5 space-y-2 flex-1">
                  {assentosLista.map(({ colab, posicaoTexto }) => {
                    const st = statusConfig[colab.status] || statusConfig.presente;
                    const StatusIcon = st.icon;

                    return (
                      <div
                        key={colab.id}
                        onClick={() => handleAbrirPresenca(colab, veiculo)}
                        className={cn(
                          'group flex items-center justify-between p-2.5 rounded-xl border transition-all cursor-pointer',
                          'bg-card hover:bg-muted/40 hover:border-emerald-500/30 shadow-xs'
                        )}
                      >
                        <div className="flex items-center gap-3 min-w-0">
                          {/* Foto Ampliada em Destaque */}
                          <div className="relative shrink-0">
                            {colab.foto ? (
                              <img
                                src={colab.foto}
                                alt={colab.nome}
                                className="w-12 h-12 rounded-xl object-cover ring-2 ring-border/80 group-hover:ring-emerald-500/50 transition-all shadow-sm"
                              />
                            ) : (
                              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-muted/80 to-muted/40 border border-border/80 flex items-center justify-center font-bold text-xs text-muted-foreground group-hover:border-emerald-500/50 shadow-sm">
                                {getIniciais(colab.nome)}
                              </div>
                            )}
                            <span
                              className={cn(
                                'absolute -bottom-1 -right-1 w-3.5 h-3.5 rounded-full ring-2 ring-card flex items-center justify-center',
                                colab.status === 'presente'
                                  ? 'bg-emerald-500'
                                  : colab.status === 'falta'
                                  ? 'bg-rose-500'
                                  : 'bg-amber-500'
                              )}
                            />
                          </div>

                          <div className="min-w-0">
                            <p className="text-xs font-bold text-foreground truncate group-hover:text-emerald-400 transition-colors">
                              {colab.nome}
                            </p>
                            <p className="text-[11px] text-muted-foreground truncate">
                              {colab.cargo}
                            </p>
                            <p className="text-[10px] text-muted-foreground/75 truncate mt-0.5">
                              {posicaoTexto}
                            </p>
                            {colab.status === 'substituto' && colab.substitutoNome && (
                              <p className="text-[10px] text-amber-400 font-semibold truncate flex items-center gap-1 mt-0.5">
                                <UserCheck className="w-3 h-3 shrink-0" />
                                Substituto: {colab.substitutoNome}
                              </p>
                            )}
                          </div>
                        </div>

                        {/* Status e Botão Interativo */}
                        <div className="flex items-center gap-1.5 shrink-0 ml-2">
                          <span
                            className={cn(
                              'inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-lg border',
                              st.bg,
                              st.text,
                              st.border
                            )}
                          >
                            <StatusIcon className="w-3 h-3" />
                            <span className="hidden sm:inline">{st.label}</span>
                          </span>
                          <ChevronRight className="w-4 h-4 text-muted-foreground/60 group-hover:text-foreground group-hover:translate-x-0.5 transition-all" />
                        </div>
                      </div>
                    );
                  })}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal Interativo de Frequência / Presença / Substituição */}
      {colaboradorSelecionado && veiculoDoColaborador && (
        <AttendanceModal
          isOpen={Boolean(colaboradorSelecionado)}
          onClose={() => {
            setColaboradorSelecionado(null);
            setVeiculoDoColaborador(null);
          }}
          colaborador={colaboradorSelecionado}
          veiculo={veiculoDoColaborador}
          colaboradoresReserva={colaboradoresReserva}
          onSalvar={handleSalvarPresenca}
        />
      )}
    </div>
  );
};

files.newContent:
import React, { useState } from 'react';
import {
  Car,
  Users,
  CheckCircle2,
  XCircle,
  UserCheck2,
  AlertCircle,
  Phone,
  Search,
  Sparkles,
  MapPin,
  Clock,
  ShieldAlert,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; className: string; icon: React.ComponentType<{ className?: string }> }> = {
  presente: {
    label: 'Presente',
    className: 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30',
    icon: CheckCircle2,
  },
  falta: {
    label: 'Falta',
    className: 'bg-rose-500/15 text-rose-400 border-rose-500/30',
    icon: XCircle,
  },
  substituto: {
    label: 'Substituto',
    className: 'bg-amber-500/15 text-amber-400 border-amber-500/30',
    icon: UserCheck2,
  },
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [modalColaborador, setModalColaborador] = useState<Colaborador | null>(null);
  const [modalVeiculo, setModalVeiculo] = useState<Veiculo | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
    if (!matchRegional) return false;

    if (!busca.trim()) return true;
    const termo = busca.toLowerCase();
    const assentos = [
      v.assentos?.motorista?.nome,
      v.assentos?.frenteDir?.nome,
      v.assentos?.trasEsq?.nome,
      v.assentos?.trasDir?.nome,
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();

    return (
      (v.prefixo || '').toLowerCase().includes(termo) ||
      (v.placa || '').toLowerCase().includes(termo) ||
      (v.modelo || '').toLowerCase().includes(termo) ||
      (v.equipe1Codigo || '').toLowerCase().includes(termo) ||
      (v.equipe2Codigo || '').toLowerCase().includes(termo) ||
      assentos.includes(termo)
    );
  });

  const handleOpenAttendance = (colab: Colaborador, veiculo: Veiculo) => {
    setModalColaborador(colab);
    setModalVeiculo(veiculo);
  };

  const handleCloseAttendance = () => {
    setModalColaborador(null);
    setModalVeiculo(null);
  };

  const getIniciais = (nome?: string) => {
    if (!nome) return 'OP';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].slice(0, 2).toUpperCase();
    return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
  };

  return (
    <div className="w-full space-y-4">
      {/* Search and Filters Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-3 rounded-2xl border border-border/60">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-2.5 w-4 h-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Buscar por prefixo, placa, equipe ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-10 border-border/60 bg-background/50"
          />
        </div>
        <div className="flex items-center gap-2">
          <Badge variant="outline" className="h-9 px-3 text-xs font-semibold tabular-nums border-border/80">
            {veiculosFiltrados.length} {veiculosFiltrados.length === 1 ? 'veículo' : 'veículos'}
          </Badge>
          {onNovaEquipeClick && (
            <Button
              type="button"
              onClick={onNovaEquipeClick}
              size="sm"
              className="h-9 px-3 gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white font-medium"
            >
              <Sparkles className="w-3.5 h-3.5" />
              <span>Nova Equipe</span>
            </Button>
          )}
        </div>
      </div>

      {/* Grid of Vehicles */}
      {veiculosFiltrados.length === 0 ? (
        <Card className="p-8 text-center border-dashed border-border/60">
          <div className="max-w-sm mx-auto space-y-3">
            <Car className="w-10 h-10 mx-auto text-muted-foreground/60" />
            <h4 className="text-sm font-bold text-foreground">Nenhum veículo localizado</h4>
            <p className="text-xs text-muted-foreground">
              Tente ajustar sua busca ou selecionar outra regional no topo.
            </p>
          </div>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((veiculo) => {
            const assentos: Array<{
              colab: Colaborador;
              posicaoTexto: string;
              equipeNumero: 1 | 2;
            }> = [
              { colab: veiculo.assentos?.motorista, posicaoTexto: 'Motorista', equipeNumero: 1 },
              { colab: veiculo.assentos?.frenteDir, posicaoTexto: 'Dianteiro Dir.', equipeNumero: 1 },
              { colab: veiculo.assentos?.trasEsq, posicaoTexto: 'Traseiro Esq.', equipeNumero: 2 },
              { colab: veiculo.assentos?.trasDir, posicaoTexto: 'Traseiro Dir.', equipeNumero: 2 },
            ].filter((item): item is { colab: Colaborador; posicaoTexto: string; equipeNumero: 1 | 2 } => Boolean(item.colab));

            const totalPresentes = assentos.filter(
              (a) => a.colab.status === 'presente' || a.colab.status === 'substituto'
            ).length;
            const temFalta = assentos.some((a) => a.colab.status === 'falta');

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'rounded-2xl border transition-all duration-200 overflow-hidden flex flex-col',
                  temFalta
                    ? 'border-rose-500/30 bg-gradient-to-b from-rose-500/5 to-card/60 shadow-lg'
                    : 'border-border/60 bg-card/60 shadow-md hover:border-border'
                )}
              >
                {/* Vehicle Header */}
                <div className="p-4 border-b border-border/40 bg-muted/20 flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2.5">
                    <div className="w-9 h-9 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center shrink-0">
                      <Car className="w-4 h-4 text-emerald-400" />
                    </div>
                    <div>
                      <div className="flex items-center gap-1.5">
                        <span className="font-extrabold text-sm text-foreground tracking-tight">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-[10px] text-muted-foreground uppercase font-mono px-1.5 py-0.5 rounded bg-muted">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground">
                        {veiculo.modelo} · {veiculo.regional === 'agua_clara' ? 'Água Clara' : 'Ribas'}
                      </p>
                    </div>
                  </div>

                  <Badge
                    variant="outline"
                    className={cn(
                      'text-[10px] font-bold tabular-nums',
                      temFalta
                        ? 'border-rose-500/40 text-rose-300 bg-rose-500/10'
                        : 'border-emerald-500/40 text-emerald-300 bg-emerald-500/10'
                    )}
                  >
                    {totalPresentes}/4 ativos
                  </Badge>
                </div>

                {/* Team Badges */}
                <div className="px-4 py-2 border-b border-border/40 bg-muted/10 flex items-center justify-between text-[11px] text-muted-foreground">
                  <div className="flex items-center gap-1">
                    <span className="font-semibold text-foreground">Equipe 1:</span>
                    <span>{veiculo.equipe1Codigo || 'EQ-1'}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <span className="font-semibold text-foreground">Equipe 2:</span>
                    <span>{veiculo.equipe2Codigo || 'EQ-2'}</span>
                  </div>
                </div>

                {/* Operadores dos 4 Assentos */}
                <div className="p-3 space-y-2 flex-1">
                  {assentos.map(({ colab, posicaoTexto, equipeNumero }) => {
                    const cfg = statusBadgeConfig[colab.status || 'presente'];
                    const IconeStatus = cfg.icon;

                    return (
                      <div
                        key={colab.id}
                        onClick={() => handleOpenAttendance(colab, veiculo)}
                        className={cn(
                          'p-2.5 rounded-xl border flex items-center justify-between gap-2.5 transition-all cursor-pointer group',
                          colab.status === 'presente'
                            ? 'border-border/50 bg-card/40 hover:bg-muted/40 hover:border-emerald-500/40'
                            : colab.status === 'falta'
                            ? 'border-rose-500/30 bg-rose-500/10 hover:border-rose-500/50'
                            : 'border-amber-500/30 bg-amber-500/10 hover:border-amber-500/50'
                        )}
                      >
                        <div className="flex items-center gap-2.5 min-w-0">
                          {colab.foto ? (
                            <img
                              src={colaboradorFoto(colab.foto)}
                              alt={colab.nome}
                              className="w-9 h-9 rounded-lg object-cover border border-border/50 shrink-0"
                            />
                          ) : (
                            <div className="w-9 h-9 rounded-lg bg-muted text-muted-foreground font-bold text-xs flex items-center justify-center shrink-0">
                              {getIniciais(colab.nome)}
                            </div>
                          )}

                          <div className="min-w-0">
                            <p className="text-xs font-semibold text-foreground truncate group-hover:text-primary transition-colors">
                              {colab.nome}
                            </p>
                            <p className="text-[10px] text-muted-foreground truncate">
                              {posicaoTexto} · Eq. {equipeNumero}
                            </p>
                            {colab.status === 'substituto' && colab.substitutoNome && (
                              <p className="text-[10px] text-amber-300 font-medium truncate">
                                Sub: {colab.substitutoNome}
                              </p>
                            )}
                            {colab.status === 'falta' && colab.motivoFalta && (
                              <p className="text-[10px] text-rose-300 truncate">
                                {colab.motivoFalta}
                              </p>
                            )}
                          </div>
                        </div>

                        <Badge
                          variant="outline"
                          className={cn('text-[10px] px-2 py-0.5 shrink-0 gap-1 font-semibold', cfg.className)}
                        >
                          <IconeStatus className="w-3 h-3" />
                          <span>{cfg.label}</span>
                        </Badge>
                      </div>
                    );
                  })}
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Attendance Modal */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={Boolean(modalColaborador)}
          onClose={handleCloseAttendance}
          colaborador={modalColaborador}
          veiculo={modalVeiculo}
          colaboradoresReserva={colaboradoresReserva}
          onSalvar={(colabId, status, motivo, obs, subId) => {
            onUpdateColaboradorStatus?.(colabId, status, motivo, obs, subId);
            handleCloseAttendance();
          }}
        />
      )}
    </div>
  );
};

function colaboradorFoto(url?: string): string {
  return url || '';
}

