import React, { useState, useEffect, useMemo } from 'react';
import {
  X,
  CheckCircle2,
  XCircle,
  UserCheck,
  UserCheck2,
  Users,
  Search,
  Phone,
  Briefcase,
  AlertCircle,
  FileText,
  MapPin,
  Clock,
  Sparkles,
} from 'lucide-react';
import { Colaborador, StatusPresenca, MotivoFalta, Veiculo } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  onClose: () => void;
  colaborador: Colaborador | null;
  veiculo?: Veiculo | null;
  colaboradoresReserva: Colaborador[];
  onSalvar: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const statusOptions: Array<{
  value: StatusPresenca;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  color: string;
  desc: string;
}> = [
  {
    value: 'presente',
    label: 'Presente',
    icon: CheckCircle2,
    color: 'emerald',
    desc: 'Operador apto e em campo no veículo',
  },
  {
    value: 'falta',
    label: 'Falta / Ausência',
    icon: XCircle,
    color: 'rose',
    desc: 'Operador ausente (atestado, falta, folga)',
  },
  {
    value: 'substituto',
    label: 'Substituição Ativa',
    icon: UserCheck2,
    color: 'amber',
    desc: 'Posto preenchido por colaborador reserva',
  },
];

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  onClose,
  colaborador,
  veiculo,
  colaboradoresReserva = [],
  onSalvar,
}) => {
  const [status, setStatus] = useState<StatusPresenca>('presente');
  const [motivo, setMotivo] = useState<MotivoFalta>('Atestado Médico');
  const [observacao, setObservacao] = useState('');
  const [substitutoId, setSubstitutoId] = useState('');
  const [buscaSubstituto, setBuscaSubstituto] = useState('');

  useEffect(() => {
    if (colaborador) {
      setStatus(colaborador.status || 'presente');
      setMotivo(colaborador.motivoFalta || 'Atestado Médico');
      setObservacao(colaborador.observacao || '');
      setSubstitutoId(colaborador.substitutoId || '');
      setBuscaSubstituto('');
    }
  }, [colaborador, isOpen]);

  const reservasDisponiveis = useMemo(() => {
    return (colaboradoresReserva || []).filter((c) => {
      if (!c) return false;
      const term = buscaSubstituto.toLowerCase().trim();
      if (!term) return true;
      return (
        (c.nome || '').toLowerCase().includes(term) ||
        (c.cargo || '').toLowerCase().includes(term) ||
        (c.telefone || '').toLowerCase().includes(term)
      );
    });
  }, [colaboradoresReserva, buscaSubstituto]);

  const substitutoSelecionado = useMemo(() => {
    if (!substitutoId) return null;
    return (colaboradoresReserva || []).find((c) => c?.id === substitutoId) || null;
  }, [colaboradoresReserva, substitutoId]);

  if (!isOpen || !colaborador) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSalvar(
      colaborador.id,
      status,
      status === 'falta' ? motivo : undefined,
      observacao.trim() || undefined,
      status === 'substituto' ? substitutoId || undefined : undefined
    );
    onClose();
  };

  const getIniciais = (nome?: string) => {
    if (!nome) return 'OP';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].slice(0, 2).toUpperCase();
    return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="relative w-full max-w-xl max-h-[92vh] flex flex-col rounded-2xl border border-border/80 bg-card shadow-2xl overflow-hidden">
        {/* Top Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border/60 bg-muted/30">
          <div className="flex items-center gap-3">
            <div className="relative">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-12 h-12 rounded-xl object-cover border border-border/60 shadow-sm"
                />
              ) : (
                <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-emerald-600 to-teal-800 text-white font-bold flex items-center justify-center text-sm shadow-sm">
                  {getIniciais(colaborador.nome)}
                </div>
              )}
              <span
                className={cn(
                  'absolute -bottom-1 -right-1 w-3.5 h-3.5 rounded-full border-2 border-card',
                  colaborador.status === 'presente'
                    ? 'bg-emerald-500'
                    : colaborador.status === 'falta'
                    ? 'bg-rose-500'
                    : 'bg-amber-500'
                )}
              />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-foreground leading-tight">
                  {colaborador.nome}
                </h3>
                <Badge variant="outline" className="text-[10px] py-0 px-1.5 border-border">
                  Equipe {colaborador.equipeNumero || 1}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground flex items-center gap-1.5 mt-0.5">
                <Briefcase className="w-3.5 h-3.5" />
                <span>{colaborador.cargo}</span>
                {veiculo?.prefixo && (
                  <>
                    <span className="opacity-50">·</span>
                    <span>{veiculo.prefixo}</span>
                  </>
                )}
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="rounded-xl p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Modal Form Body */}
        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-5 space-y-5">
          {/* Status Selection Cards */}
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
              Situação do Operador no Turno
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
              {statusOptions.map((opt) => {
                const Icon = opt.icon;
                const isSelected = status === opt.value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() => setStatus(opt.value)}
                    className={cn(
                      'p-3 rounded-xl border text-left transition-all flex flex-col justify-between gap-2 cursor-pointer',
                      isSelected
                        ? opt.color === 'emerald'
                          ? 'border-emerald-500 bg-emerald-500/10 text-emerald-300 ring-2 ring-emerald-500/20'
                          : opt.color === 'rose'
                          ? 'border-rose-500 bg-rose-500/10 text-rose-300 ring-2 ring-rose-500/20'
                          : 'border-amber-500 bg-amber-500/10 text-amber-300 ring-2 ring-amber-500/20'
                        : 'border-border/60 bg-card/40 hover:bg-muted/40 text-muted-foreground hover:border-border'
                    )}
                  >
                    <div className="flex items-center justify-between">
                      <Icon className={cn('w-4 h-4', isSelected ? 'text-current' : 'text-muted-foreground')} />
                      {isSelected && (
                        <span className="w-2 h-2 rounded-full bg-current animate-pulse" />
                      )}
                    </div>
                    <div>
                      <p className="font-semibold text-xs text-foreground">{opt.label}</p>
                      <p className="text-[10px] text-muted-foreground line-clamp-2 mt-0.5">{opt.desc}</p>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Conditional: Falta / Ausência */}
          {status === 'falta' && (
            <div className="p-3.5 rounded-xl border border-rose-500/25 bg-rose-500/5 space-y-3 animate-in fade-in-50 duration-150">
              <div className="flex items-center gap-2 text-rose-300 text-xs font-semibold">
                <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                <span>Classificação do Motivo da Ausência</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {MOTIVOS_FALTA.map((m) => (
                  <label
                    key={m}
                    className={cn(
                      'flex items-center gap-2 p-2.5 rounded-lg border text-xs cursor-pointer transition-all',
                      motivo === m
                        ? 'border-rose-500 bg-rose-500/15 text-rose-200 font-medium'
                        : 'border-border/60 bg-card/40 text-muted-foreground hover:bg-muted/40'
                    )}
                  >
                    <input
                      type="radio"
                      name="motivoFalta"
                      value={m}
                      checked={motivo === m}
                      onChange={() => setMotivo(m)}
                      className="text-rose-500 focus:ring-rose-500 rounded"
                    />
                    <span>{m}</span>
                  </label>
                ))}
              </div>
            </div>
          )}

          {/* Conditional: Substituto Selection */}
          {status === 'substituto' && (
            <div className="p-4 rounded-xl border border-amber-500/30 bg-amber-500/5 space-y-3 animate-in fade-in-50 duration-150">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-amber-300 text-xs font-semibold">
                  <UserCheck2 className="w-4 h-4 shrink-0 text-amber-400" />
                  <span>Selecionar Operador do Banco de Reserva</span>
                </div>
                <Badge variant="outline" className="text-[10px] text-amber-400 border-amber-500/30">
                  {reservasDisponiveis.length} disponíveis
                </Badge>
              </div>

              {/* Substituto Atual Selecionado */}
              {substitutoSelecionado && (
                <div className="flex items-center justify-between p-2.5 rounded-lg bg-amber-500/15 border border-amber-500/40 text-xs">
                  <div className="flex items-center gap-2">
                    <CheckCircle2 className="w-4 h-4 text-amber-400" />
                    <div>
                      <p className="font-semibold text-foreground">{substitutoSelecionado.nome}</p>
                      <p className="text-[11px] text-muted-foreground">{substitutoSelecionado.cargo}</p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => setSubstitutoId('')}
                    className="text-[11px] text-muted-foreground hover:text-rose-400 px-2 py-1 rounded hover:bg-rose-500/10 transition-colors"
                  >
                    Trocar
                  </button>
                </div>
              )}

              {/* Campo de Busca Rápida */}
              <div className="relative">
                <Search className="absolute left-3 top-2.5 w-3.5 h-3.5 text-muted-foreground" />
                <input
                  type="text"
                  placeholder="Pesquisar por nome, cargo ou telefone..."
                  value={buscaSubstituto}
                  onChange={(e) => setBuscaSubstituto(e.target.value)}
                  className="w-full h-9 pl-9 pr-3 rounded-lg border border-border/80 bg-background text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-amber-500/40"
                />
              </div>

              {/* Lista de Reservas Disponíveis */}
              <div className="max-h-44 overflow-y-auto space-y-1.5 pr-1">
                {reservasDisponiveis.length === 0 ? (
                  <div className="text-center py-4 text-xs text-muted-foreground">
                    Nenhum colaborador reserva encontrado.
                  </div>
                ) : (
                  reservasDisponiveis.map((r) => {
                    const isPicked = substitutoId === r.id;
                    return (
                      <div
                        key={r.id}
                        onClick={() => setSubstitutoId(r.id)}
                        className={cn(
                          'p-2.5 rounded-lg border flex items-center justify-between gap-2 cursor-pointer transition-all text-xs',
                          isPicked
                            ? 'border-amber-500 bg-amber-500/20 text-amber-200'
                            : 'border-border/60 bg-card/60 hover:bg-muted/40 hover:border-amber-500/40'
                        )}
                      >
                        <div className="flex items-center gap-2.5">
                          <div className="w-8 h-8 rounded-lg bg-muted flex items-center justify-center font-bold text-[11px] text-muted-foreground shrink-0">
                            {getIniciais(r.nome)}
                          </div>
                          <div>
                            <p className="font-semibold text-foreground">{r.nome}</p>
                            <p className="text-[11px] text-muted-foreground">{r.cargo}</p>
                          </div>
                        </div>

                        <div className="flex items-center gap-2 shrink-0">
                          {r.telefone && (
                            <span className="text-[10px] text-muted-foreground tabular-nums flex items-center gap-1">
                              <Phone className="w-3 h-3" />
                              {r.telefone}
                            </span>
                          )}
                          <Button
                            type="button"
                            size="sm"
                            variant={isPicked ? 'default' : 'outline'}
                            className={cn(
                              'h-7 px-2.5 text-[11px]',
                              isPicked ? 'bg-amber-600 hover:bg-amber-500 text-white' : ''
                            )}
                          >
                            {isPicked ? 'Escolhido' : 'Selecionar'}
                          </Button>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          )}

          {/* Observações Operacionais */}
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-foreground flex items-center gap-1.5">
              <FileText className="w-3.5 h-3.5 text-muted-foreground" />
              Observações do Registro (Opcional)
            </label>
            <textarea
              rows={2}
              placeholder="Descreva detalhes como atestado CID, autorização do encarregado ou motivo de remanejamento..."
              value={observacao}
              onChange={(e) => setObservacao(e.target.value)}
              className="w-full p-2.5 rounded-xl border border-border/80 bg-background text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 resize-none"
            />
          </div>

          {/* Botões do Rodapé */}
          <div className="pt-2 flex items-center justify-end gap-2 border-t border-border/50">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onClose}
              className="h-9 px-4 text-xs"
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              size="sm"
              className="h-9 px-5 text-xs bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-sm"
            >
              Salvar Alteração
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

