import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  AlertTriangle,
  UserCheck,
  UserX,
  Phone,
  Shield,
  Search,
  User,
  Info,
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  colaborador: Colaborador;
  colaboradoresReserva?: Colaborador[];
  onClose: () => void;
  onSave: (
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  colaborador,
  colaboradoresReserva = [],
  onClose,
  onSave,
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador?.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(colaborador?.motivoFalta);
  const [observacao, setObservacao] = useState(colaborador?.observacao || '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador?.substitutoId || '');
  const [buscaSubstituto, setBuscaSubstituto] = useState('');

  if (!isOpen || !colaborador) return null;

  const substitutosFiltrados = (colaboradoresReserva || []).filter((sub) => {
    if (!sub || sub.id === colaborador.id) return false;
    if (!buscaSubstituto) return true;
    return (
      (sub.nome || '').toLowerCase().includes(buscaSubstituto.toLowerCase()) ||
      (sub.cargo || '').toLowerCase().includes(buscaSubstituto.toLowerCase())
    );
  });

  const handleSalvar = () => {
    onSave(
      status,
      status === 'falta' ? motivo : undefined,
      observacao.trim() || undefined,
      status === 'substituto' ? substitutoId : undefined
    );
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="relative w-full max-w-lg rounded-2xl border border-border/80 bg-card p-6 shadow-2xl space-y-5">
        {/* Cabeçalho do Modal */}
        <div className="flex items-center justify-between border-b border-border/50 pb-3">
          <div className="flex items-center gap-3">
            {/* Foto Ampliada no Header do Modal */}
            <div className="w-14 h-14 rounded-2xl border-2 border-emerald-500/40 overflow-hidden shrink-0 shadow-md flex items-center justify-center bg-muted/40">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <span className="font-black text-foreground text-lg">
                  {getIniciais(colaborador.nome)}
                </span>
              )}
            </div>
            <div>
              <h3 className="font-bold text-base text-foreground">{colaborador.nome}</h3>
              <p className="text-xs text-muted-foreground">{colaborador.cargo}</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1 text-muted-foreground hover:bg-muted"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Seleção de Status */}
        <div className="space-y-2">
          <label className="text-xs font-semibold text-foreground">Status Operacional</label>
          <div className="grid grid-cols-3 gap-2">
            <button
              type="button"
              onClick={() => setStatus('presente')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all',
                status === 'presente'
                  ? 'border-emerald-500 bg-emerald-500/15 text-emerald-400 ring-2 ring-emerald-500/20'
                  : 'border-border/60 text-muted-foreground hover:bg-muted/40'
              )}
            >
              <CheckCircle2 className="w-5 h-5 mb-1" />
              <span>Presente</span>
            </button>

            <button
              type="button"
              onClick={() => setStatus('falta')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all',
                status === 'falta'
                  ? 'border-rose-500 bg-rose-500/15 text-rose-400 ring-2 ring-rose-500/20'
                  : 'border-border/60 text-muted-foreground hover:bg-muted/40'
              )}
            >
              <UserX className="w-5 h-5 mb-1" />
              <span>Falta</span>
            </button>

            <button
              type="button"
              onClick={() => setStatus('substituto')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all',
                status === 'substituto'
                  ? 'border-amber-500 bg-amber-500/15 text-amber-400 ring-2 ring-amber-500/20'
                  : 'border-border/60 text-muted-foreground hover:bg-muted/40'
              )}
            >
              <UserCheck className="w-5 h-5 mb-1" />
              <span>Substituto</span>
            </button>
          </div>
        </div>

        {/* Opções de Falta */}
        {status === 'falta' && (
          <div className="space-y-2 animate-in fade-in">
            <label className="text-xs font-semibold text-foreground">Motivo da Ausência</label>
            <select
              value={motivo}
              onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
              className="w-full h-10 px-3 rounded-xl border border-input bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
            >
              <option value="">Selecione o motivo...</option>
              {MOTIVOS_FALTA.map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </div>
        )}

        {/* Seleção de Substituto */}
        {status === 'substituto' && (
          <div className="space-y-3 animate-in fade-in">
            <label className="text-xs font-semibold text-foreground">Selecione o Colaborador Substituto</label>
            <div className="relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Filtrar operador por nome ou cargo..."
                value={buscaSubstituto}
                onChange={(e) => setBuscaSubstituto(e.target.value)}
                className="pl-9 h-9 text-xs"
              />
            </div>

            <div className="max-h-48 overflow-y-auto space-y-1.5 rounded-xl border border-border p-2 bg-muted/20">
              {substitutosFiltrados.length === 0 ? (
                <p className="text-center text-xs text-muted-foreground py-3">Nenhum operador reserva disponível.</p>
              ) : (
                substitutosFiltrados.map((sub) => (
                  <div
                    key={sub.id}
                    onClick={() => setSubstitutoId(sub.id)}
                    className={cn(
                      'flex items-center justify-between p-2 rounded-xl border cursor-pointer transition-all',
                      substitutoId === sub.id
                        ? 'border-amber-500 bg-amber-500/15 text-foreground ring-1 ring-amber-500/30'
                        : 'border-border/50 hover:bg-card text-muted-foreground'
                    )}
                  >
                    <div className="flex items-center gap-2.5">
                      <div className="w-9 h-9 rounded-xl border overflow-hidden shrink-0 flex items-center justify-center bg-muted/40 font-bold text-xs text-foreground">
                        {sub.foto ? (
                          <img src={sub.foto} alt={sub.nome} className="w-full h-full object-cover" />
                        ) : (
                          getIniciais(sub.nome)
                        )}
                      </div>
                      <div>
                        <p className="font-bold text-xs text-foreground">{sub.nome}</p>
                        <p className="text-[10px] text-muted-foreground">{sub.cargo}</p>
                      </div>
                    </div>
                    {substitutoId === sub.id && (
                      <CheckCircle2 className="w-4 h-4 text-amber-400 shrink-0" />
                    )}
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* Observações */}
        <div className="space-y-1.5">
          <label className="text-xs font-semibold text-foreground">Observações / Detalhes</label>
          <Input
            placeholder="Ex: Atestado entregue ao RH, retorno previsto para amanhã..."
            value={observacao}
            onChange={(e) => setObservacao(e.target.value)}
            className="text-xs h-10"
          />
        </div>

        {/* Rodapé de Ações */}
        <div className="pt-2 flex justify-end gap-2 border-t border-border/50">
          <Button type="button" variant="outline" onClick={onClose} className="rounded-xl">
            Cancelar
          </Button>
          <Button
            type="button"
            onClick={handleSalvar}
            className="bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl"
          >
            Confirmar Registro
          </Button>
        </div>
      </div>
    </div>
  );
};

files.oldContent:
import React, { useState } from 'react';
import {
  Car,
  Users,
  AlertTriangle,
  UserCheck,
  UserX,
  RefreshCw,
  Phone,
  Shield,
  ArrowRight,
  Sparkles,
  MapPin,
  CheckCircle2,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateStatus?: (
    colaboradorId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; bg: string; text: string; border: string; dot: string }> = {
  presente: {
    label: 'Presente',
    bg: 'bg-emerald-500/15',
    text: 'text-emerald-400',
    border: 'border-emerald-500/30',
    dot: 'bg-emerald-400',
  },
  falta: {
    label: 'Falta',
    bg: 'bg-rose-500/15',
    text: 'text-rose-400',
    border: 'border-rose-500/30',
    dot: 'bg-rose-400',
  },
  substituto: {
    label: 'Substituto',
    bg: 'bg-amber-500/15',
    text: 'text-amber-400',
    border: 'border-amber-500/30',
    dot: 'bg-amber-400',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateStatus,
}) => {
  const [modalOpen, setModalOpen] = useState(false);
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    if (selectedRegional === 'todas') return true;
    return v.regional === selectedRegional;
  });

  const handleOpenAttendance = (colab: Colaborador) => {
    if (!colab) return;
    setColaboradorSelecionado(colab);
    setModalOpen(true);
  };

  const handleSaveAttendance = (
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    if (colaboradorSelecionado && onUpdateStatus) {
      onUpdateStatus(colaboradorSelecionado.id, status, motivo, observacao, substitutoId);
    }
  };

  const renderSeatCollaborator = (colab?: Colaborador, cargoEtiqueta?: string) => {
    if (!colab) {
      return (
        <div className="flex flex-col items-center justify-center p-4 rounded-xl border border-dashed border-border/60 bg-muted/20 min-h-[160px] text-center">
          <Users className="w-6 h-6 text-muted-foreground/40 mb-1" />
          <span className="text-xs text-muted-foreground font-medium">Vaga Disponível</span>
          {cargoEtiqueta && <span className="text-[10px] text-muted-foreground/70">{cargoEtiqueta}</span>}
        </div>
      );
    }

    const st = statusConfig[colab.status] || statusConfig.presente;

    return (
      <div
        onClick={() => handleOpenAttendance(colab)}
        className={cn(
          'group relative flex flex-col items-center p-3.5 rounded-2xl border transition-all duration-200 cursor-pointer text-center',
          'bg-card/70 hover:bg-card hover:border-emerald-500/50 hover:shadow-lg hover:-translate-y-0.5',
          colab.status === 'falta'
            ? 'border-rose-500/30 bg-rose-500/5'
            : colab.status === 'substituto'
            ? 'border-amber-500/30 bg-amber-500/5'
            : 'border-border/70 shadow-sm'
        )}
      >
        {/* Status Badge flutuante */}
        <div className="absolute top-2.5 right-2.5">
          <span
            className={cn(
              'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold border',
              st.bg,
              st.text,
              st.border
            )}
          >
            <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', st.dot)} />
            {st.label}
          </span>
        </div>

        {/* FOTO DO COLABORADOR - AUMENTADA */}
        <div className="relative mt-2 mb-2.5">
          <div
            className={cn(
              'w-20 h-20 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-2 shadow-md transition-transform duration-200 group-hover:scale-105 flex items-center justify-center',
              colab.status === 'falta'
                ? 'border-rose-500/50 bg-rose-950/20'
                : colab.status === 'substituto'
                ? 'border-amber-500/50 bg-amber-950/20'
                : 'border-emerald-500/40 bg-emerald-950/20'
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <div className="w-full h-full flex flex-col items-center justify-center bg-gradient-to-br from-emerald-900/30 to-muted/40 text-foreground font-black text-xl sm:text-2xl">
                {getIniciais(colab.nome)}
              </div>
            )}
          </div>
          {cargoEtiqueta && (
            <span className="absolute -bottom-2 left-1/2 -translate-x-1/2 whitespace-nowrap px-2 py-0.5 rounded-md bg-muted/95 border border-border/80 text-[10px] font-bold text-foreground/90 shadow-sm">
              {cargoEtiqueta}
            </span>
          )}
        </div>

        {/* Nome do Colaborador abaixo da foto */}
        <div className="w-full mt-1.5">
          <p className="font-bold text-sm text-foreground truncate max-w-full group-hover:text-emerald-400 transition-colors">
            {colab.nome || 'Sem Nome'}
          </p>
          <p className="text-xs text-muted-foreground truncate font-medium">
            {colab.cargo || 'Operador Florestal'}
          </p>
          {colab.status === 'substituto' && colab.substitutoNome && (
            <p className="text-[11px] text-amber-400 font-medium truncate mt-0.5">
              Subst: {colab.substitutoNome}
            </p>
          )}
          {colab.status === 'falta' && colab.motivoFalta && (
            <p className="text-[11px] text-rose-400 font-medium truncate mt-0.5">
              Motivo: {colab.motivoFalta}
            </p>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {veiculosFiltrados.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border/70 p-12 text-center bg-card/40">
          <Car className="w-12 h-12 mx-auto text-muted-foreground/40 mb-3" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-sm text-muted-foreground mt-1">
            Não há equipes ou veículos registrados para a unidade selecionada.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            if (!veiculo) return null;
            return (
              <Card
                key={veiculo.id || veiculo.prefixo}
                className="overflow-hidden border border-border/80 bg-card/80 backdrop-blur-md shadow-xl hover:shadow-2xl transition-all duration-200"
              >
                {/* Header do Veículo */}
                <CardHeader className="p-4 sm:p-5 border-b border-border/50 bg-gradient-to-r from-muted/40 via-muted/20 to-transparent">
                  <div className="flex items-center justify-between gap-3 flex-wrap">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400 shrink-0">
                        <Car className="w-5 h-5" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <CardTitle className="text-lg font-black tracking-tight text-foreground">
                            {veiculo.prefixo}
                          </CardTitle>
                          <Badge variant="outline" className="text-xs font-bold border-border/80 bg-background/50">
                            {veiculo.placa}
                          </Badge>
                          <span
                            className={cn(
                              'px-2 py-0.5 rounded-full text-[10px] font-bold border',
                              veiculo.regional === 'ribas'
                                ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                                : 'bg-teal-500/10 text-teal-400 border-teal-500/30'
                            )}
                          >
                            {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                          </span>
                        </div>
                        <p className="text-xs text-muted-foreground mt-0.5 font-medium">
                          {veiculo.modelo} · Equipes {veiculo.equipe1Codigo} & {veiculo.equipe2Codigo}
                        </p>
                      </div>
                    </div>
                  </div>
                </CardHeader>

                {/* Conteúdo com os assentos / colaboradores */}
                <CardContent className="p-4 sm:p-5">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {/* Equipe Dianteira */}
                    <div className="space-y-3 p-3.5 rounded-2xl bg-muted/25 border border-border/50">
                      <div className="flex items-center justify-between pb-1.5 border-b border-border/40">
                        <span className="text-xs font-bold text-foreground flex items-center gap-1.5">
                          <Users className="w-3.5 h-3.5 text-emerald-400" />
                          Equipe 1 · {veiculo.equipe1Codigo}
                        </span>
                        <span className="text-[10px] text-muted-foreground">Cabine Frontal</span>
                      </div>
                      <div className="grid grid-cols-2 gap-2.5">
                        {renderSeatCollaborator(veiculo.assentos?.motorista, 'Motorista')}
                        {renderSeatCollaborator(veiculo.assentos?.frenteDir, 'Ajudante')}
                      </div>
                    </div>

                    {/* Equipe Traseira */}
                    <div className="space-y-3 p-3.5 rounded-2xl bg-muted/25 border border-border/50">
                      <div className="flex items-center justify-between pb-1.5 border-b border-border/40">
                        <span className="text-xs font-bold text-foreground flex items-center gap-1.5">
                          <Users className="w-3.5 h-3.5 text-teal-400" />
                          Equipe 2 · {veiculo.equipe2Codigo}
                        </span>
                        <span className="text-[10px] text-muted-foreground">Cabine Traseira</span>
                      </div>
                      <div className="grid grid-cols-2 gap-2.5">
