                  colors.badge
                )}
              >
                <span className={cn('w-1.5 h-1.5 rounded-full', colors.dot)} />
                <span>{activePanelInfo?.label ?? 'Geral'}</span>
                <span className="opacity-60">·</span>
                <span className="tabular-nums">{totalEquipes} equipes</span>
              </div>
            </div>

            {onNovaEquipe && (
              <Button
