      {modalNovoAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in">
          <div className="relative max-w-md w-full bg-card p-6 rounded-2xl border border-border shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b border-border/50 pb-3">
              <h3 className="font-bold text-base text-foreground flex items-center gap-2">
                <Plus className="w-4 h-4 text-emerald-400" />
                Cadastrar Colaborador
              </h3>
              <button
                type="button"
                onClick={() => setModalNovoAberto(false)}
                className="p-1 rounded-lg text-muted-foreground hover:bg-muted cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="space-y-3 text-xs">
              <div>
                <label className="block font-medium text-foreground mb-1">Nome Completo</label>
                <Input
                  required
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                />
              </div>

              <div>
                <label className="block font-medium text-foreground mb-1">Cargo / Função</label>
                <Input
                  placeholder="Ex: Operador de Máquinas Florestais"
                  value={novoCargo}
                  onChange={(e) => setNovoCargo(e.target.value)}
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="block font-medium text-foreground mb-1">Unidade</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as 'ribas' | 'agua_clara')}
                    className="w-full h-10 px-3 rounded-xl border border-input bg-card text-xs text-foreground"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>

                <div>
                  <label className="block font-medium text-foreground mb-1">Data Admissão</label>
                  <Input
                    placeholder="DD/MM/AAAA"
                    value={novaDataAdmissao}
                    onChange={(e) => setNovaDataAdmissao(e.target.value)}
                  />
