import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal, NovaEquipePayload } from './components/NewTeamModal';
import { AttendanceModal } from './components/AttendanceModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta } from './types';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // Estado dos Veículos e Colaboradores
  const [veiculos, setVeiculos] = useState<Veiculo[]>(() => {
    try {
      const salvo = localStorage.getItem('gestao_veiculos_cache');
      return salvo ? JSON.parse(salvo) : VEICULOS_INICIAIS;
    } catch {
      return VEICULOS_INICIAIS;
    }
  });

  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(() => {
    try {
      const salvo = localStorage.getItem('gestao_reserva_cache');
      return salvo ? JSON.parse(salvo) : COLABORADORES_RESERVA;
    } catch {
      return COLABORADORES_RESERVA;
    }
  });

  // Salvar no localStorage para persistência imediata
  useEffect(() => {
    try {
      localStorage.setItem('gestao_veiculos_cache', JSON.stringify(veiculos));
    } catch {
      // Ignora erro de storage
    }
  }, [veiculos]);

  useEffect(() => {
    try {
      localStorage.setItem('gestao_reserva_cache', JSON.stringify(colaboradoresReserva));
    } catch {
      // Ignora erro de storage
    }
  }, [colaboradoresReserva]);

  // Modais
  const [modalNovaEquipeAberto, setModalNovaEquipeAberto] = useState(false);
  const [attendanceModalConfig, setAttendanceModalConfig] = useState<{
    isOpen: boolean;
    colaborador?: Colaborador;
    veiculoId?: string;
  }>({
    isOpen: false,
  });

  // Atualizar Status de Presença do Colaborador
  const handleUpdateStatus = (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    const substColab = substitutoId ? colaboradoresReserva.find((c) => c.id === substitutoId) : undefined;

    setVeiculos((prev) =>
      prev.map((v) => {
        if (!v || !v.assentos) return v;
        const novosAssentos = { ...v.assentos };

        (['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const).forEach((pos) => {
          if (novosAssentos[pos]?.id === colaboradorId) {
            novosAssentos[pos] = {
              ...novosAssentos[pos],
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivo : undefined,
              observacao: novoStatus === 'falta' ? observacao : undefined,
              substitutoId: novoStatus === 'substituto' ? substitutoId : undefined,
              substitutoNome: novoStatus === 'substituto' && substColab ? substColab.nome : undefined,
            };
          }
        });

        return { ...v, assentos: novosAssentos };
      })
    );
  };

  // Abrir Modal de Faltas
  const handleOpenAttendanceModal = (colaborador: Colaborador, veiculoId: string) => {
    setAttendanceModalConfig({
      isOpen: true,
      colaborador,
      veiculoId,
    });
  };

  // Adicionar Nova Equipe
  const handleCriarEquipe = (payload: NovaEquipePayload) => {
    const novoVeiculo: Veiculo = {
      id: `veiculo-${Date.now()}`,
      prefixo: payload.veiculoPrefixo,
      placa: payload.veiculoPlaca,
      modelo: payload.veiculoModelo,
      ano: 2024,
      regional: payload.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: payload.codigo,
      equipe2Codigo: `${payload.codigo}-B`,
      assentos: {
        motorista: payload.motorista,
        frenteDir: payload.frenteDir,
        trasEsq: payload.trasEsq || {
          id: `colab-tras-esq-${Date.now()}`,
          nome: 'Operador Traseiro 1',
          cargo: 'Operador Florestal',
          foto: '',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: payload.codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
          unidade: payload.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
        },
        trasDir: payload.trasDir || {
          id: `colab-tras-dir-${Date.now()}`,
          nome: 'Operador Traseiro 2',
          cargo: 'Operador Florestal',
          foto: '',
          telefone: '(67) 99999-0000',
          status: 'presente',
          equipeId: payload.codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
          unidade: payload.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  // Importar Colaboradores do Excel/CSV
  const handleImportarColaboradores = (novos: ColaboradorCompleto[]) => {
    const convertidos: Colaborador[] = novos.map((n) => ({
      id: n.id,
      nome: n.nome,
      cargo: n.cargo,
      matricula: n.matricula,
      foto: n.foto,
      telefone: n.telefone,
      status: n.status,
      equipeId: n.equipeId,
      equipeNumero: n.equipeNumero,
      posicaoVeiculo: n.posicaoVeiculo,
      unidade: n.unidade,
      dataAdmissao: n.dataAdmissao,
    }));
    setColaboradoresReserva((prev) => [...convertidos, ...prev]);
  };

  // Adicionar Colaborador Manualmente
  const handleAdicionarColaborador = (novo: ColaboradorCompleto) => {
    const c: Colaborador = {
      id: novo.id,
      nome: novo.nome,
      cargo: novo.cargo,
      matricula: novo.matricula,
      foto: novo.foto,
      telefone: novo.telefone,
      status: novo.status,
      equipeId: novo.equipeId,
      equipeNumero: novo.equipeNumero,
      posicaoVeiculo: novo.posicaoVeiculo,
      unidade: novo.unidade,
      dataAdmissao: novo.dataAdmissao,
    };
    setColaboradoresReserva((prev) => [c, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col font-sans selection:bg-primary/20 selection:text-primary">
      {/* Navbar Global */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Cabeçalho de Métricas */}
        <MetricsHeader
          veiculos={veiculos}
          selectedRegional={selectedRegional}
          selectedDate={selectedDate}
          onFiltroRegionalChange={setSelectedRegional}
          onNovaEquipe={() => setModalNovaEquipeAberto(true)}
        />

        {/* Visão Alternada por Aba */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
            onUpdateColaboradorStatus={handleUpdateStatus}
            onOpenAttendanceModal={handleOpenAttendanceModal}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onUpdateColaboradorStatus={handleUpdateStatus}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onNovaEquipe={() => setModalNovaEquipeAberto(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Modal de Cadastrar Nova Equipe */}
      <NewTeamModal
        isOpen={modalNovaEquipeAberto}
        onClose={() => setModalNovaEquipeAberto(false)}
        colaboradoresReserva={colaboradoresReserva}
        onCriarEquipe={handleCriarEquipe}
      />

      {/* Modal de Presença / Falta */}
      {attendanceModalConfig.colaborador && (
        <AttendanceModal
          isOpen={attendanceModalConfig.isOpen}
          onClose={() => setAttendanceModalConfig({ isOpen: false })}
          colaborador={attendanceModalConfig.colaborador}
          veiculoId={attendanceModalConfig.veiculoId || ''}
          colaboradoresReserva={colaboradoresReserva}
          onConfirm={handleUpdateStatus}
        />
      )}
    </div>
  );
}

export default App;

