import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  Building2,
  Briefcase,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Trash2,
  FileCheck,
  Eye,
  FileUp,
  Loader2,
  CalendarDays,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula?: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
  unidade?: string;
  dataAdmissao?: string;
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [fotoModalAberta, setFotoModalAberta] = useState<{ url: string; nome: string; cargo: string } | null>(null);

  const [modalNovoAberto, setModalNovoAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novaDataAdmissao, setNovaDataAdmissao] = useState('15/01/2023');

  const [modalExcelAberto, setModalExcelAberto] = useState(false);
  const [isProcessandoExcel, setIsProcessandoExcel] = useState(false);
  const [excelPreview, setExcelPreview] = useState<ColaboradorCompleto[]>([]);
  const [excelErro, setExcelErro] = useState<string | null>(null);
  const [excelArquivoNome, setExcelArquivoNome] = useState<string>('');
  const [excelImportSucesso, setExcelImportSucesso] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
          unidade: colab.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          dataAdmissao: colab.dataAdmissao || '10/02/2023',
        });
      });
    });

    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
        unidade: r.unidade || 'Ribas do Rio Pardo',
        dataAdmissao: r.dataAdmissao || '05/06/2023',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.unidade || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleCadastrarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) return;

    const novo: ColaboradorCompleto = {
      id: `colab-custom-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim() || 'Operador Florestal',
      matricula: '',
      foto: novaFoto,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
      unidade: novaUnidade === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
      dataAdmissao: novaDataAdmissao || '15/01/2023',
    };

    setColaboradoresAdicionados((prev) => [novo, ...prev]);
    onAdicionarColaborador?.(novo);
    setModalNovoAberto(false);
    setNovoNome('');
    setNovoCargo('');
    setNovoTelefone('');
    setNovaFoto('');
  };

  const processarTextoCSV = (conteudo: string): ColaboradorCompleto[] => {
    const linhas = conteudo.split(/\r?\n/).filter((l) => l.trim().length > 0);
    if (linhas.length < 2) return [];

    const cabecalho = linhas[0].toLowerCase().split(/[,;\t]/).map((c) => c.trim().replace(/["']/g, ''));
    const idxNome = cabecalho.findIndex((c) => c.includes('nome'));
    const idxCargo = cabecalho.findIndex((c) => c.includes('cargo') || c.includes('função') || c.includes('funcao'));
    const idxUnidade = cabecalho.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('cidade'));
    const idxAdmissao = cabecalho.findIndex((c) => c.includes('admiss') || c.includes('data'));
    const idxTelefone = cabecalho.findIndex((c) => c.includes('tel') || c.includes('cel') || c.includes('fone'));

    const parsed: ColaboradorCompleto[] = [];

    for (let i = 1; i < linhas.length; i++) {
      const colunas = linhas[i].split(/[,;\t]/).map((c) => c.trim().replace(/["']/g, ''));
      const nome = (idxNome >= 0 ? colunas[idxNome] : colunas[0]) || '';
      if (!nome) continue;

      const cargo = (idxCargo >= 0 ? colunas[idxCargo] : colunas[1]) || 'Operador Florestal';
      const unidadeStr = (idxUnidade >= 0 ? colunas[idxUnidade] : colunas[2]) || 'Ribas do Rio Pardo';
      const isAguaClara = unidadeStr.toLowerCase().includes('agua') || unidadeStr.toLowerCase().includes('clara');
      const dataAdmissao = (idxAdmissao >= 0 ? colunas[idxAdmissao] : '') || '10/01/2023';
      const telefone = (idxTelefone >= 0 ? colunas[idxTelefone] : '') || '(67) 99999-0000';

      parsed.push({
        id: `planilha-colab-${Date.now()}-${i}`,
        nome,
        cargo,
        matricula: '',
        foto: '',
        telefone,
        status: 'presente',
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: isAguaClara ? 'agua_clara' : 'ribas',
        unidade: isAguaClara ? 'Água Clara' : 'Ribas do Rio Pardo',
        dataAdmissao,
      });
    }

    return parsed;
  };

  const handleArquivoPlanilhaChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setExcelArquivoNome(file.name);
    setIsProcessandoExcel(true);
    setExcelErro(null);
    setExcelPreview([]);
    setExcelImportSucesso(false);

    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith('.csv') || fileName.endsWith('.txt')) {
        const text = await file.text();
        const lista = processarTextoCSV(text);
        if (lista.length === 0) {
          setExcelErro('Nenhum colaborador detectado. Verifique as colunas da planilha (Nome, Função, Unidade).');
        } else {
          setExcelPreview(lista);
        }
      } else {
        try {
          const XLSX = await import('xlsx');
          if (XLSX && XLSX.read) {
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer, { type: 'array' });
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const csv = XLSX.utils.sheet_to_csv(firstSheet);
            const lista = processarTextoCSV(csv);
            if (lista.length === 0) {
              setExcelErro('Nenhum dado encontrado na primeira aba da planilha.');
            } else {
              setExcelPreview(lista);
            }
          } else {
            throw new Error('Módulo XLSX indisponível.');
          }
        } catch {
          const text = await file.text();
          const lista = processarTextoCSV(text);
          if (lista.length > 0) {
            setExcelPreview(lista);
          } else {
            setExcelErro('Por favor, salve a planilha como formato CSV (separado por vírgulas ou ponto-e-vírgula) para importação imediata.');
          }
        }
      }
    } catch {
      setExcelErro('Falha ao ler o arquivo. Converta sua planilha para formato CSV e tente novamente.');
    } finally {
      setIsProcessandoExcel(false);
    }
  };

  const handleConfirmarImportacao = () => {
    if (excelPreview.length === 0) return;
    setColaboradoresAdicionados((prev) => [...excelPreview, ...prev]);
    onImportarColaboradores?.(excelPreview);
    setExcelImportSucesso(true);
    setTimeout(() => {
      setModalExcelAberto(false);
      setExcelPreview([]);
      setExcelImportSucesso(false);
      setExcelArquivoNome('');
      if (excelInputRef.current) excelInputRef.current.value = '';
    }, 1200);
  };

  const downloadModeloCSV = () => {
    const csvContent =
      'Nome;Cargo / Função;Unidade;Data de Admissão;Telefone\n' +
      'Carlos Eduardo Silva;Operador de Máquinas;Ribas do Rio Pardo;15/02/2022;(67) 99812-3456\n' +
      'Lucas Gabriel Costa;Motorista Florestal;Água Clara;10/06/2023;(67) 99654-7890\n' +
      'André Silva Santos;Ajudante Geral;Ribas do Rio Pardo;03/01/2024;(67) 99988-1122\n';

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'modelo_importacao_colaboradores.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full space-y-4">
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 border border-border/80 p-4 rounded-2xl backdrop-blur-md">
        <div>
          <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-xs text-muted-foreground">
            {colaboradoresFiltrados.length} colaboradores listados · Gestão de equipe e reserva
          </p>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => setModalExcelAberto(true)}
            className="gap-1.5 border-emerald-500/40 text-emerald-300 hover:bg-emerald-500/10 cursor-pointer"
          >
            <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
            <span>Subir Planilha</span>
          </Button>

          <Button
            type="button"
            size="sm"
            onClick={() => setModalNovoAberto(true)}
            className="gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>Novo Colaborador</span>
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <div className="relative md:col-span-1">
          <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-3" />
          <Input
            placeholder="Buscar por nome, função, placa..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 h-10 bg-card"
          />
        </div>

        <div className="flex items-center gap-2 md:col-span-2 flex-wrap">
          <div className="flex items-center gap-1 bg-card p-1 rounded-xl border border-border">
            {(['todos', 'presente', 'falta', 'substituto'] as const).map((st) => (
              <button
                key={st}
                type="button"
                onClick={() => setFilterStatus(st)}
                className={cn(
                  'px-3 py-1.5 rounded-lg text-xs font-semibold capitalize transition-all cursor-pointer',
                  filterStatus === st
                    ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/40'
                    : 'text-muted-foreground hover:text-foreground'
                )}
              >
                {st}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-1 bg-card p-1 rounded-xl border border-border">
            {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
              <button
                key={reg}
                type="button"
                onClick={() => setFilterRegional(reg)}
                className={cn(
                  'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all cursor-pointer',
                  filterRegional === reg
                    ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/40'
                    : 'text-muted-foreground hover:text-foreground'
                )}
              >
                {reg === 'todas' ? 'Todas' : regionalLabel[reg]}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
        {colaboradoresFiltrados.map((c) => {
          const cfg = statusConfig[c.status] || statusConfig.presente;
          return (
            <Card key={c.id} className="p-4 bg-card/80 border-border/80 hover:border-emerald-500/40 transition-all">
              <div className="flex items-start gap-3">
                <div
                  onClick={() => c.foto && setFotoModalAberta({ url: c.foto, nome: c.nome, cargo: c.cargo })}
                  className={cn(
                    'w-14 h-14 rounded-2xl bg-muted border border-border/80 overflow-hidden flex items-center justify-center shrink-0 relative group shadow-sm',
                    c.foto ? 'cursor-pointer' : ''
                  )}
                >
                  {c.foto ? (
                    <img src={c.foto} alt={c.nome} className="w-full h-full object-cover" />
                  ) : (
                    <span className="font-bold text-sm text-muted-foreground">{getIniciais(c.nome)}</span>
                  )}
                  {c.foto && (
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Eye className="w-4 h-4 text-white" />
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-1">
                    <h4 className="font-bold text-sm text-foreground truncate">{c.nome}</h4>
                    <span className={cn('text-[10px] font-bold px-2 py-0.5 rounded-full border', cfg.className)}>
                      {cfg.label}
                    </span>
                  </div>

                  <p className="text-xs text-muted-foreground truncate mt-0.5">{c.cargo}</p>

                  <div className="mt-2.5 space-y-1 text-[11px] text-muted-foreground">
                    <div className="flex items-center gap-1.5">
                      <Building2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                      <span className="truncate">{c.unidade}</span>
                    </div>

                    <div className="flex items-center gap-1.5">
                      <Phone className="w-3.5 h-3.5 text-teal-400 shrink-0" />
                      <span className="tabular-nums">{c.telefone || 'Sem telefone'}</span>
                    </div>

                    {c.dataAdmissao && (
                      <div className="flex items-center gap-1.5">
                        <CalendarDays className="w-3.5 h-3.5 text-amber-400 shrink-0" />
                        <span className="tabular-nums">Admissão: {c.dataAdmissao}</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      {fotoModalAberta && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in">
          <div className="relative max-w-sm w-full bg-card p-4 rounded-2xl border border-border shadow-2xl text-center space-y-3">
            <button
              type="button"
              onClick={() => setFotoModalAberta(null)}
              className="absolute top-3 right-3 p-1 rounded-lg text-muted-foreground hover:bg-muted cursor-pointer"
            >
              <X className="w-5 h-5" />
            </button>
            <div className="w-48 h-48 mx-auto rounded-2xl overflow-hidden border border-border/80 shadow-md">
              <img src={fotoModalAberta.url} alt={fotoModalAberta.nome} className="w-full h-full object-cover" />
            </div>
            <div>
              <h3 className="font-bold text-base text-foreground">{fotoModalAberta.nome}</h3>
              <p className="text-xs text-muted-foreground">{fotoModalAberta.cargo}</p>
            </div>
          </div>
        </div>
      )}

      {modalNovoAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in">
          <div className="relative max-w-md w-full bg-card p-6 rounded-2xl border border-border shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b border-border/50 pb-3">
              <h3 className="font-bold text-base text-foreground flex items-center gap-2">
                <Plus className="w-4 h-4 text-emerald-400" />
                Cadastrar Colaborador
              </h3>
              <button
                type="button"
                onClick={() => setModalNovoAberto(false)}
                className="p-1 rounded-lg text-muted-foreground hover:bg-muted cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCadastrarColaborador} className="space-y-3 text-xs">
              <div>
                <label className="block font-medium text-foreground mb-1">Nome Completo</label>
                <Input
                  required
                  placeholder="Ex: João da Silva"
                  value={novoNome}
                  onChange={(e) => setNovoNome(e.target.value)}
                />
              </div>

              <div>
                <label className="block font-medium text-foreground mb-1">Cargo / Função</label>
                <Input
                  placeholder="Ex: Operador de Máquinas Florestais"
                  value={novoCargo}
                  onChange={(e) => setNovoCargo(e.target.value)}
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="block font-medium text-foreground mb-1">Unidade</label>
                  <select
                    value={novaUnidade}
                    onChange={(e) => setNovaUnidade(e.target.value as 'ribas' | 'agua_clara')}
                    className="w-full h-10 px-3 rounded-xl border border-input bg-card text-xs text-foreground"
                  >
                    <option value="ribas">Ribas do Rio Pardo</option>
                    <option value="agua_clara">Água Clara</option>
                  </select>
                </div>

                <div>
                  <label className="block font-medium text-foreground mb-1">Data Admissão</label>
                  <Input
                    placeholder="DD/MM/AAAA"
                    value={novaDataAdmissao}
                    onChange={(e) => setNovaDataAdmissao(e.target.value)}
                  />
                </div>
              </div>

              <div>
                <label className="block font-medium text-foreground mb-1">Telefone</label>
                <Input
                  placeholder="(67) 99999-0000"
                  value={novoTelefone}
                  onChange={(e) => setNovoTelefone(e.target.value)}
                />
              </div>

              <div>
                <label className="block font-medium text-foreground mb-1">Foto (Opcional)</label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFotoUpload}
                  className="w-full text-xs text-muted-foreground file:mr-2 file:py-1 file:px-2 file:rounded-lg file:border-0 file:bg-emerald-500/15 file:text-emerald-300 hover:file:bg-emerald-500/25"
                />
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-border/50">
                <Button type="button" variant="outline" size="sm" onClick={() => setModalNovoAberto(false)}>
                  Cancelar
                </Button>
                <Button type="submit" size="sm" className="bg-emerald-600 hover:bg-emerald-500 text-white">
                  Salvar
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {modalExcelAberto && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/85 backdrop-blur-sm animate-in fade-in">
          <div className="relative max-w-xl w-full bg-card p-6 rounded-2xl border border-border shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b border-border/50 pb-3">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center">
                  <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
                </div>
                <div>
                  <h3 className="font-bold text-base text-foreground">Subir Planilha de Colaboradores</h3>
                  <p className="text-xs text-muted-foreground">Importe múltiplos registros via arquivo Excel ou CSV</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalExcelAberto(false)}
                className="p-1 rounded-lg text-muted-foreground hover:bg-muted cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-3 text-xs">
              <div className="p-3 rounded-xl border border-dashed border-border/80 bg-muted/20 text-center space-y-2">
                <FileUp className="w-8 h-8 text-emerald-400 mx-auto" />
                <p className="font-medium text-foreground">Selecione seu arquivo .xlsx, .xls ou .csv</p>
                <p className="text-[11px] text-muted-foreground">
                  Colunas suportadas: Nome, Função/Cargo, Unidade, Data de Admissão, Telefone
                </p>
                <input
                  ref={excelInputRef}
                  type="file"
                  accept=".csv, .xlsx, .xls, .txt"
                  onChange={handleArquivoPlanilhaChange}
                  className="block mx-auto text-xs text-muted-foreground file:mr-2 file:py-1.5 file:px-3 file:rounded-xl file:border-0 file:bg-emerald-600 file:text-white cursor-pointer"
                />
              </div>

              {isProcessandoExcel && (
                <div className="flex items-center justify-center gap-2 py-4 text-emerald-400">
                  <Loader2 className="w-5 h-5 animate-spin" />
                  <span>Processando planilha...</span>
                </div>
              )}

              {excelErro && (
                <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-300 text-xs">
                  {excelErro}
                </div>
              )}

              {excelImportSucesso && (
                <div className="p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-300 text-xs flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4" />
                  <span>Colaboradores importados com sucesso!</span>
                </div>
              )}

              {excelPreview.length > 0 && !excelImportSucesso && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-foreground">Pré-visualização ({excelPreview.length} encontrados)</span>
                    <span className="text-[11px] text-muted-foreground">{excelArquivoNome}</span>
                  </div>
                  <div className="max-h-48 overflow-y-auto rounded-xl border border-border p-2 space-y-1">
                    {excelPreview.slice(0, 15).map((col, idx) => (
                      <div key={idx} className="flex items-center justify-between p-1.5 rounded-lg bg-card text-[11px]">
                        <div>
                          <span className="font-semibold text-foreground">{col.nome}</span>
                          <span className="text-muted-foreground ml-2">({col.cargo})</span>
                        </div>
                        <span className="text-muted-foreground">{col.unidade}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className="flex items-center justify-between pt-3 border-t border-border/50">
                <button
                  type="button"
                  onClick={downloadModeloCSV}
                  className="text-xs text-emerald-400 hover:underline flex items-center gap-1 cursor-pointer"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar modelo de exemplo
                </button>

                <div className="flex gap-2">
                  <Button type="button" variant="outline" size="sm" onClick={() => setModalExcelAberto(false)}>
                    Cancelar
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    disabled={excelPreview.length === 0 || isProcessandoExcel}
                    onClick={handleConfirmarImportacao}
                    className="bg-emerald-600 hover:bg-emerald-500 text-white"
                  >
                    Confirmar Importação
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

