export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(new Date().getMonth());

  // Coleta TODOS os faltosos do dia em TODAS as unidades (sem restrição de regional)
  const faltososDoDia = useMemo(() => {
    const faltas: Array<{
      colaborador: Colaborador;
      veiculoPrefixo: string;
      veiculoPlaca: string;
      regional: string;
      unidade: string;
    }> = [];

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ];
      assentos.forEach((c) => {
        if (c && c.status === 'falta') {
          faltas.push({
            colaborador: c,
            veiculoPrefixo: v.prefixo || 'N/D',
            veiculoPlaca: v.placa || 'N/D',
            regional: v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
            unidade: c.unidade || (v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'),
          });
        }
      });
    });

    (colaboradoresReserva || []).forEach((c) => {
      if (c && c.status === 'falta') {
        faltas.push({
          colaborador: c,
          veiculoPrefixo: 'Banco de Reserva',
          veiculoPlaca: '-',
          regional: 'Ribas do Rio Pardo',
          unidade: c.unidade || 'Ribas do Rio Pardo',
        });
      }
    });

    return faltas;
  }, [veiculos, colaboradoresReserva]);

  // Total de ausentes agrupados por unidade
  const faltasPorUnidade = useMemo(() => {
    const agrupado: Record<string, number> = {};
    faltososDoDia.forEach((f) => {
      agrupado[f.unidade] = (agrupado[f.unidade] || 0) + 1;
    });
    return agrupado;
  }, [faltososDoDia]);

  const dadosMes = useMemo(() => {
    const mesObj = HISTORICO_MENSAL_FALTAS.find((m) => m.mesIndex === mesSelecionado);
    return mesObj?.faltas || [];
  }, [mesSelecionado]);

  // Função de Impressão Direta: foca EXCLUSIVAMENTE nas pessoas que faltaram no dia de todas as unidades
  const handleImprimirRelatorioFaltas = () => {
    window.print();
  };

  const exportarCSVFaltasDia = () => {
    const dataStr = selectedDate.toLocaleDateString('pt-BR');
    const header = ['Nome do Colaborador', 'Função / Cargo', 'Unidade', 'Data de Admissão', 'Veículo / Prefixo', 'Motivo da Falta', 'Observações'];
    const rows = faltososDoDia.map((f) => [
      `"${f.colaborador.nome}"`,
      `"${f.colaborador.cargo}"`,
      `"${f.unidade}"`,
      `"${f.colaborador.dataAdmissao || 'Não informada'}"`,
      `"${f.veiculoPrefixo} (${f.veiculoPlaca})"`,
      `"${f.colaborador.motivoFalta || 'Não especificado'}"`,
      `"${f.colaborador.observacao || '-'}"`,
    ]);

    const csvContent = '\uFEFF' + [header.join(';'), ...rows.map((r) => r.join(';'))].join('\r\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `relatorio_faltas_diarias_${dataStr.replace(/\//g, '-')}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full space-y-6">
      {/* =========================================================================
          SEÇÃO EXCLUSIVA DE IMPRESSÃO (visível unicamente em @media print)
          Mostra APENAS as pessoas que faltaram no dia de TODAS as unidades
         ========================================================================= */}
      <div className="hidden print:block text-black bg-white p-6 font-sans">
        <div className="border-b-2 border-black pb-4 mb-4">
          <div className="flex justify-between items-start">
            <div>
              <h1 className="text-xl font-bold uppercase tracking-tight text-black">
                Relatório Operacional de Faltas Diárias
              </h1>
              <p className="text-xs text-gray-700 font-semibold mt-0.5">
                Consolidado Geral — Todas as Unidades (Ribas do Rio Pardo & Água Clara)
              </p>
            </div>
            <div className="text-right">
              <p className="text-xs font-bold text-black">
                Data de Referência: {selectedDate.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' })}
              </p>
              <p className="text-[10px] text-gray-600 mt-0.5">
                Emissão: {new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
          <div className="mt-3 flex gap-6 text-xs text-black border-t border-gray-300 pt-2">
            <span><strong>Total de Ausências no Dia:</strong> {faltososDoDia.length} colaborador(es)</span>
            {Object.entries(faltasPorUnidade).map(([unidade, total]) => (
              <span key={unidade}><strong>{unidade}:</strong> {total} falta(s)</span>
            ))}
          </div>
        </div>

        {faltososDoDia.length === 0 ? (
          <div className="p-8 text-center border border-gray-300 rounded text-sm text-gray-700">
            Nenhuma ausência registrada nesta data em nenhuma das unidades operacionais.
          </div>
        ) : (
          <table className="w-full text-left text-xs border-collapse">
            <thead>
              <tr className="border-b-2 border-black bg-gray-100">
                <th className="py-2 px-2 font-bold text-black">#</th>
                <th className="py-2 px-2 font-bold text-black">Nome do Colaborador</th>
                <th className="py-2 px-2 font-bold text-black">Função / Cargo</th>
                <th className="py-2 px-2 font-bold text-black">Unidade</th>
                <th className="py-2 px-2 font-bold text-black">Data Admissão</th>
                <th className="py-2 px-2 font-bold text-black">Veículo / Prefixo</th>
                <th className="py-2 px-2 font-bold text-black">Motivo da Ausência</th>
                <th className="py-2 px-2 font-bold text-black">Observações</th>
              </tr>
            </thead>
            <tbody>
              {faltososDoDia.map((item, index) => (
                <tr key={item.colaborador.id || index} className="border-b border-gray-200">
                  <td className="py-2 px-2 font-semibold text-gray-600">{index + 1}</td>
                  <td className="py-2 px-2 font-bold text-black">{item.colaborador.nome}</td>
                  <td className="py-2 px-2 text-gray-800">{item.colaborador.cargo}</td>
                  <td className="py-2 px-2 font-semibold text-gray-900">{item.unidade}</td>
                  <td className="py-2 px-2 text-gray-700">{item.colaborador.dataAdmissao || '-'}</td>
                  <td className="py-2 px-2 text-gray-800 font-mono text-[11px]">{item.veiculoPrefixo}</td>
                  <td className="py-2 px-2 font-medium text-black">{item.colaborador.motivoFalta || 'Falta Registrada'}</td>
                  <td className="py-2 px-2 text-gray-600 italic text-[11px]">{item.colaborador.observacao || '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <div className="mt-8 pt-4 border-t border-gray-300 flex justify-between text-[11px] text-gray-600">
          <div>Assinatura do Supervisor de Campo: ___________________________</div>
          <div>Assinatura RH Florestal: ___________________________</div>
        </div>
      </div>

      {/* =========================================================================
          INTERFACE EM TELA (NÃO IMPRESSA)
         ========================================================================= */}
      <div className="print:hidden space-y-6">
        {/* Banner do Relatório de Faltas do Dia com Botão de Impressão */}
        <Card className="border-amber-500/30 bg-gradient-to-r from-card/90 via-card to-amber-950/20 shadow-xl overflow-hidden">
          <CardContent className="p-5 sm:p-6">
            <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
              <div className="space-y-1.5">
                <div className="flex items-center gap-2">
                  <div className="p-2 rounded-xl bg-rose-500/15 border border-rose-500/30 text-rose-400">
                    <UserX className="w-5 h-5" />
                  </div>
                  <h2 className="text-lg font-black tracking-tight text-foreground">
                    Modelo de Impressão — Faltas do Dia (Todas as Unidades)
                  </h2>
                </div>
                <p className="text-xs text-muted-foreground max-w-2xl">
                  O modelo oficial de impressão consolida estritamente os colaboradores ausentes no dia de todas as frentes de trabalho (Ribas do Rio Pardo e Água Clara), com dados cadastrais e motivos.
                </p>
                <div className="flex flex-wrap items-center gap-2 pt-1 text-xs">
                  <Badge variant="outline" className="border-rose-500/30 text-rose-400 bg-rose-500/10 font-bold">
                    {faltososDoDia.length} ausência(s) registrada(s) hoje
                  </Badge>
                  <span className="text-muted-foreground">·</span>
                  <span className="text-muted-foreground font-medium">
                    Data: {selectedDate.toLocaleDateString('pt-BR')}
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-2 w-full md:w-auto">
                <Button
                  type="button"
