                    <thead className="bg-muted/20 text-muted-foreground border-b border-border/40">
                      <tr>
                        <th className="py-2.5 px-3 font-semibold">Colaborador</th>
                        <th className="py-2.5 px-3 font-semibold">Função / Cargo</th>
                        <th className="py-2.5 px-3 font-semibold">Unidade</th>
                        <th className="py-2.5 px-3 font-semibold">Admissão</th>
                        <th className="py-2.5 px-3 font-semibold">Veículo</th>
                        <th className="py-2.5 px-3 font-semibold">Motivo</th>
                        <th className="py-2.5 px-3 font-semibold">Observações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-border/30">
                      {faltososDoDia.map((item, idx) => (
                        <tr key={item.colaborador.id || idx} className="hover:bg-muted/30 transition-colors">
                          <td className="py-2.5 px-3 font-bold text-foreground">{item.colaborador.nome}</td>
                          <td className="py-2.5 px-3 text-muted-foreground">{item.colaborador.cargo}</td>
                          <td className="py-2.5 px-3">
                            <span className="inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-medium bg-muted/60 border border-border/60 text-foreground">
                              {item.unidade}
                            </span>
                          </td>
                          <td className="py-2.5 px-3 text-muted-foreground font-mono">{item.colaborador.dataAdmissao || '-'}</td>
                          <td className="py-2.5 px-3 text-muted-foreground font-mono">{item.veiculoPrefixo}</td>
                          <td className="py-2.5 px-3">
                            <Badge variant="destructive" className="text-[10px] py-0 px-1.5 font-medium">
                              {item.colaborador.motivoFalta || 'Falta'}
                            </Badge>
                          </td>
                          <td className="py-2.5 px-3 text-muted-foreground italic text-[11px]">
                            {item.colaborador.observacao || '-'}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Histórico Mensal de Faltas */}
        <Card className="border-border/60 bg-card/60 backdrop-blur-md shadow-lg">
          <CardHeader className="pb-3">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
              <div>
                <CardTitle className="text-base flex items-center gap-2">
                  <BarChart3 className="w-5 h-5 text-emerald-400" />
                  Histórico Consolidado de Faltas Mensais
                </CardTitle>
                <CardDescription className="text-xs">
                  Acompanhamento de ausências acumuladas por colaborador e unidade
                </CardDescription>
              </div>

              {/* Seletor de Mês */}
              <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
                <select
                  value={mesSelecionado}
                  onChange={(e) => setMesSelecionado(Number(e.target.value))}
                  className="h-9 px-3 rounded-xl border border-input bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 font-medium"
                >
                  {MESES.map((nome, idx) => (
                    <option key={nome} value={idx}>
                      {nome}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </CardHeader>
          <CardContent className="pt-0">
            <div className="rounded-xl border border-border/60 overflow-hidden bg-card/40">
              <div className="overflow-x-auto">
                <table className="w-full text-xs text-left">
                  <thead className="bg-muted/40 text-muted-foreground border-b border-border/40">
                    <tr>
                      <th className="py-2.5 px-3 font-semibold">Nome do Colaborador</th>
                      <th className="py-2.5 px-3 font-semibold">Função / Cargo</th>
                      <th className="py-2.5 px-3 font-semibold">Unidade</th>
                      <th className="py-2.5 px-3 font-semibold">Data Admissão</th>
                      <th className="py-2.5 px-3 font-semibold text-center">Faltas no Mês</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/30">
                    {dadosMes.length === 0 ? (
                      <tr>
                        <td colSpan={5} className="py-6 text-center text-muted-foreground">
                          Nenhum registro para o mês selecionado.
                        </td>
                      </tr>
                    ) : (
                      dadosMes.map((row, idx) => (
                        <tr key={idx} className="hover:bg-muted/20 transition-colors">
                          <td className="py-2.5 px-3 font-bold text-foreground">{row.nome}</td>
                          <td className="py-2.5 px-3 text-muted-foreground">{row.funcao}</td>
                          <td className="py-2.5 px-3 text-foreground">{row.unidade}</td>
                          <td className="py-2.5 px-3 text-muted-foreground font-mono">{row.dataAdmissao}</td>
                          <td className="py-2.5 px-3 text-center">
                            <span className="inline-flex items-center justify-center min-w-6 h-6 px-1.5 rounded-full text-xs font-bold bg-rose-500/15 text-rose-400 border border-rose-500/30 tabular-nums">
                              {row.totalFaltas}
                            </span>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

