import React, { useState, useMemo } from 'react';
import {
  Download,
  Calendar,
  Users,
  Car,
  TrendingUp,
  CheckCircle2,
  Printer,
  FileSpreadsheet,
  AlertCircle,
  Clock,
  Filter,
  UserX,
  FileText,
  MapPin,
  Briefcase,
} from 'lucide-react';
import { Veiculo, Colaborador, Regional } from '../types';
import { Button } from './ui/button';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface ExportReportsProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedDate?: Date;
  selectedRegional?: Regional | string;
}

export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedDate = new Date(),
  selectedRegional = 'todas',
}) => {
  const [dataInicio, setDataInicio] = useState<string>(() => {
    const hoje = selectedDate instanceof Date && !isNaN(selectedDate.getTime()) ? selectedDate : new Date();
    return hoje.toISOString().split('T')[0];
  });
  const [dataFim, setDataFim] = useState<string>(() => {
    const hoje = selectedDate instanceof Date && !isNaN(selectedDate.getTime()) ? selectedDate : new Date();
    return hoje.toISOString().split('T')[0];
  });
  const [filtroRegional, setFiltroRegional] = useState<string>('todas');
  const [gerandoDownload, setGerandoDownload] = useState(false);

  // Consolidação de todos os colaboradores alocados e em reserva
  const todosColaboradores = useMemo(() => {
    const lista: Array<{
      colaborador: Colaborador;
      veiculo?: Veiculo;
      equipeCodigo?: string;
      regionalOrigem: 'ribas' | 'agua_clara' | string;
    }> = [];

    const jaInseridos = new Set<string>();

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        { c: v.assentos.motorista, eq: v.equipe1Codigo },
        { c: v.assentos.frenteDir, eq: v.equipe1Codigo },
        { c: v.assentos.trasEsq, eq: v.equipe2Codigo },
        { c: v.assentos.trasDir, eq: v.equipe2Codigo },
      ];

      assentos.forEach(({ c, eq }) => {
        if (c && c.id && !jaInseridos.has(c.id)) {
          jaInseridos.add(c.id);
          lista.push({
            colaborador: c,
            veiculo: v,
            equipeCodigo: eq,
            regionalOrigem: v.regional || 'ribas',
          });
        }
      });
    });

    (colaboradoresReserva || []).forEach((c) => {
      if (c && c.id && !jaInseridos.has(c.id)) {
        jaInseridos.add(c.id);
        lista.push({
          colaborador: c,
          veiculo: undefined,
          equipeCodigo: 'Banco Reserva',
          regionalOrigem: c.unidade === 'Água Clara' ? 'agua_clara' : 'ribas',
        });
      }
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  // Lista EXCLUSIVA de faltas de TODAS as unidades para impressão e auditoria
  const listaFaltasGeral = useMemo(() => {
    return todosColaboradores.filter(
      (item) => item.colaborador?.status === 'falta'
    );
  }, [todosColaboradores]);

  // Métricas gerais de presença do dia
  const metricasGerais = useMemo(() => {
    const total = todosColaboradores.length;
    const presentes = todosColaboradores.filter((i) => i.colaborador.status === 'presente').length;
    const faltas = todosColaboradores.filter((i) => i.colaborador.status === 'falta').length;
    const substitutos = todosColaboradores.filter((i) => i.colaborador.status === 'substituto').length;
    const taxa = total > 0 ? Math.round(((presentes + substitutos) / total) * 100) : 100;

    return { total, presentes, faltas, substitutos, taxa };
  }, [todosColaboradores]);

  const dataFormatadaExtenso = useMemo(() => {
    try {
      const [ano, mes, dia] = dataInicio.split('-').map(Number);
      const dataObj = new Date(ano, mes - 1, dia, 12, 0, 0);
      return dataObj.toLocaleDateString('pt-BR', {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric',
      });
    } catch {
      return dataInicio;
    }
  }, [dataInicio]);

  const horaEmissao = useMemo(() => {
    return new Date().toLocaleTimeString('pt-BR', {
      hour: '2-digit',
      minute: '2-digit',
    });
  }, []);

  const handleImprimir = () => {
    window.print();
  };

  const handleExportarExcelCSV = () => {
    setGerandoDownload(true);
    try {
      const colunas = [
        'Data',
        'Nome Completo',
        'Unidade Regional',
        'Função / Cargo',
        'Matrícula',
        'Data de Admissão',
        'Status de Presença',
        'Motivo Ausência',
        'Veículo Prefixo',
        'Placa',
        'Equipe',
        'Observações',
      ];

      const linhas = listaFaltasGeral.map((item) => {
        const c = item.colaborador;
        const v = item.veiculo;
        const unidadeTexto =
          item.regionalOrigem === 'ribas'
            ? 'Ribas do Rio Pardo'
            : item.regionalOrigem === 'agua_clara'
            ? 'Água Clara'
            : c.unidade || 'Não informada';

        return [
          dataInicio,
          `"${(c.nome || '').replace(/"/g, '""')}"`,
          `"${unidadeTexto}"`,
          `"${(c.cargo || '').replace(/"/g, '""')}"`,
          `"${c.matricula || '-'}"`,
          `"${c.dataAdmissao || '-'}"`,
          'FALTA',
          `"${(c.motivoFalta || 'Não especificado').replace(/"/g, '""')}"`,
          `"${v?.prefixo || '-'}"`,
          `"${v?.placa || '-'}"`,
          `"${item.equipeCodigo || '-'}"`,
          `"${(c.observacao || '-').replace(/"/g, '""')}"`,
        ].join(';');
      });

      const csvContent = '\uFEFF' + [colunas.join(';'), ...linhas].join('\r\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute('download', `Relatorio_Faltas_Geral_${dataInicio}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Erro ao gerar relatório CSV:', err);
    } finally {
      setGerandoDownload(false);
    }
  };

  return (
    <div className="w-full space-y-6">
      {/* Estilos dedicados de impressão limpa A4 sem corte de texto */}
      <style dangerouslySetInnerHTML={{
        __html: `
          @media print {
            body {
              background: #ffffff !important;
              color: #0f172a !important;
              font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
              font-size: 11pt !important;
              margin: 0 !important;
              padding: 0 !important;
            }
            header, nav, .nao-imprimir {
              display: none !important;
            }
            .area-impressao {
              display: block !important;
              width: 100% !important;
              max-width: 100% !important;
              margin: 0 !important;
              padding: 10mm 12mm !important;
              background: #ffffff !important;
              color: #0f172a !important;
            }
            .bloco-folha {
              box-shadow: none !important;
              border: none !important;
              background: #ffffff !important;
              padding: 0 !important;
            }
            .tabela-impressao {
              width: 100% !important;
              border-collapse: collapse !important;
              table-layout: auto !important;
            }
            .tabela-impressao th, .tabela-impressao td {
              border: 1px solid #cbd5e1 !important;
              padding: 7px 10px !important;
              text-align: left !important;
              vertical-align: middle !important;
              white-space: normal !important;
              word-break: normal !important;
              overflow-wrap: break-word !important;
            }
            .tabela-impressao th {
              background-color: #f1f5f9 !important;
              color: #0f172a !important;
              font-weight: 700 !important;
              font-size: 10pt !important;
              text-transform: uppercase !important;
              letter-spacing: 0.03em !important;
            }
            .tabela-impressao td {
              font-size: 10pt !important;
              color: #1e293b !important;
            }
            .linha-par {
              background-color: #f8fafc !important;
            }
            .titulo-relatorio {
              font-size: 18pt !important;
              font-weight: 800 !important;
              color: #0f172a !important;
              margin-bottom: 4px !important;
            }
            .subtitulo-relatorio {
              font-size: 10pt !important;
              color: #475569 !important;
            }
            .badge-ausencia {
              display: inline-block !important;
              padding: 2px 6px !important;
              background-color: #fee2e2 !important;
              color: #991b1b !important;
              border: 1px solid #f87171 !important;
              border-radius: 4px !important;
              font-weight: 700 !important;
              font-size: 8.5pt !important;
              text-transform: uppercase !important;
            }
            .box-totalizador {
              border: 1px solid #cbd5e1 !important;
              background: #f8fafc !important;
              padding: 10px 14px !important;
              border-radius: 6px !important;
            }
            @page {
              size: A4 portrait;
              margin: 12mm 10mm;
            }
          }
        `,
      }} />

      {/* Painel de Controle e Ações (Ocultado na Impressora) */}
      <Card className="nao-imprimir border border-border/80 bg-card/75 backdrop-blur-md shadow-xl">
        <CardHeader className="pb-4 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
              <CardTitle className="text-lg font-bold flex items-center gap-2 text-foreground">
                <FileText className="w-5 h-5 text-emerald-400" />
                Relatório Oficial de Ausências e Faltas do Dia
              </CardTitle>
              <CardDescription className="text-xs text-muted-foreground mt-0.5">
                Consolidação unificada de todas as unidades operacionais (Ribas do Rio Pardo e Água Clara)
              </CardDescription>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <Button
                type="button"
                variant="outline"
                onClick={handleImprimir}
                className="gap-2 border-border/80 hover:bg-muted text-foreground font-semibold h-9 px-3.5"
              >
                <Printer className="w-4 h-4 text-emerald-400" />
                <span>Imprimir Relatório</span>
              </Button>

              <Button
                type="button"
                onClick={handleExportarExcelCSV}
                disabled={gerandoDownload || listaFaltasGeral.length === 0}
                className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-sm h-9 px-3.5"
              >
                <Download className="w-4 h-4" />
                <span>Exportar Planilha (CSV)</span>
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="pt-4 space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div>
              <label className="block text-xs font-semibold text-foreground mb-1.5 flex items-center gap-1.5">
                <Calendar className="w-3.5 h-3.5 text-emerald-400" />
                Data de Referência
              </label>
              <input
                type="date"
                value={dataInicio}
                onChange={(e) => {
                  setDataInicio(e.target.value);
                  setDataFim(e.target.value);
                }}
                className="w-full h-9 px-3 rounded-xl border border-input bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-foreground mb-1.5 flex items-center gap-1.5">
                <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                Escopo de Emissão
              </label>
              <div className="h-9 px-3 rounded-xl border border-border/60 bg-muted/30 text-xs text-foreground flex items-center justify-between font-medium">
                <span>Todas as Unidades Operacionais</span>
                <span className="text-[10px] font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                  Global
                </span>
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-foreground mb-1.5 flex items-center gap-1.5">
                <UserX className="w-3.5 h-3.5 text-rose-400" />
                Status do Relatório
              </label>
              <div className="h-9 px-3 rounded-xl border border-border/60 bg-muted/30 text-xs text-foreground flex items-center justify-between font-medium">
                <span>Faltas Registradas no Dia</span>
                <span className="text-xs font-bold text-rose-400 tabular-nums">
                  {listaFaltasGeral.length} ocorrência(s)
                </span>
              </div>
            </div>
          </div>

          {/* Cards Rápidos de Apoio */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 pt-2">
            <div className="rounded-xl border border-border/60 bg-card/40 p-3">
              <span className="text-[11px] text-muted-foreground block font-medium">Efetivo Monitorado</span>
              <span className="text-xl font-black text-foreground tabular-nums mt-0.5 block">
                {metricasGerais.total}
              </span>
            </div>

            <div className="rounded-xl border border-border/60 bg-card/40 p-3">
              <span className="text-[11px] text-emerald-400 block font-medium">Operadores Presentes</span>
              <span className="text-xl font-black text-emerald-400 tabular-nums mt-0.5 block">
                {metricasGerais.presentes}
              </span>
            </div>

            <div className="rounded-xl border border-rose-500/30 bg-rose-500/5 p-3">
              <span className="text-[11px] text-rose-400 block font-medium">Total de Faltas</span>
              <span className="text-xl font-black text-rose-400 tabular-nums mt-0.5 block">
                {listaFaltasGeral.length}
              </span>
            </div>

            <div className="rounded-xl border border-border/60 bg-card/40 p-3">
              <span className="text-[11px] text-muted-foreground block font-medium">Índice de Presença</span>
              <span className="text-xl font-black text-foreground tabular-nums mt-0.5 block">
                {metricasGerais.taxa}%
              </span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* ÁREA DE PRÉ-VISUALIZAÇÃO E IMPRESSÃO (Folha Limpa e Profissional) */}
      <div className="area-impressao bloco-folha rounded-2xl border border-border/80 bg-card p-6 sm:p-8 shadow-2xl space-y-6">
        {/* Cabeçalho da Folha de Impressão */}
        <div className="flex flex-col sm:flex-row sm:items-start justify-between pb-5 border-b border-border/60 gap-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="text-xs font-bold tracking-widest text-emerald-500 uppercase">
                Controle Operacional Florestal
              </span>
              <span className="text-xs text-muted-foreground">·</span>
              <span className="text-xs font-semibold text-muted-foreground uppercase">
                Consolidado Geral
              </span>
            </div>
            <h1 className="titulo-relatorio text-xl sm:text-2xl font-black text-foreground tracking-tight">
              Relatório Diário de Ausências e Faltas
            </h1>
            <p className="subtitulo-relatorio text-xs sm:text-sm text-muted-foreground capitalize">
              Referência: <span className="font-semibold text-foreground">{dataFormatadaExtenso}</span>
            </p>
          </div>

          <div className="box-totalizador text-left sm:text-right text-xs text-muted-foreground space-y-1 rounded-xl border border-border/60 bg-muted/20 p-3 shrink-0">
            <div>
              <span className="font-semibold text-foreground">Data/Hora de Emissão:</span>{' '}
              <span className="tabular-nums font-medium text-foreground">{dataInicio.split('-').reverse().join('/')} às {horaEmissao}</span>
            </div>
            <div>
              <span className="font-semibold text-foreground">Abrangência:</span>{' '}
              <span className="font-medium text-foreground">Ribas do Rio Pardo & Água Clara</span>
            </div>
            <div>
              <span className="font-semibold text-rose-500">Total de Faltas no Dia:</span>{' '}
              <span className="font-bold text-rose-500 tabular-nums text-sm">{listaFaltasGeral.length}</span>
            </div>
          </div>
        </div>

        {/* Tabela Limpa, sem Cortes e com Largura Confortável para Nomes */}
        {listaFaltasGeral.length === 0 ? (
          <div className="py-12 px-4 text-center rounded-2xl border border-dashed border-emerald-500/30 bg-emerald-500/5 space-y-3">
            <div className="w-12 h-12 rounded-full bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center mx-auto text-emerald-400">
              <CheckCircle2 className="w-6 h-6" />
            </div>
            <h3 className="text-base font-bold text-foreground">100% de Presença Registrada</h3>
            <p className="text-xs text-muted-foreground max-w-md mx-auto">
              Nenhuma ausência ou falta cadastrada para as unidades operacionais na data selecionada ({dataInicio.split('-').reverse().join('/')}).
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="overflow-x-auto rounded-xl border border-border/80">
              <table className="tabela-impressao w-full text-left border-collapse">
                <thead>
                  <tr className="bg-muted/40 border-b border-border/80 text-[11px] font-bold text-foreground uppercase tracking-wider">
                    <th className="py-3 px-4 min-w-[36px] w-[40px] text-center">#</th>
                    {/* Largura ampla e flexível sem truncate para nunca cortar nomes longos */}
                    <th className="py-3 px-4 min-w-[240px] w-auto">Nome do Colaborador</th>
                    <th className="py-3 px-4 min-w-[130px] w-[150px]">Unidade</th>
                    <th className="py-3 px-4 min-w-[150px] w-[180px]">Função / Cargo</th>
                    <th className="py-3 px-4 min-w-[110px] w-[120px]">Matrícula</th>
                    <th className="py-3 px-4 min-w-[100px] w-[110px]">Admissão</th>
                    <th className="py-3 px-4 min-w-[150px] w-[180px]">Motivo Informado</th>
                    <th className="py-3 px-4 min-w-[90px] w-[100px] text-center">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/60 text-xs">
                  {listaFaltasGeral.map((item, idx) => {
                    const c = item.colaborador;
                    const unidadeNome =
                      item.regionalOrigem === 'ribas'
                        ? 'Ribas do Rio Pardo'
                        : item.regionalOrigem === 'agua_clara'
                        ? 'Água Clara'
                        : c.unidade || 'Unidade Geral';

                    return (
                      <tr
                        key={c.id || idx}
                        className={cn(
                          'hover:bg-muted/20 transition-colors',
                          idx % 2 === 1 ? 'linha-par bg-muted/10' : 'bg-transparent'
                        )}
                      >
                        <td className="py-2.5 px-4 text-center font-bold text-muted-foreground tabular-nums">
                          {idx + 1}
                        </td>

                        {/* Nome do Colaborador com quebra natural de linha (sem truncate, sem cortes) */}
                        <td className="py-2.5 px-4 font-bold text-foreground">
                          <span className="block leading-relaxed break-words text-sm sm:text-xs">
                            {c.nome}
                          </span>
                        </td>

                        {/* Unidade */}
                        <td className="py-2.5 px-4 text-muted-foreground whitespace-normal break-words">
                          <span className="font-medium text-foreground">{unidadeNome}</span>
                        </td>

                        {/* Função / Cargo */}
                        <td className="py-2.5 px-4 text-muted-foreground whitespace-normal break-words">
                          {c.cargo || 'Operador Florestal'}
                        </td>

                        {/* Matrícula */}
                        <td className="py-2.5 px-4 tabular-nums text-muted-foreground font-mono text-[11px]">
                          {c.matricula ? c.matricula : '—'}
                        </td>

                        {/* Data de Admissão */}
                        <td className="py-2.5 px-4 tabular-nums text-muted-foreground">
                          {c.dataAdmissao ? c.dataAdmissao : '—'}
                        </td>

                        {/* Motivo Informado */}
                        <td className="py-2.5 px-4 whitespace-normal break-words">
                          <span className="font-semibold text-rose-500">
                            {c.motivoFalta || 'Falta Não Justificada'}
                          </span>
                          {c.observacao && (
                            <span className="block text-[11px] text-muted-foreground mt-0.5 italic break-words">
                              Obs: {c.observacao}
                            </span>
                          )}
                        </td>

                        {/* Status */}
                        <td className="py-2.5 px-4 text-center">
                          <span className="badge-ausencia inline-flex items-center px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider bg-rose-500/15 text-rose-400 border border-rose-500/30">
                            Falta
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Rodapé institucional para impressão com campos de validação */}
            <div className="pt-8 mt-6 border-t border-border/60 grid grid-cols-2 sm:grid-cols-3 gap-6 text-center text-xs text-muted-foreground">
              <div className="space-y-10">
                <div className="border-b border-border/80 w-4/5 mx-auto" />
                <span>Supervisão Operacional de Campo</span>
              </div>
              <div className="space-y-10">
                <div className="border-b border-border/80 w-4/5 mx-auto" />
                <span>Coordenação de RH / Pessoal</span>
              </div>
              <div className="space-y-10 col-span-2 sm:col-span-1">
                <div className="border-b border-border/80 w-4/5 mx-auto" />
                <span>Gerência de Operações Florestais</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

