    return hoje.toISOString().split('T')[0];
  });
  const [gerandoDownload, setGerandoDownload] = useState(false);

  // Consolidação de todos os colaboradores alocados e em reserva
  const todosColaboradores = useMemo(() => {
    const lista: Array<{
      colaborador: Colaborador;
      veiculo?: Veiculo;
      regionalOrigem: 'ribas' | 'agua_clara' | string;
    }> = [];

    const jaInseridos = new Set<string>();

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        { c: v.assentos.motorista },
        { c: v.assentos.frenteDir },
        { c: v.assentos.trasEsq },
        { c: v.assentos.trasDir },
      ];

      assentos.forEach(({ c }) => {
        if (c && c.id && !jaInseridos.has(c.id)) {
          jaInseridos.add(c.id);
          lista.push({
            colaborador: c,
            veiculo: v,
            regionalOrigem: v.regional || 'ribas',
          });
        }
      });
    });

    (colaboradoresReserva || []).forEach((c) => {
      if (c && c.id && !jaInseridos.has(c.id)) {
        jaInseridos.add(c.id);
        lista.push({
          colaborador: c,
          veiculo: undefined,
          regionalOrigem: c.unidade === 'Água Clara' ? 'agua_clara' : 'ribas',
        });
      }
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  // Lista EXCLUSIVA de faltas de TODAS as unidades para impressão e auditoria
  const listaFaltasGeral = useMemo(() => {
    return todosColaboradores.filter(
      (item) => item.colaborador?.status === 'falta'
    );
  }, [todosColaboradores]);

  // Métricas gerais de presença do dia
  const metricasGerais = useMemo(() => {
    const total = todosColaboradores.length;
    const presentes = todosColaboradores.filter((i) => i.colaborador.status === 'presente').length;
    const faltas = todosColaboradores.filter((i) => i.colaborador.status === 'falta').length;
    const substitutos = todosColaboradores.filter((i) => i.colaborador.status === 'substituto').length;
    const taxa = total > 0 ? Math.round(((presentes + substitutos) / total) * 100) : 100;

    return { total, presentes, faltas, substitutos, taxa };
  }, [todosColaboradores]);

  const dataFormatadaExtenso = useMemo(() => {
    try {
      const [ano, mes, dia] = dataInicio.split('-').map(Number);
      const dataObj = new Date(ano, mes - 1, dia, 12, 0, 0);
      return dataObj.toLocaleDateString('pt-BR', {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric',
      });
    } catch {
      return dataInicio;
    }
  }, [dataInicio]);

  const horaEmissao = useMemo(() => {
    return new Date().toLocaleTimeString('pt-BR', {
      hour: '2-digit',
      minute: '2-digit',
    });
  }, []);

  const handleImprimir = () => {
    window.print();
  };

  const handleExportarExcelCSV = () => {
    setGerandoDownload(true);
    try {
      const colunas = [
        'Data',
        'Nome Completo',
        'Unidade Regional',
        'Função / Cargo',
        'Matrícula',
        'Data de Admissão',
        'Status de Presença',
        'Motivo da Falta',
        'Observações',
      ];

      const linhas = listaFaltasGeral.map((item) => {
        const c = item.colaborador;
        const unidadeTexto =
          item.regionalOrigem === 'ribas'
            ? 'Ribas do Rio Pardo'
            : item.regionalOrigem === 'agua_clara'
            ? 'Água Clara'
            : c.unidade || 'Não informada';

        return [
          dataInicio,
          `"${(c.nome || '').replace(/"/g, '""')}"`,
          `"${unidadeTexto}"`,
          `"${(c.cargo || '').replace(/"/g, '""')}"`,
          `"${c.matricula || '-'}"`,
          `"${c.dataAdmissao || '-'}"`,
          'FALTA',
          `"${(c.motivoFalta || 'Não informado').replace(/"/g, '""')}"`,
          `"${(c.observacao || '-').replace(/"/g, '""')}"`,
        ].join(';');
      });

      const csvContent = '\uFEFF' + [colunas.join(';'), ...linhas].join('\r\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute('download', `Relatorio_Faltas_Geral_${dataInicio}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Erro ao exportar CSV:', err);
    } finally {
      setGerandoDownload(false);
    }
  };

  return (
    <div className="w-full space-y-6">
      {/* CSS de impressão limpo e sem cortes */}
      <style dangerouslySetInnerHTML={{
        __html: `
          @media print {
            @page {
              size: A4 portrait;
              margin: 12mm 10mm;
            }
            body {
              background: #ffffff !important;
              color: #0f172a !important;
              font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
              font-size: 10pt !important;
              margin: 0 !important;
              padding: 0 !important;
              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }
            header, nav, .nao-imprimir, [data-sidebar], .btn-imprimir, .acoes-tela {
              display: none !important;
            }
            .area-impressao {
              display: block !important;
              width: 100% !important;
              max-width: 100% !important;
              margin: 0 !important;
              padding: 0 !important;
              background: #ffffff !important;
              color: #0f172a !important;
            }
            .bloco-folha {
              box-shadow: none !important;
              border: none !important;
              background: #ffffff !important;
              padding: 0 !important;
            }
            .tabela-impressao {
              width: 100% !important;
              border-collapse: collapse !important;
              margin-top: 12px !important;
              font-size: 9.5pt !important;
            }
            .tabela-impressao th {
              background-color: #f1f5f9 !important;
              color: #1e293b !important;
              font-weight: 700 !important;
              border: 1px solid #cbd5e1 !important;
              padding: 6px 8px !important;
              text-align: left !important;
              white-space: nowrap !important;
            }
            .tabela-impressao td {
              border: 1px solid #cbd5e1 !important;
              padding: 6px 8px !important;
              vertical-align: middle !important;
              color: #334155 !important;
            }
            .tabela-impressao tr:nth-child(even) td {
              background-color: #f8fafc !important;
            }
            .quebra-evitar {
              page-break-inside: avoid !important;
            }
          }
        `,
      }} />

      {/* Painel de Controle Superior na Tela */}
      <div className="nao-imprimir flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4 p-5 rounded-2xl border border-border/70 bg-card/60 backdrop-blur-md shadow-lg">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
            <FileText className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-base font-bold text-foreground">Relatório Diário de Ausências</h2>
            <p className="text-xs text-muted-foreground">
              Espelho oficial de faltas de todas as unidades operacionais para conferência e RH
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2 acoes-tela">
          <div className="flex items-center gap-2 px-3 py-1.5 rounded-xl border border-border/80 bg-background/80 text-xs">
            <Calendar className="w-3.5 h-3.5 text-muted-foreground" />
            <input
              type="date"
              value={dataInicio}
              onChange={(e) => setDataInicio(e.target.value)}
              className="bg-transparent border-none text-foreground font-medium text-xs focus:outline-none cursor-pointer"
            />
          </div>

          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleExportarExcelCSV}
            disabled={gerandoDownload}
            className="gap-2 text-xs font-semibold"
          >
            <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
            <span>Exportar CSV</span>
          </Button>

          <Button
            type="button"
            size="sm"
            onClick={handleImprimir}
            className="gap-2 bg-primary hover:bg-primary/90 text-primary-foreground text-xs font-semibold shadow-md btn-imprimir"
          >
            <Printer className="w-4 h-4" />
            <span>Imprimir Folha A4</span>
          </Button>
        </div>
      </div>

      {/* Resumo Rápido na Tela (Oculto na Impressão) */}
      <div className="nao-imprimir grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="p-4 rounded-xl border border-border/60 bg-card/40">
          <div className="flex items-center justify-between">
            <span className="text-xs text-muted-foreground font-medium">Efetivo Total</span>
            <Users className="w-4 h-4 text-muted-foreground" />
          </div>
          <p className="text-2xl font-black text-foreground mt-2 tabular-nums">{metricasGerais.total}</p>
          <span className="text-[11px] text-muted-foreground">operadores registrados</span>
        </div>

        <div className="p-4 rounded-xl border border-emerald-500/20 bg-emerald-500/5">
          <div className="flex items-center justify-between">
            <span className="text-xs text-emerald-400 font-medium">Presentes</span>
            <CheckCircle2 className="w-4 h-4 text-emerald-400" />
          </div>
          <p className="text-2xl font-black text-emerald-300 mt-2 tabular-nums">{metricasGerais.presentes}</p>
          <span className="text-[11px] text-emerald-400/80">em campo hoje</span>
        </div>

        <div className="p-4 rounded-xl border border-rose-500/30 bg-rose-500/10">
          <div className="flex items-center justify-between">
            <span className="text-xs text-rose-400 font-bold">Total de Faltas</span>
            <UserX className="w-4 h-4 text-rose-400" />
          </div>
          <p className="text-2xl font-black text-rose-300 mt-2 tabular-nums">{listaFaltasGeral.length}</p>
          <span className="text-[11px] text-rose-400/80">todas as unidades</span>
        </div>

        <div className="p-4 rounded-xl border border-border/60 bg-card/40">
          <div className="flex items-center justify-between">
            <span className="text-xs text-muted-foreground font-medium">Taxa Operacional</span>
            <TrendingUp className="w-4 h-4 text-primary" />
          </div>
          <p className="text-2xl font-black text-foreground mt-2 tabular-nums">{metricasGerais.taxa}%</p>
          <span className="text-[11px] text-muted-foreground">adesão de escala</span>
        </div>
      </div>

      {/* ÁREA DE IMPRESSÃO (LIMPA, EXCLUSIVA DE AUSÊNCIAS, SEM COMPOSIÇÃO DE EQUIPE) */}
      <div className="area-impressao">
        <div className="bloco-folha rounded-2xl border border-border/80 bg-card/70 p-6 sm:p-8 shadow-xl">
          {/* Cabeçalho do Relatório Impresso */}
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between border-b-2 border-slate-300 dark:border-border pb-4 gap-4">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-xl bg-slate-900 text-white flex items-center justify-center font-black text-xl shrink-0 print:border print:border-slate-400">
                CF
              </div>
              <div>
                <h1 className="text-xl sm:text-2xl font-extrabold tracking-tight text-foreground print:text-black">
                  Relatório Geral de Faltas e Ausências
                </h1>
                <p className="text-xs font-semibold text-muted-foreground print:text-slate-600">
                  Consolidação Operacional Florestal · Todas as Unidades
                </p>
              </div>
            </div>

            <div className="text-right sm:text-right w-full sm:w-auto text-xs space-y-0.5 print:text-slate-700">
              <p className="font-bold text-foreground print:text-black capitalize">{dataFormatadaExtenso}</p>
              <p className="text-muted-foreground print:text-slate-500">
                Emissão: <span className="font-semibold text-foreground print:text-black">{horaEmissao}</span>
              </p>
              <div className="inline-block mt-1 px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-rose-500/15 text-rose-500 border border-rose-500/30 print:bg-slate-100 print:text-slate-800 print:border-slate-300">
                {listaFaltasGeral.length} {listaFaltasGeral.length === 1 ? 'Ausência Registrada' : 'Ausências Registradas'}
              </div>
            </div>
          </div>

          {/* Conteúdo Principal do Relatório */}
          {listaFaltasGeral.length === 0 ? (
            <div className="py-16 text-center space-y-3">
              <div className="w-12 h-12 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 flex items-center justify-center mx-auto">
                <CheckCircle2 className="w-6 h-6" />
              </div>
              <h3 className="text-base font-bold text-foreground print:text-black">Nenhuma Falta Registrada no Dia</h3>
              <p className="text-xs text-muted-foreground print:text-slate-600 max-w-sm mx-auto">
                Todas as unidades operacionais (Ribas do Rio Pardo e Água Clara) estão com 100% de presença ou substituições atendidas.
              </p>
            </div>
          ) : (
            <div className="mt-5 overflow-x-auto">
              <table className="tabela-impressao w-full text-left text-xs border-collapse">
                <thead>
                  <tr className="border-b border-border text-muted-foreground">
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">#</th>
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">Nome do Colaborador</th>
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">Unidade</th>
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">Função / Cargo</th>
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">Matrícula</th>
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">Data de Admissão</th>
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">Motivo da Ausência</th>
                    <th className="py-2.5 px-3 font-bold text-foreground print:text-slate-800">Observações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/60">
                  {listaFaltasGeral.map((item, idx) => {
                    const c = item.colaborador;
                    const unidadeNome =
                      item.regionalOrigem === 'ribas'
                        ? 'Ribas do Rio Pardo'
                        : item.regionalOrigem === 'agua_clara'
                        ? 'Água Clara'
                        : c.unidade || 'Não informada';

                    return (
                      <tr key={c.id || idx} className="quebra-evitar hover:bg-muted/30">
                        <td className="py-2.5 px-3 font-semibold text-muted-foreground print:text-slate-600 tabular-nums">
                          {idx + 1}
                        </td>
                        <td className="py-2.5 px-3 font-bold text-foreground print:text-black">
                          {c.nome || 'Não informado'}
                        </td>
                        <td className="py-2.5 px-3 text-muted-foreground print:text-slate-700 whitespace-nowrap">
                          {unidadeNome}
                        </td>
                        <td className="py-2.5 px-3 text-muted-foreground print:text-slate-700">
                          {c.cargo || '-'}
                        </td>
                        <td className="py-2.5 px-3 font-mono text-[11px] text-muted-foreground print:text-slate-600 tabular-nums">
                          {c.matricula || '-'}
                        </td>
                        <td className="py-2.5 px-3 text-muted-foreground print:text-slate-700 tabular-nums whitespace-nowrap">
                          {c.dataAdmissao || '-'}
                        </td>
                        <td className="py-2.5 px-3">
                          <span className="font-semibold text-rose-500 print:text-rose-700">
                            {c.motivoFalta || 'Falta Não Justificada'}
                          </span>
                        </td>
                        <td className="py-2.5 px-3 text-muted-foreground print:text-slate-600 italic">
                          {c.observacao || '-'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          {/* Rodapé da Folha Impressa com Assinaturas */}
          <div className="mt-12 pt-6 border-t border-slate-300 dark:border-border quebra-evitar">
            <div className="grid grid-cols-2 gap-8 text-center text-xs">
              <div>
                <div className="w-56 mx-auto border-b border-slate-400 dark:border-border h-10 mb-2"></div>
                <p className="font-bold text-foreground print:text-black">Supervisor de Campo / Operações</p>
                <p className="text-[11px] text-muted-foreground print:text-slate-500">Assinatura do Responsável</p>
              </div>
              <div>
                <div className="w-56 mx-auto border-b border-slate-400 dark:border-border h-10 mb-2"></div>
                <p className="font-bold text-foreground print:text-black">Recursos Humanos / Departamento Pessoal</p>
                <p className="text-[11px] text-muted-foreground print:text-slate-500">Conferência e Lançamento</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

