                <span className="text-lg font-bold text-slate-800 tabular-nums">{metricasGerais.total}</span>
              </div>
              <div className="bg-emerald-50/70 p-2.5 rounded-lg border border-emerald-200/80">
                <span className="text-[11px] font-semibold text-emerald-700 uppercase tracking-wide block">Presentes</span>
                <span className="text-lg font-bold text-emerald-700 tabular-nums">{metricasGerais.presentes}</span>
              </div>
              <div className="bg-rose-50/70 p-2.5 rounded-lg border border-rose-200/80">
                <span className="text-[11px] font-semibold text-rose-700 uppercase tracking-wide block">Faltas no Dia</span>
                <span className="text-lg font-bold text-rose-700 tabular-nums">{listaFaltasGeral.length}</span>
              </div>
              <div className="bg-blue-50/70 p-2.5 rounded-lg border border-blue-200/80">
                <span className="text-[11px] font-semibold text-blue-700 uppercase tracking-wide block">Taxa Presença</span>
                <span className="text-lg font-bold text-blue-700 tabular-nums">{metricasGerais.taxa}%</span>
              </div>
            </div>
          </div>

          {/* Lista de Faltas - Tabela Limpa e com Espaço Adequado para Nomes */}
          {listaFaltasGeral.length === 0 ? (
            <div className="text-center py-12 border border-dashed border-slate-200 rounded-xl bg-slate-50/50 my-4">
              <CheckCircle2 className="w-10 h-10 text-emerald-500 mx-auto mb-2" />
              <h3 className="text-base font-bold text-slate-800">Nenhuma Falta Registrada</h3>
              <p className="text-xs text-slate-500 max-w-sm mx-auto mt-1">
                Todas as frentes de trabalho registraram 100% de assiduidade ou substituições devidamente preenchidas nesta data.
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto my-3">
              <table className="tabela-impressao w-full text-left">
                <thead>
                  <tr>
                    <th style={{ width: '40px' }} className="text-center">#</th>
                    <th style={{ minWidth: '220px' }}>Nome do Colaborador</th>
                    <th style={{ minWidth: '130px' }}>Unidade</th>
                    <th style={{ minWidth: '160px' }}>Função</th>
                    <th style={{ minWidth: '85px' }}>Matrícula</th>
                    <th style={{ minWidth: '140px' }}>Motivo da Falta</th>
                    <th style={{ minWidth: '140px' }}>Observações</th>
                  </tr>
                </thead>
                <tbody>
                  {listaFaltasGeral.map((item, index) => {
                    const c = item.colaborador;
                    const unidadeNome =
                      item.regionalOrigem === 'ribas'
                        ? 'Ribas do Rio Pardo'
                        : item.regionalOrigem === 'agua_clara'
                        ? 'Água Clara'
                        : c.unidade || 'Ribas do Rio Pardo';

                    return (
                      <tr key={c.id || index} className="quebra-evitar">
                        <td className="text-center font-semibold text-slate-400 tabular-nums text-xs">
                          {index + 1}
                        </td>
                        <td className="font-semibold text-slate-900 leading-snug">
                          {c.nome}
                        </td>
                        <td className="text-slate-700 font-medium">
                          {unidadeNome}
                        </td>
                        <td className="text-slate-700">
                          {c.cargo || 'Operador Florestal'}
                        </td>
                        <td className="text-slate-600 font-mono text-xs tabular-nums">
                          {c.matricula || '-'}
                        </td>
                        <td className="text-rose-700 font-medium">
                          {c.motivoFalta || 'Não Informado'}
                        </td>
                        <td className="text-slate-500 text-xs italic">
                          {c.observacao || '-'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          {/* Rodapé Limpo de Identificação e Controle */}
          <div className="border-t border-slate-200 mt-6 pt-3 flex flex-col sm:flex-row items-center justify-between gap-2 text-[11px] text-slate-500">
            <div>
              <span>Sistema de Controle de Faltas Operacionais</span>
              <span className="mx-1.5">•</span>
              <span>Registro de Campo e Alocação</span>
            </div>
            <div className="tabular-nums">
              Total de registros: {listaFaltasGeral.length} colaboradores
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

