}) => {
  const [dataInicio, setDataInicio] = useState<string>(() => {
    const hoje = selectedDate instanceof Date && !isNaN(selectedDate.getTime()) ? selectedDate : new Date();
    return hoje.toISOString().split('T')[0];
  });
  const [gerandoDownload, setGerandoDownload] = useState(false);

  // Consolidação de todos os colaboradores alocados e em reserva
  const todosColaboradores = useMemo(() => {
    const lista: Array<{
      colaborador: Colaborador;
      veiculo?: Veiculo;
      regionalOrigem: 'ribas' | 'agua_clara' | string;
    }> = [];

    const jaInseridos = new Set<string>();

    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        { c: v.assentos.motorista },
        { c: v.assentos.frenteDir },
        { c: v.assentos.trasEsq },
        { c: v.assentos.trasDir },
      ];

      assentos.forEach(({ c }) => {
        if (c && c.id && !jaInseridos.has(c.id)) {
          jaInseridos.add(c.id);
          lista.push({
            colaborador: c,
            veiculo: v,
            regionalOrigem: v.regional || 'ribas',
          });
        }
      });
    });

    (colaboradoresReserva || []).forEach((c) => {
      if (c && c.id && !jaInseridos.has(c.id)) {
        jaInseridos.add(c.id);
        lista.push({
          colaborador: c,
          veiculo: undefined,
          regionalOrigem: c.unidade === 'Água Clara' ? 'agua_clara' : 'ribas',
        });
      }
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  // Lista EXCLUSIVA de faltas de TODAS as unidades para impressão e auditoria
  const listaFaltasGeral = useMemo(() => {
    return todosColaboradores.filter(
      (item) => item.colaborador?.status === 'falta'
    );
  }, [todosColaboradores]);

  // Métricas gerais de presença do dia
  const metricasGerais = useMemo(() => {
    const total = todosColaboradores.length;
    const presentes = todosColaboradores.filter((i) => i.colaborador.status === 'presente').length;
    const faltas = todosColaboradores.filter((i) => i.colaborador.status === 'falta').length;
    const substitutos = todosColaboradores.filter((i) => i.colaborador.status === 'substituto').length;
    const taxa = total > 0 ? Math.round(((presentes + substitutos) / total) * 100) : 100;

    return { total, presentes, faltas, substitutos, taxa };
  }, [todosColaboradores]);

  const dataFormatadaExtenso = useMemo(() => {
    try {
      const [ano, mes, dia] = dataInicio.split('-').map(Number);
      const dataObj = new Date(ano, mes - 1, dia, 12, 0, 0);
      return dataObj.toLocaleDateString('pt-BR', {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric',
      });
    } catch {
      return dataInicio;
    }
  }, [dataInicio]);

  const horaEmissao = useMemo(() => {
    return new Date().toLocaleTimeString('pt-BR', {
      hour: '2-digit',
      minute: '2-digit',
    });
  }, []);

  const handleImprimir = () => {
    window.print();
  };

  const handleExportarExcelCSV = () => {
    setGerandoDownload(true);
    try {
      const colunas = [
        'Data',
        'Nome Completo',
        'Unidade Regional',
        'Função / Cargo',
        'Matrícula',
        'Data de Admissão',
        'Status de Presença',
        'Motivo da Falta',
        'Observações',
      ];

      const linhas = listaFaltasGeral.map((item) => {
        const c = item.colaborador;
        const unidadeTexto =
          item.regionalOrigem === 'ribas'
            ? 'Ribas do Rio Pardo'
            : item.regionalOrigem === 'agua_clara'
            ? 'Água Clara'
            : c.unidade || 'Não informada';

        return [
          dataInicio,
          `"${(c.nome || '').replace(/"/g, '""')}"`,
          `"${unidadeTexto}"`,
          `"${(c.cargo || '').replace(/"/g, '""')}"`,
          `"${c.matricula || '-'}"`,
          `"${c.dataAdmissao || '-'}"`,
          'FALTA',
          `"${(c.motivoFalta || 'Não informado').replace(/"/g, '""')}"`,
          `"${(c.observacao || '-').replace(/"/g, '""')}"`,
        ].join(';');
      });

      const csvContent = '\uFEFF' + [colunas.join(';'), ...linhas].join('\r\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute('download', `Relatorio_Faltas_Geral_${dataInicio}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Erro ao exportar CSV:', err);
    } finally {
      setGerandoDownload(false);
    }
  };

  return (
    <div className="w-full space-y-6">
      {/* Estilos dedicados para impressão limpa, sem cortes de texto e sem quadros desnecessários */}
      <style
        dangerouslySetInnerHTML={{
          __html: `
          @media print {
            @page {
              size: A4 portrait;
              margin: 10mm 12mm;
            }
            body {
              background: #ffffff !important;
              color: #0f172a !important;
              font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
              font-size: 10pt !important;
              margin: 0 !important;
              padding: 0 !important;
              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }
            header, nav, .nao-imprimir, [data-sidebar], .btn-imprimir, .acoes-tela {
              display: none !important;
            }
            .area-impressao {
              display: block !important;
              width: 100% !important;
              max-width: 100% !important;
              margin: 0 !important;
              padding: 0 !important;
              background: #ffffff !important;
              color: #0f172a !important;
            }
            .bloco-folha {
              box-shadow: none !important;
              border: none !important;
              background: #ffffff !important;
              padding: 0 !important;
            }
            .tabela-impressao {
              width: 100% !important;
              table-layout: auto !important;
              border-collapse: collapse !important;
              margin-top: 10px !important;
              font-size: 9.5pt !important;
            }
            .tabela-impressao th {
              background-color: #f1f5f9 !important;
              color: #0f172a !important;
              font-weight: 700 !important;
              border-bottom: 2px solid #cbd5e1 !important;
              border-top: 1px solid #e2e8f0 !important;
              padding: 8px 10px !important;
              text-align: left !important;
              font-size: 9pt !important;
              letter-spacing: 0.02em !important;
              text-transform: uppercase !important;
            }
            .tabela-impressao td {
              border-bottom: 1px solid #e2e8f0 !important;
              padding: 9px 10px !important;
              color: #1e293b !important;
              vertical-align: middle !important;
              word-break: normal !important;
              overflow-wrap: break-word !important;
              white-space: normal !important;
            }
            .tabela-impressao tr:nth-child(even) td {
              background-color: #f8fafc !important;
            }
          }
        `,
        }}
      />

      {/* Painel de Controles da Tela (Ocultado ao imprimir) */}
      <div className="nao-imprimir rounded-2xl border border-border/70 bg-card/70 backdrop-blur-md p-5 shadow-lg space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="space-y-1">
            <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
              <FileSpreadsheet className="w-5 h-5 text-emerald-400" />
              Relatório Geral de Faltas
            </h2>
            <p className="text-xs text-muted-foreground">
              Consolidação de ausências de todas as unidades para controle diário e emissão limpa.
            </p>
          </div>

          <div className="flex items-center gap-2.5 flex-wrap">
            <Button
              type="button"
              onClick={handleImprimir}
              className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold shadow-sm rounded-xl px-4 h-10 transition-all cursor-pointer"
            >
              <Printer className="w-4 h-4" />
              <span>Imprimir / Gerar PDF</span>
            </Button>

            <Button
              type="button"
              onClick={handleExportarExcelCSV}
              disabled={gerandoDownload || listaFaltasGeral.length === 0}
              variant="outline"
              className="gap-2 border-border/80 hover:bg-card/80 text-foreground font-medium rounded-xl px-4 h-10 transition-all cursor-pointer"
            >
              <Download className="w-4 h-4 text-emerald-400" />
              <span>{gerandoDownload ? 'Exportando...' : 'Exportar CSV'}</span>
            </Button>
          </div>
        </div>

        {/* Filtro de Data */}
        <div className="flex items-center gap-3 pt-2 border-t border-border/40">
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4 text-emerald-400" />
            <span className="text-xs font-semibold text-foreground">Data do Relatório:</span>
          </div>
          <input
            type="date"
            value={dataInicio}
            onChange={(e) => setDataInicio(e.target.value)}
            className="h-9 px-3 rounded-xl border border-input bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
          />
          <span className="text-xs text-muted-foreground hidden sm:inline-block">
            {dataFormatadaExtenso}
          </span>
        </div>
      </div>

      {/* DOCUMENTO DO RELATÓRIO (Visível na tela e base para Impressão) */}
      <div className="area-impressao bloco-folha w-full rounded-2xl border border-border/60 bg-white text-slate-900 p-6 sm:p-8 shadow-xl">

        {/* Cabeçalho Limpo e Oficial */}
        <div className="border-b-2 border-slate-800 pb-4 mb-5">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="h-10 px-2.5 py-1 rounded-lg bg-slate-900 border border-slate-700 flex items-center justify-center shrink-0">
                <img
                  src="/logo_inventar_expandWEB_novo2.jpg"
                  alt="Logo"
                  className="h-7 w-auto max-w-[130px] object-contain"
                  onError={(e) => {
                    (e.target as HTMLImageElement).style.display = 'none';
                  }}
                />
              </div>
              <div>
                <h1 className="text-lg sm:text-xl font-black text-slate-900 uppercase tracking-tight leading-none">
                  Relatório Diário de Ausências e Faltas
                </h1>
                <p className="text-xs text-slate-600 mt-1 font-medium">
                  Operação Florestal — Visão Consolidada de Todas as Unidades
                </p>
              </div>
            </div>

            <div className="text-right shrink-0">
              <div className="text-xs font-bold text-slate-900 capitalize">
                {dataFormatadaExtenso}
              </div>
              <div className="text-[11px] text-slate-500 flex items-center justify-end gap-1 mt-0.5">
                <Clock className="w-3 h-3 text-slate-400" />
                <span>Emissão: {horaEmissao}</span>
              </div>
            </div>
          </div>
        </div>

        {/* Resumo Executivo Direto das Faltas (Totalizadores Rápidos) */}
        <div className="grid grid-cols-3 gap-3 mb-5">
          <div className="p-3 rounded-lg border border-slate-200 bg-slate-50 flex items-center justify-between">
            <div>
              <p className="text-[11px] font-semibold text-slate-500 uppercase tracking-wider">Total de Faltas</p>
              <p className="text-xl font-black text-rose-600 tabular-nums leading-tight mt-0.5">
                {listaFaltasGeral.length}
              </p>
            </div>
            <UserX className="w-6 h-6 text-rose-500/30" />
          </div>

          <div className="p-3 rounded-lg border border-slate-200 bg-slate-50 flex items-center justify-between">
            <div>
              <p className="text-[11px] font-semibold text-slate-500 uppercase tracking-wider">Ribas do Rio Pardo</p>
              <p className="text-xl font-bold text-slate-900 tabular-nums leading-tight mt-0.5">
                {listaFaltasGeral.filter((i) => i.regionalOrigem === 'ribas').length}
              </p>
            </div>
            <MapPin className="w-6 h-6 text-slate-300" />
          </div>

          <div className="p-3 rounded-lg border border-slate-200 bg-slate-50 flex items-center justify-between">
            <div>
              <p className="text-[11px] font-semibold text-slate-500 uppercase tracking-wider">Água Clara</p>
              <p className="text-xl font-bold text-slate-900 tabular-nums leading-tight mt-0.5">
                {listaFaltasGeral.filter((i) => i.regionalOrigem === 'agua_clara').length}
              </p>
            </div>
            <MapPin className="w-6 h-6 text-slate-300" />
          </div>
        </div>

        {/* Tabela de Colaboradores Ausentes */}
        <div className="w-full">
          <div className="flex items-center justify-between pb-2 border-b border-slate-200 mb-2">
            <span className="text-xs font-bold text-slate-800 uppercase tracking-wide">
              Relação de Colaboradores com Falta Registrada ({listaFaltasGeral.length})
            </span>
            <span className="text-[11px] text-slate-500 italic">
              Exibindo apenas registros de ausência
            </span>
          </div>

          {listaFaltasGeral.length === 0 ? (
            <div className="py-10 text-center border border-dashed border-slate-300 rounded-xl bg-slate-50 my-2">
              <CheckCircle2 className="w-8 h-8 text-emerald-500 mx-auto mb-2" />
              <p className="text-sm font-bold text-slate-800">Nenhuma falta registrada nesta data</p>
              <p className="text-xs text-slate-500 mt-0.5">
                Todas as equipes e unidades operacionais estão com 100% de presença ou substituição atendida.
              </p>
            </div>
          ) : (
            <table className="tabela-impressao w-full text-left">
              <thead>
                <tr>
                  <th className="w-10 text-center">#</th>
                  <th className="min-w-[200px]">Colaborador</th>
                  <th className="min-w-[130px]">Unidade</th>
                  <th className="min-w-[140px]">Função / Cargo</th>
                  <th className="min-w-[150px]">Motivo da Ausência</th>
                  <th className="min-w-[160px]">Observações</th>
                </tr>
              </thead>
              <tbody>
                {listaFaltasGeral.map((item, index) => {
                  const c = item.colaborador;
                  const unidadeNome =
                    item.regionalOrigem === 'ribas'
                      ? 'Ribas do Rio Pardo'
                      : item.regionalOrigem === 'agua_clara'
                      ? 'Água Clara'
                      : c.unidade || 'Não informada';

                  return (
                    <tr key={c.id || index} className="border-b border-slate-200">
                      <td className="text-center font-bold text-slate-500 text-xs tabular-nums py-2.5">
                        {index + 1}
                      </td>
                      <td className="py-2.5 pr-3">
                        <div className="font-bold text-slate-900 text-[13px] leading-snug whitespace-normal break-words">
                          {c.nome || 'Não informado'}
                        </div>
                        {c.matricula && (
                          <span className="text-[10px] text-slate-500 font-medium">
                            Matrícula: {c.matricula}
                          </span>
                        )}
                      </td>
                      <td className="py-2.5 pr-2">
                        <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-slate-100 text-slate-700 border border-slate-200 whitespace-nowrap">
                          {unidadeNome}
                        </span>
                      </td>
                      <td className="py-2.5 pr-2">
                        <span className="text-xs text-slate-700 font-medium whitespace-normal break-words">
                          {c.cargo || 'Operador Florestal'}
                        </span>
                      </td>
                      <td className="py-2.5 pr-2">
                        <span className="inline-block text-xs font-bold text-rose-700 bg-rose-50 px-2 py-0.5 rounded border border-rose-200 whitespace-normal break-words">
                          {c.motivoFalta || 'Falta Não Justificada'}
                        </span>
                      </td>
                      <td className="py-2.5 text-xs text-slate-600 italic whitespace-normal break-words">
                        {c.observacao || '—'}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>

        {/* Rodapé Limpo e Direto (Sem campos de assinatura nem RH) */}
        <div className="mt-8 pt-3 border-t border-slate-300 flex items-center justify-between text-[10px] text-slate-500">
          <span>Sistema de Controle de Presença Florestal</span>
          <span>Documento gerado automaticamente para auditoria operacional</span>
          <span>Página 1 de 1</span>
        </div>
      </div>
    </div>
  );
};

