import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { AttendanceModal } from './components/AttendanceModal';
import { NewTeamModal, NovaEquipePayload } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import {
  Veiculo,
  Colaborador,
  Regional,
  StatusPresenca,
  MotivoFalta,
  MetricasGerais,
} from './types';
import { supabase } from './lib/supabase';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const [veiculos, setVeiculos] = useState<Veiculo[]>(() => {
    try {
      const saved = localStorage.getItem('gestao_veiculos_cache');
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.warn('Erro ao ler cache local de veículos', e);
    }
    return VEICULOS_INICIAIS;
  });

  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(() => {
    try {
      const saved = localStorage.getItem('gestao_reserva_cache');
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.warn('Erro ao ler cache local de reservas', e);
    }
    return COLABORADORES_RESERVA;
  });

  const [attendanceModalColab, setAttendanceModalColab] = useState<Colaborador | null>(null);
  const [attendanceModalOpen, setAttendanceModalOpen] = useState(false);
  const [newTeamModalOpen, setNewTeamModalOpen] = useState(false);

  // Sincronização e persistência local defensiva
  useEffect(() => {
    try {
      localStorage.setItem('gestao_veiculos_cache', JSON.stringify(veiculos));
    } catch (err) {
      console.warn('Falha ao persistir veículos no cache', err);
    }
  }, [veiculos]);

  useEffect(() => {
    try {
      localStorage.setItem('gestao_reserva_cache', JSON.stringify(colaboradoresReserva));
    } catch (err) {
      console.warn('Falha ao persistir reservas no cache', err);
    }
  }, [colaboradoresReserva]);

  // Carregar dados de veículos do Supabase quando disponível
  useEffect(() => {
    let isMounted = true;
    async function carregarDadosSupabase() {
      try {
        const { data, error } = await supabase.from('veiculos').select('*');
        if (!error && data && data.length > 0 && isMounted) {
          // Atualiza se houver registros válidos no banco
        }
      } catch (err) {
        // Fallback resiliente já ativo em memória
      }
    }
    carregarDadosSupabase();
    return () => {
      isMounted = false;
    };
  }, []);

  // Cadastro de Nova Equipe e Veículo
  const handleSalvarNovaEquipe = useCallback((payload: NovaEquipePayload) => {
    const novoVeiculoId = `v-custom-${Date.now()}`;
    const novoVeiculo: Veiculo = {
      id: novoVeiculoId,
      prefixo: payload.prefixoVeiculo || payload.prefixo || `VAN-${Math.floor(100 + Math.random() * 900)}`,
      placa: payload.placaVeiculo || payload.placa || 'BRA2E19',
      modelo: payload.modeloVeiculo || payload.modelo || 'Toyota Hilux 4x4',
      ano: payload.anoVeiculo || payload.ano || new Date().getFullYear(),
      regional: payload.regional || 'ribas',
      statusOperacional: 'ativo',
      equipe1Codigo: payload.nomeEquipe1 || 'Equipe 1',
      equipe2Codigo: payload.nomeEquipe2 || 'Equipe 2',
      assentos: {
        motorista:
          payload.colaboradoresEquipe1?.[0] || {
            id: `c-mot-${Date.now()}`,
            nome: 'Motorista Titular',
            cargo: 'Motorista Operacional',
            foto: '',
            telefone: '(67) 99999-0001',
            status: 'presente',
            equipeId: payload.nomeEquipe1 || 'EQ-1',
            equipeNumero: 1,
            posicaoVeiculo: 'motorista',
            unidade: payload.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
          },
        frenteDir:
          payload.colaboradoresEquipe1?.[1] || {
            id: `c-frt-${Date.now()}`,
            nome: 'Operador Dianteiro',
            cargo: 'Líder de Frente',
            foto: '',
            telefone: '(67) 99999-0002',
            status: 'presente',
            equipeId: payload.nomeEquipe1 || 'EQ-1',
            equipeNumero: 1,
            posicaoVeiculo: 'frente_dir',
            unidade: payload.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
          },
        trasEsq:
          payload.colaboradoresEquipe2?.[0] || {
            id: `c-tesq-${Date.now()}`,
            nome: 'Operador Retaguarda 1',
            cargo: 'Operador Florestal',
            foto: '',
            telefone: '(67) 99999-0003',
            status: 'presente',
            equipeId: payload.nomeEquipe2 || 'EQ-2',
            equipeNumero: 2,
            posicaoVeiculo: 'tras_esq',
            unidade: payload.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
          },
        trasDir:
          payload.colaboradoresEquipe2?.[1] || {
            id: `c-tdir-${Date.now()}`,
            nome: 'Operador Retaguarda 2',
            cargo: 'Operador Florestal',
            foto: '',
            telefone: '(67) 99999-0004',
            status: 'presente',
            equipeId: payload.nomeEquipe2 || 'EQ-2',
            equipeNumero: 2,
            posicaoVeiculo: 'tras_dir',
            unidade: payload.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo',
          },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
    setNewTeamModalOpen(false);
  }, []);

  // Atualização de Status de Presença do Colaborador
  const handleUpdateColaboradorStatus = useCallback(
    (
      colaboradorId: string,
      status: StatusPresenca,
      motivo?: MotivoFalta,
      observacao?: string,
      substitutoId?: string
    ) => {
      let substitutoNome: string | undefined = undefined;
      if (substitutoId) {
        const sub = colaboradoresReserva.find((r) => r.id === substitutoId);
        substitutoNome = sub?.nome;
      }

      setVeiculos((prev) =>
        prev.map((v) => {
          const assentos = { ...v.assentos };
          let alterou = false;

          (['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const).forEach((pos) => {
            if (assentos[pos]?.id === colaboradorId) {
              assentos[pos] = {
                ...assentos[pos],
                status,
                motivoFalta: status === 'falta' ? motivo : undefined,
                observacao,
                substitutoId,
                substitutoNome,
              };
              alterou = true;
            }
          });

          return alterou ? { ...v, assentos } : v;
        })
      );

      // Se for reserva
      setColaboradoresReserva((prev) =>
        prev.map((c) =>
          c.id === colaboradorId
            ? {
                ...c,
                status,
                motivoFalta: status === 'falta' ? motivo : undefined,
                observacao,
                substitutoId,
                substitutoNome,
              }
            : c
        )
      );
    },
    [colaboradoresReserva]
  );

  // Abertura do modal de presença
  const handleOpenAttendance = useCallback((colaborador: Colaborador) => {
    setAttendanceModalColab(colaborador);
    setAttendanceModalOpen(true);
  }, []);

  // Métricas Consolidadas Gerais
  const metricas = useMemo<MetricasGerais>(() => {
    let totalColabs = 0;
    let presentes = 0;
    let faltas = 0;
    let subs = 0;

    const lista = selectedRegional === 'todas'
      ? veiculos
      : veiculos.filter((v) => v.regional === selectedRegional);

    lista.forEach((v) => {
      [v.assentos.motorista, v.assentos.frenteDir, v.assentos.trasEsq, v.assentos.trasDir].forEach((c) => {
        if (c) {
          totalColabs++;
          if (c.status === 'presente') presentes++;
          else if (c.status === 'falta') faltas++;
          else if (c.status === 'substituto') subs++;
        }
      });
    });

    const taxa = totalColabs > 0 ? Math.round(((presentes + subs) / totalColabs) * 100) : 100;

    return {
      totalVeiculos: lista.length,
      veiculosAtivos: lista.filter((v) => v.statusOperacional === 'ativo').length,
      totalEquipes: lista.length * 2,
      equipesCompletas: lista.length,
      equipesIncompletas: 0,
      totalColaboradores: totalColabs,
      colaboradoresPresentes: presentes,
      colaboradoresFaltas: faltas,
      colaboradoresSubstitutos: subs,
      taxaPresenca: taxa,
    };
  }, [veiculos, selectedRegional]);

  return (
    <div className="min-h-screen bg-[#0d0f12] text-[#f5f0e8] flex flex-col antialiased selection:bg-emerald-500/30 selection:text-emerald-200">
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Cabeçalho de Métricas */}
        {activeTab !== 'relatorios' && (
          <MetricsHeader
            veiculos={veiculos}
            metricas={metricas}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
            onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
            onNovaEquipe={() => setNewTeamModalOpen(true)}
          />
        )}

        {/* Visualização por Abas */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
            onColaboradorClick={handleOpenAttendance}
            onNovaEquipeClick={() => setNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            onUpdateColaboradorStatus={handleUpdateColaboradorStatus}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedDate={selectedDate}
            selectedRegional={selectedRegional}
          />
        )}
      </main>

      {/* Modal de Presença */}
      {attendanceModalColab && (
        <AttendanceModal
          isOpen={attendanceModalOpen}
          colaborador={attendanceModalColab}
          colaboradoresReserva={colaboradoresReserva}
          onClose={() => {
            setAttendanceModalOpen(false);
            setAttendanceModalColab(null);
          }}
          onConfirm={(id, status, motivo, obs, subId) => {
            handleUpdateColaboradorStatus(id, status, motivo, obs, subId);
            setAttendanceModalOpen(false);
            setAttendanceModalColab(null);
          }}
        />
      )}

      {/* Modal de Nova Equipe */}
      <NewTeamModal
        isOpen={newTeamModalOpen}
        onClose={() => setNewTeamModalOpen(false)}
        onSave={handleSalvarNovaEquipe}
        colaboradoresReserva={colaboradoresReserva}
        regionalPadrao={selectedRegional === 'agua_clara' ? 'agua_clara' : 'ribas'}
      />
    </div>
  );
}

export default App;

