            ))}
          </div>
        </div>

        <div className="p-4 space-y-3">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {cards.map((card) => (
              <div
                key={card.key}
                className={cn(
                  'relative rounded-xl border p-4 bg-gradient-to-br overflow-hidden',
                  card.borderColor,
                  card.gradientBg
                )}
              >
                <div className="flex items-start justify-between gap-2">
