                  <p className="text-xs font-bold text-foreground">{card.label}</p>
                  <p className="text-[11px] text-muted-foreground mt-0.5">{card.descricao}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

