                    Inventar
                  </span>
                </div>
                <span className="text-xs text-muted-foreground">
                  Gestão Operacional de Efetivo & Transporte
                </span>
              </div>
            </div>

            <div className="hidden sm:block h-6 w-[1px] bg-border/80 mx-1" />

            {/* Seletor de Unidade com tema Inventar */}
