                  setDropdownUnidadeAberto(!dropdownUnidadeAberto);
                  setDropdownDataAberto(false);
                }}
                className={cn(
                  'flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs font-medium transition-all cursor-pointer shadow-sm',
                  'bg-secondary/60 hover:bg-secondary border-border/80 text-foreground',
                  dropdownUnidadeAberto && 'border-primary/60 ring-2 ring-primary/20'
                )}
              >
                <Building2 className="w-3.5 h-3.5 text-primary" />
                <span className="text-muted-foreground">Unidade:</span>
                <span className="font-semibold text-foreground">{unidadeAtual.label}</span>
                <ChevronDown
                  className={cn(
                    'w-3.5 h-3.5 text-muted-foreground transition-transform ml-0.5',
