import React, { useState } from 'react';
import {
  Car,
  AlertCircle,
  CheckCircle2,
  UserX,
  UserCheck,
  Search,
  Filter,
  Phone,
  ChevronRight,
  Shield,
  Layers,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Input } from './ui/input';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional | string;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'com_falta' | 'completo'>('todos');
  const [modalColaborador, setModalColaborador] = useState<{
    colaborador: Colaborador;
    veiculoId: string;
  } | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    if (selectedRegional !== 'todas' && v.regional !== selectedRegional) return false;

    if (busca) {
      const q = busca.toLowerCase();
      const assentos = [
        v.assentos?.motorista?.nome,
        v.assentos?.frenteDir?.nome,
        v.assentos?.trasEsq?.nome,
        v.assentos?.trasDir?.nome,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();

      const prefixo = (v.prefixo || '').toLowerCase();
      const placa = (v.placa || '').toLowerCase();

      if (!prefixo.includes(q) && !placa.includes(q) && !assentos.includes(q)) {
        return false;
      }
    }

    if (filtroStatus !== 'todos') {
      const listaAssentos = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      const temFalta = listaAssentos.some((c) => c?.status === 'falta');

      if (filtroStatus === 'com_falta' && !temFalta) return false;
      if (filtroStatus === 'completo' && temFalta) return false;
    }

    return true;
  });

  const renderAssento = (
    colab: Colaborador | undefined,
    posicaoTitulo: string,
    veiculoId: string
  ) => {
    if (!colab) {
      return (
        <div className="flex items-center gap-3 p-3 rounded-lg border border-dashed border-border/70 bg-card/20 text-muted-foreground">
          <div className="w-11 h-11 rounded-lg bg-secondary/60 flex items-center justify-center text-xs text-muted-foreground/60">
            Vazio
          </div>
          <div className="text-xs">
            <span className="text-[11px] text-muted-foreground block">{posicaoTitulo}</span>
            <span className="font-medium text-muted-foreground/80">Assento vago</span>
          </div>
        </div>
      );
    }

    const isFalta = colab.status === 'falta';
    const isSub = colab.status === 'substituto';
    const isPresente = colab.status === 'presente';

    return (
      <div
        onClick={() => setModalColaborador({ colaborador: colab, veiculoId })}
        className={cn(
          'group relative flex items-center gap-3 p-3 rounded-lg border transition-all cursor-pointer',
          isFalta && 'border-rose-500/40 bg-rose-500/5 hover:border-rose-500/70',
          isSub && 'border-amber-500/40 bg-amber-500/5 hover:border-amber-500/70',
          isPresente && 'border-border/70 bg-secondary/30 hover:bg-secondary/60 hover:border-border'
        )}
      >
        {/* Foto do Colaborador com tamanho confortável */}
        <div className="relative shrink-0">
          <div className="w-12 h-12 rounded-lg border border-border/80 overflow-hidden bg-card flex items-center justify-center shadow-sm">
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover"
              />
            ) : (
              <span className="font-semibold text-xs text-muted-foreground">
                {getIniciais(colab.nome)}
              </span>
            )}
          </div>
          {/* Indicador de Status Discreto */}
          <span
            className={cn(
              'absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full border-2 border-card flex items-center justify-center',
              isPresente && 'bg-emerald-500',
              isFalta && 'bg-rose-500',
              isSub && 'bg-amber-500'
            )}
          />
        </div>

        {/* Informações */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between gap-1">
            <span className="text-[10px] text-muted-foreground uppercase font-mono tracking-wider">
              {posicaoTitulo}
            </span>
            <span
              className={cn(
                'text-[10px] font-medium capitalize',
                isPresente && 'text-emerald-400',
                isFalta && 'text-rose-400 font-semibold',
                isSub && 'text-amber-400'
              )}
            >
              {colab.status}
            </span>
          </div>

          <h4 className="text-xs font-semibold text-foreground truncate group-hover:text-primary transition-colors">
            {colab.nome}
          </h4>

          <p className="text-[11px] text-muted-foreground truncate">
            {isFalta && colab.motivoFalta ? (
              <span className="text-rose-400/90 font-medium">{colab.motivoFalta}</span>
            ) : isSub && colab.substitutoNome ? (
              <span className="text-amber-400/90 font-medium">Sub: {colab.substitutoNome}</span>
            ) : (
              colab.cargo || 'Operador Florestal'
            )}
          </p>
        </div>
      </div>
    );
  };

  return (
    <div className="w-full space-y-5">
      {/* Barra de Filtros e Busca de Veículos */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-xl border border-border/70 bg-card/60 backdrop-blur-sm">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Buscar por prefixo, placa ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/80"
          />
        </div>

        <div className="flex items-center gap-1.5 flex-wrap">
          <button
            type="button"
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-colors cursor-pointer',
              filtroStatus === 'todos'
                ? 'bg-secondary text-foreground font-semibold border border-border'
                : 'text-muted-foreground hover:text-foreground'
            )}
          >
            Todos
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('com_falta')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-colors cursor-pointer',
              filtroStatus === 'com_falta'
                ? 'bg-rose-500/15 text-rose-400 font-semibold border border-rose-500/30'
                : 'text-muted-foreground hover:text-foreground'
            )}
          >
            Com Faltas
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('completo')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-colors cursor-pointer',
              filtroStatus === 'completo'
                ? 'bg-emerald-500/15 text-emerald-400 font-semibold border border-emerald-500/30'
                : 'text-muted-foreground hover:text-foreground'
            )}
          >
            Completos
          </button>
        </div>
      </div>

      {/* Lista de Veículos em Cards Limpos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border/80 p-12 text-center bg-card/40">
          <Car className="w-10 h-10 mx-auto text-muted-foreground/40 mb-3" />
          <h3 className="text-sm font-semibold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
            Não encontramos veículos correspondentes aos filtros aplicados.
          </p>
          {onNovaEquipeClick && (
            <Button
              onClick={onNovaEquipeClick}
              size="sm"
              className="mt-4 gap-2 text-xs"
            >
              Adicionar Novo Veículo
            </Button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {veiculosFiltrados.map((v) => {
            const listaAssentos = [
              v.assentos?.motorista,
              v.assentos?.frenteDir,
              v.assentos?.trasEsq,
              v.assentos?.trasDir,
            ].filter(Boolean);

            const faltasCount = listaAssentos.filter((c) => c?.status === 'falta').length;

            return (
              <div
                key={v.id}
                className="rounded-xl border border-border/70 bg-card/70 backdrop-blur-sm p-4 space-y-4 hover:border-border transition-colors shadow-sm"
              >
                {/* Cabeçalho do Card de Veículo */}
                <div className="flex items-center justify-between border-b border-border/50 pb-3">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-lg bg-secondary flex items-center justify-center border border-border/80">
                      <Car className="w-4 h-4 text-primary" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-sm text-foreground">
                          {v.prefixo || 'Sem Prefixo'}
                        </span>
                        <span className="text-[11px] font-mono text-muted-foreground">
                          {v.placa || '-'}
                        </span>
                      </div>
                      <span className="text-[11px] text-muted-foreground">
                        {v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'} · {v.modelo || 'Veículo Operacional'}
                      </span>
                    </div>
                  </div>

                  <div>
                    {faltasCount > 0 ? (
                      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-rose-500/10 text-rose-400 border border-rose-500/20">
                        <span className="w-1.5 h-1.5 rounded-full bg-rose-400" />
                        {faltasCount} {faltasCount === 1 ? 'falta' : 'faltas'}
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                        Completo
                      </span>
                    )}
                  </div>
                </div>

                {/* Grid dos 4 Assentos (Equipe 1 e Equipe 2) */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                  <div className="space-y-2">
                    <div className="text-[11px] font-semibold text-muted-foreground px-1">
                      Equipe 1 · Frente
                    </div>
                    {renderAssento(v.assentos?.motorista, 'Motorista', v.id)}
                    {renderAssento(v.assentos?.frenteDir, 'Passageiro', v.id)}
                  </div>

                  <div className="space-y-2">
                    <div className="text-[11px] font-semibold text-muted-foreground px-1">
                      Equipe 2 · Trás
                    </div>
                    {renderAssento(v.assentos?.trasEsq, 'Trás Esq.', v.id)}
                    {renderAssento(v.assentos?.trasDir, 'Trás Dir.', v.id)}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Presença / Falta ao Clicar no Colaborador */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={!!modalColaborador}
          colaborador={modalColaborador.colaborador}
          colaboradoresReserva={colaboradoresReserva}
          veiculoId={modalColaborador.veiculoId}
          onClose={() => setModalColaborador(null)}
          onConfirm={(colabId, status, motivo, observacao, substitutoId) => {
            onUpdateColaboradorStatus?.(
              colabId,
              status,
              motivo,
              observacao,
              substitutoId
            );
            setModalColaborador(null);
          }}
        />
      )}
    </div>
  );
};

