}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'com_falta' | 'completo'>('todos');
  const [modalColaborador, setModalColaborador] = useState<{
    colaborador: Colaborador;
    veiculoId: string;
  } | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    if (selectedRegional !== 'todas' && v.regional !== selectedRegional) return false;

    if (busca) {
      const q = busca.toLowerCase();
      const assentos = [
        v.assentos?.motorista?.nome,
        v.assentos?.frenteDir?.nome,
        v.assentos?.trasEsq?.nome,
        v.assentos?.trasDir?.nome,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();

      const prefixo = (v.prefixo || '').toLowerCase();
      const placa = (v.placa || '').toLowerCase();

      if (!prefixo.includes(q) && !placa.includes(q) && !assentos.includes(q)) {
        return false;
      }
    }

    if (filtroStatus !== 'todos') {
      const listaAssentos = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      const temFalta = listaAssentos.some((c) => c?.status === 'falta');

      if (filtroStatus === 'com_falta' && !temFalta) return false;
      if (filtroStatus === 'completo' && temFalta) return false;
    }

    return true;
  });

  const renderAssento = (
    colab: Colaborador | undefined,
    posicaoTitulo: string,
    veiculoId: string
  ) => {
    if (!colab) {
      return (
        <div className="flex items-center gap-3 p-3 rounded-xl border border-dashed border-border/70 bg-card/20 text-muted-foreground">
          <div className="w-12 h-12 rounded-xl bg-secondary/60 flex items-center justify-center text-xs text-muted-foreground/60">
            Vazio
          </div>
          <div className="text-xs">
            <span className="text-[11px] text-muted-foreground block">{posicaoTitulo}</span>
            <span className="font-medium text-muted-foreground/80">Assento vago</span>
          </div>
        </div>
      );
    }

    const isFalta = colab.status === 'falta';
    const isSub = colab.status === 'substituto';
    const isPresente = colab.status === 'presente';

    return (
      <div
        onClick={() => setModalColaborador({ colaborador: colab, veiculoId })}
        className={cn(
          'group relative flex items-center gap-3 p-3 rounded-xl border transition-all cursor-pointer',
          isFalta && 'border-rose-500/40 bg-rose-500/10 hover:border-rose-500/70',
          isSub && 'border-amber-500/40 bg-amber-500/10 hover:border-amber-500/70',
          isPresente && 'border-border/80 bg-secondary/35 hover:bg-secondary/60 hover:border-primary/40'
        )}
      >
        {/* Foto do Colaborador com destaque */}
        <div className="relative shrink-0">
          <div className="w-12 h-12 rounded-xl border border-border/80 overflow-hidden bg-card flex items-center justify-center shadow-sm">
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover"
              />
            ) : (
              <span className="font-semibold text-xs text-muted-foreground">
                {getIniciais(colab.nome)}
              </span>
            )}
          </div>
          {/* Indicador de Status */}
          <span
            className={cn(
              'absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full border-2 border-card flex items-center justify-center',
              isPresente && 'bg-primary',
              isFalta && 'bg-rose-500',
              isSub && 'bg-amber-500'
            )}
          />
        </div>

        {/* Informações do Colaborador */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between gap-1">
            <span className="text-[10px] text-muted-foreground uppercase font-mono tracking-wider">
              {posicaoTitulo}
            </span>
            <span
              className={cn(
                'text-[10px] font-semibold capitalize',
                isPresente && 'text-primary',
                isFalta && 'text-rose-400',
                isSub && 'text-amber-400'
              )}
            >
              {colab.status}
            </span>
          </div>

          <h4 className="text-xs font-semibold text-foreground truncate group-hover:text-primary transition-colors">
            {colab.nome}
          </h4>

          <p className="text-[11px] text-muted-foreground truncate">
            {isFalta && colab.motivoFalta ? (
              <span className="text-rose-400/90 font-medium">{colab.motivoFalta}</span>
            ) : isSub && colab.substitutoNome ? (
              <span className="text-amber-400/90 font-medium">Sub: {colab.substitutoNome}</span>
            ) : (
              colab.cargo || 'Operador Florestal'
            )}
          </p>
        </div>
      </div>
    );
  };

  return (
    <div className="w-full space-y-5">
      {/* Barra de Filtros e Busca de Veículos */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-xl border border-border/80 bg-card/70 backdrop-blur-sm shadow-sm">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Buscar por prefixo, placa ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-9 text-xs bg-background/80 focus-visible:ring-primary/40"
          />
        </div>

        <div className="flex items-center gap-1.5 flex-wrap">
          <button
            type="button"
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'todos'
                ? 'bg-primary/20 text-primary font-semibold border border-primary/35 shadow-sm'
                : 'text-muted-foreground hover:text-foreground hover:bg-secondary/60'
            )}
          >
            Todos
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('com_falta')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'com_falta'
                ? 'bg-rose-500/20 text-rose-400 font-semibold border border-rose-500/40 shadow-sm'
                : 'text-muted-foreground hover:text-foreground hover:bg-secondary/60'
            )}
          >
            Com Ausência
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('completo')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'completo'
                ? 'bg-primary/20 text-primary font-semibold border border-primary/35 shadow-sm'
                : 'text-muted-foreground hover:text-foreground hover:bg-secondary/60'
            )}
          >
            100% Presentes
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border/80 p-12 text-center bg-card/40">
          <Car className="w-10 h-10 mx-auto text-muted-foreground/60 mb-3" />
          <h3 className="text-sm font-semibold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
            Não foram localizados veículos ou colaboradores correspondentes aos filtros aplicados.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {veiculosFiltrados.map((v) => {
            const listaAssentos = [
              v.assentos?.motorista,
              v.assentos?.frenteDir,
              v.assentos?.trasEsq,
              v.assentos?.trasDir,
            ].filter(Boolean);

            const totalPresentes = listaAssentos.filter(
              (c) => c?.status === 'presente' || c?.status === 'substituto'
            ).length;
            const totalFaltas = listaAssentos.filter((c) => c?.status === 'falta').length;

            return (
              <div
                key={v.id}
                className="rounded-2xl border border-border/80 bg-card/75 p-5 shadow-sm hover:border-primary/40 transition-all space-y-4"
              >
                {/* Cabeçalho do Card do Veículo */}
                <div className="flex items-start justify-between gap-3 pb-3 border-b border-border/60">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-primary/15 border border-primary/25 flex items-center justify-center text-primary shrink-0">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-base text-foreground tracking-tight">
                          {v.prefixo}
                        </span>
                        <span className="px-2 py-0.5 rounded text-[10px] font-mono font-semibold uppercase bg-secondary border border-border text-foreground">
                          {v.placa}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {v.modelo} • {v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {totalFaltas > 0 ? (
                      <span className="px-2.5 py-1 rounded-lg text-xs font-semibold bg-rose-500/15 text-rose-400 border border-rose-500/30">
                        {totalFaltas} {totalFaltas === 1 ? 'falta' : 'faltas'}
                      </span>
                    ) : (
                      <span className="px-2.5 py-1 rounded-lg text-xs font-semibold bg-primary/15 text-primary border border-primary/25">
                        Operação 100%
                      </span>
                    )}
                  </div>
                </div>

                {/* Bloco de Equipes e Assentos */}
                <div className="space-y-3">
                  {/* Equipe 1 */}
                  <div>
                    <div className="flex items-center justify-between text-xs font-semibold text-muted-foreground mb-2 px-1">
                      <span className="uppercase tracking-wider text-[10px] text-primary font-mono">
                        {v.equipe1Codigo || 'Equipe 1'} (Cabine Dianteira)
                      </span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      {renderAssento(v.assentos?.motorista, 'Motorista', v.id)}
                      {renderAssento(v.assentos?.frenteDir, 'Frente Dir.', v.id)}
                    </div>
                  </div>

                  {/* Equipe 2 */}
                  <div>
                    <div className="flex items-center justify-between text-xs font-semibold text-muted-foreground mb-2 px-1">
                      <span className="uppercase tracking-wider text-[10px] text-primary font-mono">
                        {v.equipe2Codigo || 'Equipe 2'} (Cabine Traseira)
                      </span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      {renderAssento(v.assentos?.trasEsq, 'Traseira Esq.', v.id)}
                      {renderAssento(v.assentos?.trasDir, 'Traseira Dir.', v.id)}
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Presença / Falta / Substituto */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={true}
          colaborador={modalColaborador.colaborador}
          colaboradoresReserva={colaboradoresReserva}
          veiculoId={modalColaborador.veiculoId}
          onClose={() => setModalColaborador(null)}
          onConfirm={(colaboradorId, novoStatus, motivo, obs, subId) => {
            onUpdateColaboradorStatus?.(colaboradorId, novoStatus, motivo, obs, subId);
            setModalColaborador(null);
          }}
        />
      )}
    </div>
  );
};

