@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    /* Paleta Institucional alinhada à Identidade Visual da Inventar Florestal */
    --background: 150 12% 7%;
    --foreground: 145 20% 96%;

    --card: 150 14% 9%;
    --card-foreground: 145 20% 96%;

    --popover: 150 14% 9%;
    --popover-foreground: 145 20% 96%;

    /* Verde Institucional Inventar (Verde Florestal Tecnológico) */
    --primary: 152 76% 40%;
    --primary-foreground: 0 0% 100%;

    --secondary: 150 10% 14%;
    --secondary-foreground: 145 15% 90%;

    --muted: 150 8% 16%;
    --muted-foreground: 145 10% 64%;

    --accent: 152 65% 32%;
    --accent-foreground: 0 0% 100%;

    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 98%;

    --border: 150 10% 18%;
    --input: 150 10% 20%;
    --ring: 152 76% 45%;

    --radius: 0.75rem;
  }
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground antialiased selection:bg-primary/20 selection:text-primary;
    font-feature-settings: "cv02", "cv03", "cv04", "cv11";
  }
}

/* Scrollbar refinada e discreta */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: hsl(var(--background));
}

::-webkit-scrollbar-thumb {
  background: hsl(var(--border));
  border-radius: 9999px;
}

::-webkit-scrollbar-thumb:hover {
  background: hsl(var(--primary) / 0.5);
}

/* Regras de impressão limpas para relatórios */
@media print {
  @page {
    size: A4 portrait;
    margin: 10mm 12mm;
  }

  body {
    background: #ffffff !important;
    color: #0f172a !important;
  }

  header, nav, footer, button, .no-print {
    display: none !important;
  }

  .print-area {
    display: block !important;
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    box-shadow: none !important;
    border: none !important;
    background: #ffffff !important;
    color: #0f172a !important;
  }
}

