import React, { useMemo, useState } from 'react';
import { Users, UsersRound, TrendingUp, PlusCircle, ShieldCheck } from 'lucide-react';
import { Veiculo, MetricasGerais, Regional } from '../types';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';

export interface MetricsHeaderProps {
  veiculos?: Veiculo[];
  metricas?: MetricasGerais;
  selectedRegional?: Regional | string;
  selectedDate?: Date;
  onFiltroRegionalChange?: (regional: 'todas' | 'ribas' | 'agua_clara') => void;
  onNovaEquipe?: () => void;
}

function calcularEquipes(lista: Veiculo[] = []) {
  let equipesCom2 = 0;
  let equipesCom3 = 0;

  (lista || []).forEach((v) => {
    if (!v || !v.assentos) return;
    const eq1 = [v.assentos?.motorista, v.assentos?.frenteDir].filter(Boolean);
    const eq2 = [v.assentos?.trasEsq, v.assentos?.trasDir].filter(Boolean);

    const ativosEq1 = eq1.filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;
    const ativosEq2 = eq2.filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;

    if (ativosEq1 === 1) equipesCom2++;
    else if (ativosEq1 >= 2) equipesCom3++;

    if (ativosEq2 === 1) equipesCom2++;
    else if (ativosEq2 >= 2) equipesCom3++;
  });

  return {
    totalVeiculos: (lista || []).length,
    totalEquipes: (lista || []).length * 2,
    equipesCom2,
    equipesCom3,
  };
}

export const MetricsHeader: React.FC<MetricsHeaderProps> = ({
  veiculos = [],
  onFiltroRegionalChange,
  onNovaEquipe,
}) => {
  const [activePanel, setActivePanel] = useState<'todas' | 'ribas' | 'agua_clara'>('todas');

  const handlePanelChange = (panel: 'todas' | 'ribas' | 'agua_clara') => {
    setActivePanel(panel);
    onFiltroRegionalChange?.(panel);
  };

  const veiculosSeguros = veiculos || [];

  const veiculosFiltrados = useMemo(() => {
    if (activePanel === 'todas') return veiculosSeguros;
    return veiculosSeguros.filter((v) => v?.regional === activePanel);
  }, [veiculosSeguros, activePanel]);

  const dadosAtivos = useMemo(() => calcularEquipes(veiculosFiltrados), [veiculosFiltrados]);
  const { equipesCom2, equipesCom3, totalEquipes, totalVeiculos } = dadosAtivos;

  const panelButtons = [
    {
      key: 'todas' as const,
      label: 'Geral Consolidado',
      count: veiculosSeguros.length,
    },
    {
      key: 'ribas' as const,
      label: 'Ribas do Rio Pardo',
      count: veiculosSeguros.filter((v) => v?.regional === 'ribas').length,
    },
    {
      key: 'agua_clara' as const,
      label: 'Água Clara',
      count: veiculosSeguros.filter((v) => v?.regional === 'agua_clara').length,
    },
  ];

  return (
    <div className="w-full space-y-4">
      {/* Barra de Ações e Filtro de Visualização Integrados à Identidade Inventar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-xl border border-border/80 bg-card/70 backdrop-blur-sm shadow-sm">
        <div className="flex items-center gap-1.5 flex-wrap">
          {panelButtons.map((btn) => (
            <button
              key={btn.key}
              type="button"
              onClick={() => handlePanelChange(btn.key)}
              className={cn(
                'flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
                activePanel === btn.key
                  ? 'bg-primary/20 text-primary font-semibold border border-primary/35 shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-secondary/60'
              )}
            >
              <span>{btn.label}</span>
              <span className={cn(
                "px-1.5 py-0.2 rounded text-[10px] font-mono tabular-nums",
                activePanel === btn.key ? "bg-primary/30 text-foreground font-bold" : "bg-muted text-muted-foreground"
              )}>
                {btn.count}
              </span>
            </button>
          ))}
        </div>

        {onNovaEquipe && (
          <Button
            type="button"
            onClick={onNovaEquipe}
            size="sm"
            className="gap-2 bg-primary text-primary-foreground font-semibold hover:bg-primary/90 shadow-sm shadow-primary/25"
          >
            <PlusCircle className="w-4 h-4" />
            <span>Nova Equipe</span>
          </Button>
        )}
      </div>

      {/* Grid Bento Elegante com os 3 Cards de Resumo */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        {/* Card 1: Veículos Ativos */}
        <div className="rounded-xl border border-border/80 bg-card/70 p-4 relative overflow-hidden group hover:border-primary/40 transition-colors">
          <div className="flex items-center justify-between text-muted-foreground">
            <span className="text-xs font-medium uppercase tracking-wider text-muted-foreground">Veículos em Campo</span>
            <div className="w-8 h-8 rounded-lg bg-primary/15 border border-primary/25 flex items-center justify-center text-primary">
              <ShieldCheck className="w-4 h-4" />
            </div>
          </div>
          <div className="mt-2 flex items-baseline gap-2">
            <span className="text-3xl font-bold tracking-tight text-foreground tabular-nums">
              {totalVeiculos}
            </span>
            <span className="text-xs text-muted-foreground font-medium">unidades ativas</span>
          </div>
          <p className="mt-1 text-[11px] text-muted-foreground/90">
            {totalEquipes} postos florestais monitorados
          </p>
        </div>

        {/* Card 2: Duplas Operacionais */}
        <div className="rounded-xl border border-border/80 bg-card/70 p-4 relative overflow-hidden group hover:border-emerald-500/40 transition-colors">
          <div className="flex items-center justify-between text-muted-foreground">
            <span className="text-xs font-medium uppercase tracking-wider text-muted-foreground">Duplas Operacionais</span>
            <div className="w-8 h-8 rounded-lg bg-emerald-500/15 border border-emerald-500/25 flex items-center justify-center text-emerald-400">
              <Users className="w-4 h-4" />
            </div>
          </div>
          <div className="mt-2 flex items-baseline gap-2">
            <span className="text-3xl font-bold tracking-tight text-foreground tabular-nums">
              {equipesCom2}
            </span>
            <span className="text-xs text-muted-foreground font-medium">equipes</span>
          </div>
          <p className="mt-1 text-[11px] text-muted-foreground/90">
            2 operadores escalados no veículo
          </p>
        </div>

        {/* Card 3: Trios / Postos Cheios */}
        <div className="rounded-xl border border-border/80 bg-card/70 p-4 relative overflow-hidden group hover:border-teal-500/40 transition-colors">
          <div className="flex items-center justify-between text-muted-foreground">
            <span className="text-xs font-medium uppercase tracking-wider text-muted-foreground">Trios / Postos Cheios</span>
            <div className="w-8 h-8 rounded-lg bg-teal-500/15 border border-teal-500/25 flex items-center justify-center text-teal-400">
              <UsersRound className="w-4 h-4" />
            </div>
          </div>
          <div className="mt-2 flex items-baseline gap-2">
            <span className="text-3xl font-bold tracking-tight text-foreground tabular-nums">
              {equipesCom3}
            </span>
            <span className="text-xs text-muted-foreground font-medium">equipes</span>
          </div>
          <p className="mt-1 text-[11px] text-muted-foreground/90">
            3 ou mais operadores escalados
          </p>
        </div>
      </div>
    </div>
  );
};

