import React, { useState } from 'react';
import {
  Car,
  AlertCircle,
  CheckCircle2,
  UserX,
  UserCheck,
  Search,
  Filter,
  Shield,
  Layers,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Input } from './ui/input';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional | string;
  onUpdateColaboradorStatus?: (
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onNovaEquipeClick?: () => void;
}

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'com_falta' | 'completo'>('todos');
  const [modalColaborador, setModalColaborador] = useState<{
    colaborador: Colaborador;
    veiculoId: string;
  } | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    if (selectedRegional !== 'todas' && v.regional !== selectedRegional) return false;

    if (busca) {
      const q = busca.toLowerCase();
      const assentos = [
        v.assentos?.motorista?.nome,
        v.assentos?.frenteDir?.nome,
        v.assentos?.trasEsq?.nome,
        v.assentos?.trasDir?.nome,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();

      const prefixo = (v.prefixo || '').toLowerCase();
      const placa = (v.placa || '').toLowerCase();

      if (!prefixo.includes(q) && !placa.includes(q) && !assentos.includes(q)) {
        return false;
      }
    }

    if (filtroStatus !== 'todos') {
      const listaAssentos = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      const temFalta = listaAssentos.some((c) => c?.status === 'falta');

      if (filtroStatus === 'com_falta' && !temFalta) return false;
      if (filtroStatus === 'completo' && temFalta) return false;
    }

    return true;
  });

  const renderAssento = (
    colab: Colaborador | undefined,
    posicaoTitulo: string,
    veiculoId: string
  ) => {
    if (!colab) {
      return (
        <div className="flex items-center gap-3 p-3 rounded-xl border border-dashed border-emerald-900/15 bg-emerald-50/20 text-emerald-900/40">
          <div className="w-12 h-12 rounded-xl bg-emerald-50 flex items-center justify-center text-xs text-emerald-800/50">
            Vazio
          </div>
          <div className="text-xs">
            <span className="text-[11px] text-emerald-800/60 block">{posicaoTitulo}</span>
            <span className="font-medium text-emerald-900/50">Assento vago</span>
          </div>
        </div>
      );
    }

    const isFalta = colab.status === 'falta';
    const isSub = colab.status === 'substituto';
    const isPresente = colab.status === 'presente';

    return (
      <div
        onClick={() => setModalColaborador({ colaborador: colab, veiculoId })}
        className={cn(
          'group relative flex items-center gap-3 p-3 rounded-xl border transition-all cursor-pointer bg-white shadow-xs',
          isFalta && 'border-rose-300 bg-rose-50/50 hover:border-rose-400',
          isSub && 'border-amber-300 bg-amber-50/50 hover:border-amber-400',
          isPresente && 'border-emerald-100 hover:border-emerald-400 hover:bg-emerald-50/40'
        )}
      >
        {/* Foto do Colaborador */}
        <div className="relative shrink-0">
          <div className="w-12 h-12 rounded-xl border border-emerald-200 overflow-hidden bg-white flex items-center justify-center shadow-xs">
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover"
              />
            ) : (
              <span className="font-semibold text-xs text-emerald-800">
                {getIniciais(colab.nome)}
              </span>
            )}
          </div>
          {/* Indicador de Status */}
          <span
            className={cn(
              'absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full border-2 border-white flex items-center justify-center',
              isPresente && 'bg-emerald-600',
              isFalta && 'bg-rose-500',
              isSub && 'bg-amber-500'
            )}
          />
        </div>

        {/* Informações do Colaborador */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between gap-1">
            <span className="text-[10px] text-emerald-900/60 uppercase font-mono tracking-wider">
              {posicaoTitulo}
            </span>
            <span
              className={cn(
                'text-[10px] font-semibold capitalize',
                isPresente && 'text-emerald-700',
                isFalta && 'text-rose-600',
                isSub && 'text-amber-700'
              )}
            >
              {colab.status}
            </span>
          </div>

          <h4 className="text-xs font-semibold text-emerald-950 truncate group-hover:text-emerald-700 transition-colors">
            {colab.nome}
          </h4>

          <p className="text-[11px] text-emerald-900/70 truncate">
            {isFalta && colab.motivoFalta ? (
              <span className="text-rose-600 font-medium">{colab.motivoFalta}</span>
            ) : isSub && colab.substitutoNome ? (
              <span className="text-amber-700 font-medium">Sub: {colab.substitutoNome}</span>
            ) : (
              colab.cargo || 'Operador Florestal'
            )}
          </p>
        </div>
      </div>
    );
  };

  return (
    <div className="w-full space-y-5">
      {/* Barra de Filtros e Busca de Veículos */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-xl border border-emerald-900/10 bg-white shadow-sm">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-emerald-700/60" />
          <Input
            placeholder="Buscar por prefixo, placa ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-9 text-xs bg-emerald-50/20 border-emerald-200 text-emerald-950 focus-visible:ring-emerald-500/30"
          />
        </div>

        <div className="flex items-center gap-1.5 flex-wrap">
          <button
            type="button"
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'todos'
                ? 'bg-emerald-600 text-white font-semibold shadow-sm shadow-emerald-700/20'
                : 'text-emerald-950/70 hover:text-emerald-950 hover:bg-emerald-50'
            )}
          >
            Todos
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('com_falta')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'com_falta'
                ? 'bg-rose-500 text-white font-semibold shadow-sm'
                : 'text-emerald-950/70 hover:text-emerald-950 hover:bg-emerald-50'
            )}
          >
            Com Falta
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('completo')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'completo'
                ? 'bg-emerald-700 text-white font-semibold shadow-sm'
                : 'text-emerald-950/70 hover:text-emerald-950 hover:bg-emerald-50'
            )}
          >
            Completos
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center rounded-2xl border border-dashed border-emerald-200 bg-white">
          <Car className="w-12 h-12 text-emerald-400 mb-3" />
          <h3 className="text-base font-bold text-emerald-950">Nenhum veículo encontrado</h3>
          <p className="text-xs text-emerald-900/60 max-w-sm mt-1 mb-4">
            Não há registros correspondentes aos filtros selecionados para esta unidade operacional.
          </p>
          {onNovaEquipeClick && (
            <Button
              type="button"
              onClick={onNovaEquipeClick}
              size="sm"
              className="bg-emerald-600 hover:bg-emerald-700 text-white gap-2"
            >
              Cadastrar Veículo & Equipe
            </Button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((v) => {
            const assentosLista = [
              v.assentos?.motorista,
              v.assentos?.frenteDir,
              v.assentos?.trasEsq,
              v.assentos?.trasDir,
            ].filter(Boolean);

            const totalFaltas = assentosLista.filter((c) => c?.status === 'falta').length;
            const totalSubs = assentosLista.filter((c) => c?.status === 'substituto').length;
            const totalPresentes = assentosLista.filter((c) => c?.status === 'presente').length;

            return (
              <div
                key={v.id || v.prefixo}
                className="rounded-2xl border border-emerald-900/10 bg-white shadow-sm hover:shadow-md hover:border-emerald-300 transition-all overflow-hidden flex flex-col"
              >
                {/* Header do Card do Veículo */}
                <div className="p-4 border-b border-emerald-100 flex items-center justify-between bg-emerald-50/40">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-emerald-600 text-white flex items-center justify-center font-bold text-sm shadow-xs">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-sm text-emerald-950">{v.prefixo}</span>
                        <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-emerald-100 text-emerald-800 font-semibold">
                          {v.placa}
                        </span>
                      </div>
                      <span className="text-[11px] text-emerald-900/60 font-medium">
                        {v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'} • {v.modelo || 'Hilux'}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-1.5">
                    {totalFaltas > 0 ? (
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 text-rose-700 border border-rose-200">
                        {totalFaltas} {totalFaltas === 1 ? 'Falta' : 'Faltas'}
                      </span>
                    ) : (
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-100 text-emerald-800 border border-emerald-200">
                        Completo
                      </span>
                    )}
                  </div>
                </div>

                {/* Corpo do Veículo: Divisão por Equipes */}
                <div className="p-4 space-y-4 flex-1">
                  {/* Equipe 1 (Frente) */}
                  <div className="space-y-2">
                    <div className="flex items-center justify-between text-[11px] font-bold text-emerald-900 uppercase tracking-wider">
                      <span>Equipe 1 • {v.equipe1Codigo || 'Frente'}</span>
                      <span className="text-[10px] text-emerald-700 font-normal">Cabine Dianteira</span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      {renderAssento(v.assentos?.motorista, 'Motorista', v.id)}
                      {renderAssento(v.assentos?.frenteDir, 'Frente Dir.', v.id)}
                    </div>
                  </div>

                  {/* Equipe 2 (Retaguarda) */}
                  <div className="space-y-2 pt-2 border-t border-emerald-100">
                    <div className="flex items-center justify-between text-[11px] font-bold text-emerald-900 uppercase tracking-wider">
                      <span>Equipe 2 • {v.equipe2Codigo || 'Retaguarda'}</span>
                      <span className="text-[10px] text-emerald-700 font-normal">Cabine Traseira</span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      {renderAssento(v.assentos?.trasEsq, 'Trás Esq.', v.id)}
                      {renderAssento(v.assentos?.trasDir, 'Trás Dir.', v.id)}
                    </div>
                  </div>
                </div>

                {/* Footer com Resumo Rápido */}
                <div className="px-4 py-2.5 bg-emerald-50/30 border-t border-emerald-100 flex items-center justify-between text-[11px] text-emerald-900/60 font-medium">
                  <span>{assentosLista.length} operadores escalados</span>
                  <div className="flex items-center gap-2">
                    <span className="text-emerald-700 font-semibold">{totalPresentes} pres.</span>
                    {totalSubs > 0 && <span className="text-amber-700 font-semibold">• {totalSubs} sub.</span>}
                    {totalFaltas > 0 && <span className="text-rose-600 font-semibold">• {totalFaltas} falta</span>}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Atualização de Presença */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={!!modalColaborador}
          colaborador={modalColaborador.colaborador}
          veiculoId={modalColaborador.veiculoId}
          colaboradoresReserva={colaboradoresReserva}
          onClose={() => setModalColaborador(null)}
          onConfirm={(colabId, status, motivo, obs, subId) => {
            onUpdateColaboradorStatus?.(colabId, status, motivo, obs, subId);
            setModalColaborador(null);
          }}
        />
      )}
    </div>
  );
};

