import React, { useState, useMemo } from 'react';
import {
  Car,
  AlertTriangle,
  CheckCircle2,
  Phone,
  Search,
  Filter,
  Users,
  Building2,
  Calendar,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Input } from './ui/input';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional | string;
  onUpdateStatus?: (
    veiculoId: string,
    posicao: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir',
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onSelectVeiculo?: (veiculo: Veiculo) => void;
}

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateStatus,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'completos' | 'incompletos'>('todos');

  // Estado para o Modal de Presença
  const [modalAberto, setModalAberto] = useState(false);
  const [colaboradorSelecionado, setColaboradorSelecionado] = useState<Colaborador | null>(null);
  const [veiculoIdSelecionado, setVeiculoIdSelecionado] = useState<string>('');
  const [posicaoSelecionada, setPosicaoSelecionada] = useState<
    'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir'
  >('motorista');

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;

      // Filtro Regional
      if (selectedRegional && selectedRegional !== 'todas') {
        if (v.regional !== selectedRegional) return false;
      }

      // Filtro de Texto (Prefixo, Placa, Modelo ou Nome dos ocupantes)
      if (busca) {
        const termo = busca.toLowerCase();
        const prefixoOk = v.prefixo?.toLowerCase().includes(termo);
        const placaOk = v.placa?.toLowerCase().includes(termo);
        const modeloOk = v.modelo?.toLowerCase().includes(termo);

        const assentos = [
          v.assentos?.motorista?.nome,
          v.assentos?.frenteDir?.nome,
          v.assentos?.trasEsq?.nome,
          v.assentos?.trasDir?.nome,
        ];
        const ocupanteOk = assentos.some((nome) => nome?.toLowerCase().includes(termo));

        if (!prefixoOk && !placaOk && !modeloOk && !ocupanteOk) {
          return false;
        }
      }

      // Filtro de Completude
      if (filtroStatus !== 'todos') {
        const assentos = [
          v.assentos?.motorista,
          v.assentos?.frenteDir,
          v.assentos?.trasEsq,
          v.assentos?.trasDir,
        ].filter(Boolean);

        const temFalta = assentos.some((c) => c?.status === 'falta');
        if (filtroStatus === 'completos' && temFalta) return false;
        if (filtroStatus === 'incompletos' && !temFalta) return false;
      }

      return true;
    });
  }, [veiculos, selectedRegional, busca, filtroStatus]);

  const abrirModalPresenca = (
    colaborador: Colaborador,
    veiculoId: string,
    posicao: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir'
  ) => {
    setColaboradorSelecionado(colaborador);
    setVeiculoIdSelecionado(veiculoId);
    setPosicaoSelecionada(posicao);
    setModalAberto(true);
  };

  const handleConfirmarPresenca = (
    colaboradorId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    if (onUpdateStatus && veiculoIdSelecionado) {
      onUpdateStatus(veiculoIdSelecionado, posicaoSelecionada, status, motivo, observacao, substitutoId);
    }
  };

  return (
    <div className="space-y-4">
      {/* Barra de Filtro de Busca e Status */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 rounded-xl border border-emerald-900/10 bg-white shadow-sm">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-emerald-800/50" />
          <Input
            placeholder="Buscar por prefixo, placa ou nome do operador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="pl-9 h-9 text-xs bg-emerald-50/40 border-emerald-200 text-emerald-950 placeholder:text-emerald-900/40 focus-visible:ring-emerald-500"
          />
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'todos'
                ? 'bg-emerald-600 text-white font-semibold shadow-sm'
                : 'text-emerald-900/70 hover:bg-emerald-50'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('completos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'completos'
                ? 'bg-emerald-600 text-white font-semibold shadow-sm'
                : 'text-emerald-900/70 hover:bg-emerald-50'
            )}
          >
            100% Presentes
          </button>
          <button
            type="button"
            onClick={() => setFiltroStatus('incompletos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer',
              filtroStatus === 'incompletos'
                ? 'bg-rose-600 text-white font-semibold shadow-sm'
                : 'text-emerald-900/70 hover:bg-emerald-50'
            )}
          >
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grid de Cards de Veículos em Fundo Branco e Detalhes Verdes */}
      {veiculosFiltrados.length === 0 ? (
        <div className="text-center py-12 rounded-xl border border-dashed border-emerald-300 bg-white p-6 shadow-sm">
          <Car className="w-10 h-10 text-emerald-400 mx-auto mb-2 opacity-60" />
          <h4 className="text-sm font-semibold text-emerald-950">Nenhum veículo encontrado</h4>
          <p className="text-xs text-emerald-800/60 mt-1">
            Tente redefinir os filtros ou adicione uma nova equipe ao sistema.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {veiculosFiltrados.map((v) => {
            const assentos = [
              { c: v.assentos?.motorista, pos: 'motorista' as const, label: 'Motorista' },
              { c: v.assentos?.frenteDir, pos: 'frente_dir' as const, label: 'Carona Diant.' },
              { c: v.assentos?.trasEsq, pos: 'tras_esq' as const, label: 'Traseiro Esq.' },
              { c: v.assentos?.trasDir, pos: 'tras_dir' as const, label: 'Traseiro Dir.' },
            ];

            const faltas = assentos.filter((a) => a.c?.status === 'falta').length;
            const presentes = assentos.filter(
              (a) => a.c && (a.c.status === 'presente' || a.c.status === 'substituto')
            ).length;

            return (
              <div
                key={v.id}
                className="rounded-xl border border-emerald-900/10 bg-white p-4 shadow-sm hover:shadow-md hover:border-emerald-300 transition-all flex flex-col justify-between gap-4"
              >
                {/* Topo do Card: Identificação do Veículo */}
                <div className="flex items-start justify-between border-b border-emerald-900/10 pb-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-emerald-50 border border-emerald-200 flex items-center justify-center text-emerald-700 shadow-sm shrink-0">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="font-bold text-base text-emerald-950 font-mono tracking-tight">
                          {v.prefixo}
                        </h3>
                        <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-emerald-100 text-emerald-800 border border-emerald-200 font-semibold">
                          {v.placa}
                        </span>
                      </div>
                      <p className="text-xs text-emerald-800/70 font-medium">
                        {v.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'} • {v.modelo}
                      </p>
                    </div>
                  </div>

                  {faltas > 0 ? (
                    <span className="flex items-center gap-1 text-[11px] font-semibold text-rose-700 bg-rose-50 border border-rose-200 px-2 py-0.5 rounded-md">
                      <AlertTriangle className="w-3.5 h-3.5" />
                      {faltas} {faltas === 1 ? 'falta' : 'faltas'}
                    </span>
                  ) : (
                    <span className="flex items-center gap-1 text-[11px] font-semibold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-md">
                      <CheckCircle2 className="w-3.5 h-3.5" />
                      Completo
                    </span>
                  )}
                </div>

                {/* Grid dos 4 Assentos Operacionais */}
                <div className="grid grid-cols-2 gap-2">
                  {assentos.map(({ c, pos, label }) => {
                    if (!c) {
                      return (
                        <div
                          key={pos}
                          className="p-2.5 rounded-lg border border-dashed border-emerald-200 bg-emerald-50/20 text-center text-xs text-emerald-800/40"
                        >
                          Vago
                        </div>
                      );
                    }

                    const isFalta = c.status === 'falta';
                    const isSubstituto = c.status === 'substituto';

                    return (
                      <button
                        key={pos}
                        type="button"
                        onClick={() => abrirModalPresenca(c, v.id, pos)}
                        className={cn(
                          'p-2.5 rounded-lg border text-left transition-all cursor-pointer relative group flex items-center gap-2.5',
                          isFalta
                            ? 'bg-rose-50/80 border-rose-200 hover:border-rose-300'
                            : isSubstituto
                            ? 'bg-amber-50/80 border-amber-200 hover:border-amber-300'
                            : 'bg-white border-emerald-200/80 hover:border-emerald-400 hover:bg-emerald-50/40 shadow-xs'
                        )}
                      >
                        {/* Foto ou Iniciais */}
                        <div className="w-9 h-9 rounded-lg overflow-hidden shrink-0 border border-emerald-900/10 flex items-center justify-center bg-emerald-100/60 shadow-xs">
                          {c.foto ? (
                            <img
                              src={c.foto}
                              alt={c.nome}
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                (e.target as HTMLImageElement).style.display = 'none';
                              }}
                            />
                          ) : (
                            <span className="font-bold text-xs text-emerald-900 font-mono">
                              {getIniciais(c.nome)}
                            </span>
                          )}
                        </div>

                        {/* Dados do Colaborador */}
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] uppercase font-semibold text-emerald-900/50 tracking-wider truncate">
                              {label}
                            </span>
                            <span
                              className={cn(
                                'w-2 h-2 rounded-full shrink-0 ml-1',
                                isFalta
                                  ? 'bg-rose-500'
                                  : isSubstituto
                                  ? 'bg-amber-500'
                                  : 'bg-emerald-500'
                              )}
                            />
                          </div>
                          <p className="font-semibold text-xs text-emerald-950 truncate leading-snug">
                            {c.nome}
                          </p>
                          <p className="text-[10px] text-emerald-800/70 truncate">
                            {isFalta
                              ? c.motivoFalta || 'Falta Registrada'
                              : isSubstituto
                              ? `Sub: ${c.substitutoNome || 'Reserva'}`
                              : c.cargo}
                          </p>
                        </div>
                      </button>
                    );
                  })}
                </div>

                {/* Rodapé do Card com as duas equipes */}
                <div className="flex items-center justify-between pt-2 border-t border-emerald-900/10 text-[11px] text-emerald-900/60 font-medium">
                  <span className="truncate">Eq. 1: {v.equipe1Codigo}</span>
                  <span className="truncate">Eq. 2: {v.equipe2Codigo}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Confirmação de Presença / Falta */}
      {colaboradorSelecionado && (
        <AttendanceModal
          isOpen={modalAberto}
          colaborador={colaboradorSelecionado}
          colaboradoresReserva={colaboradoresReserva}
          veiculoId={veiculoIdSelecionado}
          onClose={() => setModalAberto(false)}
          onConfirm={handleConfirmarPresenca}
        />
      )}
    </div>
  );
};

files.oldContent:
import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  UserCheck,
  UserX,
  Search,
} from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  colaborador: Colaborador;
  colaboradoresReserva?: Colaborador[];
  veiculoId?: string;
  onClose: () => void;
  onSave?: (
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onConfirm?: (
    colaboradorId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  colaborador,
  colaboradoresReserva = [],
  onClose,
  onSave,
  onConfirm,
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador?.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(colaborador?.motivoFalta);
  const [observacao, setObservacao] = useState(colaborador?.observacao || '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador?.substitutoId || '');
  const [buscaSubstituto, setBuscaSubstituto] = useState('');

  if (!isOpen || !colaborador) return null;

  const substitutosFiltrados = (colaboradoresReserva || []).filter((sub) => {
    if (!sub || sub.id === colaborador.id) return false;
    if (!buscaSubstituto) return true;
    return (
      (sub.nome || '').toLowerCase().includes(buscaSubstituto.toLowerCase()) ||
      (sub.cargo || '').toLowerCase().includes(buscaSubstituto.toLowerCase())
    );
  });

  const handleSalvar = () => {
    const finalMotivo = status === 'falta' ? motivo : undefined;
    const finalObs = observacao.trim() || undefined;
    const finalSub = status === 'substituto' ? substitutoId : undefined;

    if (onConfirm) {
      onConfirm(colaborador.id, status, finalMotivo, finalObs, finalSub);
    } else if (onSave) {
      onSave(status, finalMotivo, finalObs, finalSub);
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="relative w-full max-w-lg rounded-2xl border border-border/80 bg-card p-6 shadow-2xl space-y-5">
        {/* Cabeçalho do Modal */}
        <div className="flex items-center justify-between border-b border-border/50 pb-3">
          <div className="flex items-center gap-3">
            <div className="w-14 h-14 rounded-2xl border-2 border-emerald-500/40 overflow-hidden shrink-0 shadow-md flex items-center justify-center bg-muted/40">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <span className="font-black text-foreground text-lg">
                  {getIniciais(colaborador.nome)}
                </span>
              )}
            </div>
            <div>
              <h3 className="font-bold text-base text-foreground">{colaborador.nome}</h3>
              <p className="text-xs text-muted-foreground">{colaborador.cargo}</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1 text-muted-foreground hover:bg-muted"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Seleção de Status */}
        <div className="space-y-2">
          <label className="text-xs font-semibold text-foreground">Status Operacional</label>
          <div className="grid grid-cols-3 gap-2">
            <button
              type="button"
              onClick={() => setStatus('presente')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all',
                status === 'presente'
                  ? 'border-emerald-500 bg-emerald-500/15 text-emerald-400 ring-2 ring-emerald-500/20'
                  : 'border-border/60 text-muted-foreground hover:bg-muted/40'
              )}
            >
              <CheckCircle2 className="w-5 h-5 mb-1" />
              <span>Presente</span>
            </button>

            <button
              type="button"
              onClick={() => setStatus('falta')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all',
                status === 'falta'
                  ? 'border-rose-500 bg-rose-500/15 text-rose-400 ring-2 ring-rose-500/20'
                  : 'border-border/60 text-muted-foreground hover:bg-muted/40'
              )}
            >
              <UserX className="w-5 h-5 mb-1" />
              <span>Falta</span>
            </button>

            <button
              type="button"
              onClick={() => setStatus('substituto')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all',
                status === 'substituto'
                  ? 'border-amber-500 bg-amber-500/15 text-amber-400 ring-2 ring-amber-500/20'
                  : 'border-border/60 text-muted-foreground hover:bg-muted/40'
              )}
            >
              <UserCheck className="w-5 h-5 mb-1" />
              <span>Substituto</span>
            </button>
          </div>
        </div>

        {/* Opções de Falta */}
        {status === 'falta' && (
          <div className="space-y-2 animate-in fade-in">
            <label className="text-xs font-semibold text-foreground">Motivo da Ausência</label>
            <select
              value={motivo}
              onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
              className="w-full h-10 px-3 rounded-xl border border-input bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-rose-500/30"
            >
              <option value="">Selecione o motivo...</option>
              {MOTIVOS_FALTA.map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </div>
        )}

        {/* Seleção de Substituto */}
        {status === 'substituto' && (
          <div className="space-y-3 animate-in fade-in">
            <label className="text-xs font-semibold text-foreground">Selecione o Colaborador Substituto</label>
            <div className="relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Filtrar operador por nome ou cargo..."
                value={buscaSubstituto}
                onChange={(e) => setBuscaSubstituto(e.target.value)}
                className="pl-9 h-9 text-xs"
              />
            </div>

            <div className="max-h-48 overflow-y-auto space-y-1.5 rounded-xl border border-border p-2 bg-muted/20">
              {substitutosFiltrados.length === 0 ? (
                <p className="text-center text-xs text-muted-foreground py-3">Nenhum operador reserva disponível.</p>
              ) : (
                substitutosFiltrados.map((sub) => (
                  <div
                    key={sub.id}
                    onClick={() => setSubstitutoId(sub.id)}
                    className={cn(
                      'flex items-center justify-between p-2 rounded-xl border cursor-pointer transition-all',
                      substitutoId === sub.id
                        ? 'border-amber-500 bg-amber-500/10'
                        : 'border-border/40 hover:bg-muted/30'
                    )}
                  >
                    <div className="flex items-center gap-2">
                      <div className="w-7 h-7 rounded-lg bg-card border flex items-center justify-center text-[10px] font-bold">
                        {getIniciais(sub.nome)}
                      </div>
                      <div>
                        <p className="text-xs font-medium text-foreground">{sub.nome}</p>
                        <p className="text-[10px] text-muted-foreground">{sub.cargo}</p>
                      </div>
                    </div>
                    {substitutoId === sub.id && (
                      <span className="text-xs font-bold text-amber-400">Selecionado</span>
                    )}
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* Observações */}
        <div className="space-y-2">
          <label className="text-xs font-semibold text-foreground">Observações Adicionais</label>
          <textarea
            value={observacao}
            onChange={(e) => setObservacao(e.target.value)}
            placeholder="Ex: Liberado para retorno médico, justificativa entregue à liderança..."
            className="w-full h-20 p-3 rounded-xl border border-input bg-card text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary resize-none"
          />
        </div>

        {/* Ações */}
        <div className="flex items-center justify-end gap-2 pt-2 border-t border-border/50">
          <Button type="button" variant="outline" onClick={onClose} size="sm">
            Cancelar
          </Button>
          <Button
            type="button"
            onClick={handleSalvar}
            size="sm"
            className="bg-emerald-600 hover:bg-emerald-500 text-white"
          >
            Confirmar Alteração
          </Button>
        </div>
      </div>
    </div>
  );
};

