import React, { useState } from 'react';
import {
  X,
  CheckCircle2,
  UserCheck,
  UserX,
  Search,
} from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface AttendanceModalProps {
  isOpen: boolean;
  colaborador: Colaborador;
  colaboradoresReserva?: Colaborador[];
  veiculoId?: string;
  onClose: () => void;
  onSave?: (
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onConfirm?: (
    colaboradorId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
}

const MOTIVOS_FALTA: MotivoFalta[] = [
  'Atestado Médico',
  'Falta Injustificada',
  'Folga Compensatória',
  'Treinamento / Integração',
  'Problema de Transporte',
  'Licença Especial',
];

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const AttendanceModal: React.FC<AttendanceModalProps> = ({
  isOpen,
  colaborador,
  colaboradoresReserva = [],
  onClose,
  onSave,
  onConfirm,
}) => {
  const [status, setStatus] = useState<StatusPresenca>(colaborador?.status || 'presente');
  const [motivo, setMotivo] = useState<MotivoFalta | undefined>(colaborador?.motivoFalta);
  const [observacao, setObservacao] = useState(colaborador?.observacao || '');
  const [substitutoId, setSubstitutoId] = useState<string>(colaborador?.substitutoId || '');
  const [buscaSubstituto, setBuscaSubstituto] = useState('');

  if (!isOpen || !colaborador) return null;

  const substitutosFiltrados = (colaboradoresReserva || []).filter((sub) => {
    if (!sub || sub.id === colaborador.id) return false;
    if (!buscaSubstituto) return true;
    return (
      (sub.nome || '').toLowerCase().includes(buscaSubstituto.toLowerCase()) ||
      (sub.cargo || '').toLowerCase().includes(buscaSubstituto.toLowerCase())
    );
  });

  const handleSalvar = () => {
    const finalMotivo = status === 'falta' ? motivo : undefined;
    const finalObs = observacao.trim() || undefined;
    const finalSub = status === 'substituto' ? substitutoId : undefined;

    if (onConfirm) {
      onConfirm(colaborador.id, status, finalMotivo, finalObs, finalSub);
    } else if (onSave) {
      onSave(status, finalMotivo, finalObs, finalSub);
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in duration-150">
      <div className="relative w-full max-w-lg rounded-2xl border border-emerald-900/15 bg-white p-6 shadow-2xl space-y-5">
        {/* Cabeçalho do Modal */}
        <div className="flex items-center justify-between border-b border-emerald-900/10 pb-3">
          <div className="flex items-center gap-3">
            <div className="w-14 h-14 rounded-2xl border-2 border-emerald-600/30 overflow-hidden shrink-0 shadow-sm flex items-center justify-center bg-emerald-50">
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover"
                />
              ) : (
                <span className="font-bold text-emerald-900 text-lg">
                  {getIniciais(colaborador.nome)}
                </span>
              )}
            </div>
            <div>
              <h3 className="font-bold text-base text-emerald-950">{colaborador.nome}</h3>
              <p className="text-xs text-emerald-800/70">{colaborador.cargo}</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1 text-emerald-900/50 hover:bg-emerald-50 hover:text-emerald-950"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Seleção de Status */}
        <div className="space-y-2">
          <label className="text-xs font-semibold text-emerald-950">Status Operacional</label>
          <div className="grid grid-cols-3 gap-2">
            <button
              type="button"
              onClick={() => setStatus('presente')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all cursor-pointer',
                status === 'presente'
                  ? 'border-emerald-600 bg-emerald-50 text-emerald-800 ring-2 ring-emerald-500/20'
                  : 'border-emerald-900/10 text-emerald-900/60 hover:bg-emerald-50/50'
              )}
            >
              <CheckCircle2 className="w-5 h-5 mb-1 text-emerald-600" />
              <span>Presente</span>
            </button>

            <button
              type="button"
              onClick={() => setStatus('falta')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all cursor-pointer',
                status === 'falta'
                  ? 'border-rose-500 bg-rose-50 text-rose-700 ring-2 ring-rose-500/20'
                  : 'border-emerald-900/10 text-emerald-900/60 hover:bg-emerald-50/50'
              )}
            >
              <UserX className="w-5 h-5 mb-1 text-rose-600" />
              <span>Falta</span>
            </button>

            <button
              type="button"
              onClick={() => setStatus('substituto')}
              className={cn(
                'flex flex-col items-center justify-center py-3 px-2 rounded-xl border text-xs font-bold transition-all cursor-pointer',
                status === 'substituto'
                  ? 'border-amber-500 bg-amber-50 text-amber-800 ring-2 ring-amber-500/20'
                  : 'border-emerald-900/10 text-emerald-900/60 hover:bg-emerald-50/50'
              )}
            >
              <UserCheck className="w-5 h-5 mb-1 text-amber-600" />
              <span>Substituto</span>
            </button>
          </div>
        </div>

        {/* Opções de Falta */}
        {status === 'falta' && (
          <div className="space-y-2 animate-in fade-in">
            <label className="text-xs font-semibold text-emerald-950">Motivo da Ausência</label>
            <select
              value={motivo}
              onChange={(e) => setMotivo(e.target.value as MotivoFalta)}
              className="w-full h-10 px-3 rounded-xl border border-emerald-200 bg-white text-xs text-emerald-950 focus:outline-none focus:ring-2 focus:ring-rose-500/30"
            >
              <option value="">Selecione o motivo...</option>
              {MOTIVOS_FALTA.map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </div>
        )}

        {/* Seleção de Substituto */}
        {status === 'substituto' && (
          <div className="space-y-3 animate-in fade-in">
            <label className="text-xs font-semibold text-emerald-950">Selecione o Colaborador Substituto</label>
            <div className="relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-emerald-800/50" />
              <Input
                placeholder="Filtrar operador por nome ou cargo..."
                value={buscaSubstituto}
                onChange={(e) => setBuscaSubstituto(e.target.value)}
                className="pl-9 h-9 text-xs bg-emerald-50/40 border-emerald-200 text-emerald-950 placeholder:text-emerald-900/40"
              />
            </div>

            <div className="max-h-48 overflow-y-auto space-y-1.5 rounded-xl border border-emerald-200 p-2 bg-emerald-50/30">
              {substitutosFiltrados.length === 0 ? (
                <p className="text-center text-xs text-emerald-800/60 py-3">Nenhum operador reserva disponível.</p>
              ) : (
                substitutosFiltrados.map((sub) => (
                  <button
                    key={sub.id}
                    type="button"
                    onClick={() => setSubstitutoId(sub.id)}
                    className={cn(
                      'w-full flex items-center justify-between p-2 rounded-lg text-left text-xs transition-colors cursor-pointer',
                      substitutoId === sub.id
                        ? 'bg-amber-100 text-amber-900 font-semibold border border-amber-300'
                        : 'bg-white hover:bg-emerald-50 text-emerald-950 border border-emerald-100'
                    )}
                  >
                    <span className="truncate">{sub.nome}</span>
                    <span className="text-[10px] text-emerald-700">{sub.cargo}</span>
                  </button>
                ))
              )}
            </div>
          </div>
        )}

        {/* Observações */}
        <div className="space-y-1">
          <label className="text-xs font-semibold text-emerald-950">Observações adicionais (opcional)</label>
          <textarea
            value={observacao}
            onChange={(e) => setObservacao(e.target.value)}
            placeholder="Ex: Justificativa comunicada pelo supervisor de turno..."
            rows={2}
            className="w-full p-2.5 rounded-xl border border-emerald-200 bg-white text-xs text-emerald-950 placeholder:text-emerald-900/40 focus:outline-none focus:ring-2 focus:ring-emerald-500/30 resize-none"
          />
        </div>

        {/* Ações */}
        <div className="flex items-center justify-end gap-2 pt-2 border-t border-emerald-900/10">
          <Button
            type="button"
            variant="outline"
            onClick={onClose}
            className="border-emerald-200 text-emerald-900 hover:bg-emerald-50"
          >
            Cancelar
          </Button>
          <Button
            type="button"
            onClick={handleSalvar}
            className="bg-emerald-600 hover:bg-emerald-700 text-white font-semibold shadow-sm"
          >
            Salvar Status
          </Button>
        </div>
      </div>
    </div>
  );
};

