                  className="h-10 text-xs bg-emerald-50/30 border-emerald-200 text-emerald-950 placeholder:text-emerald-900/40"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-emerald-900/70 mb-1">Função / Cargo</label>
