          {/* Equipe 2 */}
          <div className="space-y-3 pt-3 border-t border-emerald-900/10">
            <div className="flex items-center gap-2 text-xs font-bold text-emerald-950 uppercase tracking-wider">
              <Users className="w-4 h-4 text-emerald-600" />
