            className={cn(
              'px-2 py-0.5 text-[10px] font-bold rounded-md uppercase tracking-wider shrink-0 transition-colors',
              cfg.badgeClass
            )}
          >
            {cfg.label}
          </span>
        </div>

        {/* Informações Centrais com FOTO GRANDE E BEM VISÍVEL */}
        <div className="flex items-center gap-3">
          {/* Avatar com tamanho expandido e anel de destaque */}
          <div className="relative shrink-0">
            <div
              className={cn(
                'w-16 h-16 sm:w-18 sm:h-18 rounded-2xl overflow-hidden bg-emerald-50 shadow-sm flex items-center justify-center transition-transform group-hover:scale-105',
                cfg.ringClass
              )}
            >
              {colaborador.foto ? (
                <img
                  src={colaborador.foto}
                  alt={colaborador.nome}
                  className="w-full h-full object-cover object-center"
                />
              ) : (
                <span className="font-extrabold text-base sm:text-lg text-emerald-900 tracking-tight">
                  {getIniciais(colaborador.nome)}
                </span>
              )}
            </div>

            {/* Ícone sutil no canto inferior do avatar */}
            <span
              className={cn(
                'absolute -bottom-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center shadow-sm border-2 border-white text-white text-[10px]',
                colaborador.status === 'presente' && 'bg-emerald-600',
                colaborador.status === 'falta' && 'bg-rose-600',
                colaborador.status === 'substituto' && 'bg-amber-600'
              )}
            >
              {colaborador.status === 'presente' && <CheckCircle2 className="w-3 h-3" />}
              {colaborador.status === 'falta' && <AlertCircle className="w-3 h-3" />}
              {colaborador.status === 'substituto' && <UserCheck className="w-3 h-3" />}
            </span>
          </div>

          {/* Dados do Colaborador com tipografia nítida */}
          <div className="min-w-0 flex-1">
            <h4 className="font-bold text-sm text-emerald-950 truncate group-hover:text-emerald-700 transition-colors">
              {colaborador.nome}
            </h4>
            <p className="text-xs text-emerald-800/80 truncate font-medium">
              {colaborador.cargo}
            </p>

            {colaborador.status === 'falta' && colaborador.motivoFalta && (
              <p className="mt-1 text-[11px] font-semibold text-rose-700 truncate bg-rose-50 px-1.5 py-0.5 rounded border border-rose-200 inline-block max-w-full">
                {colaborador.motivoFalta}
              </p>
            )}

            {colaborador.status === 'substituto' && colaborador.substitutoNome && (
              <p className="mt-1 text-[11px] font-semibold text-amber-800 truncate bg-amber-50 px-1.5 py-0.5 rounded border border-amber-200 inline-block max-w-full">
                Subst.: {colaborador.substitutoNome}
              </p>
            )}

            <div className="mt-1.5 flex items-center gap-2 text-[10px] text-emerald-900/60 font-medium">
              <span>Matrícula: {colaborador.matricula || '-'}</span>
            </div>
          </div>
        </div>

        {/* Rodapé com ação de alterar presença */}
        <div className="mt-3 pt-2 border-t border-emerald-900/5 flex items-center justify-between text-[11px] text-emerald-800 font-semibold group-hover:text-emerald-600">
          <span>Alterar presença</span>
          <span className="text-xs group-hover:translate-x-0.5 transition-transform">→</span>
        </div>
      </div>
    );
  };

  if (!veiculosFiltrados || veiculosFiltrados.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-12 text-center rounded-2xl border border-emerald-900/10 bg-white shadow-sm space-y-3">
        <div className="w-14 h-14 rounded-2xl bg-emerald-50 border border-emerald-200 flex items-center justify-center text-emerald-700">
          <Car className="w-7 h-7" />
        </div>
        <h3 className="text-base font-bold text-emerald-950">Nenhum veículo encontrado</h3>
        <p className="text-xs text-emerald-800/70 max-w-md">
          Não há veículos registrados para a unidade selecionada nesta data. Você pode cadastrar uma nova equipe ou alterar o filtro regional.
        </p>
      </div>
    );
  }

  return (
    <div className="w-full space-y-6">
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-5">
        {veiculosFiltrados.map((veiculo) => {
          const assentos = [
            veiculo.assentos?.motorista,
            veiculo.assentos?.frenteDir,
            veiculo.assentos?.trasEsq,
            veiculo.assentos?.trasDir,
          ].filter(Boolean) as Colaborador[];

          const totalPresentes = assentos.filter(
            (c) => c.status === 'presente' || c.status === 'substituto'
          ).length;
          const totalFaltas = assentos.filter((c) => c.status === 'falta').length;

          return (
            <div
              key={veiculo.id}
              className="rounded-2xl border border-emerald-900/15 bg-white shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col"
            >
              {/* Cabeçalho do Card do Veículo */}
              <div className="px-5 py-3.5 bg-gradient-to-r from-emerald-50 via-white to-emerald-50/30 border-b border-emerald-900/10 flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-emerald-600 text-white flex items-center justify-center font-bold text-sm shadow-sm shadow-emerald-700/20">
                    <Car className="w-5 h-5" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-extrabold text-base text-emerald-950 tracking-tight">
                        {veiculo.prefixo}
                      </span>
                      <span className="px-2 py-0.5 text-xs font-mono font-bold uppercase rounded bg-white text-emerald-900 border border-emerald-200 shadow-2xs">
                        {veiculo.placa}
                      </span>
                    </div>
                    <p className="text-xs text-emerald-900/70 font-medium">
                      {veiculo.modelo} • {veiculo.ano} •{' '}
                      <span className="capitalize font-semibold text-emerald-950">
                        {veiculo.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'}
                      </span>
                    </p>
                  </div>
                </div>

                {/* Resumo de Presença do Veículo */}
                <div className="flex items-center gap-2">
                  <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-emerald-100/70 border border-emerald-200 text-xs font-bold text-emerald-900">
                    <Users className="w-3.5 h-3.5 text-emerald-700" />
                    <span>{totalPresentes} / 4 em campo</span>
                  </div>
                  {totalFaltas > 0 && (
                    <span className="px-2 py-1 rounded-lg bg-rose-100 border border-rose-200 text-xs font-bold text-rose-800">
                      {totalFaltas} {totalFaltas === 1 ? 'falta' : 'faltas'}
                    </span>
                  )}
                </div>
              </div>

              {/* Informações das Duas Equipes que compartilham o veículo */}
              <div className="px-5 py-2.5 bg-white border-b border-emerald-900/5 flex items-center justify-between text-xs text-emerald-900/80">
                <div className="flex items-center gap-1.5">
                  <span className="w-2 h-2 rounded-full bg-emerald-600" />
                  <span className="font-semibold text-emerald-950">Eq. 1 (Frente):</span>
                  <span>{veiculo.equipe1Codigo || 'Equipe 1'}</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <span className="w-2 h-2 rounded-full bg-emerald-600" />
                  <span className="font-semibold text-emerald-950">Eq. 2 (Trás):</span>
                  <span>{veiculo.equipe2Codigo || 'Equipe 2'}</span>
                </div>
              </div>

              {/* Grid dos 4 Assentos do Veículo com FOTOS EM DESTAQUE */}
              <div className="p-4 grid grid-cols-1 sm:grid-cols-2 gap-3.5 flex-1 bg-white">
                {/* 1. Motorista (Equipe 1) */}
                {renderAssentoCard(
                  veiculo.assentos?.motorista,
                  'Motorista',
                  'Equipe 1',
                  veiculo.id
                )}

                {/* 2. Frente Passageiro (Equipe 1) */}
                {renderAssentoCard(
                  veiculo.assentos?.frenteDir,
                  'Passageiro Dianteiro',
                  'Equipe 1',
                  veiculo.id
                )}

                {/* 3. Traseiro Esquerdo (Equipe 2) */}
                {renderAssentoCard(
                  veiculo.assentos?.trasEsq,
                  'Passageiro Traseiro 1',
                  'Equipe 2',
                  veiculo.id
                )}

                {/* 4. Traseiro Direito (Equipe 2) */}
                {renderAssentoCard(
                  veiculo.assentos?.trasDir,
                  'Passageiro Traseiro 2',
                  'Equipe 2',
                  veiculo.id
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Modal de Gestão de Presença */}
      {modalColab && (
        <AttendanceModal
          isOpen={Boolean(modalColab)}
          colaborador={modalColab.colaborador}
          colaboradoresReserva={colaboradoresReserva}
          veiculoId={modalColab.veiculoId}
          onClose={() => setModalColab(null)}
          onSave={handleSalvarStatus}
        />
      )}
    </div>
  );
};

