import React, { useState } from 'react';
import {
  Car,
  User,
  Users,
  CheckCircle2,
  AlertCircle,
  UserCheck,
  Shield,
  Layers,
  MapPin,
  Clock,
  Sparkles,
  Phone,
  Compass,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { AttendanceModal } from './AttendanceModal';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedDate?: Date;
  selectedRegional?: Regional | string;
  onUpdateColaboradorStatus?: (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onEditarVeiculo?: (veiculo: Veiculo) => void;
  onVerDetalhesVeiculo?: (veiculo: Veiculo) => void;
  onExcluirVeiculo?: (veiculoId: string) => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; badgeClass: string; ringClass: string; dotClass: string }> = {
  presente: {
    label: 'Presente',
    badgeClass: 'bg-emerald-600 text-white shadow-sm',
    ringClass: 'ring-2 ring-emerald-500 border-emerald-400',
    dotClass: 'bg-emerald-500',
  },
  falta: {
    label: 'Falta',
    badgeClass: 'bg-rose-600 text-white shadow-sm',
    ringClass: 'ring-2 ring-rose-500 border-rose-400',
    dotClass: 'bg-rose-500',
  },
  substituto: {
    label: 'Substituto',
    badgeClass: 'bg-amber-600 text-white shadow-sm',
    ringClass: 'ring-2 ring-amber-500 border-amber-400',
    dotClass: 'bg-amber-500',
  },
};

const getIniciais = (nome?: string) => {
  if (!nome) return 'CO';
  const partes = nome.trim().split(' ');
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedDate = new Date(),
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onEditarVeiculo,
  onVerDetalhesVeiculo,
  onExcluirVeiculo,
}) => {
  const [modalColab, setModalColab] = useState<{
    colaborador: Colaborador;
    veiculoId: string;
  } | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    if (selectedRegional === 'todas') return true;
    return v.regional === selectedRegional;
  });

  const handleSalvarStatus = (
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => {
    if (!modalColab) return;
    if (onUpdateColaboradorStatus) {
      onUpdateColaboradorStatus(
        modalColab.veiculoId,
        modalColab.colaborador.id,
        novoStatus,
        motivo,
        observacao,
        substitutoId
      );
    }
    setModalColab(null);
  };

  /* Renderiza cada um dos 4 assentos dentro da cabine vista de cima */
  const renderAssentoTopView = (
    colaborador: Colaborador | undefined,
    tituloPosicao: string,
    equipeLabel: string,
    veiculoId: string,
    ehMotorista = false
  ) => {
    if (!colaborador) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-xl border border-dashed border-emerald-900/20 bg-emerald-50/50 text-center min-h-[140px]">
          <span className="text-[10px] font-bold text-emerald-900/50 uppercase tracking-wider">
            {tituloPosicao}
          </span>
          <p className="text-xs text-emerald-800/60 mt-1 font-medium">Vaga Disponível</p>
        </div>
      );
    }

    const cfg = statusBadgeConfig[colaborador.status] || statusBadgeConfig.presente;

    return (
      <div
        onClick={() => setModalColab({ colaborador, veiculoId })}
        className={cn(
          'group relative flex flex-col items-center text-center p-3 rounded-xl border transition-all duration-200 cursor-pointer bg-white hover:shadow-lg',
          'border-emerald-900/10 hover:border-emerald-600/40 hover:-translate-y-0.5'
        )}
      >
        {/* Posição e Badge de Status */}
        <div className="w-full flex items-center justify-between gap-1 mb-2">
          <div className="flex items-center gap-1 min-w-0">
            {ehMotorista && (
              <span className="w-2 h-2 rounded-full bg-emerald-600 shrink-0" title="Volante / Motorista" />
            )}
            <span className="text-[10px] font-bold tracking-wider text-emerald-900/70 uppercase truncate">
              {tituloPosicao}
            </span>
          </div>
          <span
            className={cn(
              'px-2 py-0.5 text-[9px] font-extrabold rounded-md uppercase tracking-wider shrink-0 transition-colors',
              cfg.badgeClass
            )}
          >
            {cfg.label}
          </span>
        </div>

        {/* Foto Grande e Visível em destaque de cabine */}
        <div className="relative my-1">
          <div
            className={cn(
              'w-20 h-20 sm:w-22 sm:h-22 rounded-2xl overflow-hidden bg-emerald-50/80 shadow-md flex items-center justify-center transition-transform group-hover:scale-105',
              cfg.ringClass
            )}
          >
            {colaborador.foto ? (
              <img
                src={colaborador.foto}
                alt={colaborador.nome}
                className="w-full h-full object-cover object-center"
              />
            ) : (
              <span className="font-extrabold text-xl text-emerald-900 tracking-tight">
                {getIniciais(colaborador.nome)}
              </span>
            )}
          </div>

          {/* Ícone de status no canto da foto */}
          <span
            className={cn(
              'absolute -bottom-1 -right-1 w-6 h-6 rounded-full flex items-center justify-center shadow-md border-2 border-white text-white text-[11px]',
              colaborador.status === 'presente' && 'bg-emerald-600',
              colaborador.status === 'falta' && 'bg-rose-600',
              colaborador.status === 'substituto' && 'bg-amber-600'
            )}
          >
            {colaborador.status === 'presente' && <CheckCircle2 className="w-3.5 h-3.5" />}
            {colaborador.status === 'falta' && <AlertCircle className="w-3.5 h-3.5" />}
            {colaborador.status === 'substituto' && <UserCheck className="w-3.5 h-3.5" />}
          </span>
        </div>

        {/* Nome e Cargo bem legíveis */}
        <div className="w-full mt-2 min-w-0">
          <h4 className="font-bold text-sm text-emerald-950 truncate group-hover:text-emerald-700 transition-colors" title={colaborador.nome}>
            {colaborador.nome}
          </h4>
          <p className="text-xs text-emerald-800/80 truncate font-medium">
            {colaborador.cargo}
          </p>

          <span className="inline-block mt-1 text-[10px] text-emerald-900/60 font-semibold px-2 py-0.5 bg-emerald-50 rounded">
            {equipeLabel}
          </span>

          {colaborador.status === 'falta' && colaborador.motivoFalta && (
            <p className="mt-1 text-[11px] font-semibold text-rose-700 truncate bg-rose-50 px-1.5 py-0.5 rounded border border-rose-200">
              {colaborador.motivoFalta}
            </p>
          )}

          {colaborador.status === 'substituto' && colaborador.substitutoNome && (
            <p className="mt-1 text-[11px] font-semibold text-amber-800 truncate bg-amber-50 px-1.5 py-0.5 rounded border border-amber-200">
              Subst.: {colaborador.substitutoNome}
            </p>
          )}
        </div>

        {/* Rodapé do assento */}
        <div className="w-full mt-2 pt-1.5 border-t border-emerald-900/10 flex items-center justify-center text-[10px] text-emerald-800 font-semibold group-hover:text-emerald-600">
          <span>Alterar presença →</span>
        </div>
      </div>
    );
  };

  return (
    <div className="w-full space-y-6">
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 px-4 rounded-2xl border border-dashed border-emerald-900/20 bg-white text-center">
          <div className="w-14 h-14 rounded-2xl bg-emerald-50 border border-emerald-200 flex items-center justify-center text-emerald-600 mb-3">
            <Car className="w-7 h-7" />
          </div>
          <h3 className="text-base font-bold text-emerald-950">Nenhum veículo encontrado</h3>
          <p className="text-xs text-emerald-900/60 max-w-sm mt-1">
            Não há veículos cadastrados para a regional selecionada ou os filtros atuais.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = veiculo.assentos || ({} as any);
            const totalAssentos = 4;
            const presentes = [
              assentos.motorista,
              assentos.frenteDir,
              assentos.trasEsq,
              assentos.trasDir,
            ].filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;

            return (
              <div
                key={veiculo.id}
                className="rounded-2xl border border-emerald-900/10 bg-white shadow-sm overflow-hidden flex flex-col"
              >
                {/* Cabeçalho do Card do Veículo */}
                <div className="px-5 py-4 border-b border-emerald-900/10 bg-gradient-to-r from-emerald-50/50 to-white flex flex-wrap items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-emerald-600 text-white flex items-center justify-center font-bold text-base shadow-sm">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="font-bold text-base text-emerald-950 tracking-tight">
                          {veiculo.prefixo}
                        </h3>
                        <span className="px-2 py-0.5 rounded text-[11px] font-mono font-semibold bg-emerald-100 text-emerald-800 border border-emerald-200">
                          {veiculo.placa}
                        </span>
                        <span className="text-xs text-emerald-900/70 font-medium">
                          {veiculo.modelo} ({veiculo.ano})
                        </span>
                      </div>
                      <div className="flex items-center gap-2 mt-0.5 text-xs text-emerald-900/60">
                        <MapPin className="w-3.5 h-3.5 text-emerald-600" />
                        <span>
                          {veiculo.regional === 'agua_clara' ? 'Água Clara - MS' : 'Ribas do Rio Pardo - MS'}
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <span className="text-xs font-semibold px-2.5 py-1 rounded-lg bg-emerald-100/80 text-emerald-900 border border-emerald-200 tabular-nums">
                      {presentes} de {totalAssentos} presentes
                    </span>
                  </div>
                </div>

                {/* Estrutura Visual: Carro Visto de Cima com as 4 Pessoas */}
                <div className="p-4 sm:p-5 flex-1 bg-emerald-50/20">
                  <div className="relative max-w-xl mx-auto rounded-3xl border-2 border-emerald-800/20 bg-emerald-900/[0.03] p-4 sm:p-6 shadow-inner">
                    {/* Frente do Carro (Capô / Para-brisa) */}
                    <div className="relative mb-4 flex flex-col items-center">
                      <div className="w-36 sm:w-44 h-5 rounded-t-2xl bg-emerald-800/15 border-t-2 border-x-2 border-emerald-700/30 flex items-center justify-center">
                        <span className="text-[10px] font-bold text-emerald-900/60 uppercase tracking-widest">
                          FRENTE DO VEÍCULO
