import React, { useState } from 'react';
import {
  Car,
  User,
  Users,
  CheckCircle2,
  AlertCircle,
  UserCheck,
  Shield,
  Layers,
  MapPin,
  Clock,
  ChevronRight,
  UserX,
  Phone,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';
import { AttendanceModal } from './AttendanceModal';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional: Regional | string;
  selectedDate?: Date;
  onUpdateStatus?: (
    colaboradorId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onTransferirColaborador?: (
    colaboradorId: string,
    origemVeiculoId: string,
    destinoVeiculoId: string,
    destinoPosicao: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir'
  ) => void;
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateStatus,
}) => {
  const [modalColaborador, setModalColaborador] = useState<Colaborador | null>(null);
  const [modalVeiculoId, setModalVeiculoId] = useState<string | null>(null);

  const veiculosFiltrados = veiculos.filter((v) => {
    if (!v) return false;
    if (selectedRegional === 'todas') return true;
    return v.regional === selectedRegional;
  });

  const getIniciais = (nome?: string) => {
    if (!nome) return 'CO';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
    return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
  };

  const getStatusBadge = (status?: StatusPresenca) => {
    switch (status) {
      case 'presente':
        return (
          <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-100 text-emerald-800 border border-emerald-300">
            <span className="w-1.5 h-1.5 rounded-full bg-emerald-600 animate-pulse" />
            Presente
          </span>
        );
      case 'falta':
        return (
          <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-rose-100 text-rose-800 border border-rose-300">
            <span className="w-1.5 h-1.5 rounded-full bg-rose-600" />
            Falta
          </span>
        );
      case 'substituto':
        return (
          <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-amber-100 text-amber-800 border border-amber-300">
            <span className="w-1.5 h-1.5 rounded-full bg-amber-600" />
            Substituto
          </span>
        );
      default:
        return null;
    }
  };

  const renderAssentoCockpit = (
    colab: Colaborador | undefined,
    posicaoTitulo: string,
    lado: 'esq' | 'dir',
    fila: 'frente' | 'tras',
    veiculoId: string
  ) => {
    if (!colab) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed border-emerald-900/15 bg-white/60 min-h-[140px] text-center">
          <div className="w-12 h-12 rounded-full border border-dashed border-emerald-300 flex items-center justify-center text-emerald-800/40 mb-1">
            <User className="w-5 h-5" />
          </div>
          <span className="text-[11px] font-semibold text-emerald-950/60">{posicaoTitulo}</span>
          <span className="text-[10px] text-emerald-800/50">Vago</span>
        </div>
      );
    }

    const isFalta = colab.status === 'falta';
    const isSub = colab.status === 'substituto';

    return (
      <button
        type="button"
        onClick={() => {
          setModalColaborador(colab);
          setModalVeiculoId(veiculoId);
        }}
        className={cn(
          'relative group flex flex-col items-center text-center p-3 rounded-2xl border transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md hover:-translate-y-0.5',
          isFalta
            ? 'bg-rose-50/70 border-rose-200 hover:border-rose-400'
            : isSub
            ? 'bg-amber-50/70 border-amber-200 hover:border-amber-400'
            : 'bg-white border-emerald-900/10 hover:border-emerald-500 hover:bg-emerald-50/30'
        )}
      >
        {/* Posição no veículo (tag superior) */}
        <div className="flex items-center justify-between w-full mb-2">
          <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-900/60 bg-emerald-100/60 px-2 py-0.5 rounded-md">
            {posicaoTitulo}
          </span>
          {getStatusBadge(colab.status)}
        </div>

        {/* Foto em Destaque Alto com Moldura de Assento do Carro */}
        <div className="relative mb-2">
          <div
            className={cn(
              'w-20 h-20 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-2 shadow-md transition-transform group-hover:scale-105 flex items-center justify-center bg-emerald-50',
              isFalta
                ? 'border-rose-400 ring-2 ring-rose-400/20'
                : isSub
                ? 'border-amber-400 ring-2 ring-amber-400/20'
                : 'border-emerald-600 ring-2 ring-emerald-500/20'
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className={cn(
                  'w-full h-full object-cover transition-all',
                  isFalta && 'grayscale contrast-125 opacity-70'
                )}
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <span className="text-xl font-bold text-emerald-900 font-sans">
                {getIniciais(colab.nome)}
              </span>
            )}
          </div>

          {/* Indicador de Status Rápido no Canto da Foto */}
          <div
            className={cn(
              'absolute -bottom-1 -right-1 w-6 h-6 rounded-full border-2 border-white flex items-center justify-center shadow-sm',
              isFalta ? 'bg-rose-600 text-white' : isSub ? 'bg-amber-500 text-white' : 'bg-emerald-600 text-white'
            )}
          >
            {isFalta ? (
              <UserX className="w-3.5 h-3.5" />
            ) : isSub ? (
              <UserCheck className="w-3.5 h-3.5" />
            ) : (
              <CheckCircle2 className="w-3.5 h-3.5" />
            )}
          </div>
        </div>

        {/* Informações do Colaborador com Legibilidade Clara */}
        <div className="w-full">
          <h4 className="text-xs sm:text-sm font-bold text-emerald-950 truncate max-w-full">
            {colab.nome}
          </h4>
          <p className="text-[11px] text-emerald-800/70 font-medium truncate mt-0.5">
            {colab.cargo}
          </p>

          {colab.substitutoNome && (
            <p className="text-[10px] text-amber-800 font-semibold truncate mt-1 bg-amber-100/80 px-1.5 py-0.5 rounded">
              Subst: {colab.substitutoNome}
            </p>
          )}

          {isFalta && colab.motivoFalta && (
            <p className="text-[10px] text-rose-700 font-semibold truncate mt-1 bg-rose-100/80 px-1.5 py-0.5 rounded">
              {colab.motivoFalta}
            </p>
          )}
        </div>
      </button>
    );
  };

  return (
    <div className="w-full space-y-6">
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center rounded-2xl border border-emerald-900/10 bg-white shadow-sm">
          <Car className="w-12 h-12 text-emerald-700/40 mb-3" />
          <h3 className="text-base font-bold text-emerald-950">Nenhum veículo encontrado</h3>
          <p className="text-xs text-emerald-900/60 max-w-sm mt-1">
            Não há veículos cadastrados para o filtro selecionado no momento.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const motorista = veiculo.assentos?.motorista;
            const passageiroFrente = veiculo.assentos?.frenteDir;
            const trasEsq = veiculo.assentos?.trasEsq;
            const trasDir = veiculo.assentos?.trasDir;

            const totalOperadores = [motorista, passageiroFrente, trasEsq, trasDir].filter(Boolean).length;
            const presentes = [motorista, passageiroFrente, trasEsq, trasDir].filter(
              (c) => c && (c.status === 'presente' || c.status === 'substituto')
            ).length;
            const faltas = [motorista, passageiroFrente, trasEsq, trasDir].filter(
              (c) => c && c.status === 'falta'
            ).length;

            return (
              <div
                key={veiculo.id}
                className="rounded-2xl border border-emerald-900/10 bg-white shadow-sm hover:shadow-md transition-shadow duration-200 overflow-hidden flex flex-col"
              >
                {/* Cabeçalho do Card com Identificação do Veículo */}
                <div className="p-4 bg-emerald-50/50 border-b border-emerald-900/10 flex flex-wrap items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-white border border-emerald-300 flex items-center justify-center text-emerald-700 shadow-sm shrink-0">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="text-base font-bold text-emerald-950 tracking-tight">
                          {veiculo.prefixo}
                        </span>
                        <span className="text-xs font-mono font-semibold px-2 py-0.5 rounded-md bg-white border border-emerald-200 text-emerald-900 shadow-2xs">
                          {veiculo.placa}
                        </span>
                        <Badge
                          variant="secondary"
                          className={cn(
                            'text-[10px] font-semibold uppercase tracking-wider',
                            veiculo.regional === 'ribas'
                              ? 'bg-emerald-100 text-emerald-900 border-emerald-300'
                              : 'bg-blue-100 text-blue-900 border-blue-300'
                          )}
                        >
                          {veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                        </Badge>
                      </div>
                      <p className="text-xs text-emerald-900/60 font-medium">
                        {veiculo.modelo} • {veiculo.ano}
                      </p>
                    </div>
                  </div>

                  {/* Resumo de Lotação do Veículo */}
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-semibold px-2.5 py-1 rounded-lg bg-emerald-100/80 text-emerald-900 border border-emerald-200">
                      {presentes} de {totalOperadores} em campo
                    </span>
                    {faltas > 0 && (
                      <span className="text-xs font-semibold px-2 py-1 rounded-lg bg-rose-100 text-rose-800 border border-rose-200 flex items-center gap-1">
                        <AlertCircle className="w-3.5 h-3.5" />
                        {faltas} falta{faltas > 1 ? 's' : ''}
                      </span>
                    )}
                  </div>
                </div>

                {/* Estrutura do Veículo Vista de Cima (Top-Down Car Cabin Layout) */}
                <div className="p-4 sm:p-5 flex-1 flex flex-col justify-center">
                  <div className="relative mx-auto w-full max-w-xl rounded-3xl border-2 border-emerald-900/20 bg-slate-50/70 p-4 sm:p-6 shadow-inner">
                    {/* Para-brisa Dianteiro (Frente do Carro) */}
                    <div className="relative mb-5 flex flex-col items-center">
                      <div className="w-44 sm:w-56 h-3 rounded-t-full bg-emerald-600/30 border-t-2 border-emerald-600/50" />
                      <div className="w-52 sm:w-64 h-2 rounded-t-lg bg-emerald-900/10" />
                      <div className="flex items-center justify-between w-full px-4 text-[10px] font-mono text-emerald-900/40 uppercase tracking-widest mt-1">
                        <span>Frente / Painel</span>
                        <span className="w-2 h-2 rounded-full bg-emerald-500/40" />
                      </div>
                    </div>

                    {/* Grade dos 4 Assentos (Visão de Cima: Frente e Traseira) */}
                    <div className="space-y-4">
                      {/* Fila Dianteira (Motorista à Esquerda + Frente Direita) */}
                      <div>
                        <div className="text-[10px] font-bold uppercase tracking-wider text-emerald-900/50 mb-1.5 px-1 flex items-center justify-between">
                          <span>Assentos Dianteiros</span>
                          <span className="text-[9px] font-mono font-medium text-emerald-800/60 bg-emerald-100/60 px-1.5 py-0.5 rounded">
                            {veiculo.equipe1Codigo || 'Equipe 1'}
                          </span>
                        </div>
                        <div className="grid grid-cols-2 gap-3 sm:gap-4">
                          {renderAssentoCockpit(
                            motorista,
                            'Motorista (LE)',
                            'esq',
                            'frente',
                            veiculo.id
                          )}
                          {renderAssentoCockpit(
                            passageiroFrente,
                            'Carona (LD)',
                            'dir',
                            'frente',
                            veiculo.id
                          )}
                        </div>
                      </div>

                      {/* Divisória Central da Cabine */}
                      <div className="relative flex items-center justify-center py-1">
                        <div className="w-full border-t border-dashed border-emerald-900/20" />
                        <span className="absolute bg-slate-100 px-2 text-[9px] font-mono text-emerald-900/50 uppercase">
                          Divisória Cabine
                        </span>
                      </div>

                      {/* Fila Traseira (Trás Esquerda + Trás Direita) */}
                      <div>
                        <div className="text-[10px] font-bold uppercase tracking-wider text-emerald-900/50 mb-1.5 px-1 flex items-center justify-between">
                          <span>Assentos Traseiros</span>
                          <span className="text-[9px] font-mono font-medium text-emerald-800/60 bg-emerald-100/60 px-1.5 py-0.5 rounded">
                            {veiculo.equipe2Codigo || 'Equipe 2'}
                          </span>
                        </div>
                        <div className="grid grid-cols-2 gap-3 sm:gap-4">
                          {renderAssentoCockpit(
                            trasEsq,
                            'Traseiro (LE)',
                            'esq',
                            'tras',
                            veiculo.id
                          )}
                          {renderAssentoCockpit(
                            trasDir,
                            'Traseiro (LD)',
                            'dir',
                            'tras',
                            veiculo.id
                          )}
                        </div>
                      </div>
                    </div>

                    {/* Vidro Traseiro (Traseira do Carro) */}
                    <div className="mt-5 flex flex-col items-center">
                      <div className="w-44 sm:w-56 h-2 rounded-b-full bg-emerald-900/15 border-b border-emerald-900/30" />
                      <span className="text-[9px] font-mono text-emerald-900/40 uppercase tracking-widest mt-1">
                        Traseira
                      </span>
                    </div>
                  </div>
                </div>

                {/* Rodapé do Card com Instrução Limpa */}
                <div className="px-4 py-2.5 bg-emerald-50/30 border-t border-emerald-900/10 flex items-center justify-between text-[11px] text-emerald-900/70">
                  <span>Clique no operador para alterar presença, apontar falta ou substituto</span>
                  <ChevronRight className="w-4 h-4 text-emerald-700/40" />
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Gestão de Presença / Falta */}
      {modalColaborador && (
        <AttendanceModal
          isOpen={!!modalColaborador}
          colaborador={modalColaborador}
          colaboradoresReserva={colaboradoresReserva}
          veiculoId={modalVeiculoId || undefined}
          onClose={() => {
            setModalColaborador(null);
            setModalVeiculoId(null);
          }}
          onConfirm={(colabId, status, motivo, obs, subId) => {
            onUpdateStatus?.(colabId, status, motivo, obs, subId);
            setModalColaborador(null);
            setModalVeiculoId(null);
          }}
        />
      )}
    </div>
  );
};

