import React, { useState } from 'react';
import {
  Car,
  User,
  Users,
  CheckCircle2,
  AlertCircle,
  UserCheck,
  Shield,
  Layers,
  MapPin,
  Clock,
  ChevronRight,
  UserX,
  Phone,
} from 'lucide-react';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';
import { AttendanceModal } from './AttendanceModal';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional: Regional | string;
  selectedDate?: Date;
  onUpdateStatus?: (
    colaboradorId: string,
    status: StatusPresenca,
    motivo?: MotivoFalta,
    observacao?: string,
    substitutoId?: string
  ) => void;
  onTransferirColaborador?: (
    colaboradorId: string,
    origemVeiculoId: string,
    destinoVeiculoId: string,
    destinoPosicao: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir'
  ) => void;
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateStatus,
}) => {
  const [modalColaborador, setModalColaborador] = useState<Colaborador | null>(null);
  const [modalVeiculoId, setModalVeiculoId] = useState<string | null>(null);

  const veiculosFiltrados = veiculos.filter((v) => {
    if (!v) return false;
    if (selectedRegional === 'todas') return true;
    return v.regional === selectedRegional;
  });

  const getIniciais = (nome?: string) => {
    if (!nome) return 'CO';
    const partes = nome.trim().split(' ');
    if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
    return (partes[0][0] + (partes[partes.length - 1]?.[0] || '')).toUpperCase();
  };

  const getStatusBadge = (status?: StatusPresenca) => {
    switch (status) {
      case 'presente':
        return (
          <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-100 text-emerald-800 border border-emerald-300">
            <span className="w-1.5 h-1.5 rounded-full bg-emerald-600 animate-pulse" />
            Presente
          </span>
        );
      case 'falta':
        return (
          <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-rose-100 text-rose-800 border border-rose-300">
            <span className="w-1.5 h-1.5 rounded-full bg-rose-600" />
            Falta
          </span>
        );
      case 'substituto':
        return (
          <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-amber-100 text-amber-800 border border-amber-300">
            <span className="w-1.5 h-1.5 rounded-full bg-amber-600" />
            Substituição
          </span>
        );
      default:
        return null;
    }
  };

  const renderAssentoCockpit = (
    colab: Colaborador | undefined,
    posicaoTitulo: string,
    lado: 'esq' | 'dir',
    fila: 'frente' | 'tras',
    veiculoId: string
  ) => {
    if (!colab) {
      return (
        <div className="flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed border-emerald-900/15 bg-white/60 min-h-[140px] text-center">
          <div className="w-12 h-12 rounded-full border border-dashed border-emerald-300 flex items-center justify-center text-emerald-800/40 mb-1">
            <User className="w-5 h-5" />
          </div>
          <span className="text-[11px] font-semibold text-emerald-950/60">{posicaoTitulo}</span>
          <span className="text-[10px] text-emerald-800/50">Vago</span>
        </div>
      );
    }

    const isFalta = colab.status === 'falta';
    const isSub = colab.status === 'substituto';

    // Se houver substituto escalado, localizar o substituto para pegar sua foto
    const substitutoInfo = isSub && colab.substitutoId
      ? colaboradoresReserva.find((r) => r.id === colab.substitutoId)
      : null;

    const fotoExibida = isSub && substitutoInfo?.foto ? substitutoInfo.foto : colab.foto;
    const nomeFoto = isSub && substitutoInfo?.nome ? substitutoInfo.nome : colab.nome;

    return (
      <button
        type="button"
        onClick={() => {
          setModalColaborador(colab);
          setModalVeiculoId(veiculoId);
        }}
        className={cn(
          'relative group flex flex-col items-center text-center p-3 rounded-2xl border transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md hover:-translate-y-0.5',
          isFalta
            ? 'bg-rose-50/70 border-rose-200 hover:border-rose-400'
            : isSub
            ? 'bg-amber-50/70 border-amber-200 hover:border-amber-400'
            : 'bg-white border-emerald-900/10 hover:border-emerald-500 hover:bg-emerald-50/30'
        )}
      >
        {/* Posição no veículo (tag superior) */}
        <div className="flex items-center justify-between w-full mb-2">
          <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-900/60 bg-emerald-100/60 px-2 py-0.5 rounded-md">
            {posicaoTitulo}
          </span>
          {getStatusBadge(colab.status)}
        </div>

        {/* Foto em Destaque Alto com Moldura de Assento do Carro */}
        <div className="relative mb-2">
          <div
            className={cn(
              'w-20 h-20 sm:w-24 sm:h-24 rounded-2xl overflow-hidden border-2 shadow-md transition-transform group-hover:scale-105 flex items-center justify-center bg-emerald-50',
              isFalta
                ? 'border-rose-400 ring-2 ring-rose-400/20'
                : isSub
                ? 'border-amber-400 ring-2 ring-amber-400/20'
                : 'border-emerald-600 ring-2 ring-emerald-500/20'
            )}
          >
            {fotoExibida ? (
              <img
                src={fotoExibida}
                alt={nomeFoto}
                className={cn(
                  'w-full h-full object-cover transition-all',
                  isFalta && 'grayscale contrast-125 opacity-70'
                )}
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
            ) : (
              <span className="text-xl font-bold text-emerald-900 font-sans">
                {getIniciais(nomeFoto)}
              </span>
            )}
          </div>

          {/* Indicador de Status Rápido no Canto da Foto */}
          <div
            className={cn(
              'absolute -bottom-1 -right-1 w-6 h-6 rounded-full border-2 border-white flex items-center justify-center shadow-sm',
              isFalta ? 'bg-rose-600 text-white' : isSub ? 'bg-amber-500 text-white' : 'bg-emerald-600 text-white'
            )}
          >
            {isFalta ? (
              <UserX className="w-3.5 h-3.5" />
            ) : isSub ? (
              <UserCheck className="w-3.5 h-3.5" />
            ) : (
              <CheckCircle2 className="w-3.5 h-3.5" />
            )}
          </div>
        </div>

        {/* Informações do Colaborador com Legibilidade Clara */}
        <div className="w-full">
          {/* Se for substituição, exibe o colaborador substituto com sua foto e nome com clareza */}
          {isSub && (colab.substitutoNome || substitutoInfo?.nome) ? (
            <div className="mt-0.5">
              <div className="flex items-center justify-center gap-1">
                <span className="text-[10px] font-bold text-amber-900 bg-amber-100/90 px-1.5 py-0.5 rounded">
                  Substituto em Campo:
                </span>
              </div>
              <h4 className="text-xs sm:text-sm font-bold text-amber-950 truncate max-w-full mt-0.5">
                {substitutoInfo?.nome || colab.substitutoNome}
              </h4>
              <p className="text-[10px] text-amber-900/70 truncate">
                Substituindo: {colab.nome}
              </p>
            </div>
          ) : (
            <>
              <h4 className="text-xs sm:text-sm font-bold text-emerald-950 truncate max-w-full">
                {colab.nome}
              </h4>
              <p className="text-[11px] text-emerald-800/70 font-medium truncate mt-0.5">
                {colab.cargo}
              </p>
            </>
          )}

          {isFalta && colab.motivoFalta && (
            <p className="text-[10px] text-rose-700 font-semibold truncate mt-1 bg-rose-100/80 px-1.5 py-0.5 rounded">
              {colab.motivoFalta}
            </p>
          )}
        </div>
      </button>
    );
  };

  return (
    <div className="w-full space-y-6">
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center rounded-2xl border border-emerald-900/10 bg-white shadow-sm">
          <Car className="w-12 h-12 text-emerald-700/40 mb-3" />
          <h3 className="text-base font-bold text-emerald-950">Nenhum veículo encontrado</h3>
          <p className="text-xs text-emerald-900/60 max-w-sm mt-1">
            Não há veículos cadastrados para esta regional ou os filtros selecionados.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const eq1 = [veiculo.assentos?.motorista, veiculo.assentos?.frenteDir].filter(Boolean);
            const eq2 = [veiculo.assentos?.trasEsq, veiculo.assentos?.trasDir].filter(Boolean);

            const totalAtivos = [...eq1, ...eq2].filter(
              (c) => c && (c.status === 'presente' || c.status === 'substituto')
            ).length;

            return (
              <div
                key={veiculo.id}
                className="rounded-3xl border border-emerald-900/15 bg-white shadow-sm overflow-hidden flex flex-col justify-between"
              >
                {/* Cabeçalho do Veículo */}
                <div className="p-4 sm:p-5 border-b border-emerald-900/10 bg-emerald-50/40 flex flex-wrap items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-2xl bg-white border border-emerald-600/30 shadow-sm flex items-center justify-center text-emerald-700 font-bold">
                      <Car className="w-6 h-6" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="text-base font-bold text-emerald-950 tracking-tight">
                          {veiculo.prefixo}
                        </h3>
                        <span className="font-mono text-xs font-semibold px-2 py-0.5 rounded-md bg-white border border-emerald-200 text-emerald-900 shadow-2xs">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-xs text-emerald-900/70 font-medium">
                        {veiculo.modelo} • {veiculo.ano} •{' '}
                        <span className="capitalize font-semibold text-emerald-950">
                          {veiculo.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'}
                        </span>
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-white border border-emerald-200 text-emerald-950 shadow-2xs">
                      <Users className="w-3.5 h-3.5 text-emerald-600" />
                      <span>{totalAtivos}/4 escalados</span>
                    </span>
                  </div>
                </div>

                {/* VISUALIZAÇÃO DE CIMA DO CARRO (4 PESSOAS) */}
                <div className="p-4 sm:p-6 bg-gradient-to-b from-emerald-50/20 to-white flex items-center justify-center">
                  <div className="w-full max-w-lg rounded-3xl border-2 border-emerald-900/20 bg-slate-50/60 p-4 sm:p-5 shadow-inner">
                    {/* Linha da Frente (Motorista e Passageiro Dianteiro) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 mb-3 sm:mb-4">
                      {renderAssentoCockpit(
                        veiculo.assentos?.motorista,
                        'Motorista',
                        'esq',
                        'frente',
                        veiculo.id
                      )}
                      {renderAssentoCockpit(
                        veiculo.assentos?.frenteDir,
                        'Passageiro Frente',
                        'dir',
                        'frente',
                        veiculo.id
                      )}
                    </div>

                    {/* Divisor do cockpit do veículo */}
                    <div className="relative flex items-center justify-center my-1 sm:my-2">
                      <div className="w-full border-t border-emerald-900/15" />
                      <span className="absolute bg-slate-100 px-3 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider text-emerald-900/50">
                        Fileira Traseira
                      </span>
                    </div>

                    {/* Linha de Trás (Passageiros Traseiros) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 mt-3 sm:mt-4">
                      {renderAssentoCockpit(
                        veiculo.assentos?.trasEsq,
                        'Traseiro Esquerdo',
                        'esq',
                        'tras',
                        veiculo.id
                      )}
                      {renderAssentoCockpit(
                        veiculo.assentos?.trasDir,
                        'Traseiro Direito',
                        'dir',
                        'tras',
                        veiculo.id
                      )}
                    </div>
                  </div>
                </div>

                {/* Rodapé com identificação das equipes vinculadas */}
                <div className="px-5 py-3 border-t border-emerald-900/10 bg-emerald-50/30 flex items-center justify-between text-xs text-emerald-900/70">
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-emerald-950">Equipe 1:</span>
                    <span>{veiculo.equipe1Codigo || 'Frente'}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-emerald-950">Equipe 2:</span>
                    <span>{veiculo.equipe2Codigo || 'Retaguarda'}</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Presença / Falta / Substituição com Nome e Foto do Substituto */}
      <AttendanceModal
        isOpen={!!modalColaborador}
        onClose={() => {
          setModalColaborador(null);
          setModalVeiculoId(null);
        }}
        colaborador={modalColaborador}
        colaboradoresReserva={colaboradoresReserva}
        onConfirm={(colabId, status, motivo, obs, subId) => {
          if (onUpdateStatus) {
            onUpdateStatus(colabId, status, motivo, obs, subId);
          }
        }}
      />
    </div>
  );
};

