              </h4>
              <p className="text-[10px] text-amber-900/70 truncate">
                Substituindo: {colab.nome}
              </p>
            </div>
          ) : (
            <>
              <h4 className="text-xs sm:text-sm font-bold text-emerald-950 truncate max-w-full">
                {colab.nome}
              </h4>
              <p className="text-[11px] text-emerald-800/70 font-medium truncate mt-0.5">
                {colab.cargo}
              </p>
            </>
          )}

          {isFalta && colab.motivoFalta && (
            <p className="text-[10px] text-rose-700 font-semibold truncate mt-1 bg-rose-100/80 px-1.5 py-0.5 rounded">
              {colab.motivoFalta}
            </p>
          )}
        </div>
      </button>
    );
  };

  return (
    <div className="w-full space-y-6">
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center rounded-2xl border border-emerald-900/10 bg-white shadow-sm">
          <Car className="w-12 h-12 text-emerald-700/40 mb-3" />
          <h3 className="text-base font-bold text-emerald-950">Nenhum veículo encontrado</h3>
          <p className="text-xs text-emerald-900/60 max-w-sm mt-1">
            Não há veículos cadastrados para esta regional ou os filtros selecionados.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const eq1 = [veiculo.assentos?.motorista, veiculo.assentos?.frenteDir].filter(Boolean);
            const eq2 = [veiculo.assentos?.trasEsq, veiculo.assentos?.trasDir].filter(Boolean);

            const totalAtivos = [...eq1, ...eq2].filter(
              (c) => c && (c.status === 'presente' || c.status === 'substituto')
            ).length;

            return (
              <div
                key={veiculo.id}
                className="rounded-3xl border border-emerald-900/15 bg-white shadow-sm overflow-hidden flex flex-col justify-between"
              >
                {/* Cabeçalho do Veículo */}
                <div className="p-4 sm:p-5 border-b border-emerald-900/10 bg-emerald-50/40 flex flex-wrap items-center justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-2xl bg-white border border-emerald-600/30 shadow-sm flex items-center justify-center text-emerald-700 font-bold">
                      <Car className="w-6 h-6" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="text-base font-bold text-emerald-950 tracking-tight">
                          {veiculo.prefixo}
                        </h3>
                        <span className="font-mono text-xs font-semibold px-2 py-0.5 rounded-md bg-white border border-emerald-200 text-emerald-900 shadow-2xs">
                          {veiculo.placa}
                        </span>
                      </div>
                      <p className="text-xs text-emerald-900/70 font-medium">
                        {veiculo.modelo} • {veiculo.ano} •{' '}
                        <span className="capitalize font-semibold text-emerald-950">
                          {veiculo.regional === 'agua_clara' ? 'Água Clara' : 'Ribas do Rio Pardo'}
                        </span>
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-white border border-emerald-200 text-emerald-950 shadow-2xs">
                      <Users className="w-3.5 h-3.5 text-emerald-600" />
                      <span>{totalAtivos}/4 escalados</span>
                    </span>
                  </div>
                </div>

                {/* VISUALIZAÇÃO DE CIMA DO CARRO (4 PESSOAS) */}
                <div className="p-4 sm:p-6 bg-gradient-to-b from-emerald-50/20 to-white flex items-center justify-center">
                  <div className="w-full max-w-lg rounded-3xl border-2 border-emerald-900/20 bg-slate-50/60 p-4 sm:p-5 shadow-inner">
                    {/* Linha da Frente (Motorista e Passageiro Dianteiro) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 mb-3 sm:mb-4">
                      {renderAssentoCockpit(
                        veiculo.assentos?.motorista,
                        'Motorista',
                        'esq',
                        'frente',
                        veiculo.id
                      )}
                      {renderAssentoCockpit(
                        veiculo.assentos?.frenteDir,
                        'Passageiro Frente',
                        'dir',
                        'frente',
                        veiculo.id
                      )}
                    </div>

                    {/* Divisor do cockpit do veículo */}
                    <div className="relative flex items-center justify-center my-1 sm:my-2">
                      <div className="w-full border-t border-emerald-900/15" />
                      <span className="absolute bg-slate-100 px-3 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider text-emerald-900/50">
                        Fileira Traseira
                      </span>
                    </div>

                    {/* Linha de Trás (Passageiros Traseiros) */}
                    <div className="grid grid-cols-2 gap-3 sm:gap-4 mt-3 sm:mt-4">
                      {renderAssentoCockpit(
                        veiculo.assentos?.trasEsq,
                        'Traseiro Esquerdo',
                        'esq',
                        'tras',
                        veiculo.id
                      )}
                      {renderAssentoCockpit(
                        veiculo.assentos?.trasDir,
                        'Traseiro Direito',
                        'dir',
                        'tras',
                        veiculo.id
                      )}
                    </div>
                  </div>
                </div>

                {/* Rodapé com identificação das equipes vinculadas */}
                <div className="px-5 py-3 border-t border-emerald-900/10 bg-emerald-50/30 flex items-center justify-between text-xs text-emerald-900/70">
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-emerald-950">Equipe 1:</span>
                    <span>{veiculo.equipe1Codigo || 'Frente'}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-emerald-950">Equipe 2:</span>
                    <span>{veiculo.equipe2Codigo || 'Retaguarda'}</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Presença / Falta / Substituição com Nome e Foto do Substituto */}
      <AttendanceModal
        isOpen={!!modalColaborador}
        onClose={() => {
          setModalColaborador(null);
          setModalVeiculoId(null);
        }}
        colaborador={modalColaborador}
        colaboradoresReserva={colaboradoresReserva}
        onConfirm={(colabId, status, motivo, obs, subId) => {
          if (onUpdateStatus) {
            onUpdateStatus(colabId, status, motivo, obs, subId);
          }
        }}
      />
    </div>
  );
};

